# ради данных, которые физически известны за секунды до единой закачки.
PLAN_ONLY = "--plan-only" in _ARGV_FLAGS
# ОТБОР БЕЗ РЕНДЕРА. Весь конвейер выбора кадра исполняется как обычно —
