def _argv_float(name, default):
    for a in _ARGV_FLAGS:
        if a.startswith(name + "="):
            try:
                return float(a.split("=", 1)[1])
            except ValueError:
                pass
    return default


# Предпросмотр ЗВУКА без рендера видео. Прямая причина: проверить звук на
