# Слова, по которым блок вероятно описывает физическое действие/движение —
# видео туда осмысленно (бой на стоке реально показывает бой), не просто
# механическая чётность i%2 (см. main() — та не различала "плита лежит на
# столе" от "штурм крепости", зритель подсознательно считывает периодичность
# чередования). Общая лексика военно-исторической ниши, не привязана к
# конкретному эпизоду — как THEMES, расширяется по мере надобности.
#
# РЕАЛЬНЫЙ, ИЗМЕРЕННЫЙ баг (прямая жалоба пользователя: "когда говорится, что
# герой заносит клинок, показывается просто фото меча вместо видео, где
# персонаж заносит меч"). Причина найдена и посчитана, не предположена:
# проверка шла ТОЧНЫМ совпадением словоформы со словарём, а русский язык
# склоняет и спрягает. В тексте "Герой на экране ЗАНОСИТ клинок, РЫЧИТ, враг
# ПАДАЕТ" нет ни одной словарной формы — блок уходил в фото. На реальном
# эпизоде videos/01_ves-mecha (91 блок) старая проверка срабатывала на 3
# блоках из 91 (3.3%), пропуская при этом блоки с очевидным действием. То
# есть заявленный в main() "content-aware выбор фото/видео" фактически не
# работал: в 97% случаев решение принимал h_text % 2 — ровно та механическая
# чередовка, которую этот код должен был заменить. Это тот же класс ошибки,
# что уже задокументирован в CLAUDE.md ЧАСТЬ 8 ("важно понимать" в словаре
# не ловит форму "важно понять").
#
# Теперь сравнение по ОСНОВЕ слова (startswith), а не по полной форме: на том
# же эпизоде 3 -> 14 блоков (3.3% -> 15.4%), включая тот самый блок из жалобы.
#
# Основы выверены на коллизии ВРУЧНУЮ по реальному тексту канала — наивный
# список основ давал ложные срабатывания, каждое ниже реально найдено, не
# гипотетическое: "метал" ловит "МЕТАЛЛ" (на оружейном канале — сплошь),
# "сеч" ловит "СЕЧЕНИЕ клинка" (прямой термин этой ниши), "руб" ловит
# "РУБЛЬ"/"РУБЕЖ", "сраз" ловит "СРАЗУ" (найдено прогоном по эпизоду),
# "боя"/"бои" ловят "БОЯТСЯ"/"БОИТСЯ" (тема страха в бою — постоянная у
# этого канала). Поэтому основы намеренно длиннее и конкретнее, чем
# "минимально достаточные", плюс явный стоп-список ACTION_STEM_EXCLUDE на
# слова-омонимы, которые основа всё же зацепила бы.
ACTION_STEMS = (
    "битв", "сражен", "сража", "штурм", "атак", "нападен", "напада",
    "поход", "маршир", "наступлен", "отступлен", "погоня", "погони", "погоню",
    "бегут", "бежал", "бежит", "бегом", "мчат", "мчал", "мчит", "скакал", "скачет",
    "скачка", "удар", "рубил", "рубит", "рубят", "рубить", "рубк",
    "сеча", "сечи", "сечь", "фехт", "поедин", "дуэл", "разил", "разит",
    "пожар", "горит", "горят", "горел", "взрыв", "обстрел",
    "осада", "осади", "осажд", "прорыв", "рукопашн", "схватк", "резн",
    "занос", "занёс", "занес", "замахн", "замахив", "размах", "взмах",
    "махал", "махнул", "бьёт", "бьют", "колол", "колющ", "укол", "вонз",
    "пробив", "пробил", "ломал", "ломает", "ломают", "сломал",
    "драл", "драк", "дерут", "дерёт", "режет", "резал", "резать",
    "пада", "упал", "рычит", "рычал", "отбива", "отбил", "парир",
    "швыр", "метнул", "метание", "бой",
)
# РЕАЛЬНЫЙ найденный пробел (21.09, тестовый эпизод 94_dagger_test, слот
# "Конница мчится через поле прямо на пехоту"): "мчат"/"мчал" ловят
# "мчатся"/"мчался", но НЕ ловят "мчится" (3-е лицо ед.ч. наст. времени —
# startswith сравнивает С НАЧАЛА слова, "мчится".startswith("мчат") ложно).
# Слот с явной кавалерийской атакой ушёл в фото-пул вместо видео — не потому,
# что видео не искали, а потому что искать его никто не попросил. Ровно тот
# же класс, что уже задокументирован выше про "важно понять" — словарная
# форма поймана, глагольная форма из текста — нет. "мчит" добавлен и сюда,
# и в ACTION_VIDEO_QUALIFIERS ниже (группа "running").
# Омонимы, которые основа выше всё-таки цепляет — проверяются ПЕРВЫМИ.
# Каждое слово здесь либо реально встретилось в тексте канала, либо
# заведомо частотно именно в этой нише (металл/сечение/клинок).
# Аудит 04.09 (воспроизведено живым вызовом): startswith по основам ловил
# «резная рукоять» (резн- -> fighting), «заносчивый» (-> wielding), «штурман»,
# «горелка», «походка», «ударение», «бойкот», «разительно» — блок про декор
# получал ВИДЕО с уточнением «fighting». Исключения по ОСНОВЕ (не словоформе).
ACTION_STEM_EXCLUDE_PREFIXES = ("резн", "резьб", "заносчив", "штурман", "горелк", "походк",
                                "ударен", "бойкот", "разительн")
ACTION_STEM_EXCLUDE = frozenset((
    "сразу", "маршрут", "маршрута", "маршруты", "металл", "металла",
    "металлы", "металлург", "рубль", "рубля", "рублей", "рубеж", "рубежа",
    "сечение", "сечения", "осадок", "осадки", "боится", "боятся", "боязнь",
    "бойкий", "погоны", "погон", "билет", "походка", "походки", "скачать",
    "разительный", "падаль",
))


def wants_handheld(block):
    """Лёгкая «ручная» тряска видео: фраза про движение. Со спецификацией
    кадра решает её обязательное утверждение движения; без неё — прежний
    словарь (он остаётся запасным путём для фраз без плана)."""
    spec = block.get("shot_spec")
    if spec:
        import stock_query_planner
        return stock_query_planner.has_motion(spec, must=True)
    return has_action_word(block["text"])


def has_action_word(text):
    """Описывает ли блок физическое действие/движение — критерий заказа
    ВИДЕО вместо фото (см. main()). Сравнение по основе слова, см. подробный
    разбор у ACTION_STEMS выше."""
    for w in text.split():
        w = re.sub(r'[^\w]', '', w.lower())
        if not w or w in ACTION_STEM_EXCLUDE or w.startswith(ACTION_STEM_EXCLUDE_PREFIXES):
            continue
        if any(w.startswith(s) for s in ACTION_STEMS):
            return True
    return False


# Вторая половина той же жалобы пользователя: мало ВЫБРАТЬ видео вместо фото —
# сам поисковый запрос тоже не несёт действия. На блоке "герой заносит клинок"
# запрос собирается словарём THEMES по КОРНЮ ПРЕДМЕТНОГО СЛОВА ("клинок" ->
# "medieval sword close up") и описывает предмет крупным планом, то есть
# заведомо статичный кадр — даже идеальный по этому запросу результат не
# покажет замах. Пользователь сформулировал это точно: подбор идёт "не по
# полному предложению, а только по слову".
#
# Уточнение движения добавляется ТОЛЬКО к строке видео-поиска и только когда
# в блоке реально есть глагол действия — тот же приём и та же дисциплина, что
# у disambiguate_search_query() (ключ кэша и relevance-скоринг остаются на
# исходном запросе, чтобы не сдвигать уже откалиброванные пороги
# CLIP_RELEVANCE_THRESHOLD/RISKY_QUERY_MARGIN).
#
# Формулировки ПРОВЕРЕНЫ на живом Pexels API (не подобраны по интуиции), и
# часть кандидатов отклонена по результату выдачи:
#  - "swinging" отвергнуто: тянет "woman sitting on swing" (качели) — реальный
#    мусор в выдаче на живом запросе; "wielding" на том же запросе дал ноль
#    мусора и поднял наверх бой/обнажение клинка.
#  - Группа "падает/ломается" ("falling") УБРАНА целиком: на живой проверке
#    дала слабую выдачу (абстрактный цветной паттерн среди первых пяти), а её
#    триггеры у этого канала чаще метафоричны ("спрос упал", "миф рухнул"),
#    чем физичны. Сами основы остаются в ACTION_STEMS (решение "видео вместо
#    фото" — отдельное и менее рискованное), но уточнять ими ЗАПРОС нечем:
#    честнее не уточнять, чем уточнять во вред.
ACTION_VIDEO_QUALIFIERS = (
    (("занос", "занёс", "занес", "замахн", "замахив", "размах", "взмах",
      "махал", "махнул"), "wielding"),
    (("рубил", "рубит", "рубят", "рубить", "рубк", "сеча", "сечи", "сечь"), "slashing"),
    (("колол", "колющ", "укол", "вонз"), "thrusting"),
    (("фехт", "поедин", "дуэл"), "fencing duel"),
    (("битв", "сражен", "сража", "схватк", "рукопашн", "драл", "драк", "бой",
      "резн"), "fighting"),
    (("атак", "штурм", "наступлен", "прорыв", "нападен", "напада", "осада",
      "осади", "осажд"), "charging attack"),
    (("скакал", "скачет", "скачка"), "galloping horse"),
    (("бегут", "бежал", "бежит", "бегом", "мчат", "мчал", "мчит"), "running"),
    (("маршир", "поход"), "marching"),
    (("пожар", "горит", "горят", "горел", "взрыв", "обстрел"), "fire flames"),
)


def action_video_qualifier(text):
    """Английское слово-уточнение движения по тексту блока, или None.
    Первое совпавшее правило (порядок = приоритет: конкретный жест важнее
    общего "бой"). Тот же стоп-список омонимов, что у has_action_word()."""
    if not text:
        return None
    words = [re.sub(r'[^\w]', '', w.lower()) for w in text.split()]
    words = [w for w in words if w and w not in ACTION_STEM_EXCLUDE]
    for stems, qualifier in ACTION_VIDEO_QUALIFIERS:
        if any(w.startswith(s) for w in words for s in stems):
            return qualifier
    return None


def apply_action_qualifier(query, qualifier):
    """Уточнение движения перед запросом — только те СЛОВА, которых в запросе
    ещё нет (тот же приём против дублей, что в disambiguate_search_query:
    реальный баг первой версии там — "european medieval medieval armor")."""
    if not qualifier:
        return query
    ql = query.lower()
    missing = [w for w in qualifier.split() if w not in ql]
    if not missing:
        return query
    return f"{' '.join(missing)} {query}"


def decoded_audio_duration(path):
    """Реальная длина ДЕКОДИРОВАННОГО аудио. Для MP3 ffprobe format.duration —
    оценка контейнера с паддингом кодера: аудит 04.09 измерил 60.029с против
    60.000с реальных сэмплов — лишний кадр видео без звука, сдвиг fade-out и
    конца субтитров на 29 мс. FLAC/WAV точны и так, но путь один для всех.
    None — если декод не удался (вызывающий откатывается на ffprobe)."""
    try:
        r = subprocess.run(["ffmpeg", "-v", "error", "-nostats", "-progress", "pipe:1",
                            "-i", path, "-f", "null", "-"],
                           capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=600)
        us = [int(x) for x in re.findall(r"out_time_us=(\d+)", r.stdout)]
        if r.returncode == 0 and us and us[-1] > 0:
            return us[-1] / 1_000_000.0
    except Exception:
        pass
    return None


def get_audio_duration():
    r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                        "-show_format", AUDIO_FILE], capture_output=True, text=True, encoding="utf-8", errors="replace", check=True)
    probed = float(json.loads(r.stdout)["format"]["duration"])
    decoded = decoded_audio_duration(AUDIO_FILE)
    if decoded is not None and abs(decoded - probed) > 0.5 / FPS:
        print(f"  Аудио: контейнер обещает {probed:.3f}с, реально декодируется {decoded:.3f}с — беру реальную")
    return decoded if decoded is not None else probed


ALIGNMENT_DIR = os.path.join(VIDEO_FOLDER, "media_plan", "alignment")
ALIGNMENT_TAG_RE = re.compile(r'\[short pause\]|\[pause\]')
ALIGNMENT_STRIP_TAGS = ("[energetic]", "[slowly]", "[emphasis]")

# ALIGNMENT_TAG_SPAN_RE импортируется из script_parser (см. его докстринг:
# словарь тегов живёт в ОДНОМ месте — копии уже стоили эпизоду PHRASE LOCK).
# Имя переэкспортируется здесь, потому что на pipeline_smart.ALIGNMENT_TAG_SPAN_RE
# ссылается section_sync.py и тесты.
PAUSE_CUTS_PATH = os.path.join(VIDEO_FOLDER, "media_plan", "pause_cuts.json")
_PAUSE_CUTS_CACHE = None   # ленивый кэш на процесс — файл не меняется за время рендера


def load_pause_cuts():
    """[[вырезанный_старт, вырезанный_конец], ...] в СЫРОМ времени audio.mp3
    (см. fix_pauses.save_cuts) — реальные интервалы, которые
    silencedetect+atrim вычистили из аудио. Нет файла (старый эпизод, ещё
    не пересчитанный fix_pauses.py) -> [] (тихий откат на identity-маппинг,
    raw_to_real_time тогда просто возвращает t без изменений).

    Проверка отпечатка (source_audio_md5): pause_cuts.json описывает
    порезки КОНКРЕТНОГО audio.mp3 на момент запуска fix_pauses.py. Если
    audio.mp3 потом перезаписали (новая озвучка, правка) без повторного
    fix_pauses.py — порезки больше не соответствуют реальности, а
    raw_to_real_time() молча применил бы их к чужому аудио, воспроизводя
    ровно тот класс рассинхрона, который этот файл должен был исправить.
    Несовпадение -> предупреждение в консоль + откат на [] (честно "без
    точной подгонки", а не тихая порча по устаревшим данным)."""
    global _PAUSE_CUTS_CACHE
    if _PAUSE_CUTS_CACHE is not None:
        return _PAUSE_CUTS_CACHE
    try:
        with open(PAUSE_CUTS_PATH, encoding="utf-8") as f:
            data = json.load(f)
        raw_audio_path = os.path.join(VIDEO_FOLDER, "audio.mp3")
        expected_md5 = data.get("source_audio_md5")
        if expected_md5 and os.path.exists(raw_audio_path):
            h = hashlib.md5()
            with open(raw_audio_path, "rb") as af:
                for chunk in iter(lambda: af.read(1 << 20), b""):
                    h.update(chunk)
            if h.hexdigest() != expected_md5:
                print("  ВНИМАНИЕ: pause_cuts.json не соответствует текущему audio.mp3 "
                      "(перезаписали озвучку без повторного fix_pauses.py?) — "
                      "порезки игнорирую, подписи хука пересчитаются без точной подгонки паузы.")
                _PAUSE_CUTS_CACHE = []
                return _PAUSE_CUTS_CACHE
        _PAUSE_CUTS_CACHE = [(float(a), float(b)) for a, b in data.get("cuts", [])]
    except Exception:
        _PAUSE_CUTS_CACHE = []
    return _PAUSE_CUTS_CACHE


_PAUSE_WINDOWS_CACHE = None   # ленивый кэш на процесс, как и _PAUSE_CUTS_CACHE


def load_pause_windows():
    """[[сырой_старт_тишины, сколько_оставлено], ...] — см. fix_pauses.save_cuts
    (P1-15). Используется только для музыкального "вздоха" на осознанно
    длинных паузах (см. _pause_swell_expr), поэтому переиспользует тот же
    файл/отпечаток, что и load_pause_cuts(), но не трогает её кэш и формат
    (raw_to_real_time распаковывает cuts как строгие (a, b) пары повсюду в
    файле — здесь отдельный ключ, отдельная проверка). Нет файла/ключа или
    отпечаток не совпадает с текущим audio.mp3 -> [] (тихий откат, как и
    у load_pause_cuts)."""
    global _PAUSE_WINDOWS_CACHE
    if _PAUSE_WINDOWS_CACHE is not None:
        return _PAUSE_WINDOWS_CACHE
    try:
        with open(PAUSE_CUTS_PATH, encoding="utf-8") as f:
            data = json.load(f)
        raw_audio_path = os.path.join(VIDEO_FOLDER, "audio.mp3")
        expected_md5 = data.get("source_audio_md5")
        if expected_md5 and os.path.exists(raw_audio_path):
            h = hashlib.md5()
            with open(raw_audio_path, "rb") as af:
                for chunk in iter(lambda: af.read(1 << 20), b""):
                    h.update(chunk)
            if h.hexdigest() != expected_md5:
                _PAUSE_WINDOWS_CACHE = []
                return _PAUSE_WINDOWS_CACHE
        _PAUSE_WINDOWS_CACHE = [(float(a), float(b)) for a, b in data.get("pause_windows", [])]
    except Exception:
        _PAUSE_WINDOWS_CACHE = []
    return _PAUSE_WINDOWS_CACHE


_PAUSE_INSERTS_CACHE = None


def load_pause_inserts():
    """[(сырая_позиция, секунд_вставлено), ...] из того же pause_cuts.json.

    Отдельный ключ, а не третий элемент cuts: raw_to_real_time()
    распаковывает cuts строго как пары (a, b) по всему файлу, и менять эту
    форму ради нового потребителя — тот же класс, что уже ловили у
    pause_windows. Нет ключа (эпизод старше правки) -> [] и прежнее
    поведение."""
    global _PAUSE_INSERTS_CACHE
    if _PAUSE_INSERTS_CACHE is not None:
        return _PAUSE_INSERTS_CACHE
    try:
        with open(PAUSE_CUTS_PATH, encoding="utf-8") as f:
            data = json.load(f)
        items = [(float(a), float(b)) for a, b in (data.get("pause_inserts") or [])]
        _PAUSE_INSERTS_CACHE = sorted(items)
    except Exception:
        _PAUSE_INSERTS_CACHE = []
    return _PAUSE_INSERTS_CACHE


def raw_to_real_time(t, cuts):
    """Точный (не приближённый по тегам) пересчёт сырого времени alignment.csv
    (до обрезки пауз в fix_pauses.py) в реальное время audio_fixed.mp3 —
    вычитает из t суммарно всё, что реально вырезано ДО t (частично, если t
    попадает внутрь самого вырезанного интервала). cuts — из load_pause_cuts(),
    отсортированы по возрастанию (естественный порядок silencedetect)."""
    removed = 0.0
    for a, b in cuts:
        if a >= t:
            break
        removed += min(t, b) - a
    # ВСТАВЛЕННАЯ тишина — вторая половина той же карты, и читается она
    # ЗДЕСЬ, а не у шести вызывающих. Причина ровно та, что уже дважды
    # стоила этому репозиторию сломанного тайминга: карту времени, которую
    # надо передавать руками, рано или поздно кто-нибудь не передаст.
    # Вставки появляются, когда fix_pauses.py доводит тег-паузу до её
    # документированной длины (ЧАСТЬ 10): движок отдаёт [short pause] как
    # 0.169с вместо 0.4 (замер 14.09), и без доведения звук в такую щель не
    # влезает никогда. Старый эпизод без ключа pause_inserts даёт пустой
    # список — поведение байт-в-байт прежнее.
    added = 0.0
    for pos, sec in load_pause_inserts():
        if pos >= t:
            break
        added += float(sec)
    return t - removed + added


_SECTION_OFFSETS_CACHE = None   # ленивый кэш на процесс, как и _PAUSE_CUTS_CACHE
SECTION_OFFSETS_PATH = os.path.join(VIDEO_FOLDER, "media_plan", "section_offsets.json")


def load_section_offsets():
    """{section_name: raw_global_offset_sec} из media_plan/section_offsets.json —
    пишет scripts/speech_generate.py Stage B (сам конкатенирует фрагменты,
    знает точно) ИЛИ scripts/section_sync.py (кросс-корреляция паттерна
    пауз против реального аудио — для эпизодов без Stage B, см. докстринг
    section_sync.py). Нет файла -> {} (тихий откат: offsets.get(name, 0.0)
    везде ниже даёт РОВНО прежнее поведение — локальное время секции
    трактуется как глобальное, корректно только для первой секции по
    определению, как и было до этой карты)."""
    global _SECTION_OFFSETS_CACHE
    if _SECTION_OFFSETS_CACHE is not None:
        return _SECTION_OFFSETS_CACHE
    try:
        with open(SECTION_OFFSETS_PATH, encoding="utf-8") as f:
            data = json.load(f)
        _SECTION_OFFSETS_CACHE = {str(k): float(v) for k, v in data.items()}
    except Exception:
        _SECTION_OFFSETS_CACHE = {}
    return _SECTION_OFFSETS_CACHE


def _clean_timed_chars(segment):
    """Только РЕАЛЬНО озвученные символы сегмента с их временами
    [(char, start, end), ...] — без пробелов, скобок и служебных тегов вроде
    [energetic]/[slowly] (они не читаются TTS вслух, но формально попадают в
    поток символов alignment.csv). Общая основа для _real_speech_bounds()
    (границы сегмента) и load_alignment_onsets() (посимвольная привязка
    ПОД-блоков внутри сегмента) — одна реализация фильтра на оба места,
    иначе они молча разошлись бы при следующей правке."""
    text = "".join(c for c, s, e in segment)
    excluded = set()
    for m in ALIGNMENT_TAG_SPAN_RE.finditer(text):
        excluded.update(range(m.start(), m.end()))
    return [(c, s, e) for j, (c, s, e) in enumerate(segment)
            if j not in excluded and re.match(r'[^\s\[\]]', c or "")]


def speech_chars_of_text(text):
    """Та же нормализация, что _clean_timed_chars(), но для ТЕКСТА блока —
    строка из одних озвучиваемых символов. Позволяет сопоставить блок с его
    участком посимвольного alignment один-в-один: sub-cut'ы (см.
    split_long_blocks) делят слова исходного блока БЕЗ остатка, поэтому их
    очищенные тексты, склеенные подряд, посимвольно равны очищенному тексту
    сегмента — это и даёт точную, а не пропорциональную привязку под-кадра
    ко времени озвучки."""
    text = re.sub(r'\[[^\]]*\]', '', text or "")
    return re.sub(r'[\s\[\]]', '', text)


def _real_speech_bounds(segment):
    """(старт, конец) реально озвученного текста в сегменте символов
    (index,char,start,end) — по первому и последнему озвученному символу
    (см. _clean_timed_chars). None, если в сегменте нет ни одного реального
    символа."""
    clean = _clean_timed_chars(segment)
    if not clean:
        return None
    return clean[0][1], clean[-1][2]


def _real_speech_span(segment, section_offset=0.0):
    """РЕАЛЬНАЯ (после обрезки пауз fix_pauses.py, см. raw_to_real_time)
    длительность озвученного текста в сегменте — см. _real_speech_bounds
    (общая логика, тег-агностичная граница). Раньше возвращала СЫРУЮ
    длительность (до обрезки) — а именно эта величина кормит вес блока в
    load_alignment_weights()/block_durations(), то есть раньше ДЛИТЕЛЬНОСТЬ
    КАДРА блока могла быть завышена, если внутри блока TTS сделал
    незапланированную (не тегом [pause]) паузу/вдох длиннее секунды —
    silencedetect в fix_pauses.py режет ЛЮБУЮ такую тишину, независимо от
    тегов в тексте (пойман вживую: 41 реальная порезка на 90 тегов паузы в
    эпизоде — то есть часть порезок вообще не в тех местах, где текст
    формально ожидал паузу). Теперь вес блока — точно то время, что он
    реально звучит в audio_fixed.mp3, а не в сыром audio.mp3.

    section_offset — сдвиг ЛОКАЛЬНОГО времени сегмента (свой ноль на файл
    alignment/NN.csv) в ГЛОБАЛЬНОЕ (по всему audio.mp3, та же шкала, что и
    cuts из load_pause_cuts() — см. load_section_offsets()). Раньше bounds
    (локальные) подавались в raw_to_real_time() НАПРЯМУЮ, как будто уже
    глобальные — для первой секции (HOOK) это случайно верно (локальный
    ноль совпадает с глобальным), для всех следующих секций cuts из ДРУГИХ
    участков ролика применялись не туда, давая неверный вес блока —
    реальный, эмпирически подтверждённый баг (см. section_sync.py)."""
    bounds = _real_speech_bounds(segment)
    if not bounds:
        return 0.0
    cuts = load_pause_cuts()
    real_start = raw_to_real_time(bounds[0] + section_offset, cuts)
    real_end = raw_to_real_time(bounds[1] + section_offset, cuts)
    return real_end - real_start


def _alignment_section_segments(blocks):
    """{секция: [сегмент, ...]} — разборка media_plan/alignment/NN.csv на
    сегменты по тегам пауз. Общая основа для load_alignment_weights() (вес
    блока) и load_alignment_onsets() (момент НАЧАЛА блока) — одна реализация
    на оба места. None, если папки alignment нет вообще."""
    if not os.path.isdir(ALIGNMENT_DIR):
        return None
    section_order = []
    for b in blocks:
        if not section_order or section_order[-1] != b["section"]:
            section_order.append(b["section"])
    section_segments = {}
    for i, name in enumerate(section_order):
        path = os.path.join(ALIGNMENT_DIR, f"{i:02d}.csv")
        if not os.path.exists(path):
            continue
        try:
            rows = list(csv.DictReader(open(path, encoding="utf-8")))
            chars = [(r["char"], float(r["start"]), float(r["end"])) for r in rows]
        except Exception as e:
            print(f"  alignment {path} битый, пропускаю: {e}")
            continue
        text = "".join(c for c, s, e in chars)
        segs, pos = [], 0
        for m in ALIGNMENT_TAG_RE.finditer(text):
            segs.append(chars[pos:m.start()])
            pos = m.end()
        segs.append(chars[pos:])
        section_segments[name] = segs
    return section_segments


ONSET_TEXT_MATCH_MIN_RATIO = 0.9   # ниже — текст блока разошёлся с озвученным, привязке нельзя доверять


def load_alignment_onsets(blocks):
    """РЕАЛЬНЫЙ момент НАЧАЛА речи каждого блока (сек, в шкале финального
    audio_fixed — после обрезки пауз fix_pauses.py). Список длиной len(blocks)
    или None, если хотя бы для одного блока привязка не подтвердилась
    (fail-open целиком, а не частично: половина точных онсетов и половина
    угаданных дала бы рассинхрон хуже, чем честная старая оценка).

    ЗАЧЕМ ЭТО ЕСТЬ (реальная, измеренная причина — 28 августа, разбор жалобы
    «видео показывается позже, когда фраза уже сказана»): длительности кадров
    считались по load_alignment_weights() — то есть по ДЛИНЕ речи блока, а не
    по её ПОЛОЖЕНИЮ. Дальше эта оценка проходила через семь преобразований
    (floor/cap-клэмп и rescale в block_durations, energy_mults, apply_section_
    boundary_shift ±250-400мс, apply_within_cut_shift ±80-180мс,
    apply_human_jitter ±300мс, snap_hook_cuts_to_energy), каждое из которых
    двигает границу кадра ОТНОСИТЕЛЬНО фразы, а ошибки складываются по
    накоплению — к концу хука рез уезжает от своей фразы на доли секунды и
    больше. Зритель видит ровно то, на что жаловался пользователь: кадр
    «не под озвучку».

    Длина речи не даёт положения — его даёт только ОНСЕТ. Поэтому здесь
    возвращается именно момент начала, и по нему (см. phrase_locked_durations)
    рез ставится ТОЧНО на начало следующей фразы.

    ТОЧНОСТЬ ДЛЯ ПОД-КАДРОВ: sub-cut'ы (split_long_blocks) делят слова
    исходного блока без остатка, поэтому очищенные тексты под-блоков,
    склеенные подряд, посимвольно равны очищенному тексту сегмента —
    привязка идёт по РЕАЛЬНОМУ символу alignment, а не пропорционально
    числу слов (как считается вес в load_alignment_weights).

    БЕЗОПАСНОСТЬ: текст каждого блока сверяется с реально озвученными
    символами на его позиции (ONSET_TEXT_MATCH_MIN_RATIO). Сценарий,
    поправленный ПОСЛЕ записи озвучки, не получит чужой тайминг молча —
    вернётся None, и сборка честно откатится на прежнее поведение."""
    global ALIGNMENT_ONSET_FAILURE
    ALIGNMENT_ONSET_FAILURE = None
    del SPEECH_ENDS[:]

    def _give_up(reason, **detail):
        """Запомнить ПРИЧИНУ отказа, а не просто вернуть None.

        N5 (docs/AUDIT_2026-09_DEEP.md:281): у этой функции пять разных
        точек отказа, и каждая молча выключала PHRASE LOCK на ВЕСЬ эпизод —
        в консоли при этом не появлялось ни строчки. Самый вероятный случай
        (нормализация произношения в speech_generate.py: TTS получает
        "1,5 килограмма", а script.txt содержит "1,5 кг") выглядел как
        обычный рендер, но кадры переставали держаться за фразы.
        """
        global ALIGNMENT_ONSET_FAILURE
        ALIGNMENT_ONSET_FAILURE = {"reason": reason, **detail}
        return None

    section_segments = _alignment_section_segments(blocks)
    if not section_segments:
        return _give_up("нет ни одного сегмента alignment (media_plan/alignment/*.csv)")
    section_offsets = load_section_offsets()
    cuts = load_pause_cuts()
    onsets = []
    seg_idx, char_pos = {}, {}
    for bi, b in enumerate(blocks):
        section = b["section"]
        segs = section_segments.get(section)
        if segs is None:
            return _give_up("для секции нет alignment", section=section, block_index=bi)
        k = seg_idx.get(section, 0)
        if k >= len(segs):
            return _give_up("блоков больше, чем сегментов записи — доверять нечему",
                            section=section, block_index=bi)
        clean = _clean_timed_chars(segs[k])
        pos = char_pos.get(section, 0)
        want = speech_chars_of_text(b["text"])
        if not want or pos + len(want) > len(clean):
            return _give_up("текст блока не помещается в оставшийся alignment",
                            section=section, block_index=bi,
                            text=b["text"][:60], want_chars=len(want),
                            available_chars=len(clean) - pos)
        got = "".join(c for c, s, e in clean[pos:pos + len(want)])
        ratio = difflib.SequenceMatcher(None, want.lower(), got.lower()).ratio()
        if ratio < ONSET_TEXT_MATCH_MIN_RATIO:
            return _give_up("текст блока разошёлся с озвученным",
                            section=section, block_index=bi, ratio=round(ratio, 3),
                            threshold=ONSET_TEXT_MATCH_MIN_RATIO,
                            script_text=b["text"][:60], spoken_text=got[:60])
        offset = section_offsets.get(section, 0.0)
        onsets.append(raw_to_real_time(clean[pos][1] + offset, cuts))
        # КОНЕЦ речи блока берётся ОТТУДА ЖЕ, где и начало — из символов
        # alignment. Раньше его нигде не было, и потребителям (sfx_plan)
        # приходилось складывать точный онсет с ВЕСОМ блока, а вес после
        # split_long_blocks делится между кусками ПРОПОРЦИОНАЛЬНО словам,
        # то есть является оценкой. Сложение измерения с оценкой — ровно тот
        # класс, который этот файл запрещает, и цена измерена (14.09,
        # videos/_test60s): у 3 границ из 9 «конец речи» оказывался ПОЗЖЕ
        # онсета следующего блока, тишина выходила отрицательной, и
        # speech_gap_before() честно возвращала «нет сигнала». Молча
        # пропадали и переход главы, и объектный кюй — на трети границ.
        SPEECH_ENDS.append(raw_to_real_time(clean[pos + len(want) - 1][2] + offset, cuts))
        pos += len(want)
        if pos >= len(clean):
            seg_idx[section] = k + 1
            char_pos[section] = 0
        else:
            char_pos[section] = pos
    return onsets


# ИЗМЕРЕННЫЙ конец речи каждого блока (реальная шкала), заполняется
# load_alignment_onsets() тем же посимвольным проходом, что и онсеты.
# Существует ровно затем, чтобы потребителям тишины не приходилось
# складывать точный онсет с пропорциональной оценкой веса — см. комментарий
# у самого заполнения.
SPEECH_ENDS = []

PHRASE_LOCK = os.environ.get("PHRASE_LOCK", "1") != "0"

# Почему PHRASE LOCK не включился в этом прогоне (см. load_alignment_onsets()).
# None = либо всё в порядке, либо функция ещё не вызывалась.
ALIGNMENT_ONSET_FAILURE = None


def _merge_two_blocks(pb, cb, prev_words):
    """Слить блок cb В предыдущий (уже накопленный) pb — общая часть между
    merge_short_phrase_locked_blocks() и её хвостовым случаем. prev_words —
    число слов pb ДО слияния (нужно для пересчёта позиции stat-плашки)."""
    nb = dict(pb)
    nb["text"] = (pb["text"].rstrip() + " " + cb["text"].lstrip()).strip()
    nb["words"] = pb["words"] + cb["words"]
    nb["pause_after"] = cb["pause_after"]
    if nb.get("stat") is None and cb.get("stat") is not None:
        sp = cb.get("stat_word_pos")
        nb["stat"] = cb["stat"]
        nb["stat_word_pos"] = (prev_words + sp) if sp is not None else None
    nb["is_climax"] = bool(pb.get("is_climax")) or bool(cb.get("is_climax"))
    return nb


def merge_short_phrase_locked_blocks(blocks, real_weights, total):
    """РЕАЛЬНЫЙ найденный вживую баг (29 августа, videos/_test20s, idx=4,
    1.33с) — HOOK_MIN_CLIP (см. её ревизию выше) клэмпит длительность только
    внутри block_durations()/hook_floor_for. Этот эпизод (как и любой с
    рабочим alignment.csv) идёт по PHRASE LOCK ветке (см. main(),
    phrase_locked_durations) — там длительность клипа считается СТРОГО как
    расстояние между реальными онсетами речи, без единого пола вообще:
    растянуть короткую фразу до пола означало бы, что рез уедет мимо начала
    следующей фразы — ровно тот рассинхрон, ради устранения которого PHRASE
    LOCK и был написан (см. её докстринг). Единственный способ дать
    гарантию пола БЕЗ рассинхрона — не резать на границе слишком короткой
    фразы вовсе: сливаем её текст с предыдущим блоком той же секции в один
    клип (та же идея, что уже мержит короткие sub-cut куски в
    split_long_blocks). Уцелевшие резы по-прежнему стоят РОВНО на реальном
    онсете — их просто меньше.

    БЕЗОПАСНОСТЬ СЛИЯНИЯ (реальный найденный вживую баг при первой версии
    этой функции): сливать можно ТОЛЬКО блок с is_subcut=True — то есть
    кусок, на который split_long_blocks() уже порезал ОДИН исходный
    [pause]-блок (его склеенный текст посимвольно принадлежит тому же
    сегменту alignment, см. docstring speech_chars_of_text). Слияние ДВУХ
    разных исходных [pause]-блоков (is_subcut отсутствует/False) рвёт
    привязку: посимвольный курсор load_alignment_onsets() идёт строго по
    сегментам записи, и склеенный текст двух разных сегментов не находит
    соответствия ни в одном из них — onsets на всём эпизоде становится
    None, то есть "починка" пола сломала бы ВЕСЬ phrase lock целиком
    (проверено вживую: первая версия без этой проверки именно так и
    сломала onsets на videos/_test20s). Итог: короткая фраза, стоящая
    ДЕЙСТВИТЕЛЬНО между двумя настоящими паузами (не sub-cut), пол может
    не выдержать — это честный, редкий остаточный случай (звучит короче
    пола ровно потому, что автор поставил паузы по обе стороны от неё),
    не маскируется молча.
    Никогда не сливает блоки РАЗНЫХ секций (та же граница, которую уважает
    apply_section_boundary_shift).
    Fail-open: без рабочего alignment (onsets is None) ничего не меняет —
    обычная ветка block_durations()/hook_floor_for уже даёт гарантию сама."""
    onsets = load_alignment_onsets(blocks)
    if not onsets or len(onsets) != len(blocks):
        return blocks, real_weights
    merged_blocks = [blocks[0]]
    merged_weights = [real_weights[0] if real_weights else None]
    merged_start = [onsets[0]]
    for i in range(1, len(blocks)):
        cb = blocks[i]
        pb = merged_blocks[-1]
        same_section = cb["section"] == pb["section"]
        floor = hook_floor_for(blocks, i - 1)
        gap = onsets[i] - merged_start[-1]
        if same_section and gap < floor and cb.get("is_subcut"):
            merged_blocks[-1] = _merge_two_blocks(pb, cb, pb["words"])
            pw = merged_weights[-1]
            cw = real_weights[i] if real_weights else None
            merged_weights[-1] = None if (pw is None and cw is None) else (pw or 0.0) + (cw or 0.0)
        else:
            merged_blocks.append(cb)
            merged_weights.append(real_weights[i] if real_weights else None)
            merged_start.append(onsets[i])
    # Хвост: последний клип держится от своего онсета до конца аудио — этот
    # интервал не участвовал в цикле выше (там сравнивались только соседние
    # онсеты между собой). Короче пола — сливаем с предыдущим клипом той же
    # секции (если он есть).
    if len(merged_blocks) > 1:
        tail_floor = hook_floor_for(blocks, len(blocks) - 1)
        tail_gap = total - merged_start[-1]
        if (tail_gap < tail_floor and merged_blocks[-1]["section"] == merged_blocks[-2]["section"]
                and merged_blocks[-1].get("is_subcut")):
            cb = merged_blocks.pop()
            merged_start.pop()
            cw = merged_weights.pop()
            pb = merged_blocks[-1]
            merged_blocks[-1] = _merge_two_blocks(pb, cb, pb["words"])
            pw = merged_weights[-1]
            merged_weights[-1] = None if (pw is None and cw is None) else (pw or 0.0) + (cw or 0.0)
    return merged_blocks, merged_weights


def phrase_locked_durations(onsets, total, trans_plan, fps=None):
    """Длительности клипов, при которых ВИДИМЫЙ рез приходится ТОЧНО на
    начало следующей фразы. None, если данных не хватает (fail-open).

    ДВЕ вещи, которые обязательно учесть, иначе точность теряется:

    1) КОМПЕНСАЦИЯ КРОССФЕЙДА. xfade_chain() физически СЖИМАЕТ смонтированный
       таймлайн на длительность каждого перехода (см. её же комментарий и
       hook_visual_starts): видимый старт клипа n равен cumsum(durs[:n])
       МИНУС сумма уже прошедших нахлёстов. Без поправки каждый следующий рез
       уезжает раньше своей фразы накопительно. Отсюда
       dur[i] = (онсет[i+1] - онсет[i]) + длительность_перехода[i] — при этом
       итоговая длина видео остаётся равна длине аудио (сумма поправок ровно
       компенсируется сжатием).

    2) КВАНТОВАНИЕ ПО ГРАНИЦАМ, А НЕ ПО ДЛИТЕЛЬНОСТЯМ. Клип не может быть
       дробным по кадрам. Если округлять каждую ДЛИТЕЛЬНОСТЬ отдельно (как
       делает quantize_durations_to_frames), ошибка округления складывается
       по всей цепочке. Здесь на кадровую сетку кладутся сами ГРАНИЦЫ, а
       длительности из них вычитаются — тогда каждый рез отстоит от своей
       фразы не более чем на полкадра (~21мс при 24 fps), и это НЕ копится."""
    if not onsets or total <= 0:
        return None
    fps = fps or FPS
    n = len(onsets)
    # Границы клипов на шкале РЕАЛЬНОГО аудио: клип i держится от начала своей
    # фразы до начала следующей (первый — от нуля, чтобы не было чёрного
    # экрана на ведущей тишине; последний — до конца аудио).
    bounds = [0.0] + [onsets[i] for i in range(1, n)] + [float(total)]
    if any(bounds[i + 1] <= bounds[i] for i in range(n)):
        return None   # непоследовательные онсеты — доверять нельзя
    cum = 0.0
    shifted = []
    for i, b in enumerate(bounds):
        shifted.append(b + cum)
        if i < len(trans_plan):
            cum += trans_plan[i][1]
    grid = [round(x * fps) / fps for x in shifted]
    durs = [grid[i + 1] - grid[i] for i in range(n)]
    if any(d < 1.0 / fps for d in durs):
        return None   # кадр короче одного кадра сетки физически не рендерится
    return durs


def load_alignment_weights(blocks):
    """Реальные веса длительности блоков из посимвольного alignment.csv
    (ElevenLabs/Lumean отдают его бесплатно вместе с каждым TTS-заказом —
    раньше просто не забирался). Раньше длительность блока считалась ЧИСТО
    по числу слов и общей скорости слов/сек — то есть каждое слово "весило"
    одинаково. На деле темп TTS живой: короткая ударная фраза читается
    быстрее длинной со сложными словами, [slowly]-блок — заметно медленнее.
    Реальный посимвольный тайминг ловит эту вариацию, а не усредняет её.

    Файлы лежат в media_plan/alignment/00.csv, 01.csv... — по одному на
    КАЖДУЮ секцию (HOOK, BLOCK 1, ..., FINAL) в порядке их первого появления
    в script.txt, разрезаны по буквальным вхождениям [pause]/[short pause]
    на сегменты 1:1 с под-блоками этой секции в том же порядке.

    Возвращает список той же длины, что blocks, — вес (сек) реальной речи
    на блок или None для блоков без данных (эпизод без сохранённого
    alignment, или новый блок, добавленный после записи — сборка тогда
    просто откатывается на word-count оценку для этих блоков, как раньше)."""
    section_segments = _alignment_section_segments(blocks)
    if section_segments is None:
        return None

    section_offsets = load_section_offsets()   # {} без Stage B/section_sync.py -> offset 0.0 для всех, как раньше
    weights = []
    seg_cursor = {}
    stale = 0
    for b in blocks:
        segs = section_segments.get(b["section"])
        if segs is None:
            weights.append(None)
            continue
        offset = section_offsets.get(b["section"], 0.0)
        k = seg_cursor.get(b["section"], 0)
        if k >= len(segs):
            # Число под-блоков в текущем script.txt разошлось с числом
            # сегментов в сохранённом alignment (текст правили после
            # записи) — честно откатываемся на word-count для остатка
            # секции, а не подставляем чужой сегмент не по месту.
            weights.append(None)
        else:
            # Число сегментов может совпасть, а ТЕКСТ — разойтись (слово-два
            # поправили в script.txt после записи озвучки, не тронув счётчик
            # [pause]) — тогда старый код молча применял чужой тайминг к
            # новому тексту. Fuzzy-сверка (difflib, без новых зависимостей)
            # блока против реально озвученного сегмента: разошлись сильнее
            # порога — честный откат на word-count вместо тихой подмены.
            seg_text = re.sub(r'\s+', ' ', "".join(c for c, s, e in segs[k])).strip().lower()
            block_text = re.sub(r'\s+', ' ', b["text"]).strip().lower()
            ratio = difflib.SequenceMatcher(None, block_text, seg_text).ratio() if (block_text and seg_text) else 0.0
            if ratio < 0.55:
                weights.append(None)
                stale += 1
            else:
                span = _real_speech_span(segs[k], offset)
                weights.append(span if span > 0.05 else None)
        seg_cursor[b["section"]] = k + 1
    if stale:
        print(f"  Alignment: {stale} блок(ов) текстом разошлись с сохранённым таймингом "
              f"(script.txt правили после записи?) — откат на word-count для них")
    return weights


def load_hook_word_timings(blocks=None, sub_starts=None, sub_baseline=None, real_weights=None):
    """D2: посимвольный alignment.csv хука (00.csv — хук всегда первая
    секция эпизода, см. load_alignment_weights) собран в СЛОВА.

    ИСТОРИЯ (три раунда одного и того же бага, каждый пойман вживую жалобой
    пользователя на рассинхрон подписей с голосом):
    1) слова раньше отдавались в СЫРОЙ абсолютной шкале 00.csv (до обрезки
       пауз) и напрямую сравнивались с уже обрезанной шкалой sub_starts.
    2) первый фикс приближал обрезку ПО ТЕГАМ [pause]/[short pause] в
       тексте — но fix_pauses.py режет ЛЮБУЮ акустическую тишину длиннее
       порога, включая нетегированные вдохи/микропаузы TTS (на реальном
       эпизоде — 41 реальная порезка на 90 тегов в тексте) — рассинхрон
       оставался внутри сегментов, где порезка пришлась не там, где текст
       её ожидал.
    3) raw_to_real_time() (см. fix_pauses.save_cuts/pause_cuts.json) даёт
       ТОЧНУЮ, не приближённую обрезку — но voed НАПРЯМУЮ давать точное
       "чистое" время слова оказалось МАЛО: sub_starts/sub_baseline сами
       считаются НЕ линейно от точного времени, а через block_durations() —
       там ОДИН глобальный коэффициент scale=total/sum(d) растягивает/жмёт
       ВСЕ блоки ролика разом, независимо от того, где реально резались
       паузы (в HOOK этого эпизода не отрезали ни секунды — а глобальный
       коэффициент всё равно сжимает и его, потому что пауз наотрезали в
       других секциях). Прямой точный маппинг слова уезжали в СОСЕДНИЙ блок.

    Правильная комбинация: слово сначала переводится в точное "чистое"
    время (raw_to_real_time, шаг 3), ЗАТЕМ его позиция ВНУТРИ своего
    досплитового сегмента (та же посегментная разбивка по тегам, что и в
    load_alignment_weights) пропорционально размещается в реальном окне
    блока [sub_starts[i], sub_starts[i]+sub_baseline[i]) — той же
    (глобально пересчитанной) шкале, что и картинки. real_weights (уже
    точные, см. _real_speech_span) — сколько "чистого" времени сегмента
    достаётся каждому под-блоку по порядку (sub-cuts режут один сегмент на
    несколько блоков), без остатка, раз сумма кусков точно равна точному
    спану сегмента. Без blocks/sub_starts/sub_baseline/real_weights —
    тихий откат на точное-но-не-выровненное-с-картинками время (лучше так,
    чем совсем без подписей).

    Нет alignment.csv -> [] (кинетика хука тихо не показывается, не
    регрессия — как и все alignment-based фичи в пайплайне)."""
    path = os.path.join(ALIGNMENT_DIR, "00.csv")
    if not os.path.exists(path):
        return []
    try:
        rows = list(csv.DictReader(open(path, encoding="utf-8")))
        chars = [(r["char"], float(r["start"]), float(r["end"])) for r in rows]
    except Exception:
        return []
    text = "".join(c for c, s, e in chars)
    cuts = load_pause_cuts()

    raw_segs, pos = [], 0
    for m in ALIGNMENT_TAG_RE.finditer(text):
        raw_segs.append(chars[pos:m.start()])
        pos = m.end()
    raw_segs.append(chars[pos:])

    remap = None
    if blocks and sub_starts is not None and sub_baseline is not None and real_weights is not None:
        hook_idxs = [i for i, b in enumerate(blocks) if b["section"].startswith("HOOK")]
        # Точные (после вычета реально вырезанных пауз) границы каждого
        # досплитового сегмента — та же raw_to_real_time, что уже даёт
        # real_weights через _real_speech_span, поэтому расход ниже сходится
        # без остатка (не приближение по сырому времени).
        seg_spans = []
        for seg in raw_segs:
            bounds = _real_speech_bounds(seg)
            seg_spans.append((raw_to_real_time(bounds[0], cuts), raw_to_real_time(bounds[1], cuts))
                              if bounds else None)

        remap = []
        seg_ptr = 0
        cursor = remaining = None

        def _advance_seg():
            nonlocal seg_ptr, cursor, remaining
            while seg_ptr < len(seg_spans) and seg_spans[seg_ptr] is None:
                seg_ptr += 1
            if seg_ptr < len(seg_spans):
                cursor = seg_spans[seg_ptr][0]
                remaining = seg_spans[seg_ptr][1] - seg_spans[seg_ptr][0]
            else:
                cursor, remaining = None, 0.0

        _advance_seg()
        for bi in hook_idxs:
            w = real_weights[bi] if (bi < len(real_weights) and real_weights[bi]) else 0.0
            if cursor is None or w <= 0:
                continue
            if remaining <= 1e-6:
                seg_ptr += 1
                _advance_seg()
                if cursor is None:
                    continue
            seg_start = cursor
            take = min(w, remaining)
            seg_end = seg_start + take
            if seg_end - seg_start > 1e-6:
                # sub_baseline[bi] — ПОЛНОЕ окно блока, включая хвостовую
                # паузу (block_durations() прибавляет b["pause_after"] к
                # "сырому" весу ДО floor/cap/глобального scale — см.
                # block_durations). Растягивать frac*sub_baseline напрямую
                # (было раньше) значит растягивать слово ВПЛОТЬ ДО КОНЦА
                # паузы — последнее слово блока держалось на экране почти
                # всю паузу целиком, реальная жалоба пользователя ("текста
                # не должно быть во время паузы"). Пауза — не постоянная
                # доля исходного сырого веса блока (real_weight + pause_after
                # -> sub_baseline через один и тот же floor/cap/scale), эта
                # ДОЛЯ инвариантна к равномерному масштабированию — берём её
                # и оставляем как подпись-свободный хвост окна.
                pause_after = blocks[bi].get("pause_after") or 0.0
                if pause_after > 0 and w > 0:
                    pause_frac = pause_after / (w + pause_after)
                    speech_dur = sub_baseline[bi] * (1.0 - pause_frac)
                else:
                    speech_dur = sub_baseline[bi]
                remap.append((seg_start, seg_end, sub_starts[bi], speech_dur))
            cursor = seg_end
            remaining -= take

    def rescale(t):
        real_t = raw_to_real_time(t, cuts)
        if not remap:
            return real_t
        for seg_start, seg_end, real_start, real_dur in remap:
            if seg_start - 1e-6 <= real_t <= seg_end + 1e-6:
                frac = (real_t - seg_start) / (seg_end - seg_start) if seg_end > seg_start else 0.0
                return real_start + frac * real_dur
        return real_t   # вне всех сегментов (хвостовой мусор) — не подменяем произвольно

    # Тот же спан-фильтр, что у _clean_timed_chars (см. ALIGNMENT_TAG_SPAN_RE):
    # здесь стоял ТРЕТИЙ список тех же имён, и незнакомый тег стал бы здесь не
    # просто мусором, а отдельным СЛОВОМ хук-подписи с собственным временем.
    excluded = set()
    for m in ALIGNMENT_TAG_SPAN_RE.finditer(text):
        excluded.update(range(m.start(), m.end()))
    # Вырезанный тег ТОЖЕ обязан рвать слово, не только пробел — в сыром
    # тексте тег часто стоит БЕЗ пробела ("...убеждают.[short pause]Так
    # говорят" — точка сразу перед тегом, слово сразу после), простое
    # исключение символов тега без разрыва склеивало соседние слова в одно
    # ("килограммов.Так") — поймано вживую на реальном 00.csv эпизода.
    words, cur = [], []
    for j, (c, s, e) in enumerate(chars):
        if j in excluded or c.isspace() or c in "[]":
            if cur:
                words.append(("".join(ch for ch, _, _ in cur), cur[0][1], cur[-1][2]))
                cur = []
        else:
            cur.append((c, s, e))
    if cur:
        words.append(("".join(ch for ch, _, _ in cur), cur[0][1], cur[-1][2]))
    words = [(w, rescale(s), rescale(e)) for w, s, e in words]
    return [w for w in words if w[0]]


HOOK_CAPTION_MIN_DUR = 0.40   # 2.6: было 0.15 — реальная жалоба "слишком быстро исчезают"; короткие
# слова (особенно после вырезанной паузы) читались меньше половины секунды, почти нечитаемо на
# практике. 0.40с — всё ещё быстрый кинетический темп, но экранно различимо; растяжка по-прежнему
# не вылезает за начало следующего слова (см. hook_captions_for_block), так что подряд идущие
# короткие слова просто НЕМНОГО перекрывают друг друга по расписанию блока, а не показывают оба разом.


def hook_visual_starts(blocks, durs):
    """Реальные старты клипов НА ШКАЛЕ ФИНАЛЬНОГО СМОНТИРОВАННОГО видео —
    не наивный cumsum(durs) (P0-3 доп. находка, независимый форензик-разбор
    архитектуры: xfade-переход СЖИМАЕТ итоговый таймлайн на свою
    длительность, offset = cum - this_dur, см. xfade_chain() — cumsum без
    вычета нахлёста завышает старт каждого следующего клипа на сумму уже
    прошедших нахлёстов, накопительно).

    Для ХУКА (единственное место, где сегодня есть вшитые в кадр подписи,
    см. rescale_hook_words_to_visual_time) длительность перехода ПОЛНОСТЬЮ
    детерминирована на этом этапе, ещё до того как выбраны финальные
    файлы клипов: xfade_chain() всегда даёт HOOK-переходам XFADE_DUR_HARD,
    кроме перехода СРАЗУ ПОСЛЕ блока со stat-плашкой — там SNAP_CUT_DUR
    (то же условие и тот же порядок проверки, что в xfade_chain(); ветка
    "обычный переход" — единственная, зависящая от хэша путей ЕЩЁ НЕ
    выбранных файлов — HOOK её физически никогда не достигает, см. код
    xfade_chain()). Значения вне HOOK этой функцией не гарантированы
    точными (там нет burned-caption потребителя — учитывать не нужно)."""
    sections = [b["section"] for b in blocks]
    plan = effective_transition_plan(plan_transitions(sections, blocks), sections)
    starts, cum = [], (durs[0] if durs else 0.0)
    for i, d in enumerate(durs):
        if i == 0:
            starts.append(0.0)
            continue
        # Тот же самый план, по которому реально режет xfade_chain() — не
        # копия его условий (раньше условия были продублированы здесь
        # вручную и могли разойтись при любой правке одной из двух копий).
        this_dur = plan[i - 1][1] if i - 1 < len(plan) else XFADE_DUR_HARD
        offset = max(0.0, cum - this_dur)
        starts.append(offset)
        cum = cum + d - this_dur
    return starts


def rescale_hook_words_to_visual_time(hook_words, blocks, sub_starts, sub_baseline, visual_starts, durs):
    """P0-3 форензик-аудита (реальный, подтверждённый эмпирически баг):
    load_hook_word_timings() кладёт слова на АУДИО-шкалу (sub_starts/
    sub_baseline — та же, что использует write_subtitles/write_chapters,
    честно синхронная с голосом). Но РЕАЛЬНО рендерящийся визуальный кадр
    хука после apply_section_boundary_shift/apply_within_cut_shift/
    apply_human_jitter/snap_hook_cuts_to_energy — все они сдвигают ИМЕННО
    durs, не sub_baseline, — может отличаться по длительности и старту от
    sub_baseline/sub_starts на десятки-сотни мс. Изолированный прогон
    apply_within_cut_shift() на 4 блоках хука дал накопленную ошибку
    локального тайминга подписи +0.098/+0.094/-0.093с — маленькую на
    глаз, но реальную и систематическую, не шум.

    Кусочно-линейный пересчёт: для каждого слова находим HOOK-блок, чьё
    АУДИО-окно [sub_starts[i], sub_starts[i]+sub_baseline[i]) его
    содержит, и переносим его долю позиции внутри этого окна в ту же
    долю ВИЗУАЛЬНОГО окна [visual_starts[i], visual_starts[i]+durs[i])
    того же блока — слово остаётся привязано к тому же фрагменту речи,
    просто рисуется на шкале реально показанного кадра, а не идеализиро-
    ванной аудио-шкале. Слово вне всех хук-окон (не должно случаться) —
    возвращается как есть, не подменяем произвольно."""
    hook_idxs = [i for i, b in enumerate(blocks) if b["section"].startswith("HOOK")]
    windows = [(sub_starts[i], sub_baseline[i], visual_starts[i], durs[i]) for i in hook_idxs]
    if not windows or not hook_words:
        return hook_words

    def _map(t):
        for a_start, a_dur, v_start, v_dur in windows:
            if a_dur > 1e-9 and a_start - 1e-6 <= t <= a_start + a_dur + 1e-6:
                frac = (t - a_start) / a_dur
                return v_start + frac * v_dur
        return t

    return [(w, _map(s), _map(e)) for w, s, e in hook_words]


def hook_captions_for_block(hook_words, block_start, block_dur):
    """Слова из load_hook_word_timings(), чьё время пересекается с окном
    [block_start, block_start+block_dur) конкретного HOOK-клипа — переведены
    в ЛОКАЛЬНОЕ время клипа (0 = начало клипа) и обрезаны по его границам,
    чтобы drawtext enable=between() не ссылался на моменты вне клипа.

    Минимальная длительность показа (HOOK_CAPTION_MIN_DUR) — короткие слова
    (особенно сразу после вырезанного тега паузы, см. load_hook_word_timings)
    иногда получают из alignment почти нулевую длительность и мелькают
    незаметно; растягиваем ВПЕРЁД, но не дальше начала следующего слова
    (иначе два слова читались бы на экране одновременно)."""
    caps = []
    for k, (word, s, e) in enumerate(hook_words):
        if e <= block_start or s >= block_start + block_dur:
            continue
        local_s = max(0.0, s - block_start)
        local_e = min(block_dur, e - block_start)
        if local_e - local_s < HOOK_CAPTION_MIN_DUR:
            next_start = (hook_words[k + 1][1] - block_start) if k + 1 < len(hook_words) else block_dur
            local_e = min(block_dur, next_start, local_s + HOOK_CAPTION_MIN_DUR)
        if local_e > local_s:
            caps.append((word, local_s, local_e))
    return caps


def hook_floor_for(blocks, i):
    """Пол длительности для блока i — единый HOOK_MIN_CLIP на весь хук (см.
    ревизию 29 августа у самой константы: раньше первые резы хука получали
    отдельный, более низкий пол — убран по требованию пользователя, ни один
    клип хука не должен быть короче HOOK_MIN_CLIP независимо от позиции).
    Единая функция для всех мест, что клэмпят длительность по этому полу
    (block_durations/apply_section_boundary_shift/apply_human_jitter)."""
    if not blocks[i]["section"].startswith("HOOK"):
        return MIN_CLIP
    return HOOK_MIN_CLIP


def block_durations(blocks, total, energy_mults=None, real_weights=None):
    tw = sum(b["words"] for b in blocks)
    tp = sum(b["pause_after"] for b in blocks)
    wps = tw / max(total - tp, 1)
    raw = []
    for i, b in enumerate(blocks):
        rw = real_weights[i] if real_weights else None
        base = rw if rw is not None else b["words"] / wps
        raw.append(base + b["pause_after"])
    if energy_mults:
        raw = [r * m for r, m in zip(raw, energy_mults)]
    d = []
    for i, (b, r) in enumerate(zip(blocks, raw)):
        # В хуке кадры короче и чаще — первые секунды решают, останется ли зритель.
        # Раньше пол был ОДИН на весь ролик (MIN_CLIP) — реальная короткая
        # фраза в хуке всё равно раздувалась до общего пола, и хук не
        # отличался по темпу от тела ролика. Свой, более низкий пол (ещё
        # ниже — для самых первых резов, см. hook_floor_for) — хук реально
        # может резать чаще, а не только "теоретически может".
        is_hook = b["section"].startswith("HOOK")
        cap = HOOK_MAX_CLIP if is_hook else MAX_CLIP
        floor = hook_floor_for(blocks, i)
        d.append(max(floor, min(cap, r)))
    scale = total / sum(d)
    return [x * scale for x in d]


PEXELS_BROKEN = False       # взводится только на реальном отказе API, не на пустой выдаче
# Бюджет часовой квоты Pexels (200 запросов/час на ключ). Остаток приходит
# заголовком X-Ratelimit-Remaining каждого ответа поиска; запас — сколько
# запросов ещё нужно СОБСТВЕННЫМ запросам оставшихся слотов (фото и видео),
# его выставляет main() перед каждым слотом. Дополнительные запросы пула
# (запросы фразы от планировщика, запросы секции) уходят в Pexels, только
# пока остаток больше запаса: иначе квота кончится на середине эпизода,
# пойдут 429 подряд, и PEXELS_BROKEN отключит сток до конца прогона.
PEXELS_QUOTA_LEFT = None
PEXELS_QUOTA_RESERVE = 0
PEXELS_LOW_PRIORITY_SKIPPED = 0

# --- УЧЁТ ВКЛАДА КАЖДОГО ИСТОЧНИКА ЗА ПРОГОН ----------------------------------
# Зачем. Источник кандидатов может молча давать НОЛЬ, и узнать об этом было
# неоткуда: fail-open у каждого из них возвращает пустой список на любую
# ошибку, а пул собирается из остальных как ни в чём не бывало. Ровно так
# Openverse отвечал 401 (поймано вживую 13.09), Pexels до правки 11.09 гасил
# музеи вместе с собой, а до 07.09 Openverse/Pixabay/Unsplash не вызывались
# вовсе — и во всех трёх случаях готовый ролик выглядел штатно собранным.
# Теперь по каждому источнику считается: сколько кандидатов он ПРЕДЛОЖИЛ в
# пул, сколько из них РЕАЛЬНО рассмотрено (скачано и прогнано через гейты),
# сколько ПРОШЛО гейты, сколько ВЫИГРАЛО слот, и сколько раз его поиск
# УПАЛ. Сводка печатается в конце прогона и пишется в
# media_plan/source_contribution.json — «этот ролик собран из музеев на 40%,
# Openverse дал ноль из-за 12 ошибок» становится проверяемым фактом.
SOURCE_STATS = {}
_SOURCE_STAT_FIELDS = ("offered", "considered", "gate_passed", "won", "search_errors",
                       "download_errors")
_SOURCE_ERROR_PRINTED = set()


#: Префиксы id -> имя источника в отчёте. Список ДОЛЖЕН покрывать каждый
#: префикс, который реально выдаёт хоть один сборщик кандидатов: неизвестный
#: префикс молча падает в ветку «числовой id» и записывается как Pexels.
#: Реальная цена, найденная сквозным прогоном 15.09: `euro:` в списке не
#: было, и победа кандидата Europeana попала в отчёт как победа Pexels — на
#: машине, где ключа Pexels вообще нет. То есть `source_contribution.json`
#: называл источником кадра тот, который в прогоне не участвовал, а вклад
#: реально работавшего корпуса был невидим. Тот же класс, что этот файл уже
#: закрывал счётчиками SOURCE_STATS: «источник мог молча давать НОЛЬ, и
#: узнать об этом было неоткуда» — здесь наоборот, источник молча давал
#: чужое имя.
CANDIDATE_ID_PREFIXES = ("met", "euro", "chicago", "cleveland", "openverse",
                         "pixabay", "unsplash")


def candidate_source(p):
    """Источник кандидата по префиксу его id; числовой id без префикса —
    Pexels (единственный источник, отдающий голые числовые id)."""
    pid = str((p or {}).get("id", "") if isinstance(p, dict) else (p or ""))
    for prefix in CANDIDATE_ID_PREFIXES:
        if pid.startswith(prefix + ":"):
            return prefix
    return "pexels"


def candidate_channel(p):
    """КТО принёс кандидата в пул — канал поиска, а не пространство id.

    Реальный пробел, найденный разбором собственной правки: все счётчики
    `SOURCE_STATS` выводятся из ПРЕФИКСА id (`candidate_source`), а у
    визуальной полки id обязан оставаться тем же `met:<objectID>`, что у
    музейного пути, — общий `used_ids` должен видеть один предмет как один
    (это отдельный, намеренный инвариант, и трогать его нельзя). Следствие:
    кандидат, найденный ПОЛКОЙ по описанию кадра, и кандидат, найденный
    музейным API по словам, попадали в отчёт под одним именем `met`, то
    есть на вопрос «дала ли полка этому эпизоду хоть один кадр» —
    единственный вопрос, ради которого полка и строилась, — по артефактам
    готового ролика ответить было нельзя.

    Это ровно тот же класс, что уже дважды чинён в этом файле: источник,
    который молча даёт ноль (Openverse), и источник, который молча даёт
    ЧУЖОЕ ИМЯ (победа Europeana в отчёте как победа Pexels).

    Ключ один на канал (`shelf`), а не `shelf:<корпус>`: сумма `won` по
    источникам обязана совпадать с числом выигранных слотов, а из какого
    корпуса пришёл конкретный кадр, и так записано рядом с ним —
    `_shelf_meta.corpus` уезжает в шотлист и в sidecar. Имя совпадает с
    тем, под которым уже считаются ошибки поиска полки
    (`_note_source_search_error("shelf", ...)`), иначе строка ошибок жила
    бы отдельно от строки вкладa и помечалась бы «молчащим источником»
    при работающей полке."""
    if isinstance(p, dict) and p.get("_shelf_meta"):
        return "shelf"
    return candidate_source(p)


def candidate_path_token(p):
    """ID кандидата в виде, пригодном для ИМЕНИ ФАЙЛА.

    Реальный дефект, найденный сквозным прогоном 15.09, а не чтением кода:
    имя файла-пробника собиралось из id кандидата буквально
    (`cf + f".trial_{p.get('id')}.jpg"`), а id записи Europeana — это
    `euro:/9200122/BibliographicResource_1000056125434`, то есть со
    СЛЭШАМИ. Путь уезжал в несуществующий каталог, запись падала
    `FileNotFoundError`, и КАЖДЫЙ кандидат Europeana терялся ещё ДО гейтов.

    Цена была не «20 строк в отчёте»: relevance-гейт, контрастивное вето,
    домен-гвард, дедуп по aHash и всё ранжирование не отрабатывали по
    кандидатам Europeana ВООБЩЕ, победитель брался по позиции в списке.
    То есть слой был подключён, кандидаты доезжали до пула — и пул их
    молча выбрасывал. Ровно тот класс, против которого заведены счётчики
    `SOURCE_STATS`: без них это выглядело бы как «Europeana просто не
    выигрывает».

    Точность формулировки важна: у прежних источников имя файла всё-таки
    МЕНЯЕТСЯ (`met:32684` -> `met_32684`, двоеточие не разделитель пути, но
    и не буква) — неизменным остаётся ПОВЕДЕНИЕ, потому что это временные
    файлы-пробники, живущие рядом с кэшем одного слота и не входящие ни в
    один ключ кэша. Побайтово прежним результат остаётся только у Pexels,
    чей id и так состоит из цифр.

    Побочно закрыт латентный дефект Windows: двоеточие в имени файла там
    запрещено, то есть на машине владельца пробники музейных кандидатов
    падали бы ровно так же, как падали кандидаты Europeana здесь.
    """
    token = str((p or {}).get("id", "") if isinstance(p, dict) else (p or ""))
    return re.sub(r"[^A-Za-z0-9._-]", "_", token) or "noid"


def _source_bump(source, field, n=1):
    st = SOURCE_STATS.setdefault(source, {f: 0 for f in _SOURCE_STAT_FIELDS})
    st[field] += n


def _note_source_search_error(source, exc, label=""):
    """Ошибка поиска у источника — считается и печатается один раз за прогон
    на источник (не на каждый слот: сотни одинаковых строк скрыли бы лог)."""
    _source_bump(source, "search_errors")
    if source not in _SOURCE_ERROR_PRINTED:
        _SOURCE_ERROR_PRINTED.add(source)
        code = getattr(exc, "code", None)
        print(f"  {source}: поиск не отвечает ({'HTTP %s' % code if code else type(exc).__name__}"
              f"{(': ' + label) if label else ''}) — источник даёт ноль, пул собирается из остальных; "
              f"итог по источникам — в конце прогона и в media_plan/source_contribution.json")


def reset_source_stats():
    """Один прогон — один счёт: обнуляет учёт источников и счётчики музейного
    модуля. Вызывается в начале main(); тестам и повторным вызовам в одном
    процессе — тоже отсюда."""
    global PEXELS_QUOTA_LEFT, PEXELS_LOW_PRIORITY_SKIPPED
    SOURCE_STATS.clear()
    _SOURCE_ERROR_PRINTED.clear()
    PEXELS_QUOTA_LEFT, PEXELS_LOW_PRIORITY_SKIPPED = None, 0
    for k in ("requests", "cache_hits", "cache_misses"):
        OPENVERSE_STATS[k] = 0
    try:
        import museum_sources as _mus
        _mus.reset_fetch_stats()
    except Exception:
        pass


def write_source_contribution(video_dir):
    """Сводка вклада источников — печать и media_plan/source_contribution.json.
    Пишется ВСЕГДА, даже если ни один источник не дал ничего: «нечего
    сообщить» — тоже факт, а не отсутствие файла."""
    report = {"schema_version": 1, "sources": {}, "museum_fetch": None,
              "openverse_fetch": dict(OPENVERSE_STATS)}
    for src in sorted(SOURCE_STATS):
        report["sources"][src] = dict(SOURCE_STATS[src])
    try:
        import museum_sources as _mus
        report["museum_fetch"] = dict(_mus.FETCH_STATS)
    except Exception:
        pass
    total_won = sum(v["won"] for v in report["sources"].values()) or 0
    report["total_won"] = total_won
    silent = [src for src, v in report["sources"].items()
              if (v["offered"] == 0 and v["search_errors"] > 0)
              or (v["offered"] > 0 and v["considered"] == 0 and v.get("download_errors", 0) > 0)]
    report["silent_sources"] = silent
    if PEXELS_LOW_PRIORITY_SKIPPED:
        # Пишется только когда бюджет что-то срезал: отчёт без срезов тот же,
        # что раньше, байт-в-байт.
        report["pexels_quota"] = {"left": PEXELS_QUOTA_LEFT,
                                  "low_priority_skipped": PEXELS_LOW_PRIORITY_SKIPPED}
    path = os.path.join(video_dir, "media_plan", "source_contribution.json")
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path + ".tmp", "w", encoding="utf-8") as f:
            json.dump(report, f, ensure_ascii=False, indent=2)
        os.replace(path + ".tmp", path)
    except Exception:
        pass
    if report["sources"]:
        print("  Вклад источников (предложено / рассмотрено / прошло гейты / ВЫИГРАЛО / ошибок поиска / ошибок скачки):")
        for src, v in report["sources"].items():
            share = (100.0 * v["won"] / total_won) if total_won else 0.0
            print(f"    {src:10} {v['offered']:5} / {v['considered']:4} / {v['gate_passed']:4} / "
                  f"{v['won']:4} ({share:4.0f}%) / {v['search_errors']} / {v.get('download_errors', 0)}")
        if silent:
            print(f"    ВНИМАНИЕ: источники, давшие ноль из-за ошибок поиска: {', '.join(silent)}")
    if PEXELS_LOW_PRIORITY_SKIPPED:
        print(f"  Квота Pexels: {PEXELS_LOW_PRIORITY_SKIPPED} дополнительных запросов не отправлено "
              f"(остаток {PEXELS_QUOTA_LEFT}, запас держался для собственных запросов слотов)")
    return path
PEXELS_FAIL_STREAK = 0      # подряд идущих сбоев любого рода (см. _note_pexels_failure)
PEXELS_FAIL_STREAK_LIMIT = 6


def _reset_pexels_streak():
    global PEXELS_FAIL_STREAK
    PEXELS_FAIL_STREAK = 0


def _note_pexels_failure(exc, label):
    """Аудит 04.09 (воспроизведено): один try/except на всё тело pexels_photo/
    pexels_video взводил PEXELS_BROKEN на ЛЮБОЙ ошибке — сбой скачки одной
    картинки с CDN, os.replace на Windows, исключение в скоринге — после
    чего сток отключался до конца эпизода, сотни слотов уходили в повтор
    локальных фото по кругу или в missing (и final.mp4 не собирался при
    строгом гейте). Теперь флаг — только на 401/403 (ключ/доступ) или после
    PEXELS_FAIL_STREAK_LIMIT сбоев ПОДРЯД (API реально недоступен);
    одиночная ошибка стоит одному слоту, не эпизоду."""
    global PEXELS_BROKEN, PEXELS_FAIL_STREAK
    PEXELS_FAIL_STREAK += 1
    code = getattr(exc, "code", None)
    if code in (401, 403):
        PEXELS_BROKEN = True
        print(f"  {label}: HTTP {code} — ключ/доступ Pexels отвергнут, сток отключён на этот прогон")
    elif PEXELS_FAIL_STREAK >= PEXELS_FAIL_STREAK_LIMIT:
        PEXELS_BROKEN = True
        print(f"  {label}: {exc} — {PEXELS_FAIL_STREAK} сбоев подряд, считаю API недоступным")
    else:
        print(f"  {label}: {exc} (слот без стока, сток НЕ отключаю)")

# Реальный, найденный вживую баг (27 августа, videos/_test20s, слоты 0 и 3):
# is_relevant_candidate() — гейт, не жёсткий фильтр в _score_and_pick() (см.
# докстринг pexels_photo() про лексикографический кортеж) — если ВЕСЬ
# просмотренный пул кандидатов (до PHOTO_DEDUP_MAX_TRIES штук) провалил
# relevance-гейт, побеждает всё равно "лучший из плохих" (эстетика/luma
# решают дальше по кортежу), без единой пометки об этом. На готовом рендере
# это дало слот с запросом "heavy iron dumbbell weight plate", вернувший
# фото рыцаря с мечом (relevance=0.151, порог 0.19) — пользователь поймал
# на глаз ("фото мальчика вместо гантели"), не пайплайн. Тот же принцип
# честной пометки, что visual_qc.py уже применяет к "ниже порога" кандидатам
# на Шаге 5.5 (media_plan/visual_qc_report.json) — здесь для более раннего
# этапа (сам выбор кандидата, не пост-хок QC уже выбранного). Не меняет
# поведение отбора (слот по-прежнему не остаётся пустым, см. философию
# ЧАСТИ 13) — только делает промах ВИДИМЫМ вместо молчаливого приёма.
RELEVANCE_GATE_MISSES = []   # [{"index", "query", "relevance", "threshold", "kind"}, ...]
DIRECTOR_RELEVANCE_MISSES = []   # [{"index", "text", "photo", "relevance", "threshold"}, ...]
                                  # — см. её докстринг в main() у DIRECTOR_RELEVANCE_FLOOR

# РЕАЛЬНЫЙ, найденный вживую пробел в самом RELEVANCE_GATE_MISSES выше
# (deep-audit, videos/_test20s, слот 7 "warrior on horseback with sword",
# 28 августа) — комментарий у RELEVANCE_GATE_MISSES утверждает "ВЕСЬ
# просмотренный пул провалил гейт", но код проверяет только ПОБЕДИТЕЛЯ
# (`if winner is not None and not winner["is_relevant"]`). Лексикографический
# кортеж _score_and_pick() ставит is_dup_free ПЕРЕД is_relevant — то есть
# кандидат, который релевантен и резкий, но оказался near-duplicate уже
# использованного кадра, проигрывает нерелевантному, но уникальному кандидату,
# и тогда "победитель нерелевантен" НЕ означает "пул нечего предложить" —
# кандидат, реально подходящий по смыслу, в пуле БЫЛ, просто отсеян дедупом
# (у видео — то же самое: dup_fallback конкретно для этого и заведён, см.
# pexels_video()). STOCK_EXHAUSTED_MISSES проверяет РОВНО ту ось, которую
# RELEVANCE_GATE_MISSES по факту не проверяет — "нашёлся ли в ПОЛНОСТЬЮ
# просмотренном пуле хоть один кандидат, прошедший relevance И резкость",
# НЕЗАВИСИМО от дедупа. Это строго более редкий и более сильный сигнал:
# не "победитель не идеален", а "стоку буквально нечего предложить на эту
# фразу" — практический вывод из него другой (не "проверь глазами", а
# "сгенерируй AI-картинку на Шаге 5", см. media_plan/stock_exhausted_report.json
# и render_episode.py). Не меняет отбор победителя (тот же принцип "слот не
# должен остаться пустым", ЧАСТЬ 13) — только делает этот более редкий и
# более серьёзный случай видимым отдельно от обычного relevance-промаха.
STOCK_EXHAUSTED_MISSES = []   # [{"index", "kind", "query", "n_candidates_examined",
                              #   "n_candidates_available"}, ...]

# Слоты, где VLM-арбитр ЯВНО ответил "ни один из кандидатов не подходит"
# (shot_director.NO_CANDIDATE_FITS). Сильнее любого численного промаха выше:
# RELEVANCE_GATE_MISSES говорит "порог не взят", а это — "смотрел человекоподобный
# судья и сказал нет". Реальный случай, ради которого список заведён (07.09):
# в опубликованном эпизоде такой вердикт существовал, лежал в кэше
# (media_plan/shot_director_cache/, choice: 0) и был выброшен по дороге, потому
# что превращался в тот же None, что "арбитра не было" — кадр с младенцем и
# детской бутылочкой уехал в хук на фразу про вес пакета молока.
ARBITER_REJECTED_ALL = []   # [{"index", "kind", "query", "text", "n_candidates", "is_opening"}, ...]

# --- Лестница фолбэков: уровень, который НЕ МОЖЕТ БЫТЬ НЕВЕРНЫМ ---
# Подбор устроен как гейт, а не фильтр: провалил весь пул — побеждает "лучший
# из плохих", слот всё равно заполняется (философия "слот не должен остаться
# пустым", ЧАСТЬ 13). На опубликованном эпизоде это дало кадры, про которые
# система УЖЕ ЗНАЛА, что они плохие: слот #13 отклонён relevance-гейтом, для
# слота #5 арбитр явно ответил "ни один не подходит" — оба ушли зрителю.
# Пока нет варианта, который не может быть "не про то", ужесточение гейтов
# меняет только ИМЯ показанного брака. Карточка (scripts/fallback_card.py)
# собирается из СОБСТВЕННЫХ слов диктора и изображения не содержит вовсе.
FALLBACK_CARD_ENABLED = feature_flags.enabled("FALLBACK_CARD")
# Бюджет плотности — В КОДЕ, а не в намерении. Подряд идущие карточки
# читаются как сбой вёрстки, а не как приём; много карточек — как капитуляция
# подбора. Обе цифры — потолок, а не цель: обычный эпизод не должен доходить
# и до половины.
FALLBACK_CARD_MAX_SHARE = 0.08   # не больше 8% слотов эпизода
# Версия правила выдачи бюджета (сами константы не изменились, изменилось
# КОМУ он достаётся) — для _selection_stack_signature(): без неё на прогретом
# temp_smart/ карточки остались бы на старых местах.
FALLBACK_CARD_BUDGET_VERSION = 3
# Причина карточки на слоте, у которого медиа НЕТ ВООБЩЕ (main(), ветка после
# local_photo(allow_cycle=True)). Такая карточка ставится вне бюджета — ей
# нечего заменять, кроме выпавшего блока. ДО 14.09 она всё равно писалась в
# FALLBACK_CARD_SLOTS и СЪЕДАЛА потолок карточек за БРАК: пять пустых слотов
# в начале эпизода — и на брак дальше бюджета почти не оставалось. Две разные
# гарантии («слот не пуст» и «брак закрыт в пределах 8%») делили один
# счётчик. Найдено вопросом внешнего разбора «что при кластере пустых слотов».
FALLBACK_NO_MEDIA_REASON = "no_media_at_all"
FALLBACK_CARD_MIN_GAP = 3        # минимум столько слотов между двумя карточками
FALLBACK_CARD_SLOTS = []   # [{"index", "reason", "text", "card_text"}, ...]
# Слоты, где заведомо плохое ВИДЕО заменено фотографией (см. ступень
# «видео -> музейное фото» в main()). Измеренный повод (эпизод 02, 10.09):
# среди видео-слотов брак 63% (41 из 65), среди фото — 23% (35 из 154).
# Видео-корпус Pexels на исторические темы объективно тоньше фото-корпуса,
# а музейные API видео не отдают вообще.
ABSORBED_SLOTS = []   # [{"index", "reason", "text", "carried_sec"}, ...]
# Слоты, которые НЕ получили своего кадра и поглощены соседним ПРОВЕРЕННЫМ
# кадром (он держится на экране дольше и накрывает эту фразу). Заменяет
# исход «лучший из плохих», который по золотому набору эпизода 01 дал 8
# браков из 17: гейты забраковали кадр САМИ, а показать было нечего, и
# правило «слот не может остаться пустым» выводило брак на экран.
VIDEO_RESCUED_BY_PHOTO = []   # [{"index", "reason", "query"}, ...]


_WIKIMEDIA_RE = re.compile(r"^https?://upload\.wikimedia\.org/wikipedia/commons/"
                            r"(?:thumb/)?[0-9a-f]/[0-9a-f]{2}/([^/?#]+)", re.I)


def wikimedia_thumb_url(url, width=640):
    """Ссылка на Wikimedia-файл ЗАДАННОЙ ШИРИНЫ через официальный
    Special:FilePath — не оригинал и не превью через чужой API.

    Две измеренные причины, обе пойманы на живых прогонах:

    1. Поле `thumbnail` у Openverse — это URL ЧЕРЕЗ ЕГО API
       (api.openverse.org/v1/images/<id>/thumb/), у которого лимит 20
       запросов в минуту на всё; в прогоне 14.09 он отвечал HTTP 424, и
       кандидаты Openverse молча выпадали из выборки на скачке превью.
    2. Оригиналы upload.wikimedia.org отдают **HTTP 429** с текстом
       «please ... instead use thumbnail images in sizes listed on
       w.wiki/GHai» — то есть скачивание оригиналов там прямо не
       приветствуется, и на прогоне это стоило 49 сорванных скачек и
       ПУСТОГО слота «medieval castle moat water».

    Special:FilePath?width= — документированный способ получить любую
    ширину для любого формата (jpg/png/tif/svg), без знания хэш-путей и
    без отдельных правил на каждый формат. Проверено вживую: оригинал 429,
    та же картинка через FilePath шириной 640 — 190 КБ, 200 OK.

    None — ссылка не на Wikimedia, там остаётся URL источника."""
    m = _WIKIMEDIA_RE.match(url or "")
    if not m:
        return None
    name = m.group(1)
    return (f"https://commons.wikimedia.org/wiki/Special:FilePath/{name}"
            f"?width={int(width)}")


def candidate_probe_url(p):
    """URL УМЕНЬШЕННОЙ версии кандидата для оценки (гейты, ранжирование,
    дедуп) — полноразмерная качается только у победителя.

    Почему это не потеря точности: CLIP ViT-B/32 смотрит на 224 px, SigLIP2
    Директора — на 384, aHash дедупа — на 8x8, эстетический head — на CLIP-
    признаках. Единственное, что нельзя мерить на превью, — резкость
    (уменьшение «лечит» размытие); она проверяется на полноразмерном файле
    победителя (см. pexels_photo, повторный выбор при провале).

    Поля по источникам: Pexels src.medium (350 px по высоте), музеи и
    Openverse/Pixabay/Unsplash кладут превью в src.medium сами (см. их
    сборку кандидата). Нет превью — полный URL, как раньше."""
    src = (p or {}).get("src") or {}
    return src.get("medium") or src.get("small") or src.get("large2x") or src.get("large")


# Насколько НИЖЕ своего пола должен быть скор Директора, чтобы слот считался
# заведомо негодным и получил карточку. См. разбор у самого использования в
# known_bad_reason(): «ниже пола» само по себе слишком слабый сигнал —
# абстрактная фраза роняет скор любой картинке.
DIRECTOR_CARD_DECISIVE_FRACTION = 0.5


# Утвердительный вердикт судьи: кадр посмотрели по описанию и признали
# годным. В отчёты промахов не проецируется — это не промах, а решение.
JUDGE_APPROVED_VERDICT = "judge_ok"


def effective_verdicts(verdicts):
    """Вердикты попытки после правила старшинства — ОДНОГО на весь отбор.

    Судья смотрит на сам кадр вместе с описанием кадра; пороги эмбеддинга
    (relevance, stock), Директор и арбитр — слабее. Раньше их вердикты
    писались победителю независимо от судьи, и known_bad_reason() честно
    делала из них «брак»: кадр, одобренный судьёй, уходил на вторую
    страницу, на спасение фотографией и в поглощение (найдено по коду
    25.09: record_verdict("stock") у фото пишется даже по пулу, когда сам
    победитель прошёл всё). Одобрение судьи снимает слабые вердикты; отказ
    судьи и так сильнейший. Без судьи — вердикты как есть."""
    kinds = {k for k, _rec in verdicts}
    if JUDGE_APPROVED_VERDICT in kinds and "judge" not in kinds:
        return [(k, rec) for k, rec in verdicts if k == JUDGE_APPROVED_VERDICT]
    return [(k, rec) for k, rec in verdicts if k != JUDGE_APPROVED_VERDICT]


def known_bad_reason(verdicts):
    """Почему система САМА считает кадр негодным (или None) — по вердиктам
    ТОЙ ПОПЫТКИ, которая этот кадр добыла.

    Раньше функция принимала номер слота и смотрела во все отчёты разом —
    то есть в вердикты ЛЮБОЙ попытки этого слота. Реальный случай
    (videos/94_dagger_test, слот 4): видео-попытка вернула «ничего» с
    отказом второй проверки, фото-попытка нашла годный кадр 38104230 — и
    слот поглотили по вердикту видео, которого на экране не было вовсе.
    Вердикт принадлежит кадру, а не номеру слота.

    Новых проверок не запускает и ничего не пересчитывает. Порядок причин —
    по силе сигнала: отказ арбитра сильнее численного промаха порога.
    """
    verdicts = effective_verdicts(verdicts)
    kinds = {k for k, _rec in verdicts}
    if "judge" in kinds:
        # Судья кадров посмотрел на кандидатов сеткой ВМЕСТЕ с описанием
        # кадра и оценил лучшего как брак — сильнейший сигнал в списке.
        return "shot_judge_rejected"
    if "smart_veto" in kinds:
        # Первым: единственная причина здесь — модель ПОСМОТРЕЛА на
        # реальный итоговый кадр (не на шорт-лист превью, как арбитр) и
        # сказала "не то". Прямее сигнала в этом списке нет.
        return "smart_relevance_veto"
    if "arbiter" in kinds:
        return "arbiter_rejected_all"
    if "stock" in kinds:
        return "stock_exhausted"
    if "relevance" in kinds:
        return "below_relevance_threshold"
    # Самый слабый из сигналов и поэтому последний: Директор оценивает
    # кандидата по РЕАЛЬНОМУ тексту блока, а абстрактная фраза («Я его
    # назову. Но если сказать прямо сейчас...») даёт низкий скор ЛЮБОЙ
    # картинке — там виноват не кадр.
    #
    # Отсюда требование решительности, а не просто «ниже пола». Замер на
    # videos/_test60s (9 слотов, 4 промаха Директора, вердикты глазами):
    #   слот 4  0.20x пола  брак (современный музей вместо поля боя)
    #   слот 7  0.40x пола  терпимо
    #   слот 6  0.94x пола  ГОДНО
    #   слот 1  0.95x пола  терпимо
    # Бюджет карточек на таком эпизоде равен ЕДИНИЦЕ (8% от 9 слотов), и
    # правило «любой промах» потратило бы её на слот 1 — тот, что у самого
    # пола и на экране приемлем, — оставив слот 4 в ролике. Порядок выдачи
    # решает вместо качества, ровно как уже ловили у самого бюджета.
    #
    # ЧЕСТНО про 0.5: это консервативное круглое число («вдвое ниже пола —
    # уже другой порядок, а не пограничный случай»), а НЕ измеренный
    # оптимум: четыре точки и мои глаза — не калибровка. Оно может только
    # УМЕНЬШИТЬ число карточек против наивного правила, и на замеренном
    # эпизоде отделяет единственный брак от единственного годного.
    for k, m in verdicts:
        if k != "director":
            continue
        floor = float(m.get("threshold") or 0.0)
        rel = float(m.get("relevance") or 0.0)
        if floor > 0 and rel < floor * DIRECTOR_CARD_DECISIVE_FRACTION:
            return "director_relevance_decisive"
    return None


# Вердикт попытки -> отчёт, в который он проецируется. Имена отчётов, а не
# сами списки: тест или повторный main() может подменить список на модуле, и
# проекция обязана попасть в тот, что стоит на модуле СЕЙЧАС.
VERDICT_REPORT_LISTS = {
    "judge": "SHOT_JUDGE_MISSES",
    "smart_veto": "SMART_VETO_MISSES",
    "arbiter": "ARBITER_REJECTED_ALL",
    "stock": "STOCK_EXHAUSTED_MISSES",
    "relevance": "RELEVANCE_GATE_MISSES",
    "director": "DIRECTOR_RELEVANCE_MISSES",
}

# Журнал прогона: по записи на каждую закрытую попытку и на каждое решение
# о слоте. Отчёты промахов — ПРОЕКЦИЯ того же решения (_project_verdicts),
# поэтому «отчёт говорит брак, а на экране кадр» невыразимо: и экран, и
# отчёт берут одну попытку.
RUN_JOURNAL = []


def new_attempt(index, kind):
    return selection_attempt.Attempt(index, kind, os.path.join(TEMP_FOLDER, "staging"))


def apply_selection_effect(kind, *args):
    """Единственное место, где отобранное меняет состояние эпизода.
    Вызывается только из Attempt.commit()."""
    if kind == "reserve_id":
        container, value = args
        container.add(value)
    elif kind in ("reserve_hash", "shot_size"):
        container, value = args
        container.append(value)
    elif kind == "history":
        container, value, window = args
        container.append(value)
        del container[:-window]
    elif kind == "source_won":
        (channel,) = args
        _source_bump(channel, "won")
    elif kind == "license":
        prov, query = args
        log_candidate_license(prov, query)
    else:
        raise ValueError(f"неизвестный эффект отбора: {kind!r}")


# Какой аргумент эффекта — его суть для журнала (контейнер анти-дубля или
# ритма — объект процесса, в журнале он не нужен и не сериализуем).
_EFFECT_JOURNAL_ARG = {"reserve_id": 1, "reserve_hash": 1, "shot_size": 1,
                       "history": 1, "source_won": 0, "license": 0}


def _journal_value(v):
    if isinstance(v, (str, int, float, bool, type(None))):
        return v
    try:
        return json.loads(json.dumps(v, ensure_ascii=False, sort_keys=True))
    except (TypeError, ValueError):
        return str(v)


def _journal_attempt(att, final_media):
    RUN_JOURNAL.append({
        "record": "attempt", "attempt_id": att.attempt_id, "index": att.index,
        "kind": att.kind, "state": att.state, "media": final_media,
        "verdicts": [{"kind": k, **rec} for k, rec in att.verdicts],
        # Контейнер эффекта — объект процесса, в журнал идёт только суть.
        "effects": [{"effect": k, "value": _journal_value(a[_EFFECT_JOURNAL_ARG[k]])}
                    for k, a in att.effects],
    })


def _project_verdicts(verdicts):
    for kind, rec in effective_verdicts(verdicts):
        if kind == JUDGE_APPROVED_VERDICT:
            continue
        globals()[VERDICT_REPORT_LISTS[kind]].append(rec)


def close_slot(index, attempts, shown=None, decisive=None, outcome=None):
    """ЕДИНСТВЕННАЯ точка, где решение о слоте становится состоянием.

    shown    — попытка, чей кадр встаёт на экран (или None): её эффекты
               применяются, файлы переносятся в кэш;
    decisive — попытка, по вердиктам которой принято решение (обычно та же,
               что shown; у поглощённого или заменённого карточкой слота —
               та, чей кадр отвергнут). Её вердикты уходят в отчёты.
               None — ни одна попытка ничего не добыла: тогда причина
               «почему пусто» — объединение вердиктов всех попыток
               (единственный случай, где объединение законно).
    Остальные попытки закрываются отказом: ни резерва, ни файла в кэше, ни
    вердикта в отчёте слота; всё, что они узнали, остаётся в журнале.
    Возвращает итоговый путь медиа shown (или None)."""
    final = None
    for att in attempts:
        if att is shown:
            final = att.commit(apply_selection_effect)
            _journal_attempt(att, final)
            continue
        if att.state == selection_attempt.OPEN:
            att.discard()
        # Уже закрытая отказом (исключение внутри добытчика) — тоже в журнал:
        # «попытка была и ничего не дала» — факт, а не пропуск.
        _journal_attempt(att, None)
    if decisive is not None:
        _project_verdicts(decisive.verdicts)
    else:
        for att in attempts:
            _project_verdicts(att.verdicts)
    RUN_JOURNAL.append({
        "record": "slot", "index": index,
        "outcome": outcome or ("shown" if shown is not None else "empty"),
        "shown": shown.attempt_id if shown is not None else None,
        "decisive": decisive.attempt_id if decisive is not None else None,
        "attempts": [a.attempt_id for a in attempts],
    })
    return final


def fetch_in_attempt(slot_attempts, index, kind, fn, *args, **kwargs):
    """Запустить добытчика в новой попытке слота (main())."""
    att = new_attempt(index, kind)
    slot_attempts.append(att)
    return selection_attempt.run_attempt(att, fn, *args, **kwargs)


def given_attempt(slot_attempts, index, kind, media):
    """Попытка-носитель для кадра, который не добывался отбором: залоченный
    шотлистом, локальный файл, карточка. Эффекты кадра (ритм крупностей,
    история видов медиа) она несёт так же, как попытка отбора."""
    att = new_attempt(index, kind)
    att.media = media
    slot_attempts.append(att)
    return att


def attempt_of(slot_attempts, media):
    """Попытка, добывшая этот файл (последняя, если их несколько)."""
    if not media:
        return None
    for att in reversed(slot_attempts):
        if att.media == media:
            return att
    return None


def build_slot_request(**fields):
    """Единственное место, где строится SlotRequest. Ключевые слова вместо
    позиций, чтобы порядок полей не мог перепутаться; список полей
    SlotRequest задан без значений по умолчанию — пропущенное поле здесь
    же падает TypeError, а не превращается в тихий None."""
    extra = fields.get("extra_queries")
    fields["extra_queries"] = tuple(extra) if extra else ()
    return selection_engine.SlotRequest(**fields)


def select_standalone(kind, index, fn, *args, **kwargs):
    """Добытчик, вызванный ВНЕ слотового цикла main() (тест, утилита вроде
    brief_frame_ab.py): «выбрать и сразу принять». Та же попытка и тот же
    close_slot, что в main(), — второй ветки кода нет. Внутри открытой
    попытки (её открыл main()) добытчик просто работает в ней."""
    att = selection_attempt.current()
    if att is not None:
        if att.kind != kind or att.index != index:
            raise selection_attempt.AttemptStateError(
                f"добытчик {kind}#{index} вызван внутри чужой попытки {att.attempt_id}")
        return fn(*args, **kwargs)
    att = new_attempt(index, kind)
    media = selection_attempt.run_attempt(att, fn, *args, **kwargs)
    return close_slot(index, [att], shown=att if media else None, decisive=att)


def write_run_journal(video_folder):
    path = os.path.join(video_folder, "media_plan", "run_journal.jsonl")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        for rec in RUN_JOURNAL:
            f.write(json.dumps(rec, ensure_ascii=False, sort_keys=True, default=str) + "\n")
    os.replace(tmp, path)


def fallback_card_allowed(index, n_slots, is_opening=False):
    """Пускает ли бюджет плотности поставить карточку на этот слот.

    is_opening — САМЫЙ ПЕРВЫЙ кадр ролика: карточка там запрещена. Не из
    осторожности: у зрителя есть меньше секунды решить, остаться или уйти
    (ЧАСТЬ 9, «5 рычагов хука»), и текстовая заставка на открытии слабее
    любого живого кадра — даже посредственного. В остальных слотах хука
    карточка разрешена: там она заменяет уже признанный негодным кадр, и
    честная типографика выигрывает у корейского дворца.
    """
    if not FALLBACK_CARD_ENABLED or is_opening:
        return False
    # Бюджет распределён по ДЛИНЕ эпизода, а не отдаётся первым пришедшим.
    # Измеренный симптом (эпизод 02_ne-mechom, 10.09): все 17 карточек ушли
    # на слоты 14..85, то есть на первые 39% ролика, а в оставшихся 61%
    # осталось 43 слота с УЖЕ ЗАПИСАННЫМ браком и ноль карточек — не потому
    # что там кадры лучше, а потому что бюджет кончился по календарю. Брак
    # при этом распределён по ролику почти равномерно (21/16/20/19 по
    # четвертям), так что дело именно в порядке выдачи, а не в его форме.
    # Решать глобально ("покрыть худшие") нельзя: карточка выбирается в том
    # же проходе, что и отбор, и на слоте i будущие слоты ещё не оценены.
    # Равномерная выдача — то, что доступно без второго прохода: тот же
    # суммарный потолок и тот же MIN_GAP, но конец ролика перестаёт быть
    # беззащитным.
    total_cap = max(1, int(n_slots * FALLBACK_CARD_MAX_SHARE))
    position_cap = max(1, math.ceil((index + 1) * FALLBACK_CARD_MAX_SHARE))
    # Потолок — только по карточкам, заменившим БРАК. Карточка «нет медиа»
    # (FALLBACK_NO_MEDIA_REASON) бюджета не тратит: у неё другая гарантия.
    budgeted = [s for s in FALLBACK_CARD_SLOTS
                if s.get("reason") != FALLBACK_NO_MEDIA_REASON]
    if len(budgeted) >= min(total_cap, position_cap):
        return False
    # Интервал — по ВСЕМ карточкам, включая «нет медиа»: две карточки подряд
    # читаются как сбой вёрстки независимо от того, почему они тут стоят.
    return all(abs(index - s["index"]) >= FALLBACK_CARD_MIN_GAP
               for s in FALLBACK_CARD_SLOTS)


FALLBACK_CARD_DIR_NAME = "fallback_cards"


def is_fallback_card_media(media_path):
    """Это процедурная карточка, а не найденный кадр.

    Определяется по КАТАЛОГУ, в который её кладёт build_slot_fallback_card,
    а не по списку имён: список отстаёт по построению (тот же довод, что у
    ALIGNMENT_TAG_SPAN_RE — форма надёжнее перечисления).
    """
    if not media_path:
        return False
    return (os.sep + FALLBACK_CARD_DIR_NAME + os.sep) in os.path.normpath(media_path)


def build_slot_fallback_card(index, block_text, reason):
    """Собрать карточку для слота. Возвращает путь или None (fail-open).

    Детерминизм важен не для красоты: путь и содержимое зависят только от
    текста, поэтому повторный прогон не перерендеривает слот заново.
    """
    try:
        import fallback_card
        out_dir = os.path.join(TEMP_FOLDER, FALLBACK_CARD_DIR_NAME)
        h = hashlib.md5((block_text or "").encode("utf-8")).hexdigest()[:8]
        out = os.path.join(out_dir, f"card_{index:04d}_{h}.png")
        if os.path.exists(out) and os.path.getsize(out) > 0:
            # Файл уже собран прошлым прогоном (содержимое детерминировано
            # текстом) — надпись восстанавливаем тем же выбором, не рендерим
            # картинку заново.
            card_text = fallback_card.choose_card_text(block_text)[0]
        else:
            path, card_text = fallback_card.build_fallback_card(
                block_text, out, font_path=FONT_PATH)
            if not path:
                return None
        FALLBACK_CARD_SLOTS.append({"index": index, "reason": reason,
                                    "text": block_text, "card_text": card_text})
        print(f"  [карточка] слот {index}: «{card_text}» вместо кадра ({reason})")
        return out
    except Exception as e:
        # Уровень «не может провалиться» не имеет права уронить рендер сам.
        print(f"  ВНИМАНИЕ: карточка для слота {index} не собралась ({type(e).__name__})")
        return None

# Слоты, которые в ЭТОМ прогоне реально прошли подбор кандидата (а не были
# отданы кэш-хитом клипа). Нужен для merge_slot_report(): только про эти слоты
# текущий прогон вправе что-то утверждать.
RESOLVED_SLOTS_THIS_RUN = set()


def merge_slot_report(path, fresh_misses, *, resolved_slots, extra=None):
    """Записать отчёт по слотам, НЕ стирая то, что этот прогон не проверял.

    РЕАЛЬНАЯ, измеренная дыра (04.09, разбор опубликованного эпизода):
    relevance_gate_report.json / stock_exhausted_report.json /
    director_relevance_report.json переписывались целиком на КАЖДОМ запуске
    списком промахов только текущего прогона. После частичного ре-рендера
    (в реальном случае — 4 слота из 165, остальные кэш-хиты) все три файла
    оказались ПУСТЫМИ, хотя в готовом ролике 10 явно бракованных кадров.
    Аудит эпизода становился физически невозможен: единственные машинные
    свидетельства о подборе уничтожались следующим же прогоном.

    Это ровно та ловушка, от которой предостерегает CLAUDE.md ("пустой
    автоматический отчёт — не то же самое, что проблема решена"), только
    встроенная в саму механику записи отчётов.

    Правило слияния: запись прошлого прогона по слоту сохраняется, если этот
    слот в текущем прогоне не пересобирался (о нём просто нет свежих данных —
    и честнее сохранить старый вердикт, чем молча объявить слот чистым).
    Слот, который пересобран, полностью замещается свежим результатом: старый
    вердикт относится к другому, уже не существующему кадру.

    Перенесённые записи помечаются "from_previous_run": true — чтобы читатель
    отчёта отличал измеренное сейчас от унаследованного, а не считал всё
    одинаково свежим.
    """
    resolved = set(resolved_slots or ())
    merged = {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            prev = json.load(f)
        for m in (prev.get("misses") or []):
            idx = m.get("index")
            if idx is None or idx in resolved:
                continue
            carried = dict(m)
            carried["from_previous_run"] = True
            merged[idx] = carried
    except Exception:
        pass          # нет файла/битый JSON — просто пишем свежий, как раньше
    for m in fresh_misses:
        idx = m.get("index")
        if idx is not None:
            merged[idx] = m
    payload = dict(extra or {})
    payload["slots_evaluated_this_run"] = len(resolved)
    payload["misses"] = [merged[k] for k in sorted(merged)]
    tmp = path + ".tmp"
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
    os.replace(tmp, path)
    return payload


# Отбор (2.5): фильтр по alt-тексту кандидата — тот же JSON от Pexels-поиска,
# ничего не стоит (не новый запрос, не новая скачка). Заведён после ДВУХ
# реальных вживую пойманных случаев на этом эпизоде: и-словая
