# Отдельное имя дефолта — тот же принцип и та же причина, что у
# _MOOD_GRADE_DEFAULT выше: самоаудит 03.09 нашёл 15 терминов
# (katana/samurai/kimono/wuxia/...), добавленных в channel_profile.json
