# Второй заход (тот же день): после отсева первых трёх настоящий победитель
# на месте pexels:855260 (слот "Рыцарь падает в грязь под тяжестью металла")
# оказался ДРУГИМ, ранее не встреченным браком — латиноамериканская военная
# реконструкция XIX века (соломенные шляпы, полосатые рубахи, мушкеты; ни
# доспеха, ни средневековья, ни Европы) — ни один из существующих 8 ловушек
# CONTENT_NEGATIVE_ANCHORS её не описывает (это не толпа зрителей, не кухня,
# не спортзал — она в принципе не про современность, а про НЕ ТУ эпоху/
# культуру, для видео такого класса гварда просто нет). Тот же цикл — на
# месте openverse-победителя "История решается не мечом..." (FINAL) внезапно
# оказался лагерь фестиваля живой истории СО ЗНАКОМ "ZU VERKAUFEN ZELT"
# (нем. "продаётся палатка") на фоне — торговая палатка реконструкторской
# ярмарки, не безлюдное поле боя, relevance при этом 0.053 против 0.147 у
# кандидата, которого он вытеснил: локальная правка (снятие трёх ID) задела
# порядок отбора и на слотах, чей текст/запрос не менялся вообще — состав
# использованных id/хэшей и ритм крупностей плана общие на весь эпизод.
# Оба — тоже измеренный, не гипотетический брак (кадры сохранены), оба тоже
# добавлены. Честно: это ROLLING БЛОКЛИСТ, не системное решение — он ловит
# ровно то, что уже один раз увидели глазами, и ничего, что ещё не видели.
#
# Третий заход на ТОТ ЖЕ слот ("Рыцарь падает в грязь под тяжестью металла")
# дал ТРЕТЬЕГО подряд неверного по эпохе победителя — pexels:9466647,
# наполеоновская кавалерия в мундирах со скачущими лошадьми и занесёнными
# саблями (не средневековье, не падение, а атака). Три разных видео подряд
# на одну и ту же фразу, все три — исторические реконструкции НЕ той эпохи,
# ни одна не про падение, а мимо гвардов проходят потому, что ни один из них
# не про "правильную эпоху вообще", только про современность/культуру
# клинка/явные предметные ловушки. Это уже не единичный брак, а сигнал:
# видео-пул по запросу "knight armour fallen mud" для этого канала СИСТЕМНО
# сорит реконструкциями чужих эпох сильнее, чем даёт нужное — блокировка
# четвёртого/пятого ID по одному была бы чистым whack-a-mole. Практический
# вывод (не реализован здесь, решение владельца): для этого конкретного
# слота надёжнее принудительно взять фото вместо видео (через lock в
# shotlist.json), а не продолжать ID-блокировку до бесконечности.
#
# ПРОВЕРЕНО НЕЗАВИСИМО, ВНЕ ПАЙПЛАЙНА (21.09, прямой запрос к Pexels API
# в обход всех гейтов вообще) — гипотеза «сток просто засорён» стала
# измеренным фактом, не подозрением. `videos/search?query=medieval cavalry
# charge field` отдаёт `total_results: 8000`, но живой просмотр первых 15 —
# ни одного медиевального: "soldiers riding horseback with drawn swords"
# (это и есть pexels:9466647 выше), "people marhing in traditional clothing"
# (pexels:12170117 выше), "revolutionary soldiers protecting a woman from
# the cavalry", "traditional cavalry display at CULTURAL FESTIVAL" (дословно
# современный фестиваль), "a man riding a horse firing the RIFLE" (огнестрел).
# Второй запрос `knight horseback armor` (total_results: 4860) — та же
# картина плюс "horse riding and jousting training": по превью это СОВРЕМЕННЫЙ
# конно-спортивный манеж (цветные шары-мишени, конус, столб ЛЭП), голый
# торс всадника, никакого доспеха. Четвёртый победитель этого же слота,
# pexels:9466305 ("man riding a horse while surrounding the revolutionary
# soldiers"), — из ТОГО ЖЕ первого запроса, наполеоновская/гусарская форма,
# тоже добавлен. Вывод для практики: гейты здесь НЕ виноваты и ослаблять их
# было бы неверным диагнозом — ровно эти четыре кандидата УЖЕ прошли
# relevance/домен-гвард/негативный якорь с приемлемым скором, поймать их
# смогла только ручная проверка глазами (или, у части, вторая модель). Сама
# видео-выдача по этому понятию на этом стоке — не тонкая, а системно НЕ ТОЙ
# эпохи; больше кандидатов в этот список добавлять малополезно.
_CONTENT_BLOCKED_CANDIDATE_IDS_DEFAULT = (
    "pexels:855260", "pexels:35687472", "pexels:31595410",
    "pexels:12170117", "openverse:e5690140-6fc2-46fc-880a-3028b8478606",
    "pexels:9466647", "pexels:9466305",
)
CONTENT_BLOCKED_CANDIDATE_IDS = frozenset(str(x) for x in CHANNEL_PROFILE.get(
    "content_blocked_candidate_ids", _CONTENT_BLOCKED_CANDIDATE_IDS_DEFAULT))
# Кадр отклоняется, если ЛЮБАЯ ловушка набрала не меньше, чем цель минус
# запас. Отрицательный запас = консервативно: ловушка должна ощутимо
# ПЕРЕБИВАТЬ цель, а не просто дотягиваться до неё. Именно эта
# консервативность и даёт ноль ложных отказов на замере.
#
# ПЕРЕКАЛИБРОВАНО 18.09 под SigLIP2-base256 — тот же метод, тот же золотой
# набор (40 кадров, все 8 ловушек, min margin по кандидату), другая шкала.
# Безопасная граница задаётся САМЫМ ОТРИЦАТЕЛЬНЫМ margin среди good/
# tolerable — ep01_003 (tolerable, -0.0550) — порог должен быть строго
# ниже (отрицательнее) этого значения, а не «подальше от найденной границы
# улова» (первая версия этого порога, -0.065, ошибочно буферовала В ДРУГУЮ
# СТОРОНУ и теряла ep01_020 без причины). -0.06 — с запасом 0.005 от
# ep01_003, ловит 5/17 брака (ep01_020/040/062/122/140) при 0 потерь good
# И tolerable. ЧЕСТНО чуть хуже CLIP на этой конкретной оси (тот при -0.015
# ловил 6/17) — на новой модели margin у двух good-кадров (ep01_015/032)
# отрицательнее, чем был у CLIP, и порог обязан отступить дальше, чтобы их
# не потерять. SMART_RELEVANCE_VETO (проверка ПОБЕДИТЕЛЯ более тяжёлым
# so400m+Jina ensemble, см. smart_relevance_veto() ниже) остаётся вторым,
# независимым слоем защиты именно от такого класса пропуска.
NEGATIVE_VETO_MARGIN = -0.06
NEGATIVE_VETO_ENABLED = feature_flags.enabled("NEGATIVE_VETO")


def episode_forbidden_anchors(video_dir=None):
    """Ловушки ЭТОГО эпизода — `must_not_show` из паспорта мира, пустой
    кортеж, если паспорта нет.

    САМАЯ КРУПНАЯ находка аудита 21.09, и это был не баг в гейте, а ОТСУТСТВИЕ
    ПРОВОДА. `world_card.forbidden_classes()` существует с самого появления
    паспорта, её докстринг прямо говорит «Что в кадре этого эпизода — брак.
    Уходит в вопрос приёмки кадра», а прямой grep показал: её не вызывает
    НИКТО. Паспорт тестового эпизода при этом дословно перечисляет
    `modern tactical knife`, `napoleonic uniform`, `firearm` — и ровно это
    уехало на экран: на фразу «Вот кинжал» встал современный тактический нож,
    на «Конница мчится» — наполеоновский гусар с ружьём.

    Замер на РЕАЛЬНЫХ победителях прогона (clip_relevance_multi, те же числа,
    что видит прод; margin = ловушка минус цель, порог NEGATIVE_VETO_MARGIN):

        кадр                          ловушка паспорта      канальные 8
        современный нож               +0.0276  ОТКАЗ        -0.0849  слепы
        слабый доспех (rel 0.02)      +0.0728  ОТКАЗ        +0.0569
        наполеоновский гусар          -0.0155  ОТКАЗ        -0.0944  слепы
        упавший рыцарь (годный)       -0.0886  проходит     -0.1177
        финальный всадник (годный)    -0.0741  проходит     -0.0940

    То есть канальный список слеп ровно там, где паспорт видит сразу: его
    восемь ловушек — про СОВРЕМЕННОСТЬ и культуру клинка, а весь пойманный
    брак был про ЭПОХУ, и такого гварда не существовало вообще.

    Порог берётся ТОТ ЖЕ (NEGATIVE_VETO_MARGIN) — новое калиброванное число
    на семи точках одного эпизода было бы подгонкой, а не калибровкой.

    Нет паспорта — пустой кортеж, поведение байт-в-байт прежнее.
    """
    try:
        import world_card
        return tuple(world_card.forbidden_classes(episode_world_card(video_dir)))
    except Exception:
        return ()


def negative_anchor_violation(image_path, query):
    """(отклонён_ли_кадр, какая_ловушка_сработала) — контрастивное вето.

    Считается ОДНИМ прогоном картинки против всех ловушек сразу
    (clip_relevance_multi), поэтому стоит примерно столько же, сколько один
    обычный вызов clip_relevance. (False, None) при выключенном режиме или
    недоступной модели — тот же безопасный откат, что у остальных гейтов.

    Ловушки = КАНАЛЬНЫЕ (CONTENT_NEGATIVE_ANCHORS, про современность/культуру)
    ПЛЮС ловушки ЭТОГО ЭПИЗОДА из паспорта мира (см. episode_forbidden_anchors
    — там замер, ради которого провод и появился). Одним прогоном, как и было:
    clip_relevance_multi берёт все тексты за один forward картинки.
    """
    if not NEGATIVE_VETO_ENABLED:
        return False, None
    anchors = tuple(CONTENT_NEGATIVE_ANCHORS) + episode_forbidden_anchors()
    if not anchors:
        return False, None
    scores = clip_relevance_multi(image_path, [query] + list(anchors))
    if not scores:
        return False, None
    target, negatives = scores[0], scores[1:]
    worst = max(range(len(negatives)), key=lambda k: negatives[k])
    if (target - negatives[worst]) < NEGATIVE_VETO_MARGIN:
        return True, anchors[worst]
    return False, None


def visual_domain_guard_violation(image_path, query):
    """(нарушен_ли_анкер, имя_анкера) для ПЕРВОГО сработавшего правила из
    VISUAL_DOMAIN_GUARDS, чей trigger_terms совпал с query — см. калибровку
    выше. (False, None), если анкеры не применимы к этому запросу или CLIP
    недоступен (безопасный откат, тот же принцип, что is_risky_query)."""
    ql = query.lower()
    for guard in VISUAL_DOMAIN_GUARDS:
        if not any(t in ql for t in guard["trigger_terms"]):
            continue
        euro = clip_relevance(image_path, guard["euro_prompt"])
        asian = clip_relevance(image_path, guard["asian_prompt"])
        if euro is None or asian is None:
            continue
        if (euro - asian) < guard["margin_threshold"]:
            return True, guard["name"]
    return False, None


# Доли длительности ролика, по которым видео проверяется покадрово
# (VideoAdapter: превью источника в этих точках) — не научный подбор, просто
# разброс "начало/середина/конец", чтобы не зависеть от одной случайной
# секунды.
VIDEO_DOMAIN_GUARD_SAMPLE_FRACS = (0.15, 0.5, 0.85)


# Реальный, найденный вживую случай (27 августа, videos/_test20s, слот 7):
# видео всадника с занесённым клинком — генуинное motion-blur самой
# стоковой съёмки (быстрая скачка/поворот камеры), не артефакт нашего
# рендера. Замерено на РЕАЛЬНЫХ кандидатах этого эпизода: заведомо ХОРОШЕЕ
# видео (батальная реконструкция, уже стоявшее в кадре) — резкость 1009-1952
# на 5 сэмплах по всей длительности; заведомо ПЛОХОЕ (этот всадник) —
# 92-270 на тех же 5 сэмплах, той же функцией image_sharpness_score(). Разрыв
# чистый и большой (минимум хорошего 1009 против максимума плохого 270) —
# порог 400 берётся с большим запасом в разрыв. Честно: n=2 видео, не
# статистика — тот же принцип малой калибровки, что уже применяет
# DIRECTOR_RELEVANCE_FLOOR/RISKY_QUERY_MARGIN в этом файле, не гадание с
# потолка.
VIDEO_SHARPNESS_REJECT = 400.0
VIDEO_SHARPNESS_SAMPLE_FRACS = (0.15, 0.5, 0.85)   # та же сетка, что у domain-гварда


# Ролики, не прошедшие резкость в этом прогоне (ключ — id кандидата).
# Резкость — свойство файла, а не слота: на соседнем слоте тот же ролик
# скачивался и отклонялся заново (замер эпизода 94: pixabay:125459).
_VIDEO_UNSHARP_CACHE = {}


def video_sharpness_ok(video_path):
    """Median резкости по нескольким сэмплам (не один кадр — транзиентное
    смазывание в один момент не должно топить весь клип, см. докстринг
    video_domain_guard_violation про "не доверять одному сэмплу"). None
    (не гейтит) при сбое длительности/декода — безопасный откат, как и у
    остальных опциональных проверок. РЕАЛЬНАЯ проверка на калибровочных
    видео этого эпизода (см. VIDEO_SHARPNESS_REJECT) — хорошее видео держит
    median далеко ВЫШЕ порога на всех сэмплах, плохое — далеко НИЖЕ."""
    try:
        duration = get_media_duration(video_path)
    except Exception:
        duration = None
    if not duration or duration <= 0.6:
        return None
    scores = []
    for frac in VIDEO_SHARPNESS_SAMPLE_FRACS:
        at = max(0.3, min(duration - 0.2, duration * frac))
        probe, cleanup = extract_video_probe_frame(video_path, base_at=at, retry_ats=())
        if probe is None:
            continue
        try:
            s = image_sharpness_score(probe)
        finally:
            if cleanup and os.path.exists(probe):
                os.remove(probe)
        if s is not None:
            scores.append(s)
    if not scores:
        return None
    scores.sort()
    median = scores[len(scores) // 2]
    return median >= VIDEO_SHARPNESS_REJECT


def is_relevant_candidate(image_path, query, relevance=None):
    """Итоговое решение "релевантен ли кандидат query" — тот же порог +
    risky-margin гейт, что раньше жил инлайном в цикле подбора фото (см.
    main()/pexels_photo(), вызов ниже). Вынесено в отдельную функцию, чтобы
    golden-тест (tests/test_media_selection_golden.py) гонял РЕАЛЬНУЮ
    логику принятия решения через реальный clip_relevance(), а не свою
    отдельную копию тех же трёх строк, которая могла бы молча разойтись
    с рабочим кодом при следующей правке. relevance можно передать уже
    посчитанным (вызывающий код часто уже считал его для других целей) —
    иначе считается здесь же."""
    if relevance is None:
        relevance = clip_relevance(image_path, query)
    is_relevant = relevance is None or relevance >= CLIP_RELEVANCE_THRESHOLD
    if is_relevant and relevance is not None and is_risky_query(query):
        anchor_relevance = clip_relevance(image_path, NEGATIVE_ANCHOR_PROMPT)
        if anchor_relevance is not None and (relevance - anchor_relevance) < RISKY_QUERY_MARGIN:
            is_relevant = False
    if is_relevant:
        violated, _ = visual_domain_guard_violation(image_path, query)
        if violated:
            is_relevant = False
    if is_relevant:
        # Контрастивное вето по ловушкам — см. negative_anchor_violation():
        # обобщение того же margin-механизма с одной оси (европейский клинок
        # против восточноазиатского) на восемь классов современного
        # вторжения. Стоит один прогон картинки, ловит 6 браков из 17 при
        # нуле ложных отказов на золотом наборе.
        vetoed, _ = negative_anchor_violation(image_path, query)
        if vetoed:
            is_relevant = False
    return is_relevant


# ВТОРОЙ, БОЛЕЕ ТОЧНЫЙ ВЗГЛЯД НА ПОБЕДИТЕЛЯ — SigLIP2+Jina поверх CLIP,
# НЕ ВМЕСТО НЕГО (SMART_RELEVANCE_VETO=0/1, дефолт 1, 17.09).
#
# ЗАЧЕМ ДВА СЛОЯ, А НЕ ЗАМЕНА ОДНОГО ДРУГИМ — по прямому требованию
# владельца "модель CLIP старая и глупая, замени её везде на новую".
# Проверено ИЗМЕРЕНИЕМ, а не мнением, на золотом наборе (40 кадров):
#
#   ось                                   CLIP    SigLIP2+Jina
#   AUC (ранжирует годное выше брака)     0.566   0.610
#   при нуле ложных отказов годным:
#     брака поймано                       1/17    1/17
#     терпимых потеряно                   3/7     2/7
#
# Новая модель ДЕЙСТВИТЕЛЬНО отличает лучше (AUC выше, теряет меньше
# терпимых кадров при той же строгости) — первая попытка сравнения (по
# средним числам, не по рангу) этого не показывала и была ошибкой метода,
# не находкой; поймано и исправлено в этом же заходе.
#
# НО замена ПОЛНОСТЬЮ, на КАЖДОГО кандидата пула, не сделана — и это не
# осторожность ради осторожности, а измеренная цена: живой замер на этой
# машине (15 картинок, текст РАЗНЫЙ на каждый вызов — кэш не участвует):
#
#   CLIP           :   72 мс/вызов
#   SigLIP2+Jina   : 2358 мс/вызов  (32.8x медленнее)
#
# is_relevant_candidate() вызывается на КАЖДОГО кандидата пула (десятки за
# слот, тысячи за эпизод) — на этой частоте 33x медленнее означает часы
# лишнего времени рендера, а не минуты. Ровно эта цена уже задокументирована
# в CLAUDE.md для VISUAL_DIRECTOR_MODE (там же дефолт `off` по той же
# причине) — теперь то же самое измерено для ЭТОЙ модели на ЭТОЙ задаче.
#
# Поэтому CLIP остаётся быстрым фильтром ВСЕГО пула (как был, ни одна
# калиброванная константа не тронута), а новая модель — ОДИН дополнительный
# взгляд на уже выбранного ПОБЕДИТЕЛЯ слота, перед тем как его принять:
# ~250 вызовов на эпизод вместо тысяч, те же ~10 минут, а не часы. Тот же
# архитектурный приём, что уже работает для VLM-арбитра (дорогой ресурс —
# только на шорт-лист, не на весь пул) и render_sharpness_regression()
# (проверка готового кадра, не каждого кандидата).
#
# Отклонённый победитель НЕ подменяется карточкой и НЕ повторяет соседа
# сам — он просто возвращает slot туда же, куда уже возвращают отказ
# арбитра/исчерпанный сток/провал по порогу: в SMART_VETO_MISSES, откуда
# known_bad_reason() и (с 17.09) поглощение соседним проверенным
# кадром (NEVER_SHOW_KNOWN_BAD, см. ЧАСТЬ 13 Шаг 7.3) забирают решение —
# вторая копия логики "что делать с негодным кадром" не заводится.
SMART_RELEVANCE_THRESHOLD = -0.01   # см. таблицу выше: нулевая точка золотого набора
SMART_VETO_MISSES = []   # [{"index", "query", "score"}, ...] — тот же формат, что у соседей


def smart_relevance_veto(image_path, query):
    """True — отклонить УЖЕ ВЫБРАННОГО победителя слота (см. блок-комментарий
    выше). Вызывается ОДИН раз на слот, не на кандидата — иначе цена, из-за
    которой этот же комментарий объясняет, почему это не замена CLIP.

    Fail-open, тот же принцип, что и у CLIP-гейтов: недоступна модель (нет
    torch/transformers/onnxruntime, сбой любого рода) -> False, кадр не
    теряет уже принятое решение из-за окружения без тяжёлых зависимостей."""
    if not feature_flags.enabled("SMART_RELEVANCE_VETO"):
        return False
    try:
        import visual_director
        score = visual_director.sentence_relevance(image_path, query)
    except Exception:
        return False
    if score is None:
        return False
    return score < SMART_RELEVANCE_THRESHOLD


# СУДЬЯ КАДРОВ (SHOT_JUDGE=0/1, дефолт 1; платит только при ключе шлюза).
#
# Модель «зрение + язык» через шлюз (scripts/llm_gateway.py) смотрит на
# кандидатов слота сеткой и ставит каждому 0..3 по описанию кадра и фразе
# (scripts/shot_judge.py: шкала, замер, почему сеткой). Оценка — главный
# ключ ранжирования после анти-дубля (judge_rank в _score_and_pick).
#
# ПОЧЕМУ ВЫШЕ ГЕЙТОВ ЭМБЕДДИНГА. Косинус картинки и текста не рассуждает:
# современный нож и средневековый кинжал для него почти одно и то же, лук
# у него «огнестрел» (живой случай эпизода 94). Судья на тех же кадрах
# ставит современному ножу 0, подлинным кинжалам 3. Безошибочным он НЕ
# является: на живом прогоне 23.09 он дал 3 мечу на «кинжал» и 2
# наполеоновской кавалерии на «средневековая конница» — предел зрения
# модели по эпохе (замер в shot_judge.py).
#
# ДЕНЬГИ. Флаг включён, но без LLM_GATEWAY_API_KEY судья не делает ничего:
# ключ в .env — явное согласие владельца. Потолок расходов прогона —
# SHOT_JUDGE_MAX_SPEND (токенов баланса шлюза); превышение — судья молча не
# зовётся до конца прогона, и это пишется в отчёт, а не теряется. 402
# (кончились деньги) выключает шлюз до конца прогона.
#
# ОТКАЗ — БЕЗ ПОЛУМЕР. Судья не ответил по всем кандидатам слота — оценок нет
# ни у кого (shot_judge.judge возвращает None): смешать оценённых с
# неоценёнными значило бы ранжировать случайно.
SHOT_JUDGE_DEFAULT_MODEL = "qwen/qwen3.7-plus"
SHOT_JUDGE_DEFAULT_SPEND_CAP = 300000
SHOT_JUDGE_MIN_SCORE = 2       # 2 = «предмет тот, действие/композиция иные»
SHOT_JUDGE_MISSES = []         # слоты, где лучший кадр по оценке судьи — брак
SHOT_JUDGE_LOG = []            # по вызову на попытку: оценки, цена, кэш, отказ
_SHOT_JUDGE_STATE = {"gateway": None, "made": False, "refused": None}
# Прогноз цены эпизода. Потолок срабатывает посреди ролика: дальше слоты
# идут без судьи, и качество эпизода становится неровным — начало с судьёй,
# хвост без. Замер (эпизод 94, 9 слотов): 20 832 токена баланса, ~2 300 на
# слот; эпизод в 250 слотов — ~580 тыс. при потолке 300 тыс. Цена в код не
# зашивается: после SHOT_JUDGE_FORECAST_AFTER оценённых слотов реальная
# трата на слот экстраполируется на весь эпизод, и перерасход называется
# ОДИН раз, в начале ролика, с числом и именем переменной.
SHOT_JUDGE_EPISODE_SLOTS = 0   # число слотов эпизода, ставит main()
SHOT_JUDGE_FORECAST_AFTER = 5


def shot_judge_model():
    return (os.environ.get("SHOT_JUDGE_MODEL") or "").strip() or SHOT_JUDGE_DEFAULT_MODEL


def _shot_judge_gateway():
    """Шлюз судьи на прогон или None (флаг выключен, нет ключа)."""
    if not feature_flags.enabled("SHOT_JUDGE"):
        return None
    st = _SHOT_JUDGE_STATE
    if not st["made"]:
        st["made"] = True
        import llm_gateway
        raw = (os.environ.get("SHOT_JUDGE_MAX_SPEND") or "").strip()
        try:
            cap = int(raw) if raw else SHOT_JUDGE_DEFAULT_SPEND_CAP
        except ValueError:
            print(f"  SHOT_JUDGE_MAX_SPEND={raw!r} — не число, беру {SHOT_JUDGE_DEFAULT_SPEND_CAP}")
            cap = SHOT_JUDGE_DEFAULT_SPEND_CAP
        gw = llm_gateway.Gateway(spend_cap=cap)
        if gw.configured:
            import shot_judge
            sees, why = shot_judge.vision_check(gw, shot_judge_model())
            if sees:
                st["gateway"] = gw
                print(f"  Судья кадров: {shot_judge_model()} через {gw.base_url}, потолок {cap}")
            else:
                st["refused"] = why
                print(f"  ВНИМАНИЕ: судья кадров ВЫКЛЮЧЕН на этот прогон — {why}. "
                      f"Кадры ранжируются без него; проверь SHOT_JUDGE_MODEL.")
        else:
            print("  Судья кадров: нет LLM_GATEWAY_API_KEY — кадры ранжируются без него")
    return st["gateway"]


# КАСКАД: КОГО СУДЬЯ ВООБЩЕ УВИДИТ. Пул слота — 200-950 кандидатов, а
# гейты и судья смотрят ~20: первые по порядку пула (источники вперемешку).
# Опыт 23.09 (эпизод 94, девять фото-слотов; судья оценивал все наборы в
# одном прогоне, сетки перемешаны):
#   кого видит судья            слотов с лучшим «3»   кадров с «3»
#   первые 18 пула              3 из 9                3
#   лучшие 18 из первых 100     4 из 9                —
#   лучшие 18 из всего пула     7 из 9                26
# ни один слот не стал хуже. Поэтому ранжируется ВЕСЬ пул: превью каждого
# кандидата оценивается локальной моделью гейта по описанию кадра, и гейты
# с судьёй получают лучших, а не первых.
#
# ЦЕНА И КЭШ. Проход модели — ~0.155 с на картинку на 4 ядрах (замер;
# пакетом не быстрее по одной). Эмбеддинг картинки от описания не зависит,
# а пулы соседних слотов делят половину кандидатов (эпизод 94: 3 175
# уникальных фото на 6 571 позицию) — поэтому эмбеддинг кэшируется на диск
# по адресу превью (3 КБ), превью удаляется сразу после оценки. Первый
# рендер эпизода — около минуты сверху на слот; повторный — только новые
# кандидаты. CASCADE_PREVIEW_N в .env сужает окно ради скорости. Только при
# работающем судье: опыт мерил этот случай; без ключа отбор прежний.
CASCADE_DEFAULT_PREVIEW_N = 1000
CASCADE_WORKERS = 8
_CASCADE_EMB = {}


# ВТОРАЯ СТРАНИЦА КАСКАДА. Судья смотрит лучших ~20 по описанию кадра; если
# проверка мира отклонила всех, кого он одобрил, или одобренных нет, слот
# опустеет. Живой случай (эпизод 94, «Он весил меньше, чем ты думаешь»):
# описание «маленький кинжал на раскрытой ладони» подняло наверх каскада
# современные ножи в руках — судья одобрил четыре, проверка мира отклонила
# все четыре. Следующие 18 кандидатов каскада дали семь одобренных, и
# первый же прошёл проверку мира (кованый клинок на ладони мастера); в
# двух опустевших или отклонённых слотах из трёх вторая страница нашла
# кадр. Вторая страница — отдельная попытка слота (main), и только там,
# где первая не дала годного кадра: платит один провалившийся слот.
CASCADE_PAGE = contextvars.ContextVar("CASCADE_PAGE", default=0)


@contextlib.contextmanager
def cascade_page(n):
    token = CASCADE_PAGE.set(n)
    try:
        yield
    finally:
        CASCADE_PAGE.reset(token)


def cascade_preview_n():
    raw = (os.environ.get("CASCADE_PREVIEW_N") or "").strip()
    try:
        return max(2, int(raw)) if raw else CASCADE_DEFAULT_PREVIEW_N
    except ValueError:
        return CASCADE_DEFAULT_PREVIEW_N


def _gate_embed(images=None, text=None):
    """Нормированные эмбеддинги модели гейта — те же числа, что у
    clip_relevance() (проверено: разница 0.0). None — модели нет."""
    global CLIP_BROKEN
    if not CLIP_ENABLED or CLIP_BROKEN:
        return None
    try:
        import torch
        model, processor = get_clip_model()
        with torch.no_grad():
            if text is not None:
                inp = processor(text=[text], return_tensors="pt", padding="max_length",
                                max_length=CLIP_GATE_MODEL_MAX_TEXT_LEN, truncation=True)
                out = model.get_text_features(**inp)
            else:
                out = model.get_image_features(**processor(images=images, return_tensors="pt"))
        e = out if torch.is_tensor(out) else out.pooler_output
        e = e / e.norm(dim=-1, keepdim=True)
        return e.numpy().astype("float32")
    except ImportError:
        CLIP_BROKEN = True
        return None
    except Exception:
        return None


def _cascade_key(url):
    return hashlib.md5(f"{CLIP_GATE_MODEL_NAME}|{url}".encode("utf-8")).hexdigest()


def _cascade_ident(p, url):
    """Чем называть превью в кэше каскада. Обычно — адресом. У Pixabay
    адрес превью подписан и меняется от выдачи к выдаче (разбор 24.09:
    2 770 из 4 027 строк — /get/-адреса, у 1 382 кадров, встреченных и в
    judge9, адрес другой), поэтому по адресу кэш промахивается и превью
    качается заново каждый прогон — отсюда 429 от Pixabay. Тот же кадр — тот
    же номер и тот же размер превью (суффикс _640 и т.п.) — одно имя."""
    if url and "pixabay.com/get/" in url and p.get("id"):
        import re
        size = re.search(r"_(\d+)\.\w+(?:\?|$)", url)
        kind = "video" if p.get("video_files") else "photo"
        return f"pixabay-id:{p['id']}|{kind}|{size.group(1) if size else ''}"
    return url


def _cascade_cached(key, cache_dir):
    v = _CASCADE_EMB.get(key)
    if v is None:
        fp = os.path.join(cache_dir, key + ".npy")
        if os.path.exists(fp):
            try:
                v = np.load(fp)
                _CASCADE_EMB[key] = v
            except Exception:
                v = None
    return v


def query_tiers_source():
    """Ярусы пула (selection_engine.query_tiers) — для подписи отбора: они
    меняют порядок пула, а живут в другом модуле."""
    import selection_engine
    return selection_engine.query_tiers


def cascade_texts(spec, brief, kind="photo"):
    """Тексты, по которым каскад ранжирует превью: поисковые запросы
    спецификации кадра (их пишет планировщик под эту фразу), без
    спецификации — бриф одной строкой, как раньше.

    Раньше это были must-утверждения, и кадр ставился по ХУДШЕМУ месту
    среди них. Разбор 24.09 на 324 размеченных кадрах эп.94: эта формула
    различает годное и брак на уровне случайности (AUC 0.56 фото, 0.48
    видео), а на кадрах, которые реально видит судья, ставит их в обратном
    порядке (0.44) — «худшее место» по нескольким составным утверждениям
    поднимает компромиссные кадры, посредственные по всем сразу. Лучшее
    сходство с запросами спецификации — 0.78 / 0.73; годных среди первых
    10 фото 40% -> 59%; лучший кадр слота среди первых 20 (их видит судья)
    сохранён или лучше во всех 15 слотах. Картиночные эмбеддинги те же —
    цена не меняется."""
    if spec:
        qs = [q.strip() for q in (spec.get("queries") or []) if isinstance(q, str) and q.strip()]
        if qs:
            return qs
        import shot_judge
        return [c["text"] for c in shot_judge.asked_claims(spec, kind) if c["tier"] == "must"]
    return [brief] if brief else []


def cascade_claims(spec, kind="photo"):
    """Обязательные утверждения спецификации — второй порядок каскада (см.
    cascade_reorder). Утверждение движения у фото не спрашивается: фото его
    выполнить не может."""
    if not spec:
        return []
    import shot_judge
    return [c["text"] for c in shot_judge.asked_claims(spec, kind) if c["tier"] == "must"]


def _interleave(first, second):
    """Поочерёдно из двух порядков, без повторов: первое место первого,
    первое место второго, второе место первого... Первые k мест КАЖДОГО
    порядка попадают в первые 2k итогового."""
    out, seen = [], set()
    for pair in zip(first, second):
        for x in pair:
            if x not in seen:
                seen.add(x)
                out.append(x)
    for x in list(first) + list(second):
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out


def cascade_reorder(candidates, texts, cf, probe_fn, index=None, batch=16, url_of=None,
                    claims=None):
    """Новый порядок кандидатов: первые cascade_preview_n() ранжированы по
    близости превью к текстам; кандидаты без превью — следом в прежнем
    порядке, хвост пула — за ними. Модель недоступна или оценено меньше
    двух — порядок прежний. Превью на диске не остаются.

    Текстов несколько (запросы спецификации кадра) — кандидат стоит по
    ЛУЧШЕМУ сходству с любым из них: запросы — разные формулировки одного
    кадра, и кадр, точно отвечающий одной из них, годен (см. cascade_texts).
    Один текст — прежний порядок по близости.

    claims (обязательные утверждения) — второй порядок: по ХУДШЕМУ месту
    среди утверждений, то есть кадр должен выполнять их ВСЕ вместе. Итог —
    поочерёдно из двух порядков, утверждения первыми. Причина — живой
    регресс judge12 (25.09, слот «Он весил меньше... грамм триста»):
    запросы по отдельности («medieval dagger hand», «dagger weight close
    up») подняли наверх просто мечи и кинжалы без руки, и годный кадр
    «руки держат кинжал» ушёл с 9-го места на 73-е, судья его не увидел.
    Составная фраза требует всего вместе — это держит порядок по
    утверждениям, точное совпадение с запросом — порядок по запросам.
    Поочерёдно: первые 10 мест КАЖДОГО порядка — в первых 20, их видит
    судья. Замер на размеченных кадрах 15 слотов эп.94: годных среди первых
    20 — 72 (утверждения) / 75 (запросы) / 88 (поочерёдно), лучший кадр
    среди первых 20 не хуже обоих порядков ни в одном слоте."""
    if isinstance(texts, str):
        texts = [texts]
    texts = [t for t in (texts or []) if t]
    n = cascade_preview_n()
    head = candidates[:n]
    if len(head) < 2 or not texts or np is None:
        return candidates
    t_embs = [_gate_embed(text=t) for t in texts]
    if any(e is None for e in t_embs):
        return candidates
    cache_dir = os.path.join(TEMP_FOLDER, "cascade_embed_cache")
    url_of = url_of or candidate_probe_url
    keys = {id(p): _cascade_key(_cascade_ident(p, url_of(p))) for p in head}
    emb = {id(p): _cascade_cached(keys[id(p)], cache_dir) for p in head}
    need = [p for p in head if emb[id(p)] is None]
    fresh = 0
    if need:
        os.makedirs(cache_dir, exist_ok=True)
        tmp = {id(p): cf + f".casc_{candidate_path_token(p)}.jpg" for p in need}

        def get(p):
            try:
                probe_fn(p, tmp[id(p)])
                return _downloaded_ok(tmp[id(p)])
            except Exception:
                return False
        with concurrent.futures.ThreadPoolExecutor(CASCADE_WORKERS) as ex:
            got = [p for p, ok in zip(need, ex.map(get, need)) if ok]
        with stage_timer.stage("cascade_rank", clip_idx=index):
            for k in range(0, len(got), batch):
                part, imgs = [], []
                for p in got[k:k + batch]:
                    try:
                        with PILImage.open(tmp[id(p)]) as im:
                            imgs.append(im.convert("RGB"))
                        part.append(p)
                    except Exception:
                        pass
                vecs = _gate_embed(images=imgs) if imgs else None
                if vecs is None:
                    continue
                for p, v in zip(part, vecs):
                    emb[id(p)] = v
                    _CASCADE_EMB[keys[id(p)]] = v
                    # Тот же кадр позже скачивается пробником для гейтов —
                    # эмбеддинг по содержимому файла уже готов.
                    d = _file_digest(tmp[id(p)])
                    if d:
                        _GATE_IMG_EMB_CACHE.setdefault(d, v)
                    try:
                        np.save(os.path.join(cache_dir, keys[id(p)] + ".npy"), v)
                    except Exception:
                        pass
                    fresh += 1
        for f in tmp.values():
            try:
                os.remove(f)
            except OSError:
                pass
    have = [(k, p) for k, p in enumerate(head) if emb[id(p)] is not None]
    if len(have) < 2:
        return candidates
    best = {k: max(float(emb[id(p)] @ t[0]) for t in t_embs) for k, p in have}
    by_query = [k for k, _p in sorted(have, key=lambda kp: (-best[kp[0]], kp[0]))]
    order = by_query
    c_texts = [c for c in (claims or []) if c]
    if c_texts == texts:
        c_texts = []      # без запросов в спецификации тексты и есть утверждения
    c_embs = [_gate_embed(text=c) for c in c_texts] if c_texts else []
    if c_embs and all(e is not None for e in c_embs):
        places = {}
        for t in c_embs:
            by_t = sorted(have, key=lambda kp: (-float(emb[id(kp[1])] @ t[0]), kp[0]))
            for place, (k, _p) in enumerate(by_t):
                places.setdefault(k, []).append(place)
        by_claims = [k for k, _p in sorted(have, key=lambda kp: (max(places[kp[0]]),
                                                                places[kp[0]][0], kp[0]))]
        order = _interleave(by_claims, by_query)
    pos = dict(have)
    ranked = [pos[k] for k in order]
    seen = {id(p) for p in ranked}
    print(f"  слот {index}: каскад — {len(ranked)} из {len(head)} кандидатов ранжированы "
          f"по описанию кадра (новых оценок {fresh})")
    return ranked + [p for p in head if id(p) not in seen] + list(candidates[n:])


# ЧИТАЕМОСТЬ КАДРА — ФИЗИКА, А НЕ СМЫСЛ. Судья оценивает кадр по описанию
# буквально и не проверяет, виден ли предмет: живой случай (эпизод 94,
# «Но именно он решал исход поединка», бриф «...sharp point catching
# light») — высшую оценку 3 получил почти чёрный кадр с тонким бликом
# иглы: средняя яркость 16 из 255, 93% пикселей почти чёрные. Гейты
# эмбеддинга (и прежняя яркостная проверка видео) стоят в ранжировании
# НИЖЕ оценки судьи, поэтому такой кадр побеждал. Ключ читаемости стоит
# ВЫШЕ судьи и нечитаемые кадры судье не показываются.
# Порог — физический и с запасом, а не подгонка: на золотом наборе
# (40 размеченных кадров опубликованного эпизода) самый тёмный ГОДНЫЙ
# кадр — 56% почти чёрных пикселей (осознанно тёмный грейд канала), брак
# в эпизоде 94 — 93%; порог 85% не задевает ни одного годного и
# терпимого кадра.
UNREADABLE_DARK_LEVEL = 25
UNREADABLE_DARK_SHARE = 0.85


def frame_readable(path):
    """1 — на кадре что-то видно, 0 — кадр почти целиком чёрный. Сбой
    чтения — 1: не проверили, значит не бракуем."""
    try:
        with PILImage.open(path) as im:
            g = im.convert("L")
            g.thumbnail((256, 256))
            h = g.histogram()
        n = sum(h)
        return 0 if n and sum(h[:UNREADABLE_DARK_LEVEL]) / n >= UNREADABLE_DARK_SHARE else 1
    except Exception:
        return 1


def judge_rank(c):
    """Ключ ранжирования по оценке судьи; нет оценки — -1."""
    v = c.get("judge")
    return v if isinstance(v, int) else -1


def spec_key_parts(spec):
    """Спецификация кадра в ключ кэша кандидата: она меняет, кого проверка
    считает лучшим, и без неё прогретый кэш отдавал бы выбор по прежней
    спецификации (или без неё)."""
    if not spec:
        return []
    return ["spec:" + hashlib.sha256(json.dumps(spec, sort_keys=True, ensure_ascii=False)
                                     .encode("utf-8")).hexdigest()[:12]]


def judge_candidates(index, kind, phrase, brief, candidates_info, spec=None):
    """Проставляет c["judge"] каждому кандидату без дубля (или никому) и
    возвращает True, если судья отработал по всему слоту."""
    for c in candidates_info:
        c["judge"] = None
        c["verify"] = None
        for k in ("_asked", "verify_focus", "verify_nothing", "verify_perfect", "world_clear"):
            c.pop(k, None)
    if index is not None and index >= SHOT_JUDGE_PAID_SLOTS:
        return False   # платная проверка — только хук (см. SHOT_JUDGE_PAID_SLOTS)
    gw = _shot_judge_gateway()
    # У видео судья смотрит ленту из трёх кадров ролика (judge_path), у
    # фото — сам кадр.
    judged = [c for c in candidates_info
              if c.get("is_dup_free") and c.get("is_readable", 1)
              and os.path.exists(c.get("judge_path") or c["path"])]
    if gw is None or not judged:
        return False
    import shot_judge
    model = shot_judge_model()
    rep = {}
    import world_card
    card = episode_world_card()
    setting = world_card.judge_setting(card)
    # Сетка спрашивает про ФОКУС спецификации фразы, если она есть: бриф
    # описывает идеальный кадр целиком («стрела отскакивает от помятого
    # нагрудника»), и в нём крупный предмет весит столько же, сколько главное.
    if spec:
        brief = spec["focus"]
    scores = shot_judge.judge(gw, model, phrase=phrase, brief=brief,
                              candidates=[(str(c["p"].get("id")), c.get("judge_path") or c["path"])
                                          for c in judged],
                              cache_dir=os.path.join(TEMP_FOLDER, "shot_judge_cache"), report=rep,
                              kind=kind, setting=setting)
    SHOT_JUDGE_LOG.append({"index": index, "kind": kind, "model": model, "brief": brief,
                           "setting": setting, "scores": scores, **rep})
    if scores is None:
        # Сетка не ответила (живой случай judge12, слот 0: шлюз четыре раза
        # подряд вернул 502) — слот раньше шёл вообще без проверки. Решает же
        # не сетка, а проверка по утверждениям: её вызовы отдельные, со своими
        # повторами. Без сетки финалисты — первые по каскаду; не ответила и
        # проверка — слот без судьи, как раньше.
        _verify_finalists(index, kind, phrase, brief, judged, gw, model, card, spec)
        if not any(c.get("verify") is not None for c in judged):
            print(f"  слот {index}: судья кадров не ответил ({rep.get('refused')}) — ранжирование без него")
            return False
        print(f"  слот {index}: сетка судьи не ответила ({rep.get('refused')}) — первые по каскаду "
              f"проверены по утверждениям")
        _judge_budget_forecast(index, gw)
        return True
    for c in judged:
        c["judge"] = scores[str(c["p"].get("id"))]
    _verify_finalists(index, kind, phrase, brief, judged, gw, model, card, spec)
    _judge_budget_forecast(index, gw)
    return True


def _judge_budget_forecast(index, gw):
    """Прогноз цены эпизода по уже потраченному; перерасход — одна громкая
    строка и запись в журнал судьи. Прогноз по оценённым слотам, поэтому
    при кэш-хитах он завышен — ошибка в сторону раннего предупреждения."""
    st = _SHOT_JUDGE_STATE
    st.setdefault("slots", set()).add(index)
    # Платно судятся только первые SHOT_JUDGE_PAID_SLOTS слотов — прогноз по ним.
    n, total = len(st["slots"]), min(SHOT_JUDGE_EPISODE_SLOTS, SHOT_JUDGE_PAID_SLOTS)
    cap = getattr(gw, "spend_cap", None)
    if st.get("warned") or not cap or total <= 0 or n < SHOT_JUDGE_FORECAST_AFTER:
        return
    projected = int(gw.spent / n * total)
    if projected <= cap:
        return
    st["warned"] = True
    at = int(cap / max(gw.spent / n, 1))
    print(f"  ВНИМАНИЕ: судья кадров — прогноз {projected} токенов баланса на эпизод "
          f"({total} слотов, ~{gw.spent // n} на слот) при потолке {cap}: судья "
          f"выключится примерно на слоте {at}, дальше кадры без него. Поднять "
          f"потолок — SHOT_JUDGE_MAX_SPEND в .env.")
    SHOT_JUDGE_LOG.append({"forecast": projected, "cap": cap, "slots": total,
                           "per_slot": gw.spent // n, "cutoff_slot": at})


# ПРОВЕРКА ФИНАЛИСТОВ ПО УТВЕРЖДЕНИЯМ СПЕЦИФИКАЦИИ (shot_judge.verify_claims,
# план 24.09 «одна спецификация кадра на фразу»). Лучшие по сетке
# VERIFY_FINALISTS кадров отвечают по одному кадру, выполнено ли каждое
# утверждение спецификации фразы (фокус и детали по убыванию важности); код
# сравнивает кадры по вектору в порядке спецификации (shot_judge.
# claims_vector): главный предмет не из мира или 3D — отказ, фокус выше
# всего, чужое на фоне — штраф. Нет спецификации — одно утверждение из
# брифа (shot_judge.spec_from_brief), путь тот же.
# Прежняя проверка («тот ли предмет: yes/close/no» + замены из плана)
# засчитала нагрудник без стрелы «близкой заменой» на фразе «Стрела
# скользит по нагруднику» — см. docs/quality/POOL_RECALL_EP94.md.
VERIFY_FINALISTS = 5
# Рассуждение модели в проверке выключено по замеру (эп.94, 223 кадра):
# без него порядок почти тот же, а вызов в разы быстрее и дешевле
# (~200 токенов баланса за кадр против ~540) и не обрывается пустым
# ответом на лимите выхода.
VERIFY_REASONING = False


def verify_finalists_of(judged, more=False):
    """Кого проверять: лучшие по сетке ∪ первые в порядке пула (порядок —
    каскад по утверждениям спецификации) ∪ все помеченные словарём запретов
    (их может пропустить на экран только проверка, см. filter_pool_by_text).
    Сетка оценивает кучки по 9 в своей шкале и шумит; кадр с главным, которому
    она поставила ниже, всё равно доходит до проверки, если каскад поставил
    его вперёд. more — следующая порция по каскаду из ещё не проверенных
    (все первые отклонены)."""
    if more:
        return [c for c in judged if not c.get("_asked")][:VERIFY_FINALISTS]
    order = sorted(range(len(judged)), key=lambda k: (-judge_rank(judged[k]), k))
    picked = order[:VERIFY_FINALISTS] + list(range(min(VERIFY_FINALISTS, len(judged))))
    picked += [k for k, c in enumerate(judged) if c["p"].get("_blocklisted")]
    return [judged[k] for k in dict.fromkeys(picked)]


# ПРЕДОХРАНИТЕЛЬ МИРА НА ЭПИЗОД. Отказ «главный предмет не из мира фразы»
# верен, пока верен паспорт и пока в источниках вообще есть кадры этого мира.
# Неверный паспорт (или ниша, где в стоках только современность, — биржевой
# крах 1929 года) превратил бы отказ в опустошение всего ролика.
#
# Голосует СЛОТ, а не кадр: слот «чужой», если больше половины его кадров с
# найденным главным отклонены по миру. Прежний счёт по кадрам срабатывал на
# ОДНОМ слоте — десять современных ножей на фразе «Вот кинжал» выключали
# отказ для всего ролика ровно там, ради чего отказ и заведён. Нужны голоса
# WORLD_BREAKER_MIN_SLOTS разных слотов и чужое большинство среди них.
# Решение берётся в начале слота и внутри слота не меняется; голоса лежат в
# media_plan/world_breaker.json под отпечатком паспорта — слоты из кэша не
# теряют голос, и повторный рендер решает так же, как первый.
WORLD_BREAKER_MIN_SLOTS = 5
WORLD_BREAKER_SHARE = 0.5
WORLD_VOTES_NAME = "world_breaker.json"


def _world_votes_path():
    return os.path.join(VIDEO_FOLDER, "media_plan", WORLD_VOTES_NAME)


def _world_votes():
    st = _SHOT_JUDGE_STATE
    if st.get("world_votes") is None:
        votes = {}
        try:
            with open(_world_votes_path(), encoding="utf-8") as f:
                data = json.load(f)
            if data.get("passport") == _world_digest_for_signature():
                votes = {int(k): bool(v) for k, v in (data.get("slots") or {}).items()}
        except Exception:  # noqa: BLE001 — нет или битый файл: голосов нет
            votes = {}
        st["world_votes"] = votes
    return st["world_votes"]


def world_veto_active():
    votes = _world_votes()
    n = len(votes)
    return not (n >= WORLD_BREAKER_MIN_SLOTS and sum(votes.values()) / n > WORLD_BREAKER_SHARE)


def _record_world_vote(index, focus_frames, foreign_frames):
    """Голос слота после всей его проверки. Слот без кадров с главным не
    голосует: там не о чем судить мир."""
    if index is None or focus_frames < 1:
        return
    was = world_veto_active()
    votes = _world_votes()
    votes[int(index)] = foreign_frames * 2 > focus_frames
    try:
        os.makedirs(os.path.dirname(_world_votes_path()), exist_ok=True)
        tmp = _world_votes_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"passport": _world_digest_for_signature(),
                       "slots": {str(k): v for k, v in sorted(votes.items())}}, f, indent=1)
        os.replace(tmp, _world_votes_path())
    except Exception:  # noqa: BLE001 — не записалось: решение прогона всё равно в памяти
        pass
    if was and not world_veto_active():
        foreign = sum(votes.values())
        print(f"  ВНИМАНИЕ: в {foreign} слотах из {len(votes)} проверка отклонила по миру большинство "
              f"кадров, где главное найдено. Паспорт мира не совпадает с тем, что есть в "
              f"источниках (или сам паспорт неверен) — дальше «чужой мир» штрафуется, а не "
              f"отклоняется. Проверь media_plan/world_card.json.")
        SHOT_JUDGE_LOG.append({"world_breaker": True, "slots": len(votes), "foreign": foreign})


def _verify_finalists(index, kind, phrase, brief, judged, gw, model, card, spec=None):
    """c["verify"] финалистам: вектор утверждений или "veto";
    c["verify_focus"] — найдено ли главное; c["verify_nothing"] — не найдено
    ничего обязательного; c["world_clear"] — мир проверен и чист. Все
    финалисты отклонены по миру — проверяется следующая порция по каскаду.
    Сбой проверки кадра — None: кадр стоит ниже проверенных, но не
    бракуется."""
    import shot_judge
    import world_card
    spec = spec or shot_judge.spec_from_brief(phrase, brief)
    # Мир — отдельным вопросом без фразы, один на картинку, со списком
    # чужих культур паспорта (замер 24.09, 223 размеченных кадра эп.94, по
    # два прогона): верных пар 75-78% -> 81-82%, лучший кадр слота 6-7 -> 8
    # из 9, годных отклонено 4-7 -> 4; цена замера +27%. Список культур
    # внутри вопроса по утверждениям — хуже (749 пар, 11 годных отклонено:
    # пластинчатый доспех читался как азиатский); мир отдельно без списка —
    # 6 из 9, современный нож остаётся.
    setting = world_card.claims_setting(card)
    cg_veto = world_card.is_historical(card)
    cache = os.path.join(TEMP_FOLDER, "shot_judge_cache")
    world_veto = world_veto_active()
    focus_frames = foreign_frames = 0

    def ask(c):
        frames = len(c.get("frames") or []) or None
        return shot_judge.verify_claims(gw, model, phrase=phrase, spec=spec, setting=setting,
                                        path=c.get("judge_path") or c["path"], kind=kind,
                                        cache_dir=cache, reasoning=VERIFY_REASONING,
                                        caption=candidate_caption(c.get("p")), frames=frames,
                                        world_separate=True)

    for more in (False, True):
        finalists = verify_finalists_of(judged, more)
        if not finalists:
            break
        with concurrent.futures.ThreadPoolExecutor(max(1, len(finalists))) as ex:
            got = list(ex.map(ask, finalists))
        verified = vetoed = 0
        for c, (ans, info) in zip(finalists, got):
            c["_asked"] = True
            if ans is None:
                continue
            focus = shot_judge.focus_met(spec, ans)
            if focus:
                focus_frames += 1
                foreign_frames += 1 if ans.get("main_in_world") is False else 0
            vec = shot_judge.claims_vector(spec, ans, world_veto=world_veto, cg_veto=cg_veto)
            c["verify"] = "veto" if vec is None else vec
            c["verify_focus"] = focus
            c["verify_nothing"] = shot_judge.nothing_met(spec, ans)
            c["verify_perfect"] = vec is not None and shot_judge.musts_met_clean(spec, ans)
            c["world_clear"] = shot_judge.world_clear(ans)
            verified += 1
            # «Ничего обязательного не найдено» — такой же брак для решения о
            # следующей порции, как отказ: иначе слот уходил на вторую
            # страницу пула (новая сетка и новая проверка), не проверив
            # остальных кандидатов первой.
            vetoed += 1 if vec is None or c["verify_nothing"] else 0
            SHOT_JUDGE_LOG.append({"index": index, "kind": kind, "model": model,
                                   "id": str(c["p"].get("id")), "verify": ans, "vector": vec, **info})
            if vec is None:
                print(f"  слот {index}: проверка отклонила кадр — {ans.get('why')}")
        if not verified or vetoed < verified:
            break
        # Все проверенные отклонены: одна следующая порция по каскаду, а не
        # непроверенный кандидат из того же пула. Отклонена и она — слот
        # честно брак (judge_rejected победителя), его поглощает сосед.
    _record_world_vote(index, focus_frames, foreign_frames)


def candidate_caption(p):
    """Подпись кандидата для проверки финалиста: текст источника (alt, слаг,
    теги, название) плюс паспорт музейного предмета — годы и культура.
    Паспорт до этого места не доходил вовсе: он решал только, пустить ли
    предмет в пул."""
    if not isinstance(p, dict):
        return ""
    text = pexels_candidate_text(p)
    meta = p.get("_museum_meta") or {}
    extra = []
    if meta.get("begin") or meta.get("end"):
        extra.append(f"dated {meta.get('begin')}-{meta.get('end')}")
    if meta.get("culture"):
        extra.append(str(meta["culture"]))
    return (text + ("; " + ", ".join(extra) if extra else "")).strip()


def verify_key(c):
    """Ключ ранжирования проверки финалиста. Отказ и «ничего обязательного не
    найдено» — ниже непроверенного: проверенный брак не должен обгонять
    кадр, который проверка просто не видела. Проверки не было ни у кого — у
    всех одно значение, порядок прежний."""
    v = c.get("verify")
    if v == "veto":
        return (-9,)
    if not isinstance(v, tuple):
        return (-1,)
    if c.get("verify_nothing"):
        return (-5,)
    return v

def shot_judge_signature(index=None):
    """Кто судит кадры в этом прогоне — входит в подпись отбора: включение
    судьи, смена модели или вопроса меняют победителя, и без подписи
    прогретый кэш кандидатов отдавал бы выбор, сделанный без судьи. Наличие
    ключа входит сюда же: без ключа судья не работает вовсе. Шлюз при этом
    не создаётся — подпись не должна печатать и не ходит в сеть.

    Судья не работает (флаг выключен или нет ключа) — пустая строка: отбор
    тогда байт-в-байт прежний, и менять ключи кэша значило бы заставить
    владельца без ключа перекачать эпизод ради изменения, которого нет.
    Слот вне платной зоны (index >= SHOT_JUDGE_PAID_SLOTS) — тоже пустая
    строка: судья его не видит."""
    if not shot_judge_active(index):
        return ""
    import inspect
    import shot_judge
    import world_card
    # Логика ранжирования и вопроса — исходником, а не номером версии,
    # который забывают поднять: правка любой из этих функций меняет
    # победителя, и прогретый кэш не должен отдавать прежний выбор.
    logic = hashlib.sha256("".join(inspect.getsource(f) for f in (
        shot_judge.claims_vector, shot_judge.claim_values, shot_judge.focus_met,
        shot_judge.nothing_met, shot_judge.musts_met_clean, shot_judge.asked_claims,
        shot_judge.claims_question, _verify_finalists, verify_finalists_of, verify_key,
        judge_candidates, judge_rejected, judge_approved, screen_allowed, claims_checked,
        filter_pool_by_text,
        blocklist_clearable, world_veto_active, _record_world_vote,
        cascade_texts, cascade_claims, _interleave, cascade_reorder, world_card.claims_setting,
        shot_judge.world_only_question, shot_judge.world_of_image)).encode("utf-8")
        + shot_judge.CLAIMS_PROMPT.encode("utf-8")
        + shot_judge.WORLD_ONLY_PROMPT.encode("utf-8")).hexdigest()[:12]
    return repr(("judge", shot_judge_model(), shot_judge.PROMPT_VERSION, SHOT_JUDGE_MIN_SCORE,
                 "cascade", cascade_preview_n(), "claims", shot_judge.CLAIMS_VERSION, logic,
                 shot_judge.VERIFY_MAX_SIDE, VERIFY_FINALISTS, VERIFY_REASONING,
                 "world_veto", world_veto_active(),
                 "readable",
                 UNREADABLE_DARK_LEVEL, UNREADABLE_DARK_SHARE))


# ПЛАТНАЯ ПРОВЕРКА — ТОЛЬКО ХУК (решение владельца 24.09). Судья стоит денег
# на каждом слоте; первые 25 слотов — хук, самое дорогое место по удержанию.
# Дальше слоты идут бесплатным путём (пул, гейты, физические проверки) — и
# подпись судьи в их ключи кэша не входит: смена модели судьи не должна
# перекачивать слоты, которые судья не видит.
SHOT_JUDGE_PAID_SLOTS = 25


def shot_judge_active(index=None):
    """Судья для слота index (None — вообще в прогоне) возможен: флаг, ключ
    и слот в платной зоне. Без сети."""
    if index is not None and index >= SHOT_JUDGE_PAID_SLOTS:
        return False
    return (feature_flags.enabled("SHOT_JUDGE")
            and bool((os.environ.get("LLM_GATEWAY_API_KEY") or "").strip()))


def winner_quality(c):
    """Качество победителя для сравнения видов: (ключ проверки, оценка сетки,
    совершенен ли). Судьи не было — None."""
    if c is None:
        return None
    g = c.get("judge")
    if not isinstance(g, int) and not isinstance(c.get("verify"), (tuple, str)):
        return None
    return (verify_key(c), g if isinstance(g, int) else -1, bool(c.get("verify_perfect")))


def _as_quality(score):
    """Оценка сетки (int) или качество (tuple) -> сравнимое качество."""
    import shot_judge
    if score is None:
        return None
    if isinstance(score, int):
        return ((-1,), score, score >= shot_judge.SCORE_MAX)
    score = tuple(score)
    return (tuple(score[0]), score[1], bool(score[2]) if len(score) > 2 else False)


def quality_approved(q):
    """Одобрено: проверка нашла главное в своём мире (элементы вектора 0 —
    мир, 1 — главное); без проверки — оценка сетки."""
    v, g = q[0], q[1]
    if v == (-1,):
        return g >= SHOT_JUDGE_MIN_SCORE
    return len(v) > 1 and v[0] >= 1 and v[1] >= 1


def quality_perfect(q):
    """Второй вид добывать незачем: все обязательные утверждения выполнены,
    мир свой, фон чист; без проверки — высшая оценка сетки."""
    return bool(q and q[2])


def pick_kind_by_judge(first_kind, first_score, other_score, prefer_video):
    """Какой вид медиа ставить в слот, когда добыты оба: фото и видео.

    Решает проверка: вектор утверждений спецификации одной фразы у обоих
    видов одинаковой длины и в одном порядке, а движение фото выполнить не
    может физически (shot_judge.asked_claims) — поэтому видео, где главное
    видно в движении, обходит фото, а фото с главным обходит видео без него,
    ровно в том порядке важности, что задала спецификация. Равные — прежнее
    правило вида. У второго вида нет оценки — он берётся, только если первый
    не одобрен: неизвестное лучше известного брака, известное годное — нет.
    Возвращает "photo" или "video"."""
    other_kind = "video" if first_kind == "photo" else "photo"
    first, other = _as_quality(first_score), _as_quality(other_score)
    if first is None:
        return first_kind
    if other is None:
        return other_kind if not quality_approved(first) else first_kind
    if other[:2] != first[:2]:
        return other_kind if other[:2] > first[:2] else first_kind
    return "video" if prefer_video else "photo"


def judge_rejected(c):
    """Кадр — брак: отказ проверки (главный предмет не из мира, 3D в
    историческом эпизоде), не выполнено НИ ОДНО обязательное утверждение,
    помечен словарём запретов и не очищен проверкой мира; без проверки —
    оценка сетки ниже порога. Кадр без главного, но с обязательной деталью,
    — не брак: он остаётся ближайшей заменой (focus_met=False в отчёте)."""
    if c is None:
        return True
    if c["p"].get("_blocklisted") and not c.get("world_clear"):
        return True
    v = c.get("verify")
    if v == "veto":
        return True
    if isinstance(v, tuple):
        return bool(c.get("verify_nothing"))
    return not (isinstance(c.get("judge"), int) and c["judge"] >= SHOT_JUDGE_MIN_SCORE)


def judge_approved(c):
    """Кадр одобрен судьёй: проверка нашла главное; без проверки — оценка
    сетки не ниже порога."""
    if c is None or judge_rejected(c):
        return False
    if isinstance(c.get("verify"), tuple):
        return bool(c.get("verify_focus"))
    return True


def claims_checked(c):
    """Кадр проверен по утверждениям спецификации (или одобрен сеткой): более
    слабая вторая проверка эмбеддингом его решение не перебивает."""
    return isinstance((c or {}).get("verify"), tuple) or judge_approved(c)


def screen_allowed(c):
    """Может ли кандидат вообще стоять на экране: помеченный словарём
    запретов — только если проверка мира на этом кадре состоялась и чиста."""
    return 0 if (c["p"].get("_blocklisted") and not c.get("world_clear")) else 1


def video_smart_relevance_veto(video_path, query):
    """То же, что smart_relevance_veto(), но для ВИДЕО-победителя: своей
    картинки у видео нет, поэтому берётся один кадр-пробник (та же функция
    и та же точка t=0.5, что уже использует plain_fallback-пересчёт
    релевантности чуть выше — вторая формула того же момента не заводится).
    Пробник удаляется сразу после использования в любом случае."""
    if not feature_flags.enabled("SMART_RELEVANCE_VETO"):
        return False
    probe, cleanup = extract_video_probe_frame(video_path)
    if probe is None:
        return False
    try:
        return smart_relevance_veto(probe, query)
    finally:
        if cleanup and os.path.exists(probe):
            try:
                os.remove(probe)
            except OSError:
                pass


# Версия ПРАВИЛ гейта, которые живут НЕ внутри перечисленных в
# candidate_gate_signature() функций, а в месте их ВЫЗОВА (pexels_photo/
# pexels_video) — inspect.getsource() таких изменений не видит, и без явного
# маркера правка правила молча не инвалидировала бы уже закэшированного
# кандидата, отобранного по старому правилу (ровно тот класс бага, который
# эта подпись и создавалась закрывать, см. её докстринг).
# 2 -> гейт релевантности сверяет кандидата с запросом ЕГО БЛОКА, а не с тем
#      запросом пула, из которого кандидат приплыл (28 августа, см. разбор у
#      вызова is_relevant_candidate() в pexels_photo()).
CANDIDATE_GATE_RULES_VERSION = 2

_CANDIDATE_GATE_SIG = None   # см. candidate_gate_signature(), считается лениво один раз


def media_sidecar_path(media_path):
    """Путь к sidecar-метаданным кэшированного кандидата: <файл>.meta.json."""
    return media_path + ".meta.json"


def write_media_sidecar(media_path, *, pexels_id=None, query=None, kind=None,
                        ahash_hex=None, relevance=None, chosen_by=None,
                        provenance=None, quality=None):
    """Записать, ЧТО именно лежит в кэш-файле кандидата.

    РЕАЛЬНАЯ, найденная вживую дыра (04.09), которую это закрывает: имя
    кэш-файла кодирует только (слот, хэш запроса, хэш правил гейта) — по нему
    невозможно узнать ни Pexels-ID кадра, ни его визуальный хэш. Следствия:

    1. N8 из docs/AUDIT_2026-09_DEEP.md: на кэш-хите ID не регистрировался в
       used_ids, и анти-дубль ПО ID был мёртв для всех закэшированных слотов.
    2. Хуже: когда кэширован сам КЛИП (temp_smart/clip_*.mp4), функция подбора
       вообще не вызывается, и слот не попадает ни в used_ids, ни в
       used_hashes. На частичном ре-рендере (161 клип из 165 — кэш-хиты)
       структуры дедупа оказываются почти пустыми, и любой заново подбираемый
       слот спокойно берёт кадр, уже стоящий в другом месте ролика. Так в
       опубликованном эпизоде появился дубль: одна и та же фотография
       (Pexels 31474665) на 58-й секунде и на 11-й минуте.

    Sidecar пишется рядом с файлом и переживает любые кэш-хиты, потому что
    живёт ровно столько же, сколько сам файл. Ошибка записи не критична —
    метаданные вспомогательные, потерять кадр из-за них было бы хуже, чем
    остаться без ID (тот же fail-open, что у остальных необязательных слоёв).
    """
    try:
        payload = {"pexels_id": pexels_id, "query": query, "kind": kind,
                   "ahash": ahash_hex, "relevance": relevance,
                   "chosen_by": chosen_by, "written_at": time.time()}
        # Провенанс переживает кэш-хит ровно потому, что лежит рядом с
        # файлом: на повторном прогоне подбор не вызывается вообще, и
        # другого места, где происхождение кадра ещё известно, нет.
        if provenance:
            payload["provenance"] = provenance
        # Оценка проверки кадра: на повторном рендере кадр берётся из кэша
        # без проверки, и без записанной оценки выбор «фото или видео»
        # сравнивал бы свежую оценку одного вида с пустотой у другого —
        # и мог поставить в слот вид, который в прошлый раз проиграл.
        if quality is not None:
            payload["quality"] = quality
        tmp = media_sidecar_path(media_path) + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False)
        os.replace(tmp, media_sidecar_path(media_path))
    except Exception:
        pass


_LICENSE_MANIFEST_SEEN = set()


def candidate_provenance(p):
    """Происхождение кандидата в едином виде — или None для обычного стока.

    Музеи и Openverse кладут в кандидата `_museum_meta`/`_openverse_meta`
    (эпоха, культура, лицензия, страница предмета). До этой правки оба поля
    ставились и не читались НИ ОДНОЙ строкой кода: комментарий у
    _openverse_meta прямо обещал «пригодится, если кандидат победит и
    понадобится атрибуция/аудит источника», но забирать их было некому.
    Следствие не юридическое (берётся только CC0 и public domain, атрибуция
    не требуется по решению владельца), а следственное: по готовому ролику
    нельзя было ответить, из какого архива пришёл конкретный кадр — а именно
    это нужно, если источник однажды промаркирует чужую работу ошибочно.

    Юридический след при этом СУЩЕСТВОВАЛ, но только в
    stock_fetch_multisource.py (Шаг 4, ручной мультисток) — то есть не на том
    пути, которым эти кандидаты реально попадают в эпизод.
    """
    if not isinstance(p, dict):
        return None
    shelf = p.get("_shelf_meta")
    meta = p.get("_museum_meta") or p.get("_openverse_meta") or shelf
    if not meta:
        return None
    out = {"id": p.get("id"), "title": p.get("alt") or None,
           "page": p.get("url") or None,
           # КАНАЛ, а не пространство id: у кандидата полки id обязан
           # остаться `met:<objectID>`/`euro:/...`, и без этого поля
           # запись о происхождении не отвечала бы на вопрос, каким путём
           # кадр найден.
           "channel": candidate_channel(p)}
    if meta is shelf:
        # ПРОБЕЛ, найденный разбором собственной правки 15.09: кандидат
        # ВИЗУАЛЬНОЙ ПОЛКИ нёс только `_shelf_meta`, а сюда смотрели ровно
        # два других поля — то есть победивший кадр полки уходил в ролик
        # БЕЗ единой строки о происхождении: ни записи в
        # `source_license_manifest.jsonl`, ни ссылки на предмет в шотлисте.
        # Докстринг этой же функции объясняет, зачем след вообще нужен —
        # «если источник однажды промаркирует чужую работу ошибочно», — а
        # у второго корпуса полки основание публикации как раз самое
        # слабое из всех: Public Domain Mark это не отказ от прав, а
        # пометка «ограничений не известно» (см. докстринг
        # europeana_corpus). То есть след пропадал ровно там, где он
        # нужнее всего. Проверено прогоном до правки:
        # candidate_provenance(кандидат_полки) -> None.
        meta = {k: v for k, v in meta.items() if k != "score"}
    out.update({k: v for k, v in meta.items() if v not in (None, "", {})})
    return out


def log_candidate_license(provenance, query):
    """Дописать происхождение победившего кадра в журнал эпизода.

    Append-only, по одной строке на кандидата: перезапись целиком повторила
    бы уже описанную дыру merge_slot_report() — на частичном ре-рендере
    журнал остался бы почти пустым, хотя кадры в ролике те же. Повтор в
    пределах прогона гасится по id. Ошибка записи не роняет подбор: потерять
    кадр из-за строчки в журнале хуже, чем потерять строчку.
    """
    if not provenance:
        return
    key = str(provenance.get("id"))
    if key in _LICENSE_MANIFEST_SEEN:
        return
    try:
        d = os.path.join(VIDEO_FOLDER, "media_plan")
        os.makedirs(d, exist_ok=True)
        row = dict(provenance, query=query, logged_at=time.time())
        with open(os.path.join(d, "source_license_manifest.jsonl"),
                  "a", encoding="utf-8") as f:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
        _LICENSE_MANIFEST_SEEN.add(key)
    except Exception:
        pass


def _restore_cached_quality(cf):
    """Оценка проверки кадра из кэша -> заметка попытки (см. quality в
    write_media_sidecar). Нет записи — заметки нет, как раньше."""
    q = read_media_sidecar(cf).get("quality")
    if q is not None:
        try:
            selection_attempt.record_note("quality", _as_quality(q))
        except Exception:  # noqa: BLE001 — вне попытки (прямой вызов): нечего помечать
            pass


def read_media_sidecar(media_path):
    """Прочитать sidecar кандидата. Нет файла/битый JSON -> {} (не исключение).

    Отсутствие sidecar — норма для кэша, скачанного ДО появления этого
    механизма: старые файлы просто не дают ID, и дедуп по ID для них работает
    как раньше (никак), а дедуп по aHash считается на месте от самого файла.
    """
    try:
        with open(media_sidecar_path(media_path), "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def register_cached_media(media_path, used_ids=None, used_hashes=None, kind="photo"):
    """Вернуть уже стоящий в ролике кадр в структуры анти-дубля.

    Вызывается там, где медиа НЕ проходит подбор заново — на кэш-хите клипа в
    main() и на кэш-хите кандидата. Без этого вызова дедуп видит только слоты,
    реально пересобранные в текущем прогоне (см. write_media_sidecar()).

    ID берётся из sidecar (если он есть), aHash — из sidecar, а при его
    отсутствии считается прямо от файла: для фото это дёшево и работает даже
    на старом кэше без метаданных. Для видео aHash по файлу здесь НЕ считается
    сознательно — нужен прогон ffmpeg за кадром-пробником, а это заметная цена
    на каждом кэш-хите ради вторичной проверки; видео дедуплицируется по ID из
    sidecar. Возвращает True, если удалось зарегистрировать хоть что-то.

    Регистрирует в ТЕКУЩУЮ попытку (selection_attempt), а применяет коммит:
    вернуть кадр в анти-дубль — такое же изменение состояния эпизода, как и
    выбрать его, и у него та же единственная точка применения.
    """
    meta = read_media_sidecar(media_path)
    done = False
    pid = meta.get("pexels_id")
    if used_ids is not None and pid is not None:
        selection_attempt.record_effect("reserve_id", used_ids, pid)
        done = True
    if used_hashes is not None:
        h = meta.get("ahash")
        if h is None and kind == "photo":
            try:
                h = ahash(media_path)
            except Exception:
                h = None
        if h is not None:
            selection_attempt.record_effect("reserve_hash", used_hashes, h)
            done = True
    return done


def _selection_stack_signature():
    """Отпечаток КОНФИГУРАЦИИ отбора: какие слои реально решают, кто победит,
    и из какого по размеру пула они выбирают. Входит в
    candidate_gate_signature() -> в имя файла кэша кандидата.

    РЕАЛЬНЫЙ, измеренный симптом, ради которого это заведено (04.09, разбор
    опубликованного эпизода 01_ves-mecha): candidate_gate_signature() хэшировала
    ФУНКЦИИ гейтов и ПОРОГИ, но не режимы. Значит включение VLM-арбитра или
    Semantic Visual Director (.env: VISUAL_DIRECTOR_MODE=assist,
    VLM_ARBITER_MODE=on) НЕ меняло ключ кэша ни одного слота — уже скачанный
    кандидат, выбранный ДО появления этих слоёв голым косинусом эмбеддингов,
    молча отдавался как есть при каждом следующем прогоне. Готовый эпизод —
    лоскутное одеяло решений разных поколений системы, замороженных в момент
    первого скачивания. Это и есть прямой источник жалобы "то работает, то не
    работает": соседние слоты объективно выбраны разными алгоритмами.

    Тот же класс бага, что уже закрыт для РЕНДЕРА (render_recipe_signature() +
    _look_management_cache_signature()/_visual_director_cache_signature()/
    arbiter_cache_suffix() в params_hash, см. main()) — рендер-сторона
    инвалидируется при смене режима, сторона ОТБОРА не инвалидировалась. Здесь
    та же дисциплина переносится на отбор.

    Размер пула — в том же отпечатке и по той же причине: FAST_MODE_START_INDEX
    (после него DIRECTOR_MIN_POOL 8->2, PHOTO_DEDUP_MAX_TRIES 20->5) физически
    определяет, из скольких кандидатов вообще шёл выбор. Кадр, выбранный из
    двух, и кадр, выбранный из восьми — решения разной силы, и переиспользовать
    первое после расширения пула значит молча остаться на более бедном выборе.

    SHOT_DIRECTOR_MODE сюда СОЗНАТЕЛЬНО НЕ включён (проверено по коду, не
    предположение): он влияет только на ТЕКСТ запроса, а запрос и весь пул
    запросов секции уже входят в qkey/qhash имени кэш-файла (см. pexels_photo()
    у qkey). Включение/выключение режима меняет запрос -> меняет qhash ->
    инвалидация происходит и без него. Добавить его сюда значило бы гарантированно
    перекачивать весь эпизод на каждое переключение флага, ничего при этом не
    исправляя.

    Читается В МОМЕНТ ВЫЗОВА (не на импорте) — как и весь остальной код,
    работающий с реестром режимов."""
    return "sel:" + repr((
        feature_flags.mode("VLM_ARBITER_MODE"),
        feature_flags.mode("VISUAL_DIRECTOR_MODE"),
        DIRECTOR_MIN_POOL, PHOTO_DEDUP_MAX_TRIES, BASE_MIN_POOL, FAST_BASE_MIN_POOL,
        # Ранжирование среди прошедших гейты (корзина relevance до эстетики) и
        # чередование источников внутри запроса — оба меняют, КТО побеждает,
        # при тех же гейтах; без подписи на прогретом temp_smart/ правка не
        # дошла бы до экрана (13.09, A/B на 9 слотах эпизода 02).
        RELEVANCE_RANK_BUCKET, POOL_SOURCE_INTERLEAVE_VERSION, SHOT_TYPE_ROUTING_VERSION,
        # Слияние формулировок меняет ПОРЯДОК кандидатов в пуле, то есть
        # какие BASE_MIN_POOL из них вообще дойдут до оценки — ровно тот
        # же класс изменения, что чередование источников выше.
        feature_flags.enabled("QUERY_FUSION"), query_fusion.QUERY_FUSION_VERSION,
        # В музей уходит авторский запрос, а не уточнённый — другой
        # состав музейных кандидатов, без подписи правка не дошла бы
        # до экрана на прогретом temp_smart/.
        MUSEUM_RAW_QUERY_VERSION,
        # ДЕЙСТВУЮЩАЯ граница (не пол): у эпизода с длинным хуком она другая,
        # а значит другой и размер пула, из которого выбран победитель.
        _FAST_MODE_START, FAST_DIRECTOR_MIN_POOL, FAST_PHOTO_DEDUP_MAX_TRIES,
        # Видео — общее ядро (VideoAdapter): пул оценки по превью и версия
        # устройства видео-пути вместо прежних бюджетов скачиваний.
        VIDEO_PREVIEW_POOL, VIDEO_ENGINE_VERSION,
        # Openverse — НОВЫЙ ИСТОЧНИК кандидатов, конкурирующий с Pexels в том
        # же пуле (см. _openverse_search_photos). Включение архивов меняет
        # состав пула для уже закэшированного слота так же, как включение
        # VLM-арбитра/Директора меняет то, кто в нём победит — без этого
        # флага здесь переключение OPENVERSE_ENABLED на прогретом temp_smart/
        # не доходило бы до экрана: победитель остался бы старым файлом.
        feature_flags.enabled("OPENVERSE_ENABLED"),
        # Каскад запросов к архивам: до него архивная ветка возвращала ноль
        # кандидатов на длинных запросах (замер — 0 на 8 из 8 сломанных
        # запросов эпизода 02), то есть меняет САМ СОСТАВ пула, а не только
        # ранжирование внутри него.
        OPENVERSE_QUERY_CASCADE_VERSION,
        # Прямые API музеев — НОВЫЙ источник кандидатов с известной эпохой,
        # меняет состав пула так же, как включение Openverse.
        feature_flags.enabled("MUSEUM_SOURCES_ENABLED"),
        MUSEUM_SOURCES_VERSION,
        # ПАСПОРТ МИРА ЭПИЗОДА. Меняет якорь, который подставляется в КАЖДЫЙ
        # запрос из брифа и в каскад архивов, то есть меняет сам текст
        # запроса и состав пула у всех источников сразу. Без подписи смена
        # паспорта (или его появление) не дошла бы до экрана на прогретом
        # temp_smart/ — тот же класс, что уже закрыт для Openverse и музеев.
        # В подпись входят ЯКОРЯ И ПОРОГ КУЛЬТУРЫ, а не весь файл: правка
        # `notes` не обязана перерендеривать эпизод целиком.
        era_anchors_effective(),
        # Вторая проверка победителя (SigLIP2+Jina поверх CLIP, см. блок-
        # комментарий у smart_relevance_veto()) применяется ПОСЛЕ отбора,
        # но кэш-хит отдаёт файл раньше, чем эта проверка вообще вызвана —
        # без подписи включение флага (или смена порога) не дошло бы до
        # уже закэшированных слотов.
        feature_flags.enabled("SMART_RELEVANCE_VETO"), SMART_RELEVANCE_THRESHOLD,
        # Запрос из брифа — НОВЫЙ запрос в пуле слота, то есть другой состав
        # кандидатов у каждого источника. Без подписи это не дошло бы до
        # экрана на прогретом temp_smart/.
        BRIEF_STOCK_QUERY_VERSION,
        BRIEF_STOCK_QUERY_MAX_WORDS,
        # Визуальная полка — источник, который приносит В ПУЛ ДРУГИХ
        # кандидатов на тот же запрос (сравнение идёт с изображениями, а не
        # со словами описания). Без подписи включение полки на прогретом
        # temp_smart/ не дошло бы до экрана: клип уже отрендерен по
        # кандидату, выбранному до неё.
        feature_flags.enabled("SHELF_INDEX"),
        shelf_index_version(),
        SHELF_SEARCH_LIMIT,
        # Pixabay/Unsplash — ровно та же причина, что у двух флагов выше:
        # включение источника меняет СОСТАВ пула, а значит и победителя, и
        # без подписи такая смена на прогретом temp_smart/ не дошла бы до
        # экрана вообще (кандидат уже выбран и закэширован).
        feature_flags.enabled("PIXABAY_ENABLED"),
        feature_flags.enabled("UNSPLASH_ENABLED"),
        # Ступень «негодное видео -> фотография» меняет САМ ТИП медиа в слоте,
        # то есть то, что реально увидит зритель. Ключ клипа считается до
        # резолва медиа — без флага здесь на прогретом temp_smart/ в слоте
        # осталось бы прежнее видео.
        feature_flags.enabled("VIDEO_PHOTO_RESCUE"),
        # Лестница фолбэков меняет то, ЧТО реально окажется в слоте, а не
        # только то, как выбирается кандидат. Ключ клипа считается ДО
        # резолва медиа, поэтому без флага здесь включение карточек не
        # доходило бы до экрана на прогретом temp_smart/ вообще.
        feature_flags.enabled("FALLBACK_CARD"),
        FALLBACK_CARD_MAX_SHARE, FALLBACK_CARD_MIN_GAP,
        FALLBACK_CARD_BUDGET_VERSION,
        # Видео-путь получил тот же compute_extra_score(), что и фото (см.
        # VIDEO_DIRECTOR_SCORE_VERSION выше) — меняет, кто побеждает среди
        # уже прошедших гейты видео-кандидатов, без флага здесь смена
        # алгоритма ранжирования не дошла бы до экрана на прогретом кэше.
        VIDEO_DIRECTOR_SCORE_VERSION,
        # Порядок ключей кортежа _score_and_pick(): is_relevant выше size_ok
        # (14.09) — другой победитель на том же пуле.
        RANKING_ORDER_VERSION,
    )) + _aesthetic_selection_suffix()


def _aesthetic_selection_suffix():
    """Хвост подписи отбора для ВЫКЛЮЧЕННОЙ эстетики — и только для неё.

    РЕАЛЬНЫЙ, проверенный по коду дефект (найден внешним разбором 18.09,
    подтверждён grep'ом): aesthetic_score() участвует в ранжировании
    прошедших гейты кандидатов (_score_and_pick()), то есть напрямую решает,
    КТО победит в слоте. Но AESTHETIC_SCORE не входил ни в одну подпись:
    ни в _selection_stack_signature(), ни в candidate_gate_signature().
    Следствие ровно то же, что уже было закрыто для VISUAL_DIRECTOR_MODE и
    VLM_ARBITER_MODE выше: на прогретом temp_smart/ выключение эстетики не
    доходило до экрана вообще — кандидат уже выбран и закэширован, клип
    берётся по os.path.exists(out) -> continue ДО переподбора. То есть флаг,
    существующий ради ответа на вопрос «не эстетика ли побеждает смысл»,
    у того, кто уже отрендерил эпизод, был неработающим.

    Почему суффиксом, а не ещё одним полем кортежа выше: при ДЕФОЛТЕ
    (AESTHETIC_SCORE=1, эстетика включена) подпись обязана остаться
    байт-в-байт прежней, иначе сама эта правка перерендерила бы весь
    прогретый кэш у каждого, кто флаг никогда не трогал — «апгрейд плюс
    полный перерендер», а не апгрейд. Тот же приём и та же причина, что у
    arbiter_cache_suffix() в main() и у KENBURNS_ADAPTIVE_CANVAS в
    render_recipe_signature()."""
    return "" if AESTHETIC_ENABLED else "|aesthetic:off"


def candidate_gate_signature(index=None):
    """Отпечаток ПРАВИЛ ОТБОРА кандидата (relevance/анахронизм-гвард/
    дизамбигуация запроса) — входит в имя файла кэша temp_smart/pexels_cache
    и temp_smart/pexels_video_cache.

    РЕАЛЬНЫЙ, найденный вживую на Шаге 7.5 баг (QC теста videos/_test20s,
    27 августа): pexels_photo()/pexels_video() кэшируют скачанный файл по
    ключу "{индекс_слота}_{хэш_запроса}" и на кэш-хите отдают его СРАЗУ
    (см. комментарий "size>0, не просто exists" в обеих функциях) — ни
    is_relevant_candidate(), ни video_domain_guard_violation() на кэш-хите
    вообще не вызываются повторно. На практике: слот с запросом "sword
    blade close up" закэшировал кадр восточноазиатской катаны (видео
    0004_a29e160f.mp4, скачано 23 августа) ДО того, как в этот файл попал
    multi-frame video-domain-guard (более поздняя правка той же сессии) —
    и при каждом следующем прогоне ЭТОГО ЖЕ эпизода отдавался как есть,
    потому что улучшение проверки не меняло ключ кэша: анахронизм пережил
    свой собственный фикс. render_recipe_signature() уже решает ровно этот
    класс бага для temp_smart/clip_*.mp4 (визуальный РЕЦЕПТ рендера) — эта
    функция то же самое для temp_smart/pexels_cache и
    temp_smart/pexels_video_cache (правила ОТБОРА кандидата, другой этап
    пайплайна, другой кэш, тот же класс проблемы).

    Инвалидация грубая (правка любой из перечисленных функций/констант —
    даже строчки комментария внутри — считается сменой правил): та же
    осознанно консервативная сторона, что у render_recipe_signature() —
    лишняя перезакачка дешевле молча просроченного анахронизм-гварда.
    Сбой inspect -> стабильная заглушка, поведение как раньше, без падения.

    Хэшируются ТРИ разные вещи, не одна: (1) исходники функций-гейтов,
    (2) пороги/таблицы-константы, (3) _selection_stack_signature() — режимы
    слоёв, реально выбирающих победителя, и размер пула, из которого он
    выбирался (см. её докстринг: без пункта 3 включение VLM-арбитра и
    Semantic Visual Director не инвалидировало ни одного слота, и эпизод
    собирался из решений разных поколений системы)."""
    global _CANDIDATE_GATE_SIG
    if _CANDIDATE_GATE_SIG is not None:
        return _with_judge_signature(_CANDIDATE_GATE_SIG, index)
    try:
        import inspect
        parts = [inspect.getsource(f) for f in (
            is_relevant_candidate, visual_domain_guard_violation,
            # Видео судится покадрово по превью источника: какие кадры
            # (video_preview_urls) и как (video_frames_violate) — правило
            # отбора, как и гварды выше.
            video_preview_urls, video_frames_violate,
            disambiguate_search_query, _qualifier_fits_world,
            # Сопоставление термина правила с запросом — ОТДЕЛЬНАЯ функция, и
            # без неё здесь правка «как ищем термин» (составные слова,
            # британское написание, ловушки) не меняла бы подпись, то есть на
            # прогретом кэше не дошла бы до экрана. Тот же класс пробела, что
            # уже описан выше: список терминов в подписи был, а логика его
            # применения — нет.
            query_mentions_term,
            is_risky_query,
            # image_sharpness_score/video_sharpness_ok — резкость кандидата
            # (PHOTO_SHARPNESS_REJECT/VIDEO_SHARPNESS_REJECT) — ТОЖЕ правило
            # отбора, хоть и не внутри is_relevant_candidate() самой (вызывается
            # отдельно в pexels_photo()/pexels_video()) — тот же класс пробела,
            # что уже описан в докстринге этой функции выше (анахронизм пережил
            # свой фикс) — без явного перечисления здесь правка порога/формулы
            # резкости молча не инвалидировала бы уже закэшированный размытый
            # кандидат, отобранный до этого фикса (реальный случай — слот 7,
            # videos/_test20s, 27 августа).
            image_sharpness_score, video_sharpness_ok,
            # _selection_stack_signature() ниже — РЕЖИМЫ и РАЗМЕР ПУЛА, а не
            # функции; см. её докстринг, там же разбор реального симптома.
            # Найдено самоаудитом 03.09 (тот же принцип, что уже применён к
            # image_sharpness_score/video_sharpness_ok выше): вызываются по
            # имени изнутри уже перечисленных функций, реально влияют на
            # решение гейта, @memoize_by_frame их не защищает МЕЖДУ
            # прогонами (та же оговорка, что у render_recipe_signature()).
            #
            # clip_relevance — САМА функция, дающая число: используется и в
            # is_relevant_candidate() (порог CLIP_RELEVANCE_THRESHOLD), и в
            # visual_domain_guard_violation() (euro/asian margin — то есть
            # сам анахронизм-гвард, ради которого эта сигнатура и была
            # создана изначально), и в NEGATIVE_ANCHOR_PROMPT-проверке.
            clip_relevance,
            # extract_video_probe_frame — из video_sharpness_ok(): решает,
            # КАКОЙ именно кадр видео (с ретраями от вырожденного/чёрного)
            # идёт на проверку резкости — другой кадр даёт другой результат.
            extract_video_probe_frame,
            # filter_alt_blocklist/pexels_candidate_text — жанровый фильтр по
            # ТЕКСТУ кандидата. Сам список терминов (CONTENT_ALT_BLOCKLIST)
            # в подписи уже был, а логика его применения — нет: правка 07.09
            # (читать слаг url, а не только alt, и применять фильтр к видео)
            # изменила, КОГО отсеет тот же самый список, не тронув ни одной
            # перечисленной ниже константы. Без этих двух строк такая правка
            # молча не инвалидировала бы кандидатов, отобранных по старому
            # правилу — ровно тот класс пробела, о котором докстринг выше.
            filter_alt_blocklist, pexels_candidate_text, filter_pool_by_text,
            query_tiers_source(), cascade_texts, verify_finalists_of,
            # _candidate_block_key/candidate_source — логика CONTENT_BLOCKED_
            # CANDIDATE_IDS ниже: список id в подписи уже есть, а то, КАК id
            # кандидата сопоставляется с ним (префикс источника) — нет; без
            # этих двух строк правка сопоставления не дошла бы до кэша.
            _candidate_block_key, candidate_source,
            # negative_anchor_violation — новый гейт внутри
            # is_relevant_candidate(); его правка меняет, кто пройдёт отбор,
            # и обязана инвалидировать уже закэшированных кандидатов.
            negative_anchor_violation,
            # _video_candidate_too_short — отсев видео, которое нельзя
            # показать без сломанного растяжения. Меняет, КТО вообще
            # доходит до гейтов, — значит обязан инвалидировать уже
            # закэшированных кандидатов, отобранных по старому правилу.
            _video_candidate_too_short,
        )]
        parts.append(repr((
            CLIP_RELEVANCE_THRESHOLD, RISKY_QUERY_MARGIN, NEGATIVE_ANCHOR_PROMPT,
            RISKY_GENERIC_TERMS, VISUAL_DOMAIN_GUARDS, VIDEO_DOMAIN_GUARD_SAMPLE_FRACS,
            CONTENT_ALT_BLOCKLIST, QUERY_DISAMBIGUATION_RULES,
            # Данные, по которым термин правила ищется в запросе. Сами правила
            # (QUERY_DISAMBIGUATION_RULES) в подписи были, а написания,
            # ловушки и суффиксы — нет: правка любого из трёх меняет, у КАКИХ
            # запросов появится уточнение, и обязана инвалидировать кандидатов,
            # скачанных по неуточнённому запросу.
            QUERY_TERM_SPELLINGS, QUERY_TERM_TRAPS, QUERY_TERM_SUFFIXES,
            CONTENT_NEGATIVE_ANCHORS, NEGATIVE_VETO_MARGIN, NEGATIVE_VETO_ENABLED,
            # Ловушки ПАСПОРТА ЭПИЗОДА (must_not_show). Их значения приходят
            # не из кода, а из media_plan/world_card.json — правка паспорта
            # меняет, кого отсеет вето, не трогая ни одной строки исходника,
            # и без этой строки на прогретом кэше не дошла бы до экрана.
            # Кортеж (не множество) — порядок из JSON стабилен между
            # процессами, в отличие от repr(frozenset), см. разбор ниже.
            episode_forbidden_anchors(),
            # Все поля мира паспорта: эпоха, культуры, регистр решают музейный
            # фильтр и проверку мира на кадре. Правка культуры при той же
            # строке ловушек иначе оставляла бы на прогретом кэше победителей,
            # выбранных по прежнему миру.
            _world_digest_for_signature(),
            # Сколько раз вето вправе взять следующего кандидата вместо того,
            # чтобы убить слот (см. VETO_REPICK_MAX) — меняет победителя.
            VETO_REPICK_MAX,
            # frozenset, не сам объект: repr(frozenset) перебирает элементы в
            # порядке их хэшей, а хэш строк рандомизирован ПОПРОЦЕССНО
            # (PYTHONHASHSEED) — вставленный напрямую, он давал бы разную
            # подпись на каждом новом запуске процесса, даже без единого
            # изменения содержимого множества. Реальный, пойманный тестом
            # регресс (test_selection_stack_signature.py, две проверки
            # РАВЕНСТВА подписи между отдельными подпроцессами): без sorted()
            # обе падали, потому что "то же самое" не значило "тот же repr".
            tuple(sorted(CONTENT_BLOCKED_CANDIDATE_IDS)),
            PHOTO_SHARPNESS_REJECT, VIDEO_SHARPNESS_REJECT, VIDEO_SHARPNESS_SAMPLE_FRACS,
            SHARPNESS_PROBE_MAX_SIDE, CANDIDATE_GATE_RULES_VERSION,
            VIDEO_MAX_TIME_STRETCH,
            # Сама МОДЕЛЬ, дающая число (18.09: CLIP -> SigLIP2-base256, см.
            # get_clip_model()) — clip_relevance() как функция не поменяла
            # исходный текст (только то, что грузит get_clip_model()), значит
            # inspect.getsource(clip_relevance) в списке parts выше остался
            # БЫ прежним и не инвалидировал бы кэш сам по себе. Без этой
            # строки смена модели молча не дошла бы до уже закэшированных
            # temp_smart/pexels_cache — ровно тот класс бага, ради которого
            # эта функция вообще написана (см. докстринг выше).
            CLIP_GATE_MODEL_NAME,
        )))
        parts.append(_selection_stack_signature())
    except Exception:
        _CANDIDATE_GATE_SIG = "gate:unknown"
        return _CANDIDATE_GATE_SIG
    _CANDIDATE_GATE_SIG = "gate:" + hashlib.md5("".join(parts).encode()).hexdigest()[:10]
    return _with_judge_signature(_CANDIDATE_GATE_SIG, index)


def _with_judge_signature(base, index):
    """Подпись правил отбора слота: общая часть плюс судья, если слот в
    платной зоне. Судьи у слота нет — подпись байт-в-байт общая."""
    judge = shot_judge_signature(index)
    if not judge:
        return base
    return "gate:" + hashlib.md5((base + judge).encode()).hexdigest()[:10]


# P2 (аудит "зерно vs частицы в мире"): часть стокового контента УЖЕ несёт
# собственные визуальные частицы (падающий снег, пыль, капли дождя, боке) —
# найдено вживую прямым просмотром кадра (фото "EXCALIBUR" со снегом,
# см. коммит). Наше процедурное зерно (grain_blend_complex) кладётся ОДНИМ
# и тем же opacity на любой клип, независимо от того, есть ли у исходника
# уже своя текстура — на "частицастых" клипах зритель видит два разных по
# характеру источника мелких точек сразу.
#
# Калибровано вживую (НЕ на глаз): 10 подтверждённых прямым просмотром
# кандидатов — частицастые (реальный дождь/снег/пыль на кадре, включая
# "EXCALIBUR", реальные Pexels-фото по запросам "sword snow"/"medieval
# weapon dust particles"/"sword rain droplets") дают relevance против
# PARTICLE_PROMPT в диапазоне 0.208..0.287; чистые "по делу" кадры того же
# оружейного топика (рыцари/легионеры/косплей без частиц, включая один
# кадр с обычным несфокусированным зелёным фоном — НЕ частицы, просто
# боке) — 0.115..0.216. Порог 0.21 — выше единственного пограничного
# случая (0.2156, подтверждённое отсутствие частиц) и не выше самого
# слабого подтверждённого частицастого случая (0.2079). Точность неидеальна
# (граница узкая, ~0.006), но цена ошибки низкая: ложное срабатывание
# просто чуть снижает opacity зерна на обычном фото с боке — не искажает
# контент и не отбрасывает кандидата (кандидат остаётся выбранным, меняется
# только позже наложение зерна).
PARTICLE_PROMPT = "falling snow dust particles bokeh in frame"
# ПЕРЕСЧИТАНО 18.09 под SigLIP2-base256, но НЕ ПЕРЕИЗМЕРЕНО живьём — в
# репозитории нет сохранённых фикстур "частицастых"/"чистых" кадров из
# исходной калибровки (10 подтверждённых пар не персистентны). Вместо
# живой проверки — линейная аффинная оценка по золотому набору: new =
# 1.1512 * clip + (-0.1862) (регрессия по 40 парам relevance(query) CLIP
# против SigLIP2-base256 на тех же изображениях/запросах, r высокий —
# см. корреляцию 0.892 между моделями на этом наборе). Подставляя старый
# порог 0.21, оценка даёт ~0.056. ЧЕСТНО: это ЭКСТРАПОЛЯЦИЯ, не измерение
# на частицах — цена ошибки здесь низкая (ложное срабатывание просто
# меняет opacity зерна, не отбрасывает кандидата, см. коммент выше), но
# перед тем как доверять этому числу как калиброванному — нужна живая
# проверка на реальных частицастых/чистых кадрах (как в исходной
# калибровке), не сделана в этом заходе.
PARTICLE_SCORE_THRESHOLD = 0.056
PARTICLE_GRAIN_SCALE = 0.5   # во сколько раз снижаем GRAIN_OPACITY на "частицастом" клипе


def measure_particle_score(path, is_video=False):
    """clip_relevance() кандидата против PARTICLE_PROMPT — см. калибровку
    выше. Для видео — один кадр-пробник (тот же приём, что measure_luma()
    уже использует для видео: -ss 0.5, не кадр 0, реальный сток иногда
    начинается с чёрного лидер-кадра). None при недоступной CLIP-модели —
    вызывающий код тогда просто не масштабирует opacity (безопасный откат,
    тот же принцип, что и у остальных CLIP-гейтов в файле)."""
    if is_video:
        tmp = path + "._particle_probe.jpg"
        try:
            r = subprocess.run(["ffmpeg", "-y", "-ss", "0.5", "-i", path, "-frames:v", "1", "-q:v", "5", tmp],
                                capture_output=True, timeout=20)
            if r.returncode != 0 or not os.path.exists(tmp):
                return None
            score = clip_relevance(tmp, PARTICLE_PROMPT)
        except Exception:
            score = None
        finally:
            if os.path.exists(tmp):
                os.remove(tmp)
        return score
    return clip_relevance(path, PARTICLE_PROMPT)


# CLIP (openai/clip-vit-base-patch32) снесён отсюда 18.09 по прямому и
# дважды подтверждённому требованию владельца («клип более старая и глупая
# модель, замени её везде») — не по умолчанию, а перманентно: имена
# `get_clip_model()`/`clip_relevance()`/`CLIP_ENABLED`/`CLIP_BROKEN` остались
# ИСТОРИЧЕСКИМИ (70+ мест вызова в pipeline_smart.py и 5 других файлов —
# переименование всех означало бы риск без пользы), но модель ВНУТРИ них
# теперь SigLIP2-base-patch16-256 (та же архитектура, что уже год как
# работает в visual_director.py для sentence_relevance(), только младший
# вариант — со400m там осознанно ОТДЕЛЬНАЯ, более тяжёлая модель под другую
# задачу, эту не трогает).
#
# ИЗМЕРЕНО на золотом наборе (40 кадров эп.01, 17.09), не предположено:
#   AUC (ранжирует годное выше брака)        CLIP 0.566   SigLIP2-base256 0.658
#   реальная скорость (15 картинок, CPU)     CLIP 72мс    SigLIP2-base256  50мс
# Быстрее И точнее одновременно — тот редкий случай, где смены модели не
# стоит ничего по скорости (сравни с тяжёлым ensemble so400m+Jina в
# visual_director.py — 2358мс/вызов, 32.8x медленнее CLIP, поэтому ТОТ
# остаётся точечной проверкой ПОБЕДИТЕЛЯ слота, SMART_RELEVANCE_VETO, а не
# гейтом всего пула).
#
# ЧЕСТНО про предел находки: на самой строгой рабочей точке (ноль потерь и
# по «годным», и по «терпимым») разница CLIP/SigLIP2-base256 почти стирается
# (1 кадр брака из 17) — реальный отрыв виден только при готовности терять
# больше «терпимых» кадров. На 40 картинках это может быть частично шум
# выборки (n=16/7/17 по группам) — решение принято по прямому требованию
# владельца, а не потому что находка была однозначной победой без сомнений.
#
# ЛИНЕЙНАЯ ГОЛОВА LAION-ЭСТЕТИКИ (get_aesthetic_head() ниже) сюда НЕ входит
# и намеренно НЕ переведена на новую модель — это претренированная линейная
# регрессия, математически привязанная к 512-мерному пространству эмбеддинга
# ИМЕННО CLIP ViT-B/32 (веса обучены на нём людьми, не переносятся на другую
# архитектуру/размерность без переобучения на новом датасете разметки,
# которого в этой сессии нет). aesthetic_score() поэтому держит СВОЙ,
# отдельный, узко для этой цели загружаемый CLIP ViT-B/32
# (get_aesthetic_clip_model() ниже) — единственное место в файле, где
# CLIP реально остался, и это не гейт/не решение «показывать или нет»,
# а второстепенный тай-брейк ранжирования уже прошедших гейты кандидатов.
CLIP_GATE_MODEL_NAME = "google/siglip2-base-patch16-256"
CLIP_GATE_MODEL_MAX_TEXT_LEN = 64   # max_position_embeddings текстовой башни,
                                      # тот же параметр, что и у so400m в
                                      # visual_director.py (не настраиваемый)

_clip_model = None
_clip_processor = None


def get_clip_model():
    """Несмотря на имя (историческое, см. блок-комментарий выше) — грузит
    SigLIP2-base-patch16-256, не CLIP. AutoModel/AutoProcessor (та же пара
    классов, что уже используется в visual_director._get_siglip2_model()) —
    SiglipModel поддерживает тот же контракт вызова, что раньше использовал
    CLIPModel (joint forward -> .image_embeds/.text_embeds, get_text_features(),
    get_image_features()), проверено вживую перед переключением."""
    global _clip_model, _clip_processor
    if _clip_model is None:
        from transformers import AutoModel, AutoProcessor
        _clip_model = AutoModel.from_pretrained(CLIP_GATE_MODEL_NAME, trust_remote_code=False).eval()
        _clip_processor = AutoProcessor.from_pretrained(CLIP_GATE_MODEL_NAME, trust_remote_code=False)
    return _clip_model, _clip_processor


_aesthetic_clip_model = None
_aesthetic_clip_processor = None


def get_aesthetic_clip_model():
    """ЕДИНСТВЕННОЕ оставшееся место реальной загрузки CLIP ViT-B/32 —
    см. блок-комментарий у get_clip_model() выше про то, почему
    get_aesthetic_head() не может просто переехать на новую модель.
    Загружается лениво и отдельно от get_clip_model() — не тот же
    синглтон, не тот же кэш, не гейтит is_relevant_candidate()/
    negative_anchor_violation()/VISUAL_DOMAIN_GUARDS и им подобные,
    только aesthetic_score()."""
    global _aesthetic_clip_model, _aesthetic_clip_processor
    if _aesthetic_clip_model is None:
        from transformers import CLIPModel, CLIPProcessor
        name = "openai/clip-vit-base-patch32"
        _aesthetic_clip_model = CLIPModel.from_pretrained(name).eval()
        _aesthetic_clip_processor = CLIPProcessor.from_pretrained(name)
    return _aesthetic_clip_model, _aesthetic_clip_processor


# clip_relevance()/aesthetic_score() ниже читают module-level флаги
# CLIP_ENABLED/CLIP_BROKEN/AESTHETIC_ENABLED помимо своих аргументов — но
# все три МОНОТОННЫ в рамках одного прогона (CLIP_ENABLED/AESTHETIC_ENABLED
# фиксируются один раз на импорте из окружения, CLIP_BROKEN только False->
# True и никогда обратно), значит memoize_by_frame безопасен: если результат
# на (путь, текст) уже закэширован, флаги с тех пор могли только СИЛЬНЕЕ
# отключить CLIP, никогда не включить его заново — закэшированный
# "рабочий" ответ не может стать неверным из-за более позднего отказа.
_CLIP_TEXT_EMB_CACHE = {}


def clip_relevance_multi(image_path, texts):
    """Косинусы ОДНОЙ картинки против НЕСКОЛЬКИХ текстов за один прогон.

    clip_relevance() делает полный forward модели на каждую пару
    (картинка, текст) — то есть vision-башня гоняется по одному и тому же
    кадру столько раз, сколько текстов. Для контрастивного вето
    (negative_anchor_violation ниже, 8 ловушек на кандидата) это была бы
    девятикратная цена там, где физически нужен один прогон картинки.

    Здесь vision-башня считается ОДИН раз, текстовые эмбеддинги кэшируются
    на процесс (их всего горстка на весь эпизод — сами ловушки и запросы
    повторяются), и ответ получается матричным умножением.

    Возвращает список той же длины, что texts, или None при недоступной
    модели — тот же безопасный откат, что у clip_relevance().
    """
    if not CLIP_ENABLED or CLIP_BROKEN or not texts:
        return None
    img = _gate_image_vec(image_path)
    if img is None:
        return None
    vecs = [_gate_text_vec(t) for t in texts]
    if any(v is None for v in vecs):
        return None
    return [float(img @ v) for v in vecs]


# ОДИН ПРОГОН КАРТИНКИ НА ВСЕ ГЕЙТЫ (замер 24.09, py-spy по живому прогону
# эпизода 94): 72% процессорного времени отбора уходило в контрастивное вето,
# и 86% из них — в ТЕКСТОВУЮ башню, заново считавшую одни и те же 14 строк
# (запрос + ловушки канала + ловушки паспорта) на каждую картинку; а одна и
# та же картинка-пробник проходила через картиночную башню 4-5 раз подряд
# (релевантность, домен-гвард дважды, вето). Совместный forward модели и
# раздельные эмбеддинги дают одни и те же числа (замер: наибольшая разница
# 6.7e-8), поэтому эмбеддинг картинки считается один раз на СОДЕРЖИМОЕ файла
# (sha1 байтов — пробник, скачанный заново с тем же адресом, попадает в тот
# же ключ, а перезаписанный файл с другим кадром — нет), текста — один раз
# на строку, а косинус — скалярное произведение.
_GATE_IMG_EMB_CACHE = {}


def _file_digest(path):
    try:
        with open(path, "rb") as f:
            return hashlib.sha1(f.read()).hexdigest()
    except OSError:
        return None


def _gate_image_vec(image_path):
    d = _file_digest(image_path)
    if d is None:
        return None
    v = _GATE_IMG_EMB_CACHE.get(d)
    if v is None:
        try:
            with PILImage.open(image_path) as im:
                img = im.convert("RGB")
        except Exception:  # noqa: BLE001 — нечитаемый файл: скора нет, как раньше
            return None
        e = _gate_embed(images=[img])
        if e is None:
            return None
        v = _GATE_IMG_EMB_CACHE[d] = e[0]
    return v


def _gate_text_vec(text):
    v = _CLIP_TEXT_EMB_CACHE.get(text)
    if v is None:
        e = _gate_embed(text=text)
        if e is None:
            return None
        v = _CLIP_TEXT_EMB_CACHE[text] = e[0]
    return v


@memoize_by_frame
def clip_relevance(image_path, text):
    """Косинусная близость картинки и текста ЗАПРОСА — сырой косинус
    эмбеддингов SigLIP2-base-patch16-256 (см. блок-комментарий у
    get_clip_model() — модель заменена 18.09, имя функции осталось
    историческим). Диапазон на наших фото по факту другой, чем был у
    CLIP (~-0.06..+0.18, не ~0.1..0.3) — см. пороги, откалиброванные под
    новую шкалу: CLIP_RELEVANCE_THRESHOLD и др. ниже. None при отключённой
    фиче/сбое модели — вызывающий код тогда просто не гейтит по релевантности
    (безопасный откат, тот же принцип, что PARALLAX_LIBS/PARALLAX_BROKEN)."""
    got = clip_relevance_multi(image_path, [text])
    return None if got is None else got[0]


# --- Эстетическая оценка кадра (LAION aesthetic predictor v1, линейная
# голова поверх CLIP ViT-B/32) — та же модель, что уже загружена для
# clip_relevance(), никакого нового тяжёлого скачивания. Голова — всего
# 513 чисел (512-мерный вес + bias), извлечена ОДИН РАЗ из официальных
# весов (shunk031/aesthetics-predictor-v1-vit-base-patch32 на HF — это
# репаковка оригинальных LAION-AI/aesthetic-predictor sa_0_4_vit_b_32_
# linear.pth в формат HF, GitHub-источник в этой сессии недоступен по
# сетевой политике, HF открыт) и сохранена как assets/aesthetic/*.npz —
# не .pth (pickle, может исполнять код при загрузке), голый numpy-массив,
# без риска.
AESTHETIC_ENABLED = os.environ.get("AESTHETIC_SCORE", "1") != "0"
_aesthetic_head = None


def get_aesthetic_head():
    global _aesthetic_head
    if _aesthetic_head is None:
        path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                             "assets", "aesthetic", "laion_aesthetic_vit_b_32_head.npz")
        data = np.load(path)
        _aesthetic_head = (data["weight"], float(data["bias"]))
    return _aesthetic_head


SHARPNESS_PROBE_MAX_SIDE = 720   # тот же нормализующий размер, что уже использует
                                  # visual_qc.py — Лапласиан-дисперсия растёт с
                                  # разрешением исходника, не только с реальной
                                  # резкостью; сравнивать источник и рендер нужно
                                  # в ОДНОЙ шкале.


def image_sharpness_score(image_path):
    """Дисперсия Лапласиана (тот же дешёвый blur-детектор, что уже использует
    visual_qc.py sharpness_score() — не дублируется оттуда напрямую: тот файл
    ИМПОРТИРУЕТ pipeline_smart, обратный импорт дал бы цикл). None при сбое
    чтения/декода или недоступности numpy — вызывающий код просто не гейтит
    по этой оси (тот же безопасный откат, что и у остальных опциональных
    скореров пайплайна)."""
    if np is None:
        return None
    try:
        img = PILImage.open(image_path).convert("L")
        w, h = img.size
        scale = SHARPNESS_PROBE_MAX_SIDE / max(w, h)
        if scale < 1.0:
            img = img.resize((max(1, round(w * scale)), max(1, round(h * scale))), PILImage.LANCZOS)
        arr = np.asarray(img, dtype=np.uint8)
        if PARALLAX_LIBS:   # cv2 доступен — см. import cv2 в начале файла
            return float(cv2.Laplacian(arr, cv2.CV_64F).var())
        kernel = np.array([[0.0, 1.0, 0.0], [1.0, -4.0, 1.0], [0.0, 1.0, 0.0]])
        lap = _convolve2d_same(arr.astype(np.float64), kernel)
        return float(lap.var())
    except Exception:
        return None


# Реальный, найденный вживую случай (27 августа, videos/_test20s, слот 3):
# apply_depth_of_field() размыл САМ ОБЪЕКТ, не только фон (см. коммит про
# _dof_focus_depth) — но НИЧТО в пайплайне до этого коммита не сравнивало
# резкость ГОТОВОГО РЕНДЕРА с резкостью ИСХОДНОГО фото. visual_qc.py (Шаг
# 5.5) проверяет резкость только СЫРОГО кандидата ДО рендера — у него
# физически нет доступа к тому, что Ken Burns/параллакс/ГРИП/грейд сделают
# с кадром ПОСЛЕ. Эта проверка — единственное место, которое умеет поймать
# ЛЮБОЙ будущий баг того же КЛАССА (не только сегодняшний DOF): рендер,
# который ощутимо размывает кадр относительно его же источника, независимо
# от причины (новый неудачный фильтр, регрессия в параллаксе, что угодно).
#
# Калибровка (n=4 реальных клипа этого эпизода, честно — не строгая
# статистика, а быстрая проверка на реальных данных перед тем, как
# использовать порог, см. принцип "не гадать" по всему пайплайну):
# baggy DOF (найденный баг) дал rendered/source = 245/596 = 0.41; тот же
# кадр после фикса — 639/596 = 1.07; фото с намеренным боке крупного плана
# (книга, естественное размытие фона в самом источнике) — 155/245 = 0.64;
# фото без выраженной глубины (весы) — 145/144 = 1.01. Порог 0.5 — с
# запасом ниже честного кинематографичного боке (0.64), но ловит реальный
# найденный случай (0.41). Advisory, не hard-reject (тот же принцип, что
# AESTHETIC_BORDERLINE в visual_qc.py) — рендер не останавливается, флаг
# идёт в отчёт для Шага 7.5.
RENDER_SHARPNESS_DROP_RATIO = 0.5
RENDER_QC_REPORT = []   # [{"index", "source", "rendered", "source_sharpness",
                         #   "rendered_sharpness", "ratio"}, ...] — см. main()


def render_sharpness_regression(source_photo, rendered_clip):
    """(флаг_подозрительно_размыто, ratio) — сравнивает резкость ИСХОДНОГО
    фото с резкостью кадра-пробника ИЗ ГОТОВОГО РЕНДЕРА (см.
    RENDER_SHARPNESS_DROP_RATIO выше). Пробник берётся с середины клипа
    (extract_video_probe_frame, тот же метод, что уже используют домен-гварды
    видео) — не с первого кадра, где ещё может идти вход в кенбёрнс.
    (None, None) на любом сбое (декод/недоступность numpy-CV) — безопасный
    откат, проверка просто не участвует, как и остальные опциональные оси."""
    src_sharp = image_sharpness_score(source_photo)
    if src_sharp is None or src_sharp <= 1.0:
        return None, None   # почти однотонный/вырожденный источник — не с чем сравнивать
    probe, cleanup = extract_video_probe_frame(rendered_clip, base_at=0.5)
    if probe is None:
        return None, None
    try:
        rendered_sharp = image_sharpness_score(probe)
    finally:
        if cleanup and os.path.exists(probe):
            os.remove(probe)
    if rendered_sharp is None:
        return None, None
    ratio = rendered_sharp / src_sharp
    return (ratio < RENDER_SHARPNESS_DROP_RATIO, ratio)


@memoize_by_frame
def aesthetic_score(image_path):
    """Эстетическая оценка кадра — линейная регрессия поверх L2-нормали-
    зованного CLIP image embedding (формула подтверждена по исходному коду
    модели: image_embeds /= norm(...); prediction = predictor(image_embeds)).
    Диапазон на реальных фото ~3-7 (проверено вживую на 25 кадрах эпизода —
    топ-3 по оценке визуально заметно сильнее по композиции/свету, чем
    низ; самый низкий скор корректно поймал случайно затесавшийся в кэш
    нерелевантный кадр — рюкзак/ноутбук вместо меча). None при отключённой
    фиче/сбое — вызывающий код просто не использует критерий (безопасный
    откат, тот же принцип, что CLIP_BROKEN/PARALLAX_BROKEN).

    Держит СВОЙ, отдельный от get_clip_model() CLIP ViT-B/32 (см.
    get_aesthetic_clip_model() и блок-комментарий у get_clip_model() про
    то, почему линейная голова LAION не может переехать на SigLIP2 без
    переобучения) — AESTHETIC_ENABLED/CLIP_ENABLED (флаги гейта) всё ещё
    управляют этим включателем (эстетика — надстройка над тем же общим
    выключателем CLIP-класса функций), но сбой/поломка СВОЕЙ модели
    отмечается в AESTHETIC_CLIP_BROKEN, не в CLIP_BROKEN — падение
    SigLIP2-гейта не обязано гасить эстетику и наоборот."""
    global AESTHETIC_CLIP_BROKEN
    if not AESTHETIC_ENABLED or not CLIP_ENABLED or AESTHETIC_CLIP_BROKEN:
        return None
    try:
        import torch
        model, processor = get_aesthetic_clip_model()
        img = PILImage.open(image_path).convert("RGB")
        inputs = processor(images=[img], return_tensors="pt")
        with torch.no_grad():
            vis_out = model.vision_model(pixel_values=inputs["pixel_values"])
            feat = model.visual_projection(vis_out.pooler_output)
        e = (feat / feat.norm(dim=-1, keepdim=True))[0].numpy()
        w, b = get_aesthetic_head()
        return float(e @ w + b)
    except ImportError:
        AESTHETIC_CLIP_BROKEN = True
        return None
    except Exception:
        return None


_depth_model = None


def get_depth_model():
    global _depth_model
    if _depth_model is None:
        from transformers import pipeline as hf_pipeline
        _depth_model = hf_pipeline(task="depth-estimation",
                                    model="depth-anything/Depth-Anything-V2-Small-hf")
    return _depth_model


def estimate_depth(canvas_bgr):
    """Карта глубины (float32, 0..1, 1=близко) — строится по УЖЕ обрезанному
    холсту (canvas_bgr из fill_crop_canvas), а не по исходному фото.
    Раньше модель считала глубину по несжатому оригиналу (его родное
    соотношение сторон), а карта потом растягивалась голым cv2.resize под
    размер холста — без кропа, который применялся к цветной картинке. При
    несовпадении соотношения сторон (портретное фото под альбомный холст)
    карта глубины съезжала и тянулась не по тому же кадру, что видит
    зритель: параллакс сдвигал пиксели по чужой геометрии — отсюда
    видимое искажение/"плавание" картинки. Считая глубину прямо по canvas,
    геометрия гарантированно совпадает."""
    model = get_depth_model()
    h, w = canvas_bgr.shape[:2]
    img = PILImage.fromarray(canvas_bgr[:, :, ::-1])  # BGR -> RGB
    out = model(img)
    depth = np.array(out["predicted_depth"], dtype=np.float32)
    if depth.shape != (h, w):
        depth = cv2.resize(depth, (w, h), interpolation=cv2.INTER_LINEAR)
    d_min, d_max = float(depth.min()), float(depth.max())
    if d_max - d_min < 1e-6:
        return np.full((h, w), 0.5, dtype=np.float32)
    depth = (depth - d_min) / (d_max - d_min)
    # Depth-Anything даёт РЕЗКИЙ край на границе объекта (перепад ~0..1 за
    # 1-2px — проверено: grad p99 ~0.08, максимум >2.0 на пиксель). При
    # remap с parallax_px до ~70px это превращает границу в артефакт
    # "двойного контура"/расслоения на резких силуэтах (рукоять меча на
    # фоне боке) — то, что видно глазом как "ИИ-искажение". Настоящей
    # физически верной параллакс-окклюзии тут всё равно нет (плоская
    # картинка, не многослойная сцена), поэтому лечим не резкость карты,
    # а её крутизну: широкое гауссово размытие растягивает переход через
    # много пикселей, и remap плывёт плавно вместо "разрыва" на 1-2px —
    # тот же приём, что использует Apple/Google в 3D-Ken-Burns эффектах.
    sigma = max(3.0, min(h, w) * 0.018)
    depth = cv2.GaussianBlur(depth, (0, 0), sigmaX=sigma)
    return depth


# Кадрирование источников, у которых пропорция далека от 16:9.
#
# РЕАЛЬНЫЙ, ИЗМЕРЕННЫЙ дефект. Весь пайплайн приводит фото к кадру одним и
# тем же приёмом — increase+crop («залить и обрезать», см. compute_crop_offset
# и fill_crop_canvas ниже). Для стока Pexels (обычно 3:2) это стоит 16%
# высоты и незаметно. Но с подключением музеев, архивов Openverse и Pixabay
# в пул пошёл материал, которого там раньше не было: страницы кодексов,
# надгробные эффигии, доспехи в полный рост, гобелены — то есть ПОРТРЕТНЫЕ
# снимки. Сколько от них остаётся при том же кропе (посчитано геометрией,
# ar/1.778 по высоте):
#
#     миниатюра рукописи 3:4      видно 42%  -> обрезано 58%
#     страница кодекса 2:3        видно 38%  -> обрезано 62%
#     доспех в рост 9:16          видно 32%  -> обрезано 68%
#     квадрат 1:1                 видно 56%  -> обрезано 44%
#
# И это ДО зума Ken Burns, который снимает ещё 8-22%. То есть подлинная
# страница рукописи показывалась зрителю узкой горизонтальной полосой из
# середины — гейты при этом считали кандидата отличным, потому что судили
# по ЦЕЛОМУ изображению, а не по тому, что реально попадёт в кадр.
#
# Решение — стандартное для жанра (и ровно то, что рекомендует продакшн-
# спецификация канала): вписать изображение ЦЕЛИКОМ, а пустоту по бокам
# закрыть размытой и затемнённой копией его же. Затемнение обязательно —
# без него яркая подложка перетягивает внимание с самого кадра.
#
# Порог выбран не на глаз: 4:3 — та пропорция, на которой increase+crop
# теряет ровно четверть высоты. Всё, что ШИРЕ (включая 3:2 Pexels и 16:9),
# идёт прежним путём БАЙТ-В-БАЙТ; подложка появляется только там, где
# обычный кроп уничтожил бы больше четверти кадра.
ASPECT_FIT_MIN_RATIO = 4 / 3
ASPECT_BACKDROP_BLUR = 42        # sigma размытия подложки на холсте 1920x1080
ASPECT_BACKDROP_DARKEN = 0.55    # множитель яркости подложки (документ просит -15%, берём сильнее:
                                  # подложка тут не фон сцены, а заполнение пустоты)
# Передний план вписывается не впритык к краю кадра, а с запасом под зум:
# ZOOM_FLOOR=1.04 уже в первом кадре показывает 96% холста, поэтому при
# полной высоте у страницы рукописи сразу срезался бы верх и низ.
ASPECT_FIT_SAFE = 0.92
ASPECT_FIT_CACHE_DIR = "aspect_fit"


def needs_aspect_backdrop(iw, ih):
    """Нужна ли этому источнику подложка вместо обычного кропа."""
    if not iw or not ih or ih <= 0:
        return False
    return (iw / ih) < ASPECT_FIT_MIN_RATIO


def aspect_fit_backdrop(photo_path, out_dir=None, width=None, height=None):
    """Путь к 16:9-версии кадра: сам кадр целиком + размытая тёмная подложка.

    Возвращает ИСХОДНЫЙ путь, если подложка не нужна (кадр 4:3 и шире),
    фича выключена или что-то пошло не так — fail-open, тот же принцип, что
    у остальных опциональных слоёв: ни один слот не должен пропасть из-за
    этого шага. Результат кэшируется по (путь, mtime, размер, параметры),
    поэтому повторный прогон не пересобирает композит."""
    if not feature_flags.enabled("ASPECT_FIT_BACKDROP"):
        return photo_path
    W = width or WIDTH
    H = height or HEIGHT
    try:
        with PILImage.open(photo_path) as probe:
            probe = PILImageOps.exif_transpose(probe)
            iw, ih = probe.size
        if not needs_aspect_backdrop(iw, ih):
            return photo_path
        base = out_dir or os.path.join(TEMP_FOLDER, ASPECT_FIT_CACHE_DIR)
        os.makedirs(base, exist_ok=True)
        key = hashlib.md5("|".join([
            os.path.abspath(photo_path), str(os.path.getmtime(photo_path)),
            str(os.path.getsize(photo_path)), f"{W}x{H}",
            f"{ASPECT_BACKDROP_BLUR}:{ASPECT_BACKDROP_DARKEN}:{ASPECT_FIT_SAFE}",
        ]).encode()).hexdigest()[:12]
        dest = os.path.join(base, f"{key}.jpg")
        if os.path.exists(dest) and os.path.getsize(dest) > 0:
            return dest
        with PILImage.open(photo_path) as im:
            im = PILImageOps.exif_transpose(im).convert("RGB")
            # Подложка: то же изображение, залитое на весь кадр (increase+crop),
            # размытое и притемнённое.
            scale = max(W / im.width, H / im.height)
            bw, bh = max(1, round(im.width * scale)), max(1, round(im.height * scale))
            bg = im.resize((bw, bh), PILImage.LANCZOS).crop(
                ((bw - W) // 2, (bh - H) // 2, (bw - W) // 2 + W, (bh - H) // 2 + H))
            bg = bg.filter(PILImageFilter.GaussianBlur(ASPECT_BACKDROP_BLUR))
            bg = PILImageEnhance.Brightness(bg).enhance(ASPECT_BACKDROP_DARKEN)
            # Передний план: изображение целиком, вписанное с запасом под зум.
            fit = min(W * ASPECT_FIT_SAFE / im.width, H * ASPECT_FIT_SAFE / im.height)
            fw, fh = max(1, round(im.width * fit)), max(1, round(im.height * fit))
            fg = im.resize((fw, fh), PILImage.LANCZOS)
            bg.paste(fg, ((W - fw) // 2, (H - fh) // 2))
            tmp = dest + ".tmp"
            bg.save(tmp, "JPEG", quality=95, subsampling=0)
            os.replace(tmp, dest)
        return dest
    except Exception as e:
        print(f"  подложка 16:9 не собралась для {os.path.basename(str(photo_path))}: {e} — кадрирую как раньше")
        return photo_path


def fill_crop_canvas(photo_path, cw, ch, anchor=None):
    """Тот же increase+crop, что и в ffmpeg-пути: заливаем холст целиком,
    обрезаем лишнее — без чёрных полос по краям (BGR для cv2). anchor —
    та же логика, что в compute_crop_offset (см. detect_face_anchor):
    None -> центр-кроп, как было всегда."""
    img = PILImage.open(photo_path).convert("RGB")
    iw, ih = img.size
    nw, nh, x0, y0 = compute_crop_offset(iw, ih, cw, ch, anchor)
    img = img.resize((nw, nh), PILImage.LANCZOS)
    img = img.crop((x0, y0, x0 + cw, y0 + ch))
    arr = np.array(img)[:, :, ::-1].copy()   # RGB -> BGR
    return arr


def apply_depth_of_field(canvas, depth, strength_gain=1.0):
    """Размывает фон холста ПРОПОРЦИОНАЛЬНО дистанции от переднего плана —
    см. DOF_* константы выше. Один Gaussian-blur прохода + линейный (по
    DOF_FALLOFF_POWER) блендинг по уже посчитанной depth-карте, без второй
    модели. strength_gain — тот же content-aware множитель, что уже
    масштабирует parallax_px/depth_zoom_strength (depth.std() / референс) —
    на плоских кадрах (студийный фон почти без глубины) эффект слабее, не
    выдаёт ложный "боке" там, где реального разделения план/фон нет."""
    if not DOF_ENABLED:
        return canvas
    h, w = canvas.shape[:2]
    sigma = DOF_SIGMA_FRAC * min(h, w) * max(0.3, min(1.5, strength_gain))
    if sigma < 1.0:
        return canvas
    blurred = cv2.GaussianBlur(canvas, (0, 0), sigmaX=sigma)
    focus_depth = _dof_focus_depth(depth, h, w)
    blur_weight = np.clip((focus_depth - depth) / focus_depth, 0.0, 1.0) ** DOF_FALLOFF_POWER
    blur_weight = blur_weight[:, :, None]
    return (canvas.astype(np.float32) * (1.0 - blur_weight)
            + blurred.astype(np.float32) * blur_weight).astype(np.uint8)


# Occlusion-aware двухслойный варп — независимая реализация общеизвестной
# техники "layered depth image" (см. "3D Ken Burns Effect from a Single
# Image", Niklaus/Mai/Yang/Liu, 2019 — та же архитектурная идея, на которую
# уже ссылается комментарий у estimate_depth() выше; код здесь свой, на
# штатном OpenCV cv2.inpaint(), ничего не заимствовано из чужих репозиториев).
#
# ПРОБЛЕМА, которую это решает: PARALLAX_MAX_STRETCH/WARP_SIGMA_FRAC выше —
# рабочий, измеренный фикс для одного-единственного плоского remap()
# (растяжение снижено с 172% до 13% на реальном кадре) — но это смягчение
# СИМПТОМА (сглаженная карта глубины растягивает разрыв на больше пикселей),
# не устранение ПРИЧИНЫ: на границе объекта remap() всё ещё сэмплит один и
# тот же холст по обе стороны разрыва, соседние выходные пиксели неизбежно
# тянут текстуру через границу. Настоящая проблема физическая: фото —
# плоское, за передним планом реально НЕТ данных о том, что там на самом
# деле (окклюзия) — плоский remap с этим ничего не может поделать
# принципиально, только маскировать растяжку размытием.
#
# РЕШЕНИЕ: разложить холст на 2 слоя по Otsu-порогу depth-карты (близко/
# далеко — порог считается автоматически по бимодальности гистограммы
# глубины, не гадание с процентилем). Область под "близким" объектом на
# ФОНОВОМ слое затягивается cv2.inpaint() ОДИН раз на фото (не на кадр —
# дорого) — правдоподобным продолжением фона, а не дырой/растяжкой.
# На каждом кадре оба слоя варпятся ТЕМ ЖЕ самым map_x/map_y, что и раньше
# (архитектура remap-цикла не меняется), и компонуются через мягкую
# (растушёванную) альфа-маску переднего плана — там, где раньше задняя
# плоскость стягивалась в мазок, теперь виден уже готовый (не рвущийся)
# инпейнт-фон.
PARALLAX_OCCLUSION_AWARE = os.environ.get("PARALLAX_OCCLUSION_AWARE", "1") != "0"
PARALLAX_INPAINT_RADIUS = 5   # px, стандартный диапазон cv2.inpaint() (3-7)


def foreground_background_layers(canvas, depth):
    """(bg_plate, fg_alpha) — фоновый слой с инпейнтом под передним планом
    и мягкая (0..1) альфа-маска "насколько этот пиксель — передний план".

    Сбой (inpaint не встал/маска пустая/вся картинка одним классом) ->
    (canvas, None) — вызывающий код на None откатывается на старый
    однослойный путь, тот же fail-open принцип, что у остального параллакса."""
    try:
        d8 = np.clip(depth * 255, 0, 255).astype(np.uint8)
        _, fg_mask = cv2.threshold(d8, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
        # Otsu не гарантирует, какой класс какой — у нас депт=1 значит
        # "близко", проверяем и при необходимости инвертируем маску так,
        # чтобы fg_mask действительно соответствовал БЛИЖНЕМУ объекту.
        if fg_mask.mean() <= 0 or fg_mask.mean() >= 255:
            return canvas, None   # вся картинка одним классом — слоить нечего
        if float(depth[fg_mask > 0].mean()) < float(depth[fg_mask == 0].mean()):
            fg_mask = 255 - fg_mask
        k = PARALLAX_INPAINT_RADIUS * 2 + 1
        inpaint_mask = cv2.dilate(fg_mask, np.ones((k, k), np.uint8))
        bg_plate = cv2.inpaint(canvas, inpaint_mask, PARALLAX_INPAINT_RADIUS, cv2.INPAINT_TELEA)
        sigma = max(2.0, min(canvas.shape[:2]) * 0.01)
        fg_alpha = cv2.GaussianBlur(fg_mask.astype(np.float32) / 255.0, (0, 0), sigmaX=sigma)
        return bg_plate, fg_alpha
    except Exception:
        return canvas, None


def parallax_kenburns(photo, out, dur, title=None, zoom_in=None, pan_dir=None, stat=None,
                       section="", stat_variant=0, brightness_bias=0.0, energy_bias=0.0,
                       stat_delay=0.0, levels=None, wb=None, grain_scale=1.0, captions=None,
                       look_filter=None, domain=None):
    """2.5D-версия kenburns(): собственный покадровый рендер (OpenCV remap)
    вместо ffmpeg zoompan — только так можно сделать смещение, зависящее от
    глубины пикселя. При любой накладке (модель не встала, ffmpeg-пайп упал)
    возвращает False — вызывающий код откатывается на обычный kenburns()."""
    # Та же подложка, что и в kenburns(): параллакс строит свой холст через
    # fill_crop_canvas(), то есть тем же increase+crop.
    photo = aspect_fit_backdrop(photo)
    global PARALLAX_BROKEN
    if PARALLAX_BROKEN:
        return False
    proc = None
    stderr_f = None
    stderr_path = None
    try:
        frames = max(1, round(dur * FPS))
        cw, ch = round(WIDTH * PARALLAX_MARGIN), round(HEIGHT * PARALLAX_MARGIN)
        canvas = fill_crop_canvas(photo, cw, ch, anchor=resolve_crop_anchor(photo))
        try:
            depth = estimate_depth(canvas)
        except Exception as e:
            # Сбой именно тут почти всегда системный (модель не встала /
            # сеть до HF Hub отвалилась), не проблема конкретной картинки —
            # дальше пытаться на каждом из оставшихся хайлайтов бессмысленно,
            # только тратим время на повторную (медленную) загрузку модели.
            print(f"  depth-модель недоступна, параллакс выключается на остаток ролика: "
                  f"{type(e).__name__} {e}")
            PARALLAX_BROKEN = True
            return False

        h, zoom_in_default, pan_dir_default = kb_hash_choices(photo)
        if zoom_in is None:
            zoom_in = zoom_in_default
        dx, dy = pan_dir if pan_dir is not None else pan_dir_default
        rate_jit = ((h >> 5) % 1000) / 1000.0
        pan_jit = ((h >> 15) % 1000) / 1000.0
        # C6: см. kenburns() — та же логика скорости зума в такт энергии голоса.
        energy_zoom_mult = 1.0 + max(-0.5, min(0.5, energy_bias)) * 0.2
        delta = max(ZOOM_DELTA_MIN, min(ZOOM_DELTA_MAX,
                    ZOOM_RATE_BASE * dur * (0.75 + rate_jit * 0.5) * energy_zoom_mult))
        max_zoom = ZOOM_FLOOR + delta
        pan_amt_frac = PAN_SAFETY * (PAN_JITTER_MIN + pan_jit * (PAN_JITTER_MAX - PAN_JITTER_MIN))
        # Content-aware сила эффекта: раньше parallax_px был один и тот же
        # для любой картинки — эффект работает эффектно только там, где в
        # карте глубины ЕСТЬ реальный контраст (чёткое разделение объект/
        # фон); на плоских/текстурных кадрах (макро металла, ткань, ровный
        # задник) та же сила выглядит как случайное дрожание, не параллакс,
        # потому что двигать там физически нечего. depth.std() — дешёвая
        # мера контраста уже посчитанной карты (без доп. модели). Референс
        # 0.22 — медиана std по реальным фото канала (проверено: 0.18-0.31
        # на 8 кадрах), не гадание. Верхняя граница 1.4 — не разгоняем сверх
        # разумного. Нижняя граница поднята с 0.4 до 0.6 по прямой жалобе
        # пользователя (параллакс на хук-кадре с низкоконтрастным фоном
        # выглядел почти неотличимо от обычного Ken Burns) — parallax_kenburns
        # вызывается ИСКЛЮЧИТЕЛЬНО на highlight-кадрах (хук/открывашки
        # разделов/climax, см. is_parallax_highlight()), то есть именно там,
        # где эффект по замыслу должен читаться сильнее всего; 0.6 — разумная
        # правка на глаз, НЕ пересчитана заново на большой выборке фото
        # (честно, как и исходное значение 0.4 не было "гаданием", но и не
        # калибровкой в строгом смысле).
        depth_contrast = float(depth.std())
        strength_gain = max(0.6, min(1.4, depth_contrast / 0.22))
        parallax_px = PARALLAX_PX_BASE * (0.7 + rate_jit * 0.6) * strength_gain
        # Отдельная, СИЛЬНО сглаженная карта глубины именно для геометрии
        # варпа (см. PARALLAX_WARP_SIGMA_FRAC/PARALLAX_MAX_STRETCH выше).
        # Исходная `depth` остаётся резкой и дальше идёт в apply_depth_of_field()
        # и в depth_contrast — боке и оценка контраста хотят чёткий край,
        # геометрия от чёткого края рвётся.
        warp_depth = cv2.GaussianBlur(
            depth, (0, 0), sigmaX=max(3.0, min(cw, ch) * PARALLAX_WARP_SIGMA_FRAC))
        _gy, _gx = np.gradient(warp_depth)
        warp_grad = float(np.percentile(np.hypot(_gx, _gy), 99))
        # DEPTH_ZOOM_STRENGTH — насколько сильно ближние/дальние слои
        # расходятся по СКОРОСТИ ЗУМА при push/pull (не только по офсету
        # при пане, как раньше). Настоящая перспектива: у камеры, которая
        # реально приближается к сцене, ближние объекты растут в кадре
        # быстрее дальних — старая версия зумила все пиксели с одной и той
        # же скоростью независимо от глубины (это и есть "2D remap", не
        # честная 3D-репроекция). depth_zoom_strength тоже масштабируется
        # content-aware — той же логикой, что и parallax_px выше.
        depth_zoom_strength = 0.12 * strength_gain
        # Гарантия бюджета искажения (см. PARALLAX_MAX_STRETCH выше) — обе
        # ручки режутся по ИЗМЕРЕННОМУ на этом фото градиенту, а не по общей
        # константе. У depth_zoom_strength вклад в растяжение больше в
        # (min(кадра)/2) раз: он множит не смещение, а КООРДИНАТУ, то есть
        # эффект растёт с удалением от центра кадра — поэтому и потолок свой.
        if warp_grad > 1e-6:
            parallax_px = min(parallax_px, PARALLAX_MAX_STRETCH / warp_grad)
            depth_zoom_strength = min(
                depth_zoom_strength,
                PARALLAX_MAX_STRETCH / (warp_grad * (min(WIDTH, HEIGHT) / 2.0)))
        # Боке/глубина резкости (см. apply_depth_of_field()/DOF_* выше) —
        # размывает canvas ОДИН раз до начала покадрового remap-цикла, тот
        # же canvas дальше варпится по кадрам как обычно (background
        # остаётся размытым и через движение параллакса — оптически
        # корректно, размытие свойство сцены, не текущего вида камеры).
        #
        # РЕАЛЬНЫЙ, найденный вживую баг (deep-audit, videos/_test20s, слот 2
        # "видеоигры и школьные учебники", прямая жалоба пользователя на
        # размытие). strength_gain выше — ОДНА величина на geometric-
        # параллакс (parallax_px/depth_zoom_strength, клэмп 0.6..1.4) И на
        # силу DOF-боке — но это разные вещи: широкий geometric-клэмп
        # безопасен (сильнее едет параллакс на контрастной сцене — это и
        # есть цель), а тот же множитель для sigma боке на сцене с БОЛЬШИМ
        # разбросом глубины (толпа зрителей вдалеке + трава на разных
        # дистанциях + фигуры на переднем плане — depth.std()=0.288, близко
        # к потолку 1.4x) даёт sigma=29.7px при DOF_SIGMA_FRAC=0.014 — и,
        # что важнее, порог фокуса (_dof_focus_depth(), медиана ЦЕНТРАЛЬНОГО
        # патча) на такой сцене оставляет ~62% всего кадра НИЖЕ порога
        # (измерено: (depth < focus).mean() = 0.618) — то есть боке ложится
        # не только на реальный дальний план, но и на значительную часть
        # среднего плана, который в РЕАЛЬНОМ источнике был резким целиком
        # (обычное для photojournalism/массовых сцен глубокое ГРИП, не
        # мелкая диафрагма) — на готовом рендере это читается не как боке,
        # а как "фото размазано". Разделяем: geometric strength_gain остаётся
        # как был (0.6..1.4, доказанно безопасен), DOF получает СВОЙ, более
        # консервативный потолок 1.0 (нижняя граница 0.5 — тоже чуть строже
        # 0.6, тот же принцип "не разгонять на бесспорно сложной сцене").
        # На этом кадре: sigma 29.7px -> 22.7px (-24%), фракция ниже порога
        # не меняется (это управляется focus_depth/falloff, не strength_gain)
        # — не заявляю, что это полностью убирает эффект, только честно
        # снижает силу там, где content-aware сигнал (высокий depth.std())
        # сегодня трактуется как "разгоняй сильнее", а физически чаще
        # означает "тут много разных планов, потолок не должен разгонять
        # боке ТАК агрессивно, как на чистом двухслойном кадре".
        dof_strength_gain = max(0.5, min(1.0, strength_gain))
        canvas = apply_depth_of_field(canvas, depth, dof_strength_gain)
        # Occlusion-aware фоновый слой (см. foreground_background_layers()
        # выше) — считается ОДИН раз на фото, до покадрового цикла. bg_alpha
        # is None -> старый однослойный remap (fail-open, не другое
        # поведение при выключенном/сбойном PARALLAX_OCCLUSION_AWARE).
        bg_plate, fg_alpha = ((canvas, None) if not PARALLAX_OCCLUSION_AWARE
                               else foreground_background_layers(canvas, depth))
        # C2: лёгкий 3D-наклон камеры (roll) — до TILT_MAX_DEG, направление
        # по хэшу фото. Независимая от зума/пана ось движения, добавляет
        # ощущение "камера не на рельсах, а в руках", не дублирует то, что
        # уже даёт depth-параллакс (тот двигает БЛИЖНИЕ/ДАЛЬНИЕ слои с разной
        # скоростью, это вращает кадр целиком).
        TILT_MAX_DEG = 0.6
        tilt_dir = 1 if (h & 0x100) else -1
        # Не крутим кадр под цифрой-плашкой — читаемость важнее, тот же
        # принцип, что static_hold у kenburns() (параллакс своей "статичной"
        # ветки не имеет, гасим только этот один эффект).
        tilt_theta_max = 0.0 if stat else math.radians(TILT_MAX_DEG * tilt_dir)

        cx, cy = cw / 2.0, ch / 2.0
        ox_grid, oy_grid = np.meshgrid(np.arange(WIDTH, dtype=np.float32),
                                        np.arange(HEIGHT, dtype=np.float32))

        cmd = ["ffmpeg", "-y", "-f", "rawvideo", "-pix_fmt", "bgr24",
               "-s", f"{WIDTH}x{HEIGHT}", "-r", str(FPS), "-i", "-"]
        # Зерно — второй вход, ДО -frames:v (тот должен остаться однозначно
        # выходной опцией — если между ним и следующим -i ничего не стоит,
        # ffmpeg привязал бы его ко входу grain, а не к выходу).
        if GRAIN_ENABLED:
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
        vf = film_look(h, section, brightness_bias, energy_bias, levels, wb, domain)
        if look_filter:   # Reference-Guided Look Management — см. kenburns()
            vf += f",{look_filter}"
        if title or stat or captions:
            vf = add_overlays(vf, dur, title, stat, stat_variant, stat_delay, media_path=photo)
            vf = add_kinetic_captions(vf, captions)
        if GRAIN_ENABLED:
            fc = f"[0:v]{vf}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}"
            cmd += ["-filter_complex", fc, "-map", "[vout]"]
        else:
            cmd += ["-vf", vf]
        tmp_out = render_tmp_path(out)
        cmd += ["-frames:v", str(frames), "-c:v", "libx264", "-preset", RENDER_PRESET, "-crf", RENDER_CRF,
                "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS + [tmp_out]
        # РЕАЛЬНЫЙ баг, пойманный на реальном продакшн-рендере (не гипотеза):
        # stderr=subprocess.PIPE здесь НИКОГДА не вычитывался, пока родитель
        # покадрово пишет сырое видео в stdin ниже — классический subprocess
        # deadlock: если ffmpeg успевает написать в stderr больше системного
        # лимита пайпа (обычно 64КБ на Linux) ДО того, как родитель дозапишет
        # все кадры, ffmpeg блокируется на записи в свой заполненный stderr,
        # родитель блокируется на proc.stdin.write() — оба ждут друг друга
        # НАВСЕГДА. Не зависит от содержимого фото/fps/модели — только от
        # того, сколько именно диагностики ffmpeg успел написать для
        # конкретного клипа, поэтому и выглядело "случайным" (не каждый
        # клип, только те, что перешли порог буфера). Критично: это блокирует
        # proc.stdin.write() ВНУТРИ цикла ниже — proc.wait(timeout=60) дальше
        # по коду вообще не успевает сработать, до него не доходит.
        # Файл вместо пайпа — стандартный фикс: запись в файл не имеет
        # аналогичного лимита буфера, ffmpeg никогда не блокируется на нём.
        stderr_path = render_tmp_path(out) + ".stderr.log"
        stderr_f = open(stderr_path, "wb")
        proc = subprocess.Popen(cmd, stdin=subprocess.PIPE,
                                 stdout=subprocess.DEVNULL, stderr=stderr_f)

        for frame_i in range(frames):
            t = frame_i / frames
            eased = 3 * t ** 2 - 2 * t ** 3   # smoothstep — тот же профиль, что у zoompan-версии
            zoom = (ZOOM_FLOOR + delta * eased) if zoom_in else (max_zoom - delta * eased)
            pan_px = pan_amt_frac * eased * min(cw, ch) * 0.5 * ((1 - 1 / zoom))

            map_x0 = cx + (ox_grid - WIDTH / 2) / zoom + dx * pan_px
            map_y0 = cy + (oy_grid - HEIGHT / 2) / zoom + dy * pan_px
            map_x0 = np.clip(map_x0, 0, cw - 1)
            map_y0 = np.clip(map_y0, 0, ch - 1)

            # warp_depth, а НЕ depth: геометрию двигаем по сглаженной карте
            # (см. PARALLAX_WARP_SIGMA_FRAC) — резкий край карты глубины и
            # есть источник разрыва картинки на силуэтах.
            d_here = cv2.remap(warp_depth, map_x0, map_y0, interpolation=cv2.INTER_LINEAR,
                                borderMode=cv2.BORDER_REPLICATE)
            extra = (d_here - 0.5) * parallax_px * eased   # центрировано: ближе/дальше среднего
            # 3D-репроекция (не только офсет при пане, но и СКОРОСТЬ ЗУМА
            # по глубине): d_here уже известен на "базовой" (единый zoom)
            # позиции — используем его как приближение реальной глубины
            # источника (двухпроходная аппроксимация, честный mesh-warp
            # избыточен для этой задачи). zoom_gain > 1 для близких
            # пикселей (d_here -> 1) — под push-in они растут БЫСТРЕЕ
            # среднего, зеркально для дальних (d_here -> 0) — это и есть
            # разница между "камера едет" (старая версия, все пиксели
            # растут с одной скоростью) и "камера едет СКВОЗЬ сцену с
            # глубиной" (ближние слои обгоняют дальние).
            zoom_gain = 1.0 + (d_here - 0.5) * depth_zoom_strength * eased
            zoom_gain = np.clip(zoom_gain, 0.88, 1.15)
            map_x = cx + (ox_grid - WIDTH / 2) / (zoom * zoom_gain) + dx * pan_px + dx * extra
            map_y = cy + (oy_grid - HEIGHT / 2) / (zoom * zoom_gain) + dy * pan_px + dy * extra
            # Лёгкий поворот кадра (roll) — независимая от зума/пана степень
            # свободы: камера не строго на рельсах, а слегка меняет угол.
            # Амплитуда мала (умещается в запас холста PARALLAX_MARGIN=1.5,
            # проверено вживую на отсутствие смазанных краёв), направление —
            # детерминировано по хэшу фото.
            if tilt_theta_max != 0.0:
                theta = tilt_theta_max * eased
                cos_t, sin_t = np.float32(math.cos(theta)), np.float32(math.sin(theta))
                rel_x, rel_y = map_x - cx, map_y - cy
                map_x = cx + rel_x * cos_t - rel_y * sin_t
                map_y = cy + rel_y * cos_t + rel_x * sin_t
            map_x = np.clip(map_x, 0, cw - 1)
            map_y = np.clip(map_y, 0, ch - 1)

            frame = cv2.remap(canvas, map_x, map_y, interpolation=cv2.INTER_LINEAR,
                               borderMode=cv2.BORDER_REPLICATE)
            if fg_alpha is not None:
                # Тот же map_x/map_y (единая геометрия варпа не меняется) —
                # только источник для "того, что за передним планом" теперь
                # уже заполненный инпейнт-фон, а не растянутая текстура.
                frame_bg = cv2.remap(bg_plate, map_x, map_y, interpolation=cv2.INTER_LINEAR,
                                      borderMode=cv2.BORDER_REPLICATE)
                alpha = cv2.remap(fg_alpha, map_x, map_y, interpolation=cv2.INTER_LINEAR,
                                   borderMode=cv2.BORDER_REPLICATE)[:, :, None]
                frame = (frame.astype(np.float32) * alpha
                         + frame_bg.astype(np.float32) * (1.0 - alpha)).astype(np.uint8)
            proc.stdin.write(frame.tobytes())

        proc.stdin.close()
        proc.wait(timeout=60)
        stderr_f.close()
        stderr_f = None
        if proc.returncode != 0:
            with open(stderr_path, "rb") as f:
                err_tail = f.read().decode(errors="replace")[-200:]
            print(f"  параллакс-рендер не встал ({os.path.basename(out)}): {err_tail}")
            finalize_render(tmp_out, out, False)
            return False
        # Без ретрая здесь намеренно — покадровый python-цикл с depth-моделью
        # на порядок дороже по времени, чем zoompan-версия, а у вызывающего
        # кода (main()) УЖЕ есть готовый fallback на дешёвый kenburns() при
        # False. Достаточно честно вернуть False на битом файле — верификация
        # ffprobe тут заменяет ретрай, не дублирует его.
        ok, reason, _ = verify_clip(tmp_out, dur)
        if not ok:
            print(f"  параллакс-файл не прошёл проверку ({os.path.basename(out)}): {reason}")
            finalize_render(tmp_out, out, False)
            return False
        return finalize_render(tmp_out, out, True)
    except Exception as e:
        print(f"  параллакс сорвался ({os.path.basename(out)}): {type(e).__name__} {e}")
        finalize_render(render_tmp_path(out), out, False)
        return False
    finally:
        # Раньше при сбое ПОСРЕДИ покадрового цикла (BrokenPipeError на
        # stdin.write, таймаут на wait) дочерний ffmpeg не убивался вообще —
        # завис бы висячим процессом до конца сессии. Гасим его в любом
        # случае, если он ещё жив к выходу из функции.
        if proc is not None and proc.poll() is None:
            try:
                proc.kill()
                proc.wait(timeout=5)
            except Exception:
                pass
        if stderr_f is not None:
            try:
                stderr_f.close()
            except Exception:
                pass
        if stderr_path is not None:
            try:
                os.remove(stderr_path)
            except OSError:
                pass


# Не динамический ramp внутри клипа (это отдельная и намного более сложная
# задача — переменная PTS-кривая), а постоянная скорость по контексту клипа:
# хук чуть быстрее — энергичнее, финал чуть медленнее — снимает напряжение.
SPEED_BIAS = {"HOOK": 1.12, "FINAL": 0.92}


def measure_motion(vid, start, span, samples=4):
    """Дешёвая оценка реального движения в клипе (frame-diff на N мелких
    170x90-кадрах, тот же приём, что measure_luma) — speed ramp (см. ниже)
    имеет смысл только там, где в кадре РЕАЛЬНО что-то происходит (взмах,
    шаг, панорама съёмщика), а не когда объект просто лежит/стоит в кадре —
    там ускорение ничем не мотивировано и выглядит как рывок, не приём.
    0.0 при любой ошибке/отсутствии numpy — ramp тогда просто не применяется
    (безопасный откат на старое поведение, тот же принцип, что PARALLAX_LIBS)."""
    if np is None:
        return 0.0
    try:
        frames = []
        for i in range(samples):
            t = start + span * (i + 0.5) / samples
            tmp = vid + f"._motion_probe_{i}.jpg"
            r = subprocess.run(
                ["ffmpeg", "-y", "-ss", f"{t:.2f}", "-i", vid, "-frames:v", "1",
                 "-vf", "scale=160:90", tmp],
                capture_output=True, timeout=15)
            if r.returncode == 0 and os.path.exists(tmp):
                img = PILImage.open(tmp).convert("L")
                frames.append(np.asarray(img, dtype=np.float32))
                os.remove(tmp)
        if len(frames) < 2:
            return 0.0
        diffs = [float(np.abs(frames[i] - frames[i - 1]).mean()) for i in range(1, len(frames))]
        return (sum(diffs) / len(diffs)) / 255.0
    except Exception:
        return 0.0


# Slow -> fast -> normal внутри ОДНОГО клипа — подчёркивает момент реального
# действия (замах, шаг, столкновение), а не плоская постоянная скорость на
# весь план (то, что уже делает SPEED_BIAS выше на уровне целого клипа).
# Тройка (доля_длительности_на_выходе, множитель_скорости).
SPEED_RAMP_SEGMENTS = [(0.30, 0.85), (0.45, 1.20), (0.25, 1.00)]
SPEED_RAMP_MOTION_THRESHOLD = 0.02   # ниже — план статичен, ramp не гейтится сюда
# РЕАЛЬНЫЙ баг, пойманный на реальном продакшн-рендере (не гипотеза): спид-
# рамп (split -> trim/setpts -> concat) в паре с film_look() (свой отдельный
# split/gblur=sigma=14/blend для bloom-эффекта, см. film_look()) вешает
# ffmpeg на источниках с аномально высоким fps (60/1, 60000/1001) —
# воспроизведено напрямую бисекцией: голый ramp без film_look — 20с, ramp+
# деффликер — 19с, ramp+film_look — не укладывается в 90с. На обычных
# ~24-30fps источниках та же связка (156 других клипов того же эпизода)
# отрабатывает штатно — проблема именно в комбинации высокого fps с
# вложенными split/concat узлами графа, не в film_look()/ramp по отдельности.
# Порог с запасом выше стандартных 24/25/30fps стока, ниже проблемных 60fps.
# 60fps-исходники и так часто сняты specifically под готовое замедление —
# пропуск доп. спид-рампа на них не потеря приёма, разумный трейд-офф.
SPEED_RAMP_MAX_SOURCE_FPS = 40.0


def build_speed_ramp_filter(skip, dur, actual, label_in="base", label_out="ramped"):
    """[label_in] -> trim/setpts по SPEED_RAMP_SEGMENTS -> concat -> [label_out],
    как отдельный кусок filter_complex-графа (не обычный -vf, т.к. нужен
    concat нескольких setpts-кусков одного и того же входа). None, если
    исходника не хватает (safety margin) — вызывающий код тогда просто не
    применяет ramp, как есть."""
    needed = dur * sum(frac * mult for frac, mult in SPEED_RAMP_SEGMENTS)
    if actual - skip < needed + 0.05:
        return None
    n = len(SPEED_RAMP_SEGMENTS)
    # Один и тот же [label_in] нельзя подать входом сразу в 3 независимых
    # trim (ffmpeg не фанаутит именованный pad автоматически) — явный split.
    split_labels = [f"{label_out}_s{i}" for i in range(n)]
    parts = [f"[{label_in}]split={n}{''.join(f'[{s}]' for s in split_labels)}"]
    labels, pos = [], skip
    for i, (frac, mult) in enumerate(SPEED_RAMP_SEGMENTS):
        out_d = dur * frac
        src_d = out_d * mult
        lbl = f"{label_out}{i}"
        # Motion blur ТОЛЬКО на реально ускоренном (mult>1) сегменте — без
        # смаза ускорение через голый setpts выглядит цифровым рывком
        # (кадры просто чаще пропускаются), со смазом читается как
        # операторский приём. Замедленный/нормальный сегмент не трогаем —
        # там лишнее размытие только портит резкость, которую специально
        # вернули unsharp'ом (см. film_look). tmix не меняет число кадров/
        # длительность — безопасно вставлять здесь без пересчёта таймингов.
        blur = ",tmix=frames=3:weights='1 2 1'" if mult > 1.0 else ""
        parts.append(
            f"[{split_labels[i]}]trim=start={pos:.3f}:duration={src_d:.3f},"
            f"setpts=PTS-STARTPTS,setpts={1 / mult:.5f}*PTS{blur}[{lbl}]")
        labels.append(f"[{lbl}]")
        pos += src_d
    parts.append(f"{''.join(labels)}concat=n={len(labels)}:v=1:a=0[{label_out}]")
    return ";".join(parts)


def detect_scene_change_offset(vid, max_skip, scene_threshold=0.12):
    """Сцен-анализ вместо чисто произвольного хэш-пропуска (см. video_render):
    ищем РЕАЛЬНЫЙ момент смены кадра/начала движения в допустимом окне
    [0, max_skip] штатным ffmpeg-детектором сцен (select=gt(scene,THRESH) —
    честный frame-diff, не полноценный optical flow, но быстро и без новых
    зависимостей). Берём САМУЮ ПОЗДНЮЮ найденную смену в пределах окна —
    максимально используем допустимый запас, но приземляемся точно на
    реальное событие в кадре, а не на случайное место.

    Порог уверенности: сцен не найдено (статичный до самого края план,
    либо анализ не удался) -> None, вызывающий код откатывается на старый
    детерминированный хэш-пропуск — то же safety-поведение, что у
    anchor-кропа/saliency (см. resolve_crop_anchor)."""
    try:
        r = subprocess.run(
            ["ffmpeg", "-i", vid, "-t", f"{max_skip:.2f}", "-vf",
             f"select='gt(scene\\,{scene_threshold})',showinfo", "-f", "null", "-"],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=30)
        times = [float(m) for m in re.findall(r"pts_time:([\d.]+)", r.stderr)]
        candidates = [t for t in times if 0.1 <= t <= max_skip]
        return max(candidates) if candidates else None
    except Exception:
        return None


def video_render(vid, out, dur, title=None, stat=None, section="", stat_variant=0,
                  brightness_bias=0.0, energy_bias=0.0, stat_delay=0.0, levels=None, wb=None,
                  grain_scale=1.0, handheld=False, captions=None, ffmpeg_threads=None):
    """Аналог kenburns(), но для стокового видео: без zoompan (движение уже
    есть в кадре), заливка кадра целиком + обрезка (не letterbox), растяжение
    по времени, если исходный ролик короче нужной длительности.

    handheld — лёгкая ручная тряска (C3): у фото уже есть film weave
    (WOBBLE_AMP_CANVAS_PX), у видео-стока движения камеры не было вообще —
    боевые сцены на стоке выглядели подозрительно гладко (будто со штатива).
    Заказывается по контенту (ACTION_WORDS в тексте блока, см. main()), не
    на каждый видео-кадр — на спокойных сюжетах тряска ничем не мотивирована.

    Speed ramp (slow->fast->normal, SPEED_RAMP_SEGMENTS) — отдельный путь
    через -filter_complex (нужен concat нескольких setpts-кусков ОДНОГО
    входа, обычный -vf так не умеет). Применяется только когда есть и запас
    исходника, и реальное движение в кадре (measure_motion) — иначе тихо
    падаем обратно на старый -vf путь ниже."""
    try:
        actual = get_media_duration(vid)
    except Exception:
        actual = dur
    # Заказ в кадрах — та же причина, что в kenburns(): точная единица вместо
    # сравнения дробных секунд (см. комментарий у -frames:v ниже).
    frames = max(1, int(round(dur * FPS)))
    h = int(hashlib.md5(vid.encode()).hexdigest()[:8], 16)
    if handheld:
        # Небольшой запас (3.5%) сверх целевого кадра под тряску — тот же
        # принцип, что PARALLAX_MARGIN у фото, просто меньше (тут не нужно
        # места под пан/зум, только под дрожание в несколько пикселей).
        ov_w, ov_h = round(WIDTH * 1.035), round(HEIGHT * 1.035)
        amp = 6.0
        ph1, ph2 = ((h >> 3) % 628) / 100.0, ((h >> 11) % 628) / 100.0
        shake_x = f"{amp:.1f}*sin(2*PI*t*0.9+{ph1:.2f})+{amp*0.6:.1f}*sin(2*PI*t*2.3+{ph2:.2f})"
        shake_y = f"{amp:.1f}*sin(2*PI*t*1.1+{ph2:.2f})+{amp*0.6:.1f}*sin(2*PI*t*2.7+{ph1:.2f})"
        scale_crop = (f"scale={ov_w}:{ov_h}:force_original_aspect_ratio=increase,"
                      f"crop={WIDTH}:{HEIGHT}:x='({ov_w}-{WIDTH})/2+{shake_x}':"
                      f"y='({ov_h}-{HEIGHT})/2+{shake_y}',setsar=1")
    else:
        scale_crop = f"scale={WIDTH}:{HEIGHT}:force_original_aspect_ratio=increase,crop={WIDTH}:{HEIGHT},setsar=1"
    if DEFLICKER_ENABLED:
        # ПОСЛЕ scale/crop (работает на целевом разрешении, не на исходнике —
        # дешевле, порядок с setpts ниже не важен: deflicker смотрит на
        # ПОСЛЕДОВАТЕЛЬНОСТЬ кадров, setpts меняет только PTS-метки, не сам
        # контент/порядок кадров), ДО film_look() — творческий грейд видит уже
        # сглаженный по яркости кадр, не сырой источник.
        scale_crop += f",{DEFLICKER_FILTER.rstrip(',')}"
    bias = next((v for k, v in SPEED_BIAS.items() if section.startswith(k)), 1.0)
    # Стоковое видео часто начинается со статичного/вялого кадра до того, как
    # начнётся реальное движение (панорама разгоняется, руки только подносят
    # предмет к камере) — первая секунда почти всегда самая скучная в клипе.
    # Пропуск возможен только если есть запас (actual заметно больше dur) —
    # иначе откусили бы от нужной длительности и пришлось бы растягивать
    # (setpts) остаток, что и так уже отдельная ветка ниже. Детерминированный
    # джиттер по хэшу файла — не одна и та же доля пропуска на каждом клипе.
    skip = 0.0
    if actual - dur > 0.6:
        max_skip = min(1.6, (actual - dur) * 0.5)
        scene_skip = detect_scene_change_offset(vid, max_skip)
        skip = scene_skip if scene_skip is not None else (
            max_skip * (0.5 + ((h >> 20) % 1000) / 1000.0 * 0.5))

    ramp_filter = None
    margin_needed = dur * sum(frac * mult for frac, mult in SPEED_RAMP_SEGMENTS)
    if actual - skip >= margin_needed + 0.05:
        src_fps = get_media_fps(vid)
        # SPEED_RAMP_MAX_SOURCE_FPS — см. докстринг константы (реальный
        # зависший рендер на 60fps-стоке, не гипотеза). src_fps=None
        # (ffprobe не смог определить) -> не гейтим, прежнее поведение.
        if src_fps is None or src_fps <= SPEED_RAMP_MAX_SOURCE_FPS:
            motion = measure_motion(vid, skip, min(dur, actual - skip))
            if motion >= SPEED_RAMP_MOTION_THRESHOLD:
                ramp_filter = build_speed_ramp_filter(skip, dur, actual)

    tmp_out = render_tmp_path(out)
    if ramp_filter:
        tail = film_look(h, section, brightness_bias, energy_bias, levels, wb)
        full_tail = tail
        if title or stat or captions:
            full_tail = add_overlays(tail, dur, title, stat, stat_variant, stat_delay)
            full_tail = add_kinetic_captions(full_tail, captions)
        cmd = ["ffmpeg", "-y", "-i", vid]
        if GRAIN_ENABLED:
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
            filter_complex = (f"[0:v]{scale_crop}[base];{ramp_filter};"
                               f"[ramped]{full_tail}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}")
        else:
            filter_complex = f"[0:v]{scale_crop}[base];{ramp_filter};[ramped]{full_tail}[vout]"
        cmd += ["-filter_complex", filter_complex,
               "-map", "[vout]", "-frames:v", str(frames), "-an",
               "-c:v", "libx264", "-preset", RENDER_PRESET, "-crf", RENDER_CRF,
               "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS
        if ffmpeg_threads:
            cmd += ["-threads", str(ffmpeg_threads)]
        cmd += [tmp_out]
        ok, reason = run_ffmpeg_with_retry(
            lambda: subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=render_timeout_sec(dur)),
            tmp_out, dur, os.path.basename(out))
        if ok:
            return finalize_render(tmp_out, out, True)
        print(f"  speed ramp не встал на видео ({os.path.basename(out)}): {reason} — рисую без ramp")

    vf_base = scale_crop
    setpts_factor = None
    if actual < dur - 0.05:
        setpts_factor = dur / max(actual, 0.1)   # уже растягиваем нехватку — bias не добавляем поверх
    elif bias != 1.0 and actual >= dur * bias:
        setpts_factor = 1.0 / bias
    if setpts_factor is not None:
        vf_base += f",setpts={setpts_factor:.5f}*PTS"
    vf_base += f",{film_look(h, section, brightness_bias, energy_bias, levels, wb)}"
    vf_overlay = None
    if title or stat or captions:
        vf_overlay = add_overlays(vf_base, dur, title, stat, stat_variant, stat_delay)
        vf_overlay = add_kinetic_captions(vf_overlay, captions)

    def render(vf):
        cmd = ["ffmpeg", "-y"]
        if skip > 0.05:
            cmd += ["-ss", f"{skip:.2f}"]
        cmd += ["-i", vid]
        if GRAIN_ENABLED:
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
            fc = f"[0:v]{vf}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}"
            cmd += ["-filter_complex", fc, "-map", "[vout]"]
        else:
            cmd += ["-vf", vf]
        cmd += ["-frames:v", str(frames), "-an",
                "-c:v", "libx264", "-preset", RENDER_PRESET, "-crf", RENDER_CRF,
                "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS
        if ffmpeg_threads:
            cmd += ["-threads", str(ffmpeg_threads)]
        cmd += [tmp_out]
        return subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=render_timeout_sec(dur))

    label = os.path.basename(out)
    if vf_overlay:
        ok, reason = run_ffmpeg_with_retry(lambda: render(vf_overlay), tmp_out, dur, label)
        if ok:
            return finalize_render(tmp_out, out, True)
        if not _looks_like_drawtext_failure(reason):
            # См. _looks_like_drawtext_failure — тот же принцип, что kenburns().
            print(f"  [{label}] рендер видео с подписями не удался ({reason}) — "
                  f"это не про drawtext, не откатываюсь на версию без них")
            return finalize_render(tmp_out, out, False)
        print(f"  титр/плашка не встали на видео ({label}): {reason} — рисую без них")
    ok, reason = run_ffmpeg_with_retry(lambda: render(vf_base), tmp_out, dur, label)
    if not ok:
        print(f"  [{label}] рендер видео не удался после {RENDER_RETRY_ATTEMPTS} попыток: {reason}")
    return finalize_render(tmp_out, out, ok)


# Во сколько раз видео-кандидату РАЗРЕШЕНО быть короче своего слота.
# video_render() растягивает нехватку через setpts (setpts_factor = dur /
# actual) — без интерполяции кадров: каждый исходный кадр просто держится
# несколько выходных, то есть 3-секундный клип в 12-секундном слоте едет
# вчетверо медленнее и заметно дёргается. Потолка у этого растяжения не
# было вообще, а отбор кандидата смотрел ТОЛЬКО на ширину файла
# (min(files, key=|width - WIDTH|)) — поле duration, которое Pexels отдаёт
# для каждого видео в той же выдаче, не читалось нигде.
#
# 1.5 выбран как граница ЗАМЕТНОСТИ, а не как "хорошо бы подлиннее":
# замедление до полутора раз на 24 fps читается как спокойный темп сцены,
# дальше — как подтормаживающее видео. Гейт сознательно мягкий: его задача
# — убрать кандидатов, чей результат ОБЪЕКТИВНО сломан, а не улучшать
# подбор (этим занимаются relevance/домен-гвард/вето, и трогать их баланс
# здесь нельзя — релевантность на этом канале дефицитнее длины).
VIDEO_MAX_TIME_STRETCH = 1.5

# Слоты, где фильтр реально сработал — для сводки в конце прогона. Пустой
# список = на этом эпизоде проблема не возникала (честная запись "нечего
# сообщить", тот же принцип, что у остальных отчётов).
VIDEO_TOO_SHORT_FILTERED = []   # [{"index", "dropped", "kept"}, ...]


def _video_candidate_too_short(item, slot_dur):
    """Кандидат, которого физически нельзя показать в слоте slot_dur без
    растяжения сильнее VIDEO_MAX_TIME_STRETCH.

    duration у Pexels — целые секунды, поэтому сравнение консервативное:
    отсутствующее/нечисловое значение считается ПРИГОДНЫМ (fail-open — тот
    же принцип, что у всех остальных опциональных проверок здесь: не знаем
    — не отбрасываем)."""
    if not slot_dur or slot_dur <= 0:
        return False
    try:
        dur = float(item.get("duration") or 0)
    except (TypeError, ValueError):
        return False
    if dur <= 0:
        return False
    return dur * VIDEO_MAX_TIME_STRETCH < slot_dur


VIDEO_MIN_LUMA_HARD = 0.06     # ниже — кадр практически чёрный, отбраковка
VIDEO_PREFER_MIN_LUMA = 0.18   # ниже — кадр читается плохо, уступает более светлому
_PEXELS_VIDEO_SEARCH_CACHE = {}


def _pexels_search_videos(api_query):
    """Видео-выдача Pexels с кэшем на процесс — та же причина и та же
    механика, что у _pexels_search_photos (см. её докстринг): без кэша сбор
    пула из всех запросов секции упёрся бы в квоту 200/час."""
    if api_query in _PEXELS_VIDEO_SEARCH_CACHE:
        return _PEXELS_VIDEO_SEARCH_CACHE[api_query]
    if not PEXELS_API_KEY:
        return []   # см. _pexels_search_photos: без ключа — пустой вклад, не выход
    q = urllib.parse.quote(api_query)

    def fetch():
        req = urllib.request.Request(
            f"https://api.pexels.com/videos/search?query={q}&per_page=80&orientation=landscape",
            headers={"Authorization": PEXELS_API_KEY, "User-Agent": UA})
        with urllib.request.urlopen(req, timeout=15) as r:
            _note_pexels_quota(r)
            return json.load(r)
    data = cached_search_json("pexels_video", f"{api_query}|80|landscape", fetch)
    videos = data.get("videos") or []
    _PEXELS_VIDEO_SEARCH_CACHE[api_query] = videos
    return videos


# ОТБОР ВИДЕО В ОБЩЕМ ЯДРЕ (этап 3 перестройки).
#
# Раньше видео отбиралось своей рукописной копией алгоритма (pexels_video,
# затем _select_video) — и каждое улучшение фото доезжало до видео поздно
# или никогда (CLAUDE.md перечисляет семь таких случаев). Главное узкое
# место было физическим: чтобы проверить кандидата, ролик СКАЧИВАЛСЯ
# целиком ради одного кадра-пробника, поэтому смотрели 3-5 роликов из
# сотен (замер эпизода 94: 3-5 из 163-492), и бюджет решал, а не смысл.
#
# Теперь кандидат оценивается по ПРЕВЬЮ-КАДРАМ, которые источник отдаёт сам:
# у Pexels — 15 кадров по длине ролика (берутся 15/50/85% — ровно те точки,
# на которых видео проверялось и раньше, VIDEO_DOMAIN_GUARD_SAMPLE_FRACS),
# у Pixabay — один кадр-обложка. Скачивается только победитель; резкость и
# вторая проверка — на настоящем файле, провал — следующий по ранжированию.
#
# Проверки и ранжирование — ТЕ ЖЕ функции, что у фото: is_relevant_candidate
# на среднем кадре плюс гварды на каждом кадре (нарушение на любом —
# нарушение ролика, та же семантика, что у многокадровых гвардов), судья
# кадров — на ленте из трёх кадров, выбор — _score_and_pick.
VIDEO_PREVIEW_FRACS = VIDEO_DOMAIN_GUARD_SAMPLE_FRACS
# Сколько кандидатов оценивать по превью. Превью — три маленьких JPEG и
# три прохода CLIP (доли секунды), поэтому пул видео равен пулу фото и НЕ
# урезается после хука: урезание было ценой скачивания роликов, а его нет.
VIDEO_PREVIEW_POOL = BASE_MIN_POOL
# Версия устройства видео-пути: входит в подпись отбора — смена того, КАК
# отбирается видео, обязана перевыбрать кадры на прогретом кэше.
VIDEO_ENGINE_VERSION = 1


def video_preview_urls(v):
    """Адреса превью-кадров кандидата по порядку времени (<= 3)."""
    pics = [p for p in (v.get("video_pictures") or []) if p.get("picture")]
    if pics:
        pics = sorted(pics, key=lambda p: p.get("nr", 0))
        idx = list(dict.fromkeys(round((len(pics) - 1) * f) for f in VIDEO_PREVIEW_FRACS))
        return [pics[k]["picture"] for k in idx]
    return [u for u in (v.get("_preview_frames") or []) if u]


def video_middle_url(v):
    """Средний кадр превью ролика — то, по чему каскад его ранжирует."""
    urls = video_preview_urls(v)
    return urls[len(urls) // 2] if urls else None


def video_middle_probe(v, dest):
    url = video_middle_url(v)
    if not url:
        raise ValueError("нет превью")
    atomic_url_download(urllib.request.Request(url, headers={"User-Agent": UA}), dest, timeout=20)


def video_strip(frames, dest, height=240):
    """Лента из кадров одного ролика слева направо — то, что видит судья."""
    from PIL import Image
    ims = []
    for f in frames:
        im = Image.open(f).convert("RGB")
        ims.append(im.resize((max(1, int(im.width * height / im.height)), height)))
    strip = Image.new("RGB", (sum(i.width for i in ims) + 6 * (len(ims) - 1), height), (0, 0, 0))
    x = 0
    for im in ims:
        strip.paste(im, (x, 0))
        x += im.width + 6
    strip.save(dest, quality=88)
    return dest


def video_frames_violate(frames, query):
    """Гварды домена и ловушек на КАЖДОМ кадре: нарушение на любом —
    нарушение ролика (та же семантика, что у многокадровых гвардов по файлу:
    брак в одном месте ролика не виден в другом)."""
    for f in frames:
        if visual_domain_guard_violation(f, query)[0] or negative_anchor_violation(f, query)[0]:
            return True
    return False


class VideoAdapter(selection_engine.MediaAdapter):
    """Адаптер видео для ядра отбора. Контракт — как у PhotoAdapter;
    отличия идут только от природы видео (превью-кадры, лента для судьи,
    скачивание одного победителя)."""
    kind = "video"

    def cache_path(self, request):
        cache = os.path.join(TEMP_FOLDER, "pexels_video_cache")
        os.makedirs(cache, exist_ok=True)
        _brief_key = candidate_brief_key(request.shot_brief, uses_shelf=False)
        qkey = "|".join([request.query] + sorted(q for q in (request.extra_queries or [])
                                                 if q and q != request.query)
                        + ([request.text_key] if request.text_key else [])
                        + ([_brief_key] if _brief_key else [])
                        + spec_key_parts(request.shot_spec))
        qhash = hashlib.md5(qkey.encode()).hexdigest()[:8]
        gate_sig = candidate_gate_signature(request.index).split(":", 1)[-1]
        return os.path.join(cache, f"{request.index:04d}_{qhash}_{gate_sig}.mp4")

    def cache_hit(self, request, cf):
        """Как у фото: кадр из кэша, визуально повторяющий уже показанное,
        не принимается (раньше видео проверялось только по id). Отпечаток
        кадра берётся из sidecar — ffmpeg на кэш-хите не нужен."""
        used_hashes = request.used_hashes
        h = read_media_sidecar(cf).get("ahash")
        if used_hashes and h and min((hamming(h, uh) for uh in used_hashes), default=99) \
                <= PHOTO_DEDUP_HAMMING:
            return None
        register_cached_media(cf, used_ids=request.used_video_ids,
                              used_hashes=request.used_hashes, kind="video")
        _restore_cached_quality(cf)
        _reset_pexels_streak()
        return cf

    def brief_query(self, request):
        return brief_stock_query_of(request)

    def sources(self, request, pq):
        api_q = stock_api_query(request, pq, video=True)
        low = pq not in slot_own_queries(request)
        out = []
        for fetch in (_pexels_search_videos, _pixabay_search_videos):
            if (fetch is _pexels_search_videos
                    and not pexels_query_allowed(api_q, _PEXELS_VIDEO_SEARCH_CACHE, low)):
                out.append([])
                continue
            out.append([dict(v, _origin_query=pq) for v in fetch(api_q)])
        return out

    def filter_pool(self, request, pool):
        pool = filter_pool_by_text(pool, request.index)
        used_ids, slot_dur = request.used_video_ids, request.slot_dur
        if used_ids is not None:
            pool = ([v for v in pool if v.get("id") not in used_ids]
                    + [v for v in pool if v.get("id") in used_ids])
        if slot_dur:
            long_enough = [v for v in pool if not _video_candidate_too_short(v, slot_dur)]
            if long_enough and len(long_enough) < len(pool):
                VIDEO_TOO_SHORT_FILTERED.append(
                    {"index": request.index, "dropped": len(pool) - len(long_enough),
                     "kept": len(long_enough), "slot_dur": round(float(slot_dur), 2)})
                pool = long_enough
        return pool

    def note_offered(self, pool):
        for v in pool:
            _source_bump(candidate_channel(v), "offered")

    def on_failure(self, request, exc):
        _note_pexels_failure(exc, f"Pexels video [{request.query}]")

    def _preview(self, v, cf):
        """Кадры превью на диск: список путей по времени или None."""
        paths = []
        for k, url in enumerate(video_preview_urls(v)):
            dest = cf + f".prev_{candidate_path_token(v)}_{k}.jpg"
            atomic_url_download(urllib.request.Request(url, headers={"User-Agent": UA}),
                                dest, timeout=20)
            if not _downloaded_ok(dest):
                return None
            paths.append(dest)
        return paths or None

    def _download(self, v, dest):
        files = [f for f in (v.get("video_files") or [])
                 if f.get("file_type") == "video/mp4" and f.get("width")]
        if not files:
            raise ValueError("нет mp4")
        best = min(files, key=lambda f: abs(f["width"] - WIDTH))
        atomic_url_download(urllib.request.Request(best["link"], headers={"User-Agent": UA}),
                            dest, timeout=40)

    def choose(self, request, pool, cf):
        query, index = request.query, request.index
        used_hashes, recent_sizes = request.used_hashes, request.recent_sizes
        score_fn, arbiter_text = request.video_score_fn, request.arbiter_text
        if shot_judge_active(index):
            # Каскад и у видео (раньше смотрелись 20 первых по кругу — 3-9%
            # пула): средний кадр превью каждого ролика ранжируется по
            # утверждениям спецификации, как фото — по своему превью.
            pool = cascade_reorder(pool, cascade_texts(request.shot_spec, request.shot_brief or query,
                                                       "video"),
                                   cf, video_middle_probe, index, url_of=video_middle_url,
                                   claims=cascade_claims(request.shot_spec, "video"))
            # Уже использованные в эпизоде ролики — в хвост и после каскада
            # (filter_pool их понизил, каскад без этого поднимал бы обратно).
            used = request.used_video_ids or ()
            pool = [v for v in pool if v.get("id") not in used] + [v for v in pool if v.get("id") in used]
        trial_slice = pool[:VIDEO_PREVIEW_POOL]
        with concurrent.futures.ThreadPoolExecutor(
                max_workers=max(1, min(PHOTO_PREFETCH_WORKERS, len(trial_slice)))) as ex:
            previews = list(ex.map(lambda v: self._safe_preview(v, cf), trial_slice))
        candidates_info = []
        for v, frames in zip(trial_slice, previews):
            if not frames:
                _source_bump(candidate_channel(v), "download_errors")
                continue
            _source_bump(candidate_channel(v), "considered")
            mid = frames[len(frames) // 2]
            try:
                h = ahash(mid)
            except Exception:
                h = None
            min_d = (min((hamming(h, uh) for uh in used_hashes), default=99)
                     if (h is not None and used_hashes) else 99)
            size_ok = 1
            if recent_sizes is not None:
                try:
                    size_ok = 0 if estimate_shot_size(mid) in recent_sizes[-2:] else 1
                except Exception:
                    size_ok = 1
            relevance = clip_relevance(mid, query)
            relevant = is_relevant_candidate(mid, query, relevance=relevance)
            if relevant and video_frames_violate([f for f in frames if f != mid], query):
                relevant = False
            luma = None
            try:
                luma = measure_luma(mid)
            except Exception:
                pass
            if luma is not None and luma < VIDEO_MIN_LUMA_HARD:
                relevant = False
            aesthetic = aesthetic_score(mid)
            strip = video_strip(frames, cf + f".strip_{candidate_path_token(v)}.jpg")
            candidates_info.append({
                "path": mid, "judge_path": strip, "frames": frames, "p": v, "hash": h,
                "is_readable": frame_readable(mid),
                "is_dup_free": 1 if min_d > PHOTO_DEDUP_HAMMING else 0, "size_ok": size_ok,
                # Читаемость кадра — ось ТЕХНИЧЕСКОЙ годности (рядом с
                # резкостью): тёмный ролик плохо читается на экране при
                # любом смысле, поэтому уступает читаемому выше тонкой
                # разницы релевантности, но ниже самого прохождения гейтов —
                # то же правило, что прежний видео-путь держал отдельным
                # сравнением; здесь — тем же ранжированием, что у фото.
                "is_relevant": 1 if relevant else 0,
                "sharp_ok": 1 if (luma is None or luma >= VIDEO_PREFER_MIN_LUMA) else 0,
                "aesthetic_val": aesthetic if aesthetic is not None else 0.0,
                "luma_score": 0.0,
                "min_d": min_d, "relevance": relevance,
            })
            if relevant and min_d > PHOTO_DEDUP_HAMMING:
                _source_bump(candidate_channel(v), "gate_passed")
        try:
            return self._pick(request, candidates_info, cf, len(pool))
        finally:
            for c in candidates_info:
                for f in c["frames"] + [c["judge_path"]]:
                    try:
                        os.remove(f)
                    except OSError:
                        pass

    def _safe_preview(self, v, cf):
        try:
            return self._preview(v, cf)
        except Exception:
            return None

    def _pick(self, request, candidates_info, cf, n_available):
        query, index = request.query, request.index
        if not candidates_info:
            return None
        judged = judge_candidates(index, "video", request.block_text,
                                  request.shot_brief or query, candidates_info,
                                  request.shot_spec)
        score_fn = request.video_score_fn
        base, director = _score_and_pick(candidates_info, score_fn)
        winner = director if (request.director_assist and director is not None) else base
        chosen_by = "video_director" if winner is director and director is not base else "video_ranked"
        if (request.arbiter_text is not None and winner is not None and not judged
                and feature_flags.mode("VLM_ARBITER_MODE") == "on"):
            shortlist = (_build_opening_shortlist(candidates_info, base, director)
                         if request.is_opening else
                         _build_arbiter_shortlist(candidates_info, base, director, query))
            if len(shortlist) >= 2:
                import shot_director
                pick = shot_director.arbitrate_hook_candidates(
                    request.arbiter_text, [c["path"] for c in shortlist],
                    [c["p"].get("id") for c in shortlist], VIDEO_FOLDER,
                    is_opening=request.is_opening)
                if pick is shot_director.NO_CANDIDATE_FITS:
                    selection_attempt.record_verdict("arbiter", {
                        "index": index, "kind": "video", "query": query,
                        "text": request.arbiter_text, "n_candidates": len(shortlist),
                        "is_opening": bool(request.is_opening)})
                elif pick is not None:
                    match = next((c for c in shortlist if c["path"] == pick), None)
                    if match is not None:
                        winner, chosen_by = match, "video_arbiter"
        # Скачивается только победитель. Провал скачивания, резкости или
        # второй проверки (кроме одобренного судьёй) — кандидат уступает
        # место следующему, тем же приёмом, что у фото.
        repicks = 0
        rejected, rejected_ids = [], set()
        while winner is not None:
            reason = None
            vid_key = _candidate_block_key(winner["p"])
            if _VIDEO_UNSHARP_CACHE.get(vid_key):
                # Этот ролик уже скачивался в прогоне и не прошёл резкость —
                # тот же файл даст тот же вердикт; качать его заново незачем.
                reason = "sharpness"
                winner["sharp_ok"] = 0
            else:
                try:
                    self._download(winner["p"], cf)
                    if not _downloaded_ok(cf):
                        reason = "download"
                except Exception:
                    reason = "download"
            if reason == "sharpness":
                pass
            elif reason == "download":
                _source_bump(candidate_channel(winner["p"]), "download_errors")
                winner["is_dup_free"] = 0
            elif video_sharpness_ok(cf) is False:
                reason = "sharpness"
                winner["sharp_ok"] = 0
                _VIDEO_UNSHARP_CACHE[vid_key] = True
            elif not claims_checked(winner) and video_smart_relevance_veto(cf, query):
                reason = "smart_veto"
                winner["is_relevant"] = 0
            if reason is None:
                break
            rejected.append({"id": winner["p"].get("id"), "reason": reason})
            rejected_ids.add(id(winner))
            if repicks >= VETO_REPICK_MAX:
                winner = None
                break
            repicks += 1
            chosen_by = chosen_by + "+repick" if "+repick" not in chosen_by else chosen_by
            winner = _repick(candidates_info, winner, score_fn, request.director_assist,
                             rejected_ids, same_meaning=(reason == "sharpness"))
        if winner is None:
            selection_attempt.record_verdict("smart_veto", {"index": index, "query": query, "kind": "video",
                                                            "rejected": rejected})
            try:
                os.remove(cf)
            except OSError:
                pass
            why = ", ".join(f"{r['id']}: {r['reason']}" for r in rejected) or "нет кандидатов"
            print(f"  слот {index}: видео не принято ({why}) — слот остаётся без видео")
            return None
        if not winner["is_relevant"]:
            selection_attempt.record_verdict("relevance", {
                "index": index, "query": query, "relevance": winner.get("relevance"),
                "threshold": CLIP_RELEVANCE_THRESHOLD, "kind": "video"})
            selection_attempt.record_verdict("stock", {
                "index": index, "kind": "video", "query": query,
                "n_candidates_examined": len(candidates_info),
                "n_candidates_available": n_available})
            chosen_by = "video_below_threshold"
        if judged:
            chosen_by += "+judge"
            selection_attempt.record_note("judge_score", winner.get("judge"))
            selection_attempt.record_note("quality", winner_quality(winner))
            selection_attempt.record_note("focus_met", bool(winner.get("verify_focus")))
        if (judged and judge_rejected(winner)) or (not judged and winner is not None and not screen_allowed(winner)):
            selection_attempt.record_verdict("judge", {
                "index": index, "kind": "video", "query": query,
                "brief": request.shot_brief, "score": winner.get("judge"),
                "model": shot_judge_model()})
        elif judged:
            selection_attempt.record_verdict(JUDGE_APPROVED_VERDICT, {
                "index": index, "kind": "video", "score": winner.get("judge")})
        pick = winner["p"]
        if request.used_video_ids is not None:
            selection_attempt.record_effect("reserve_id", request.used_video_ids, pick.get("id"))
        if request.used_hashes is not None and winner["hash"] is not None:
            selection_attempt.record_effect("reserve_hash", request.used_hashes, winner["hash"])
        selection_attempt.record_effect("license", candidate_provenance(pick), query)
        selection_attempt.record_effect("source_won", candidate_channel(pick))
        write_media_sidecar(cf, pexels_id=pick.get("id"), query=query, kind="video",
                            ahash_hex=winner["hash"], relevance=winner.get("relevance"),
                            chosen_by=chosen_by, provenance=candidate_provenance(pick),
                            quality=(winner_quality(winner) if judged else None))
        _reset_pexels_streak()
        return cf


VIDEO_ADAPTER = VideoAdapter()


def _select_video(request):
    return selection_engine.select(request, VIDEO_ADAPTER)


def _select_photo(request):
    return selection_engine.select(request, PHOTO_ADAPTER)


# Отбор по виду медиа. Фото — ядро с адаптером фото; видео — пока своим
# путём (этап 3 переносит его в то же ядро).
MEDIA_SELECTORS = {"photo": _select_photo, "video": _select_video}

# Мгновенный рез после stat-плашки. Раньше 0.03с — при FPS=24 это 0.72 кадра,
# то есть физически НЕ короче обычного hardcut: ffmpeg всё равно округлял его
# до того же одного кадра. Один кадр — реальный минимум сетки, и теперь это
# написано честно (ветка в плане переходов остаётся отдельной: смысл разный,
# и при другом FPS значения снова разойдутся).
SNAP_CUT_DUR = 1 / FPS


def quantize_dur_to_frame(d):
    """Длительность -> ближайшее целое число кадров (минимум один кадр)."""
    return max(1, int(round(d * FPS))) / FPS


def quantize_durations_to_frames(durs):
    """Кадровая сетка для ВСЕХ длительностей клипов, с диффузией ошибки
    округления в следующий клип.

    Зачем (реальный, посчитанный рассинхрон, не гипотеза): длительность
    клипа физически не может быть дробной по кадрам — ffmpeg всё равно
    отдаёт целое число кадров. Раньше клипу заказывалось, например, 3.5671с,
    а на выходе получалось 86 кадров = 3.5833с, то есть в среднем +20мс на
    каждый клип В ОДНУ СТОРОНУ. На эпизоде из 400-500 кадров (после
    sub-cuts) это 8-10 секунд систематического ухода видео вперёд от
    голоса, которые потом просто отрезались финальным муксом (-t по длине
    аудио) — то есть последние кадры ролика вообще не доезжали, а картинка
    к концу отставала от текста.

    Диффузия (carry) важнее самого округления: без неё ошибки округления
    (до полукадра каждая) складывались бы случайным блужданием на сотнях
    клипов; с carry суммарная ошибка ВСЕГО таймлайна ограничена полукадром
    (~21мс при 24fps) независимо от числа клипов."""
    out, carry = [], 0.0
    for d in durs:
        target = d + carry
        q = quantize_dur_to_frame(target)
        carry = target - q
        out.append(q)
    return out


def plan_transitions(sections, blocks=None, xfade_dur=XFADE_DUR):
    """План склейки: [(тип_перехода, длительность), ...] длиной len(sections)-1,
    где элемент j описывает переход между клипами j и j+1.

    ЗАЧЕМ ОТДЕЛЬНАЯ ФУНКЦИЯ (реальный баг, а не рефакторинг ради красоты).
    Раньше тип и длительность перехода выбирались ВНУТРИ xfade_chain() по
    хэшу ПУТЕЙ ФАЙЛОВ клипов. А пути содержат params_hash, в который входит
    длительность клипа (см. main()) — то есть узнать план можно было только
    ПОСЛЕ того, как длительности уже посчитаны. Но длительности считаются
    из бюджета нахлёстов, а бюджет — это и есть сумма плана: замкнутый круг.
    Из-за него estimate_xfade_budget() был вынужден брать ВЕРХНЮЮ ГРАНИЦУ
    "обычной" пары (0.1667с) вместо факта, а факт — 85% одного кадра
    (0.0417с). Перебор ~0.12с на каждой обычной склейке; на 300+ обычных
    склейках 40-минутного эпизода это 35+ секунд, на которые видео
    оказывалось ДЛИННЕЕ аудио. Финальный мукс обрезал их по -t, то есть:
    (1) хвост ролика (несколько последних кадров) не попадал в файл вообще,
    (2) картинка накопительно отставала от голоса — к концу эпизода на
    десятки секунд, при том что весь остальной код (alignment.csv,
    section_sync, snap_hook_cuts_to_energy) борется за точность до
    десятых долей секунды.

    Хэш теперь считается от (номер склейки + имена секций) — данных,
    известных ДО выбора файлов. Разнообразие ровно то же (тот же md5, та же
    статистика), круговая зависимость исчезла, и один и тот же план
    используется и для бюджета, и для реальной склейки, и для расчёта
    визуальных стартов подписей — они физически не могут разойтись.

    Логика ветвления — ровно та, что была в xfade_chain() (переход = сигнал
    драматургии): граница секции -> заметный переход; sub-cut -> один кадр;
    сразу после stat-плашки -> snap; хук -> только жёсткие резы; остальное —
    85% hardcut / 15% короткий диссолв."""
    plan = []
    cut_hist, boundary_hist = [], []
    for i in range(1, len(sections)):
        h = int(hashlib.md5(f"xfade:{i}|{sections[i - 1]}|{sections[i]}".encode()).hexdigest()[:8], 16)
        is_boundary = sections[i] != sections[i - 1]
        b_prev = blocks[i - 1] if blocks else None
        b_cur = blocks[i] if blocks else None
        if is_boundary:
            candidate = BOUNDARY_TRANSITIONS[h % len(BOUNDARY_TRANSITIONS)]
            transition = pick_no_repeat(boundary_hist, candidate, BOUNDARY_TRANSITIONS, 1)
            this_dur = xfade_dur
        elif b_cur is not None and b_cur.get("is_subcut"):
            transition, this_dur = "fade", XFADE_DUR_HARD
        elif b_prev is not None and b_prev.get("stat"):
            transition, this_dur = "fade", SNAP_CUT_DUR
        elif b_cur is not None and sections[i].startswith("HOOK"):
            transition, this_dur = "fade", XFADE_DUR_HARD
        else:
            candidate = "hardcut" if (h % 20 >= 3) else XFADE_TRANSITIONS[(h >> 8) % len(XFADE_TRANSITIONS)]
            choice = pick_no_repeat(cut_hist, candidate, ["hardcut"] + XFADE_TRANSITIONS, max_repeat=3)
            this_dur = XFADE_DUR_HARD if choice == "hardcut" else xfade_dur * 0.4
            transition = "fade" if choice == "hardcut" else choice
        plan.append((transition, quantize_dur_to_frame(this_dur)))
    return plan


def xfade_chain(clips, durs, sections, out, xfade_dur=XFADE_DUR, blocks=None, plan=None):
    """Один проход filter_complex с цепочкой xfade между ВСЕМИ соседними
    кадрами — вместо жёсткой склейки. Переход = сигнал драматургии, не
    случайность: раньше тип перехода выбирался чисто хэшем путей файлов,
    без связи со сменой темы/функции блока — dissolve мог случайно попасть
    внутрь одной фразы, hardcut — между разделами. Теперь мотивированно
    (нужен параллельный список blocks — метаданные клипов, is_subcut/stat/
    section; без него откат на старое хэш-разнообразие для обратной
    совместимости):
    - граница секции → dissolve/fadeblack/fadewhite (смена темы)
    - sub-cut внутри одного исходного блока → только hardcut (это один кадр
      мысли, разрезанный на фазы — не повод анонсировать переход)
    - сразу после клипа со stat-плашкой → snap cut (мгновенный, короче
      обычного hardcut — цифра "впечаталась" и тут же сменилась)
    - весь хук → только hardcut (энергия, скорость, никаких dissolve)
    - остальное — 85% hardcut / 15% короткий dissolve (не полный xfade_dur)
    Возвращает (True, итоговая_длительность) или (False, 0.0), если
    что-то пошло не так (тогда main() откатывается на обычный concat -c copy)."""
    n = len(clips)
    if n < 2:
        return False, 0.0
    # План склейки (тип/длительность каждого перехода) считает plan_transitions()
    # — ОДИН источник истины и для бюджета длительностей, и для этой склейки,
    # и для visual_starts подписей (см. её докстринг про круговую зависимость).
    if plan is None:
        plan = plan_transitions(sections, blocks, xfade_dur=xfade_dur)
    parts, prev_label, cum = [], "0:v", durs[0]
    for i in range(1, n):
        transition, this_dur = plan[i - 1]
        offset = max(0.0, cum - this_dur)
        out_label = f"vx{i}" if i < n - 1 else "vout"
        # .6f, не .3f: offset к концу длинного эпизода — тысячи секунд, и
        # округление до миллисекунд может сдвинуть его на кадр относительно
        # плана (ffmpeg переводит offset в кадры). Полукадр при 24fps — 21мс,
        # запас на порядок больше миллисекунды, но печатать точно ничего не
        # стоит, а гарантия появляется.
        parts.append(f"[{prev_label}][{i}:v]xfade=transition={transition}:"
                     f"duration={this_dur:.6f}:offset={offset:.6f}[{out_label}]")
        cum = cum + durs[i] - this_dur
        prev_label = out_label
    cmd = ["ffmpeg", "-y"]
    for c in clips:
        cmd += ["-i", c]
    # Это единственный проход, который видит ВСЮ склейку сразу — то, что
    # уйдёт на YouTube (финальный мукс делает -c:v copy, второго прохода
    # уже не будет). Каждый отдельный клип и так уже CRF 17 (RENDER_CRF, см.
    # kenburns/video_render/parallax_kenburns) — если тут снова ужать до 23,
    # это второе поколение потерь поверх первого, заметное именно на тёмном
    # грейде (градиенты/дым/зерно). FINAL_PASS_PRESET/CRF — разовая цена, не
    # на каждый маленький клип.
    cmd += ["-filter_complex", ";".join(parts), "-map", "[vout]"] + final_pass_encode_args() + [out]
    # РЕАЛЬНЫЙ пробел, пойманный аудитом того же класса багов, что и
    # SPEED_RAMP_MAX_SOURCE_FPS/parallax stderr-deadlock (см. их докстринги
    # выше): у этого вызова не было НИКАКОГО timeout — при зависании ffmpeg
    # (тот же класс проблем, что и задокументированный ниже "молча роняет
    # кадры и застревает") весь уже отрендеренный за часы прогон терялся бы
    # молча, без единого сигнала. cum — суммарная длительность чанка (до 35
    # клипов на FINAL_PASS_PRESET+FINAL_PASS_CRF (medium+16), тяжелее, чем
    # per-clip RENDER_PRESET+RENDER_CRF (veryfast+17) — щедрый множитель
    # (30x), это последний рубеж защиты от НАСТОЯЩЕГО зависания, не бюджет
    # под скорость.
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace",
                            timeout=max(180, cum * 30))
    except subprocess.TimeoutExpired:
        print(f"  xfade-склейка зависла (таймаут {max(180, cum * 30):.0f}с), откат на concat.")
        return False, 0.0
    if r.returncode != 0:
        print("  xfade-склейка не удалась, откат на concat:", r.stderr[-300:])
        return False, 0.0
    # Пойман вживую на 150 клипах (после sub-cuts): ffmpeg возвращает 0
    # (успех), но при очень длинной цепочке последовательных xfade в ОДНОМ
    # filter_complex молча "роняет" кадры (dup=0 drop=20000+ в stderr) и
    # застревает на застывшем кадре с середины ролика — итоговый файл
    # правильной длины (после -shortest/-t на муксе), но 800+ секунд из
    # них заморожены. Return-код тут не индикатор, реальная длительность —
    # индикатор. На ~90 клипах (до sub-cuts) с той же схемой такого не
    # было — это масштабная проблема ffmpeg с очень длинной цепочкой в
    # одном графе, не баг в математике offset/cum (та проверена отдельно).
    try:
        real_dur = get_media_duration(out)
    except Exception:
        real_dur = 0.0
    expected = max(cum, 0.1)
    if real_dur < expected * 0.9 - 2.0:
        print(f"  xfade-склейка вернула 0, но реальная длительность {real_dur:.1f}с "
              f"против ожидаемых {expected:.1f}с (похоже на застревание ffmpeg на "
              f"длинной цепочке xfade) — откат на concat.")
        return False, 0.0
    return True, expected


XFADE_CHUNK_SIZE = 35   # порог чанкования — см. xfade_chain_chunked


def _chunk_bounds(n, sections, chunk_size):
    """(start,end) полуинтервалы индексов клипов на чанки ~chunk_size —
    резать ТОЛЬКО на границах section (там и так планировался заметный
    dissolve/fadeblack/fadewhite, см. xfade_chain — на стыке чанков он
    станет обычным concat-cut, это читается как ещё один hardcut, не как
    потеря приёма, в отличие от разрыва ПОСЕРЕДИНЕ фразы). Защита от
    вырожденного случая (вся секция длиннее 2×chunk_size — например,
    гигантский BODY без внутренних BLOCK) — режем принудительно, не гоняясь
    за границей до бесконечности: маленькая потеря одного перехода лучше
    риска снова упереться в ту же ffmpeg-багу на длинной цепочке."""
    if n <= chunk_size:
        return [(0, n)]
    bounds, pos = [0], 0
    while pos < n:
        target = min(pos + chunk_size, n)
        if target >= n:
            bounds.append(n)
            break
        j = target
        hard_cap = min(pos + chunk_size * 2, n)
        while j < hard_cap and sections[j] == sections[j - 1]:
            j += 1
        bounds.append(j)
        pos = j
    bounds = sorted(set(bounds))
    chunks = list(zip(bounds[:-1], bounds[1:]))
    # xfade_chain() требует минимум 2 клипа (n<2 -> (False, 0.0) сразу) —
    # де-фрагментируем случайный "хвостик" в 1 клип (получается, если
    # граница секции легла ровно на предпоследний индекс) слиянием с
    # соседним чанком, а не оставляем orphan-чанк, гарантированно
    # роняющий всю сборку в откат на concat.
    fixed = []
    for a, b in chunks:
        if b - a < 2 and fixed:
            pa, _ = fixed[-1]
            fixed[-1] = (pa, b)
        else:
            fixed.append((a, b))
    if len(fixed) > 1 and fixed[0][1] - fixed[0][0] < 2:
        (a0, _), (_, b1) = fixed[0], fixed[1]
        fixed[0] = (a0, b1)
        del fixed[1]
    return fixed


def xfade_chain_chunked(clips, durs, sections, out, temp_dir, xfade_dur=XFADE_DUR, blocks=None,
                         chunk_size=XFADE_CHUNK_SIZE):
    """Обёртка над xfade_chain(): на длинной цепочке (150+ клипов после
    sub-cuts) один filter_complex со всеми xfade сразу ловит документированный
    в xfade_chain() баг ffmpeg — молча роняет кадры и застревает на
    застывшем кадре с середины ролика, при том что return-код 0. Раньше
    единственным ответом был полный откат на голый concat — ролик собирался,
    но терял ВСЕ переходы разом. Вместо этого режем на чанки по chunk_size
    (см. _chunk_bounds — только по границам section), каждый чанк — свой
    независимый xfade_chain() (короткая цепочка, баг не всплывает), чанки
    склеиваются -c copy (без потерь, все чанки — один и тот же кодек/
    параметры). Если ХОТЯ БЫ один чанк не собрался — честный откат на
    concat всего ролика, как раньше (лучше без переходов, чем сорванная
    сборка)."""
    n = len(clips)
    bounds = _chunk_bounds(n, sections, chunk_size)
    # Один общий план на весь ролик, чанкам отдаются его СРЕЗЫ: элемент
    # plan[j] описывает переход между глобальными клипами j и j+1, значит
    # внутри чанка [a, b) работают переходы plan[a:b-1] (переход на самом
    # входе чанка не делается вообще — чанки склеиваются concat -c copy,
    # именно это учитывает estimate_xfade_budget()).
    plan = plan_transitions(sections, blocks, xfade_dur=xfade_dur)
    if len(bounds) <= 1:
        return xfade_chain(clips, durs, sections, out, xfade_dur=xfade_dur, blocks=blocks, plan=plan)
    chunk_files, chunk_total = [], 0.0
    for ci, (a, b) in enumerate(bounds):
        cblocks = blocks[a:b] if blocks else None
        cout = os.path.join(temp_dir, f"_xchunk_{ci:03d}.mp4")
        ok, cdur = xfade_chain(clips[a:b], durs[a:b], sections[a:b], cout,
                                xfade_dur=xfade_dur, blocks=cblocks, plan=plan[a:b - 1])
        if not ok:
            print(f"  чанк {ci} ({b - a} клипов) xfade не собрался — вся склейка откатывается на concat")
            return False, 0.0
        chunk_files.append(cout)
        chunk_total += cdur
    concat_list = os.path.join(temp_dir, "_xchunk_concat.txt")
    open(concat_list, "w", encoding="utf-8").write(
        "".join(f"file '{os.path.abspath(c)}'\n" for c in chunk_files))
    r = subprocess.run(["ffmpeg", "-y", "-f", "concat", "-safe", "0",
                        "-i", concat_list, "-c", "copy", out], capture_output=True, text=True, encoding="utf-8", errors="replace")
    if r.returncode != 0:
        print("  склейка чанков xfade не удалась, откат на concat:", r.stderr[-300:])
        return False, 0.0
    # Чанки скопированы в out побайтово (-c copy) — дальше они не нужны
    # никому: xfade_chain() выше не кэширует их между прогонами (cout
    # каждый раз перезаписывается заново), а весь код ниже по пайплайну
    # (pad_to_length/финальный мукс) работает только с out. Раньше чанки
    # (~столько же места, сколько сам out) оставались лежать мёртвым
    # грузом до konца прогона — на реальном 165-клипном эпизоде это было
    # ~2.9 ГБ пиковой нехватки диска, буквально то место, где сборка
    # несколько раз падала на "No space left on device" при последующем
    # финальном муксе. Удаление — не оптимизация с компромиссом: это
    # чистая уборка уже скопированных временных файлов, out от неё не
    # зависит и не меняется. Сбой удаления (permissions и т.п.) не должен
    # рушить уже УСПЕШНУЮ склейку — не критично, просто предупреждение.
    for cf in chunk_files:
        try:
            os.remove(cf)
        except OSError as e:
            print(f"  предупреждение: не удалось удалить временный чанк {cf}: {e}")
    return True, chunk_total


def estimate_xfade_budget(blocks, chunk_size=XFADE_CHUNK_SIZE):
    """Сколько склейка суммарно "съест" нахлёстами — теперь ТОЧНО, а не
    оценкой сверху: это буквально сумма того самого плана, по которому
    xfade_chain() потом и режет (см. plan_transitions() — там же история
    бага с круговой зависимостью и цена перебора: 35+ секунд ухода видео
    от аудио на 40-минутном эпизоде).

    Учитывается и чанкование: xfade_chain_chunked() склеивает чанки через
    concat -c copy, то есть переход НА ВХОДЕ каждого чанка не делается и
    нахлёста не потребляет — раньше эти ~0.4с на каждый чанк (13-14 чанков
    на длинном эпизоде) тоже уходили в перебор."""
    sections = [b["section"] for b in blocks]
    plan = plan_transitions(sections, blocks)
    if not plan:
        return 0.0
    return sum(d for _t, d in effective_transition_plan(plan, sections, chunk_size))


def effective_transition_plan(plan, sections, chunk_size=XFADE_CHUNK_SIZE):
    """План переходов, каким его РЕАЛЬНО исполняет xfade_chain_chunked():
    переход на входе каждого чанка (concat -c copy между чанками) не делается
    и нахлёста не потребляет — его длительность здесь обнуляется. Аудит
    04.09 (реальная находка, воспроизведена снippet'ом на 400 блоках): эту
    поправку знал только estimate_xfade_budget(), а два других потребителя
    того же плана — phrase_locked_durations() и hook_visual_starts() —
    прибавляли/вычитали нахлёст и на стыках чанков тоже. На любом эпизоде
    длиннее XFADE_CHUNK_SIZE клипов после первой границы чанка каждый кадр
    показывался на XFADE_DUR (0.417с) позже своей фразы, накопительно
    (7 чанков — +2.5с к финалу, 40-минутный эпизод — ~5.5с), видео
    становилось длиннее аудио, хвост резался финальным муксом, а
    phrase_timeline.json показывал дрейф 0, потому что считался той же
    неверной формулой. Теперь все четыре потребителя (бюджет, PHRASE LOCK,
    visual_starts, сама склейка) читают один и тот же эффективный план."""
    if not plan:
        return list(plan)
    dropped = {a for a, _b in _chunk_bounds(len(sections), sections, chunk_size) if a > 0}
    return [(t, 0.0 if (i + 1) in dropped else d) for i, (t, d) in enumerate(plan)]


def pad_to_length(video, target, temp_dir):
    """Достраивает видео до нужной длины заморозкой последнего кадра — нужно
    после xfade_chain(), если реальный итог всё же короче target (несмотря
    на estimate_xfade_budget с запасом сверху — редкий остаточный случай,
    не обычный путь). Возвращает (путь, gap) — gap > 0 означает, что
    заморозка реально сработала, main() отражает это в QC."""
    cur = get_media_duration(video)
    gap = target - cur
    if gap <= 0.05:
        return video, 0.0
    lastframe = os.path.join(temp_dir, "_lastframe.jpg")
    padclip = os.path.join(temp_dir, "_pad.mp4")
    padded = os.path.join(temp_dir, "_padded.mp4")
    subprocess.run(["ffmpeg", "-y", "-sseof", "-0.3", "-i", video,
                    "-vframes", "1", lastframe], capture_output=True)
    r = subprocess.run(["ffmpeg", "-y", "-loop", "1", "-i", lastframe, "-t", f"{gap:.3f}"]
                       + final_pass_encode_args() + [padclip],
                       capture_output=True, text=True, encoding="utf-8", errors="replace")
    if r.returncode != 0:
        return video, gap
    lst = os.path.join(temp_dir, "_pad_concat.txt")
    open(lst, "w", encoding="utf-8").write(
        f"file '{os.path.abspath(video)}'\nfile '{os.path.abspath(padclip)}'\n")
    r = subprocess.run(["ffmpeg", "-y", "-f", "concat", "-safe", "0",
                        "-i", lst, "-c", "copy", padded], capture_output=True, text=True, encoding="utf-8", errors="replace")
    return (padded, gap) if r.returncode == 0 else (video, gap)


def get_media_duration(path):
    r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                        "-show_format", path], capture_output=True, text=True, encoding="utf-8", errors="replace", check=True)
    return float(json.loads(r.stdout)["format"]["duration"])


def get_media_fps(path):
    """r_frame_rate первого видеопотока (см. SPEED_RAMP_MAX_SOURCE_FPS) —
    None при любой ошибке/отсутствии видеопотока (fail-open, тот же принцип,
    что get_media_duration/measure_motion): вызывающий код тогда не гейтит
    спид-рамп по fps вообще, прежнее поведение."""
    try:
        r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                            "-select_streams", "v:0", "-show_entries", "stream=r_frame_rate",
                            path], capture_output=True, text=True, encoding="utf-8", errors="replace", check=True)
        rate = json.loads(r.stdout)["streams"][0]["r_frame_rate"]
        num, _, den = rate.partition("/")
        return float(num) / float(den or 1)
    except Exception:
        return None


def audio_qc(path, label="Audio QC"):
    """Технический QC дорожки — тот же принцип, что qc_report() для
    картинок: не блокирует, только честно докладывает брак, который иначе
    заметили бы только на слух постфактум (клиппинг, слишком тихо/громко,
    длинные участки мёртвой тишины помимо самих [pause] — забытый обрыв
    записи). Бесплатно — штатные ffmpeg-фильтры astats/silencedetect,
    никакого нового API.

    Вызывается ДВАЖДЫ: на входном голосе (что нам дали) и на ГОТОВОМ
    final.mp4 (что услышит зритель) — см. label. Долгое время проверялся
    только вход, и вся мастер-цепочка (обработка голоса, подложка, дакинг,
    loudnorm, лимитер) уходила к зрителю вообще без технической проверки:
    обе реальные поломки музыки в этом проекте нашлись ручными замерами,
    а не отчётом.
    """
    try:
        r = subprocess.run(
            ["ffmpeg", "-nostats", "-i", path, "-af",
             "astats=reset=0,silencedetect=noise=-40dB:d=1.5", "-f", "null", "-"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            # Тот же класс, что чинил аудит 04.09 у measure_loudnorm_stats():
            # фиксированные 120 с — это полный декод, на часовом эпизоде он
            # не укладывается, и QC молча не выполнялся вообще.
            timeout=max(120, int(_audio_len_for_timeout(path) * 0.5)))
        err = r.stderr
    except Exception as e:
        print(f"  {label}: не удалось проверить ({e})")
        return
    warns = []
    m = re.search(r"Peak level dB:\s*(-?[\d.]+)", err)
    if m and float(m.group(1)) > -0.1:
        warns.append(f"пик {m.group(1)} dBFS — на грани клиппинга")
    m = re.search(r"RMS level dB:\s*(-?[\d.]+)", err)
    rms = float(m.group(1)) if m else None
    if rms is not None and rms < -35:
        warns.append(f"RMS {rms:.1f} dBFS — очень тихо")
    elif rms is not None and rms > -12:
        warns.append(f"RMS {rms:.1f} dBFS — очень громко/пережато")
    silences = [float(x) for x in re.findall(r"silence_duration:\s*([\d.]+)", err)]
    if silences:
        try:
            dur = get_media_duration(path)
            ratio = sum(silences) / dur
            if ratio > 0.15:
                warns.append(f"{ratio*100:.0f}% дорожки — тишина длиннее 1.5с (мёртвый воздух?)")
        except Exception:
            pass
    print(f"{label}: {'; '.join(warns)}" if warns
          else f"{label}: клиппинга/аномальной громкости не найдено")


def build_master_af(loud_stats, fade_out_st, fade_in_sec):
    """Мастер-цепочка финального прохода: loudnorm -> лимитер -> фейды.

    Вынесено из main() отдельной функцией, чтобы порядок ступеней можно было
    проверить тестом, а не только прочитать. Порядок здесь — не вкусовщина:

    * лимитер ПОСЛЕ loudnorm — иначе loudnorm поднял бы уровень уже после
      того, как потолок выставлен, и потолок перестал бы быть потолком;
    * лимитер ПЕРЕД afade — afade только уменьшает уровень, так что на
      результат он не влияет, но обратный порядок заставил бы лимитер
      работать на затухающих хвостах, где он бесполезен;
    * порог лимитера — та же константа LOUDNORM_TARGET_TP, что цель true
      peak у loudnorm: две ступени не должны спорить о потолке.

    loud_stats=None — первый проход не измерился, идём однопроходным
    (динамическим) loudnorm; это уже существующий откат, лимитер в нём
    тем более уместен.
    """
    base = f"loudnorm=I={LOUDNORM_TARGET_I}:TP={LOUDNORM_TARGET_TP}:LRA={LOUDNORM_TARGET_LRA}"
    if loud_stats:
        base += (f":linear=true:measured_I={loud_stats['input_i']}:"
                 f"measured_TP={loud_stats['input_tp']}:"
                 f"measured_LRA={loud_stats['input_lra']}:"
                 f"measured_thresh={loud_stats['input_thresh']}:"
                 f"offset={loud_stats['target_offset']}")
    stages = [base]
    if MASTER_LIMITER_ENABLED:
        stages.append(f"alimiter=limit={LOUDNORM_TARGET_TP}dB:"
                      f"attack={MASTER_LIMITER_ATTACK_MS}:"
                      f"release={MASTER_LIMITER_RELEASE_MS}:level=disabled")
    stages.append(f"afade=t=in:st=0:d={fade_in_sec}")
    stages.append(f"afade=t=out:st={fade_out_st:.3f}:d=2")
    return ",".join(stages)


def write_audio_master_report(video_dir, final_lufs=None):
    """media_plan/audio_master_report.json — чем собран звук этого ролика.

    Ровно тот же принцип, что feature_flags.json для видео: по готовому
    файлу должно быть можно ответить, какой была подложка и почему, а не
    вспоминать. Особенно теперь, когда усиление подложки не константа в
    исходнике, а результат измерения на месте (music_bed_gain_db()).
    """
    payload = {
        "music_enabled": bool(MUSIC_ENABLED),
        "bed": MUSIC_BED_DECISION,
        "target_gap_lu": MUSIC_BED_GAP_LU,
        "duck": {"threshold": MUSIC_DUCK_THRESHOLD, "ratio": MUSIC_DUCK_RATIO,
                 "attack_ms": MUSIC_DUCK_ATTACK_MS, "release_ms": MUSIC_DUCK_RELEASE_MS},
        "climax_dip_db": CLIMAX_DIP_DB,
        "voice_process_enabled": bool(VOICE_PROCESS_ENABLED),
        "limiter": ({"limit_db": LOUDNORM_TARGET_TP,
                     "attack_ms": MASTER_LIMITER_ATTACK_MS,
                     "release_ms": MASTER_LIMITER_RELEASE_MS}
                    if MASTER_LIMITER_ENABLED else None),
        "loudnorm": {"I": LOUDNORM_TARGET_I, "TP": LOUDNORM_TARGET_TP,
                     "LRA": LOUDNORM_TARGET_LRA},
        "final_lufs": final_lufs,
    }
    try:
        path = os.path.join(video_dir, "media_plan", "audio_master_report.json")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=1)
        os.replace(tmp, path)
        return path
    except Exception as e:
        # Отчёт вспомогательный: потерять готовый ролик из-за него было бы
        # хуже, чем остаться без него (тот же fail-open, что у sidecar).
        print(f"  ВНИМАНИЕ: audio_master_report не записан ({type(e).__name__})")
        return None


@memoize_by_frame
def ahash(photo_path, size=8):
    """Средний хэш (average hash) картинки — 64-битная строка, дешёвая
    замена imagehash-библиотеке (Pillow уже обязательная зависимость, лишний
    пакет не нужен). Похожие по контенту кадры дают близкий хэш даже если
    это разные файлы с разных источников."""
    img = PILImage.open(photo_path).convert("L").resize((size, size), PILImage.LANCZOS)
    pixels = list(img.getdata())
    avg = sum(pixels) / len(pixels)
    return "".join("1" if p > avg else "0" for p in pixels)


def hamming(a, b):
    return sum(c1 != c2 for c1, c2 in zip(a, b))


def qc_report(media_log):
    """Не блокирует сборку — просто честно докладывает, если несколько
    кадров ролика визуально почти одинаковые (Pexels ID разные, а по факту
    похожий кроп/пересъёмка того же сюжета — то, что ловится глазом, но не
    ловится дедупом по ID). Порог 6 бит из 64 — эмпирически "заметно похоже".
    Возвращает список дублей — раньше это тонуло в середине лога, а ГОТОВО
    выглядело как чистый успех; теперь main() отражает находку в итоговой
    строке и коде возврата (не блокирует сборку — только честно не молчит:
    тот же принцип, что уже применён к пропущенным блокам)."""
    if len(media_log) < 2:
        return []
    hashes = []
    for i, path in media_log:
        try:
            hashes.append((i, ahash(path)))
        except Exception:
            pass
    dupes = []
    for a in range(len(hashes)):
        for bb in range(a + 1, len(hashes)):
            i1, h1 = hashes[a]
            i2, h2 = hashes[bb]
            d = hamming(h1, h2)
            if d <= 6:
                dupes.append((i1 + 1, i2 + 1, d))
    if dupes:
        print(f"QC: похожие кадры (проверь глазами) — {dupes}")
    else:
        print("QC: явных повторов по картинке не найдено")
    return dupes


def apply_section_boundary_shift(blocks, durs):
    """Лёгкая версия J/L-cut. Классический приём (звук следующей сцены
    начинается раньше её картинки) тут физически не из чего собрать — вся
    озвучка это один сплошной файл на весь ролик, а не отдельная дорожка
    на клип. Но можно сдвинуть саму ТОЧКУ ВИДЕО-РЕЗА относительно границы
    фразы на 250-400мс раньше или позже вместо ровно момента паузы —
    зритель считывает лёгкую рассинхронность видео/смыслового реза как
    признак ручного монтажа, а не нарезки строго по паузам. Сумма
    длительностей не меняется — время просто перетекает между соседними
    блоками ДО и ПОСЛЕ границы секции.

    2.7 (доразбор второго продакшн-документа, п.3.2 "J/L-cuts — главный
    приём, по которому документалка ощущается срежиссированной"): раньше
    сдвиг применялся ТОЛЬКО на границах секций (HOOK->BLOCK1 и т.п.) — то
    есть буквально на паре резов за весь ролик, а не на "каждой смене
    сцены", как советует источник. Подавляющее большинство резов (внутри
    одной секции) резались РОВНО по границе фразы — без единой микро-
    рассинхронности. apply_within_cut_shift() ниже — тот же механизм,
    меньшая амплитуда (клипы внутри секции короче — большой сдвиг съел бы
    заметную долю короткого кадра), применяется отдельным проходом сразу
    после этой функции."""
    d = list(durs)
    for i in range(1, len(blocks)):
        if blocks[i]["section"] == blocks[i - 1]["section"]:
            continue
        h = int(hashlib.md5(blocks[i]["text"][:40].encode()).hexdigest()[:8], 16)
        mag = 0.25 + (h % 150) / 1000.0   # 0.25-0.40с, детерминировано по тексту
        give = mag if (h & 1) else -mag
        floor_prev = hook_floor_for(blocks, i - 1)
        floor_cur = hook_floor_for(blocks, i)
        if d[i - 1] - give >= floor_prev and d[i] + give >= floor_cur:
            d[i - 1] -= give
            d[i] += give
    return d


def apply_within_cut_shift(blocks, durs):
    """J/L-cut для резов ВНУТРИ секции — см. докстринг apply_section_boundary_shift
    (2.7): та же идея (точка видео-реза чуть раньше/позже границы фразы,
    сумма длительностей сохраняется), но НЕ на границах секций (там уже
    отработала apply_section_boundary_shift своей, более крупной амплитудой)
    и с меньшим сдвигом — иначе на 3-4-секундном кадре сдвиг в 300мс это уже
    десятая часть его собственной длины, заметно искажает темп.

    Пропускаем два случая, где сдвиг СЕМАНТИЧЕСКИ неверен, не просто
    "не нужен": sub-cut внутри одного исходного блока (это одна и та же
    мысль, разрезанная на фазы показа — граница между её кусками не несёт
    "смены сцены", J/L-cut тут нечего анонсировать) и рез сразу после
    stat-плашки (snap cut — намеренно МГНОВЕННЫЙ, цифра "впечаталась" и тут
    же сменился кадр; сдвигать его — противоречить собственному замыслу
    snap cut, не улучшать его)."""
    d = list(durs)
    for i in range(1, len(blocks)):
        if blocks[i]["section"] != blocks[i - 1]["section"]:
            continue   # уже сдвинуто apply_section_boundary_shift
        if blocks[i].get("is_subcut") or blocks[i - 1].get("stat"):
            continue
        h = int(hashlib.md5((blocks[i - 1]["text"][-30:] + blocks[i]["text"][:30]).encode()).hexdigest()[:8], 16)
        mag = 0.08 + (h % 100) / 1000.0   # 0.08-0.18с — заметно меньше, чем на границе секции
        give = mag if (h & 1) else -mag
        floor_prev = hook_floor_for(blocks, i - 1)
        floor_cur = hook_floor_for(blocks, i)
        if d[i - 1] - give >= floor_prev and d[i] + give >= floor_cur:
            d[i - 1] -= give
            d[i] += give
    return d


def apply_human_jitter(blocks, durs, magnitude=0.3):
    """Механическая регулярность длительностей — узнаваемый штамп автослайдшоу:
    даже с real-alignment таймингом (см. load_alignment_weights) сетка
    остаётся слишком "правильной". Живой монтаж имеет микронеровности:
    иногда кадр обрывается на 2.3с раньше расчётного, иногда держится
    дольше. Джиттер — детерминированный (hashlib.md5 текста, не встроенный
    hash() — тот рандомизирован между запусками и сломал бы кэш), сумма
    длительностей сохраняется РОВНО (вычитаем среднее смещение из всех
    дельт вместо пропорционального масштабирования — иначе масштаб просто
    съедает большую часть эффекта на длинном ролике)."""
    deltas = []
    for b in blocks:
        h = int(hashlib.md5((b["section"] + b["text"][:40]).encode()).hexdigest()[:8], 16)
        frac = (h % 1000) / 1000.0
        deltas.append((frac - 0.5) * 2 * magnitude)
    mean_delta = sum(deltas) / len(deltas)
    deltas = [x - mean_delta for x in deltas]
    # Свой пол для хука (hook_floor_for — с учётом ещё более низкого пола на
    # первые резы) — иначе джиттер молча утаскивал бы уже нарочно короткие
    # хук-кадры обратно к общему MIN_CLIP, сводя на нет весь смысл отдельного,
    # более быстрого пола (см. block_durations).
    out = [max(hook_floor_for(blocks, i), d + delta)
           for i, (d, delta) in enumerate(zip(durs, deltas))]
    scale = sum(durs) / sum(out)
    return [x * scale for x in out]


SUBCUT_MIN_SOURCE_DUR = 8.0   # блок короче этого не режем вообще
SUBCUT_MIN_PART_DUR = 3.0     # ни один получившийся под-кадр не короче этого
SUBCUT_CONTRAST_WORDS = {"но", "однако", "зато", "хотя", "просто", "ведь",
                          "потому", "поэтому", "притом", "притом,"}
# Раньше здесь стоял отдельный, более агрессивный набор порогов
# (SUBCUT_HOOK_MIN_SOURCE_DUR=2.0/SUBCUT_HOOK_MIN_PART_DUR=0.9/
# SUBCUT_HOOK_MIN_WORDS=4) для первых HOOK_OPENING_CUTS блоков хука — резал
# короткие фразы открытия на ещё более мелкие куски (вплоть до ~1с).
# Убрано целиком вместе с HOOK_OPENING_MIN_CLIP/HOOK_OPENING_CUTS (см.
# HOOK_MIN_CLIP выше) по прямому требованию пользователя: хук теперь режется
# теми же порогами (SUBCUT_MIN_SOURCE_DUR/SUBCUT_MIN_PART_DUR), что и тело
# ролика — единственное, что остаётся хук-специфичным, это сам пол
# длительности готового клипа (HOOK_MIN_CLIP=2.2 через hook_floor_for).

_PURE_NUMBER_RE = re.compile(r'^\d+$')   # "1240" из "1240." — год/номер, не конец предложения


def _internal_sentence_boundaries(words):
    """Индексы слов (резать ПОСЛЕ этого индекса), где внутри блока заканчивается
    ЗАКОНЧЕННОЕ предложение (.!?) — реальный, найденный вживую класс бага (27
    августа, videos/_test20s, финальный блок хука "Готов спорить, что да.
    Герой на экране заносит клинок..."): один физический блок сценария может
    содержать НЕСКОЛЬКО риторически независимых предложений, если автор не
    поставил между ними [pause]/[short pause] (границы блока и так уже
    задаются тегами — по построению ВНУТРИ уже распарсенного блока такого
    тега нет, значит любая точка/! /? внутри текста блока — это ровно тот
    случай, когда автор ЗАБЫЛ явно разметить границу, не намеренно оставил
    monolith). Раньше split_long_blocks() решал резать ТОЛЬКО по длительности
    (est < SUBCUT_MIN_SOURCE_DUR) — короткий по времени, но составной по
    смыслу блок (три предложения, произнесённые быстро) не резался вовсе,
    и все они получали ОДИН общий кадр — зритель видит "не тот" кадр в
    момент смены смысла внутри блока. Последнее слово блока не считается
    внутренней границей (это и так конец блока). Число с точкой на конце
    ("1240.") не считается концом предложения — почти всегда десятичная
    точка/номер, не разрыв смысла."""
    bounds = []
    for i, word in enumerate(words[:-1]):
        core = word.rstrip('»"\')')
        if core and core[-1] in ".!?" and not _PURE_NUMBER_RE.match(core[:-1]):
            bounds.append(i + 1)
    return bounds


def _usable_split_points(points, total_words, est, min_part):
    """Точки реза, после которых КАЖДЫЙ кусок дотягивает до min_part.

    Реальный случай (videos/_test60s, замер 14.09): у блока хука на 8.10с
    граница предложения стоит после «Я его назову.» — первый кусок 1.10с.
    split_long_blocks честно резала там, а merge_short_phrase_locked_blocks
    тут же склеивала обратно (1.10с ниже пола клипа хука 2.2с), и блок
    оставался 8.10с. Другую точку при этом никто не пробовал: fallback-и
    (контраст-союзы / число / середина) стоят под `if not split_at`, а
    список был НЕ пуст — в нём лежала непригодная точка.
    Итог замера: хук 3 кадра, средняя 6.94с при норме ЧАСТИ 14 «3-6 сек».

    Жадно слева направо: точка принимается, только если и кусок от
    предыдущей принятой, и весь оставшийся хвост не короче min_part."""
    if not points or not total_words or not est:
        return []
    out, last = [], 0
    for p in sorted(set(points)):
        if not (0 < p < total_words):
            continue
        if est * ((p - last) / total_words) < min_part:
            continue
        if est * ((total_words - p) / total_words) < min_part:
            continue
        out.append(p)
        last = p
    return out


def split_long_blocks(blocks, real_weights):
    """Один блок = один клип 4-20 сек — механическая сетка "одна мысль = одна
    картинка". Профессиональный монтаж на одну длинную фразу даёт 2-3
    визуальных решения. Режем блок, если он длиннее SUBCUT_MIN_SOURCE_DUR
    (по реальному alignment-весу, при его отсутствии — грубая оценка по
    словам) — ЛИБО, независимо от длительности, если внутри блока несколько
    ЗАКОНЧЕННЫХ предложений без явного [pause]/[short pause] между ними (см.
    _internal_sentence_boundaries — реальный найденный случай, короткий по
    времени, но составной по смыслу блок раньше не резался вовсе). Внутри —
    по смысловым триггерам: сами границы предложений (приоритет), иначе
    контраст-союзы ("но"/"однако"/...) или первое число за пределами первой
    четверти блока. Без триггеров, но всё равно длинный — режем ровно посередине по словам.
    Реальный вес блока делится между кусками ПРОПОРЦИОНАЛЬНО их доле слов —
    сумма сохраняется, ничего не выдумываем сверху. Запрос к стоку для
    под-кадров остаётся тем же самым блоком (resolve_queries считается уже
    ПОСЛЕ split, на новом расширенном списке — если у куска нет своего
    ключевого слова, он унаследует запрос соседнего куска той же секции,
    та же логика, что уже работает для обычных блоков), картинка другая —
    засчёт дедупа по used_photo_ids на большем пуле Pexels (per_page=40)."""
    new_blocks, new_weights = [], []
    for b, w in zip(blocks, real_weights or [None] * len(blocks)):
        min_source = SUBCUT_MIN_SOURCE_DUR
        min_part = SUBCUT_MIN_PART_DUR
        min_words = 8
        est = w if w is not None else b["words"] / 2.08
        words = b["text"].split()
        # sentence_bounds — см. _internal_sentence_boundaries(): несколько
        # ЗАКОНЧЕННЫХ (.!?) предложений в одном блоке — сигнал сильнее и
        # надёжнее, чем длительность est. Проверяем ДО обоих ранних выходов
        # (по длительности/по числу слов) — реальный найденный случай был
        # именно коротким по времени (4.1с — заведомо младше SUBCUT_MIN_
        # SOURCE_DUR=8.0), но составным по смыслу (3 предложения). Без этого
        # условия оба ранних выхода отсекли бы ровно тот блок, который и
        # нужно резать.
        sentence_bounds = _usable_split_points(
            _internal_sentence_boundaries(words), len(words), est, min_part)
        if est < min_source and not sentence_bounds:
            new_blocks.append(b)
            new_weights.append(w)
            continue
        if len(words) < min_words and not sentence_bounds:
            new_blocks.append(b)
            new_weights.append(w)
            continue
        split_at = list(sentence_bounds)
        if not split_at:
            trigger = []
            for i, word in enumerate(words):
                wl = word.strip(",.!?—–:;»«").lower()
                if wl in SUBCUT_CONTRAST_WORDS and 2 <= i <= len(words) - 3:
                    trigger.append(i)
            for i, word in enumerate(words):
                if re.search(r'\d', word) and i > len(words) // 4:
                    trigger.append(i)
                    break
            # Те же грабли, что у границ предложений выше: непригодная точка
            # не должна закрывать дорогу следующему триггеру.
            split_at = _usable_split_points(trigger, len(words), est, min_part)
        if not split_at:
            # Без смыслового триггера резать РОВНО посередине по счёту слов
            # означало иногда рвать словосочетание внутри одной фразы ("в
            # тысячу" | "раз" — тайминг не привязан к речи). Ищем ближайшую к
            # середине пунктуационную границу (конец клаузы: , . ! ? — ; :) —
            # рез попадает на естественную паузу произношения. Не нашли ни
            # одной в разумном радиусе — старое поведение (ровно посередине).
            mid = len(words) // 2
            found = None
            for radius in range(0, len(words) // 2 + 1):
                for cand in (mid - radius, mid + radius):
                    if 2 <= cand <= len(words) - 3 and words[cand - 1].rstrip()[-1:] in ",.!?—;:":
                        found = cand
                        break
                if found is not None:
                    break
            # Кандидаты в порядке предпочтения: сперва пунктуационная
            # граница (рез попадает на естественную паузу произношения),
            # потом сырая середина. Раньше `mid` был недостижим, если
            # пунктуация нашлась вообще — и блок оставался нерезаным, даже
            # когда середина делила его на два законных куска. Замер
            # 14.09: блок хука 8.10с, пунктуация на 2.95с (ниже пола 3.0),
            # середина 4.05/4.05 — годится, но не пробовалась.
            split_at = []
            for cand in ([found] if found is not None else []) + [mid]:
                split_at = _usable_split_points([cand], len(words), est, min_part)
                if split_at:
                    break
            if not split_at:
                # Блок физически не делится на два куска выше пола — оставляем
                # как есть. Это честный отказ, а не молчаливый рез пополам.
                new_blocks.append(b)
                new_weights.append(w)
                continue
        bounds = sorted(set([0] + split_at + [len(words)]))
        chunks = [(a, c) for a, c in zip(bounds, bounds[1:]) if c > a]
        # Склеиваем куски короче SUBCUT_MIN_PART_DUR (по доле слов от est)
        # с предыдущим — не даём под-кадру уйти ниже комфортной длины.
        total_w = len(words)
        merged = []
        for a, c in chunks:
            frac = (c - a) / total_w
            if merged and est * frac < min_part:
                pa, _ = merged[-1]
                merged[-1] = (pa, c)
            else:
                merged.append((a, c))
        # Дыра в цикле выше: у ПЕРВОГО куска `merged` ещё пуст, поэтому
        # короткий первый кусок проходил без всякой проверки — склеивать его
        # было не с чем НАЗАД. Склеиваем ВПЕРЁД. Само по себе это схлопывает
        # рез обратно, поэтому главная защита — _usable_split_points() выше
        # (не выбирать такую точку вовсе); здесь второй, страховочный слой.
        while len(merged) >= 2 and est * ((merged[0][1] - merged[0][0]) / total_w) < min_part:
            (a0, _c0), (_a1, c1) = merged[0], merged[1]
            merged[:2] = [(a0, c1)]
        if len(merged) < 2:
            new_blocks.append(b)
            new_weights.append(w)
            continue
        # Плашка раньше ВСЕГДА доставалась первому куску (k==0) независимо от
        # того, где в исходном блоке реально стоял [stat:...] — если рез
        # приходился ДО фразы с числом, цифра на экране показывалась на
        # куске, где она ещё не произнесена, а реальный кусок с числом
        # оставался без плашки вовсе. stat_word_pos (см. parse_blocks) —
        # позиция тега в словах исходного блока; находим, в какой ИМЕННО
        # кусок она попадает, и пересчитываем позицию относительно НАЧАЛА
        # этого куска (nb-локально), чтобы дальше по конвейеру плашку можно
        # было синхронизировать с моментом озвучки, а не с началом клипа.
        stat_pos = b.get("stat_word_pos")
        for k, (a, c) in enumerate(merged):
            nb = dict(b)
            nb["text"] = " ".join(words[a:c])
            nb["words"] = c - a
            has_stat = b["stat"] is not None and stat_pos is not None and (
                (a < stat_pos <= c) or (stat_pos <= 0 and k == 0))
            nb["stat"] = b["stat"] if has_stat else None
            nb["stat_word_pos"] = max(0, stat_pos - a) if has_stat else None
            nb["pause_after"] = b["pause_after"] if k == len(merged) - 1 else 0.0
            nb["is_subcut"] = k > 0   # для choose_motion_mode() (1.4) — деталь, не главный кадр фразы
            # is_climax (2.8) — та же логика, что и у плашки: тег стоит перед
            # НАЧАЛОМ исходного блока, значит момент, к которому привязана
            # тишина-акцент, попадает в ПЕРВЫЙ получившийся под-кадр, не во
            # все (dict(b) выше скопировал бы флаг во все k без явного сброса).
            nb["is_climax"] = b.get("is_climax", False) if k == 0 else False
            # sfx добавлен ПОЗЖЕ stat/climax и остался без сброса: dict(b)
            # копировал ВЕСЬ список в каждый под-кадр, а word_pos оставался
            # от исходного блока. Замер 14.09: один тег [sfx:armour_clank] в
            # сценарии дал ДВА кюя (блоки 5 и 6) с чужими позициями. Тот же
            # класс и то же лекарство, что уже применены к плашке: кюй живёт
            # в ТОМ куске, куда попала его позиция, и она пересчитывается
            # относительно начала этого куска.
            nb["sfx"] = [dict(x, word_pos=max(0, int(x.get("word_pos", 0)) - a))
                         for x in (b.get("sfx") or [])
                         if a <= int(x.get("word_pos", 0)) < c
                         or (int(x.get("word_pos", 0)) <= 0 and k == 0)]
            new_blocks.append(nb)
            new_weights.append((w * (c - a) / total_w) if w is not None else None)
    return new_blocks, new_weights


#: Счётчики языка камеры за прогон. Существуют по той же причине, что и
#: SOURCE_STATS: слой, который принимает решения и не оставляет следа,
#: невозможно ни проверить, ни опровергнуть по готовому ролику.
CAMERA_LANGUAGE_STATS = {
    "with_stage": 0,            # кадров, у которых стадия рассказа известна
    "without_stage": 0,         # кадров без стадии -> прежнее поведение
    "stage_had_direction": 0,   # стадия имела мнение о наезде/отъезде
    "direction_overridden_by_antirepeat": 0,   # и сколько раз его перебило вето
    "modes": {},                # какие режимы движения реально выпали
}


def reset_camera_language_stats():
    """Один прогон — один счёт (тот же принцип, что reset_source_stats)."""
    CAMERA_LANGUAGE_STATS["with_stage"] = 0
    CAMERA_LANGUAGE_STATS["without_stage"] = 0
    CAMERA_LANGUAGE_STATS["stage_had_direction"] = 0
    CAMERA_LANGUAGE_STATS["direction_overridden_by_antirepeat"] = 0
    CAMERA_LANGUAGE_STATS["modes"] = {}


def write_camera_language_report(video_dir):
    """media_plan/camera_language_report.json — ЧЕМ на самом деле решалось
    движение в этом ролике.

    Пишется ВСЕГДА, даже когда слой не сработал ни разу: «нечего сообщить»
    — тоже факт, а не отсутствие файла (тот же принцип, что у остальных
    отчётов эпизода). Без него ответ на вопрос «камера в этом ролике
    ездила по смыслу или по хэшу имени файла» существовал бы только в
    чьей-то памяти — ровно то состояние, из которого этот слой и вырос."""
    try:
        import camera_language
        total = CAMERA_LANGUAGE_STATS["with_stage"] + CAMERA_LANGUAGE_STATS["without_stage"]
        report = {
            "schema_version": 1,
            "enabled": bool(feature_flags.enabled("CAMERA_LANGUAGE")),
            "version": camera_language.CAMERA_LANGUAGE_VERSION,
            "shots_total": total,
            "shots_with_stage": CAMERA_LANGUAGE_STATS["with_stage"],
            "shots_without_stage": CAMERA_LANGUAGE_STATS["without_stage"],
            "stage_had_direction": CAMERA_LANGUAGE_STATS["stage_had_direction"],
            "direction_overridden_by_antirepeat":
                CAMERA_LANGUAGE_STATS["direction_overridden_by_antirepeat"],
            "modes": dict(CAMERA_LANGUAGE_STATS["modes"]),
            # САМИ ПРАВИЛА, а не только их следствия: по готовому ролику
            # нужно уметь ответить не только «что выпало», но и «по какому
            # закону». Тот же принцип, по которому feature_flags.json
            # отвечает на вопрос «каким пайплайном собран этот ролик».
            "language": {st: camera_language.describe(st)
                         for st in camera_language.STAGE_CAMERA},
        }
        d = os.path.join(video_dir, "media_plan")
        os.makedirs(d, exist_ok=True)
        tmp = os.path.join(d, "camera_language_report.json.tmp")
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(report, f, ensure_ascii=False, indent=2)
        os.replace(tmp, os.path.join(d, "camera_language_report.json"))
        return report
    except Exception:
        # Отчёт вспомогательный: потерять ролик из-за строчки в журнале
        # хуже, чем потерять строчку (тот же fail-open, что у sidecar).
        return None


def _camera_language_recipe_source():
    """Якорь для render_recipe_signature() — см. комментарий в её списке.

    Пустая функция-держатель не годилась бы: подпись берёт ИСХОДНИК того,
    что ей передали, поэтому здесь перечислены сами функции языка камеры.
    Правка палитры внутри модуля меняет их исходник и, значит, подпись."""
    import inspect
    import camera_language
    return "".join(inspect.getsource(f) for f in (
        camera_language.camera_palette,
        camera_language.pick_from_palette,
        camera_language.stage_zoom_in,
    )) + repr(camera_language.STAGE_CAMERA) + repr(camera_language.STAGE_ZOOM_IN) \
       + repr(camera_language.SHOT_SIZE_DROP)


def render_recipe_signature():
    """Отпечаток САМОГО РЕЦЕПТА картинки (исходный код функций рендера +
    ключевые константы) — входит в params_hash кэша temp_smart/ (см. main()).

    Закрывает класс бага, который в этом файле был честно описан как
    "ЗАМЕТКА НА БУДУЩЕЕ" у _warm_mult(), но не закрыт: params_hash хэшировал
    только РАНТАЙМ-параметры блока (текст/длительность/запрос/подписи), а не
    версию рецепта. Любая правка грейда (film_look/_scene_bias/_warm_mult),
    зерна, движения камеры или оформления плашек молча переживала уже
    отрендеренные клипы: на следующем прогоне часть эпизода оставалась в
    старом рецепте, часть — в новом, причём разница видна на глаз только
    при сравнении кадров, а в логе не сказано ничего. Ровно эта ловушка
    уже требовала ручной чистки temp_smart/ "не забыть перед правкой".

    Теперь смена рецепта инвалидирует кэш САМА. Инвалидация грубая (любая
    правка перечисленных функций — даже строчки лога — считается сменой
    рецепта): это осознанно консервативная сторона, лишний перерендер
    дешевле молча смешанного грейда в одном ролике.

    Сбой inspect (нестандартная упаковка, .pyc без исходника) -> стабильная
    заглушка: поведение как раньше, без падения."""
    try:
        import inspect
        parts = [inspect.getsource(f) for f in (
            # aspect_fit_backdrop/needs_aspect_backdrop — часть РЕЦЕПТА кадра:
            # правка порога или вида подложки меняет уже отрендеренный клип,
            # а ни один рантайм-параметр params_hash при этом не двигается.
            aspect_fit_backdrop, needs_aspect_backdrop,
            film_look, _scene_bias, _warm_mult, grain_blend_complex,
            add_overlays, add_kinetic_captions, kenburns, video_render,
            parallax_kenburns, choose_motion_mode, piecewise_ease_expr,
            # ЯЗЫК КАМЕРЫ живёт ОТДЕЛЬНЫМ модулем, и его таблица — это
            # рецепт, а не рантайм-параметр: правка палитры стадии меняет
            # движение уже отрендеренного клипа, при этом исходник
            # choose_motion_mode остаётся прежним побайтово. Берём исходник
            # самих функций модуля (а не номер версии, который забывают
            # поднять) — тот же приём, что уже стоит на дисковых кэшах
            # кандидатов.
            _camera_language_recipe_source,
            # is_parallax_highlight — ТОЖЕ часть рецепта, не рантайм-параметр:
            # правка её условий (например, что считать highlight-моментом)
            # меняет, КАКОЙ путь рендера (parallax_kenburns vs обычный
            # kenburns) получит уже закэшированный клип, при том что ни один
            # из перечисленных выше рантайм-параметров params_hash при этом
            # не меняется — без неё такая правка молча не инвалидировала бы
            # старый кэш (тот же класс бага, что и у остальных функций здесь).
            is_parallax_highlight,
            # foreground_background_layers — ТОЖЕ часть рецепта: вызывается
            # ИЗНУТРИ parallax_kenburns() (по имени, не инлайн-кодом), поэтому
            # правка её собственного тела не меняет исходник parallax_kenburns
            # и молча не инвалидировала бы старый кэш — тот же класс пробела,
            # что и у is_parallax_highlight выше.
            foreground_background_layers,
            # apply_depth_of_field/_dof_focus_depth — тот же класс пробела,
            # что foreground_background_layers выше: вызываются ИЗНУТРИ
            # parallax_kenburns() по имени, правка их тела (например, замена
            # DOF_FOCUS_DEPTH на адаптивный порог, 27 августа) не меняет
            # исходник parallax_kenburns и молча не инвалидировала бы старый
            # кэш без явного перечисления здесь.
            apply_depth_of_field, _dof_focus_depth,
            # Найдено самоаудитом 03.09 (Explore-агент, тот же принцип, что
            # уже применён к is_parallax_highlight/foreground_background_
            # layers/apply_depth_of_field выше): все функции ниже вызываются
            # ПО ИМЕНИ изнутри уже перечисленных film_look/kenburns/
            # parallax_kenburns/video_render, реально влияют на итоговую
            # картинку и НЕ мемоизированы между прогонами процесса (в
            # отличие от кандидатов ниже, у @memoize_by_frame — она
            # ВНУТРИПРОЦЕССНАЯ, не защищает от staleness МЕЖДУ прогонами,
            # см. её докстринг) — правка их тела молча не инвалидировала бы
            # старый temp_smart/clip_*.mp4, тот же класс бага, что и у уже
            # перечисленных функций.
            #
            # auto_levels_params/auto_wb_params — из film_look(): дают
            # contrast/brightness/colorchannelmixer техническую нормировку
            # ДО творческого грейда, идут прямо в возвращаемую строку
            # фильтра.
            auto_levels_params, auto_wb_params,
            # kb_hash_choices — из kenburns()/parallax_kenburns(): даёт
            # zoom_in/pan_dir по умолчанию, которые входят в z=/x=/y=
            # выражение zoompan.
            kb_hash_choices,
            # estimate_busyness — из kenburns(): напрямую масштабирует силу
            # зума (delta *= 0.7 при busy > 0.6).
            estimate_busyness,
            # resolve_crop_anchor/compute_crop_offset — из kenburns()/
            # parallax_kenburns(): решают, какая часть фото попадёт в
            # crop=.
            resolve_crop_anchor, compute_crop_offset,
            # pick_stat_variant — из add_overlays(): выбирает между 4
            # визуально разными оформлениями stat-плашки.
            pick_stat_variant,
            # detect_scene_change_offset — из video_render(): решает, с
            # какого момента исходного видео стартует клип (-ss).
            detect_scene_change_offset,
            # measure_motion/build_speed_ramp_filter — из video_render():
            # решают, применяется ли speed-ramp вообще, и строят сам
            # filter_complex-граф эффекта.
            measure_motion, build_speed_ramp_filter,
            # estimate_depth/fill_crop_canvas — из parallax_kenburns():
            # единственный источник карты глубины, от которой зависят
            # parallax_px/depth_zoom_strength И уже перечисленные выше
            # apply_depth_of_field/foreground_background_layers — их более
            # фундаментальный апстрим-источник данных, ранее в список не
            # попавший.
            estimate_depth, fill_crop_canvas,
        )]
        # ЯЗЫК КАМЕРЫ живёт ОТДЕЛЬНЫМ модулем, и его ТАБЛИЦА — это рецепт,
        # а не рантайм-параметр: правка палитры стадии меняет движение уже
        # отрендеренного клипа, при этом исходник choose_motion_mode
        # остаётся побайтово прежним. Берётся РЕЗУЛЬТАТ вызова, а не
        # inspect.getsource() функции-якоря: собственный промах, пойманный
        # своим же тестом — текст якоря от правки таблицы не меняется, и
        # подпись оставалась прежней, то есть гвард выглядел поставленным и
        # не работал.
        parts.append(_camera_language_recipe_source())
        parts.append(repr((
            sorted(MOOD_GRADE.items()), sorted(DOMAIN_WARM_PUSH_SCALE.items()),
            GRAIN_ENABLED, GRAIN_OPACITY, DEFLICKER_ENABLED, DOF_ENABLED,
            DOF_FOCUS_DEPTH, DOF_FOCUS_DEPTH_FLOOR, DOF_FOCUS_CENTER_Y, DOF_FOCUS_CENTER_X,
            FPS, WIDTH, HEIGHT, ZOOM_FLOOR, ZOOM_RATE_BASE,
            ZOOM_DELTA_MIN, ZOOM_DELTA_MAX, PAN_SAFETY,
            PARALLAX_ENABLED, PARALLAX_WARP_SIGMA_FRAC, PARALLAX_MAX_STRETCH,
            PARALLAX_OCCLUSION_AWARE, PARALLAX_INPAINT_RADIUS,
            HOOK_KINETIC_CAPTIONS_ENABLED,
            CLIP_PIX_ARGS, COLOR_META_ARGS,
        )))
        # KENBURNS_ADAPTIVE_CANVAS — УСЛОВНО, только когда флаг взведён.
        # Почему не просто ещё одно поле в кортеже выше: при дефолте (=0)
        # подпись обязана остаться байт-в-байт прежней, иначе сама эта
        # правка инвалидировала бы весь прогретый temp_smart/ у каждого,
        # кто флаг никогда не трогал — «апгрейд плюс перерендер», а не
        # апгрейд. Почему вообще нужно: холст входит в crop=/zoompan и
        # масштабирует амплитуду покачивания (WOBBLE_AMP_CANVAS_PX *
        # kb_cw/8000, см. kenburns()) — то есть это часть рецепта, но
        # значение берётся из ENV, а не из исходника kenburns(), и хэш
        # исходника его не видит: включение флага на прогретом кэше молча
        # смешало бы клипы с холстом 8000x4500 и 2880x1620 в одном ролике.
        # Хэшируется реальный размер холста (не только факт флага) — смена
        # KENBURNS_CANVAS_MARGIN при включённом флаге тоже меняет рецепт.
        if KENBURNS_ADAPTIVE_CANVAS:
            parts.append(repr(("KENBURNS_ADAPTIVE_CANVAS", _kenburns_canvas_size())))
        # LUMA_MATCH — УСЛОВНО, ровно по той же причине и тем же приёмом, что
        # KENBURNS_ADAPTIVE_CANVAS строкой выше. Профиль читается из реестра В
        # МОМЕНТ РЕНДЕРА (luma_match_params() в main()) и даёт brightness_bias
        # КАЖДОМУ клипу, то есть является частью РЕЦЕПТА картинки — но исходник
        # самой luma_match_params() при смене значения не меняется ни на байт, и
        # хэш исходников его не видит. Следствие, проверенное по коду (18.09):
        # переключение LUMA_MATCH=strong/max/none на прогретом temp_smart/ молча
        # не меняло ничего — клип брался готовым (os.path.exists(out) ->
        # continue) ДО того, как профиль вообще прочитан. Рычаг, заведённый
        # ради выбора между скачком яркости 36/255 и 28/255, был неработающим
        # ровно у того, кто уже отрендерил эпизод и хотел сравнить два варианта.
        #
        # Дефолт ("normal") в подпись НЕ добавляется: иначе сама эта правка
        # перерендерила бы весь прогретый кэш у каждого, кто флаг не трогал.
        # Хэшируются реальные (clamp, gain), а не ИМЯ профиля: опечатка в .env
        # даёт fail-open на "normal" (см. докстринг luma_match_params()), и
        # подпись в этом случае обязана совпасть с прежней, а не разойтись
        # из-за текста, который ни на что не влияет.
        _luma_profile = luma_match_params()
        if _luma_profile != LUMA_MATCH_PROFILES["normal"]:
            parts.append(repr(("LUMA_MATCH", _luma_profile)))
    except Exception:
        return "recipe:unknown"
    return "recipe:" + hashlib.md5("".join(parts).encode()).hexdigest()[:10]


RENDER_RECIPE_SIG = None   # считается один раз в main() (см. render_recipe_signature)


def _stock_api_pacing(i, use_pexels, use_local):
    """Пауза раз в 10 слотов, пока идёт отбор из стока (квота Pexels
    200 запросов/час). Одна функция на оба пути — обычный прогон и
    --select-only: пейсинг влияет на то, словит ли сток 429, то есть на
    сетевое поведение, и расходиться между режимами он не имеет права."""
    if use_pexels and not use_local and i % 10 == 9:
        time.sleep(0.4)


def finish_select_only(shot_entries, n_blocks):
    """Итог режима --select-only. Коды возврата — ТЕ ЖЕ, что у рендера
    (EXIT_OK/EXIT_BUILT_WITH_WARNINGS/EXIT_NOT_BUILT), со смыслом «отбор»
    вместо «сборка»: 0 — каждый слот получил проверенный кадр; 2 — часть
    слотов поглощена или осталась без медиа; 1 — не выбрано ничего. Новой
    семантики кодов не заводится: render_episode.py и render_with_retry.py
    уже понимают эти три числа."""
    with_media = sorted(i for i, e in shot_entries.items() if e.get("file"))
    _have = set(with_media)
    without = [i for i in range(n_blocks) if i not in _have]
    print(f"ОТБОР ГОТОВ (без рендера): кадр выбран у {len(with_media)} из {n_blocks} слот(ов)"
          + (f"; без кадра: {[i + 1 for i in without]}" if without else ""))
    print(f"  Шотлист и отчёты отбора — {os.path.join(VIDEO_FOLDER, 'media_plan')}. "
          f"Артефакты рендера не тронуты.")
    if not with_media:
        return EXIT_NOT_BUILT
    return EXIT_BUILT_WITH_WARNINGS if without else EXIT_OK


def check_jobs_in_order(pending_jobs):
    """pending_jobs обязан идти строго по ВОЗРАСТАНИЮ индекса блока — этого
    (и только этого) требует xfade-склейка ниже: кадры должны попасть в
    цепочку в том же порядке, в каком идут блоки сценария.

    РЕАЛЬНЫЙ БАГ, который здесь жил (падение всего прогона, не порча
    порядка): проверка была `assert job["i"] == k` — то есть требовала,
    чтобы индекс блока СОВПАДАЛ с позицией в списке. Но блок, для которого
    не нашлось ни фото, ни видео (кончилась квота Pexels, пустая выдача по
    запросу, нет ключа), в pending_jobs НЕ добавляется вообще — это штатный
    путь `continue` с записью в missing/render_manifest. После первого же
    такого блока все последующие позиции сдвигались на единицу, и ровно эта
    "защитная" проверка роняла весь рендер сырым AssertionError с
    трейсбеком — вместо аккуратного отчёта "СТОП: N клип(ов) не приняты"
    (RENDER_STRICT_GATE, ниже) или сборки без пропущенных кадров. То есть
    страховка от гипотетического бага сама создавала гарантированное
    падение на самом обычном сценарии.

    Возрастание (а не равенство позиции) — это и есть настоящий инвариант:
    он держится при любом числе пропусков и ловит именно то, от чего
    страховка ставилась (переставленные/дублированные задания)."""
    prev = -1
    for pos, job in enumerate(pending_jobs):
        if job["i"] <= prev:
            raise AssertionError(
                f"pending_jobs не по порядку: позиция {pos} содержит блок {job['i']} "
                f"после блока {prev} — склейка получила бы кадры не в том порядке "
                f"(см. комментарий у append в main())")
        prev = job["i"]
    return True


def print_plan_summary(blocks, durs, queries, total, xfade_budget, n_blocks_before_subcuts):
    """Свод для --plan-only (см. PLAN_ONLY): показывает то же самое, что
    иначе можно узнать только по факту рендера — часы CPU спустя. Ни ffmpeg,
    ни сетевых вызовов к Pexels/CLIP-моделям здесь нет: только уже
    посчитанные blocks/durs/queries.

    Побочные файлы (shot_manifest.json/subtitles.srt/chapters.txt) к этому
    моменту уже записаны вызывающим кодом (main()) — это чистая печать
    свода поверх них, не отдельный проход."""
    n_sections = len({b["section"] for b in blocks})
    n_subcuts = sum(1 for b in blocks if b.get("is_subcut"))
    n_generic = sum(1 for q in queries
                    if q in GENERIC_FALLBACKS or q in generic_fallback_queries_effective())
    total_dur = sum(durs)
    predicted_final = total_dur - xfade_budget

    print("\n=== PLAN-ONLY: сборка НЕ запускалась (ни одного вызова ffmpeg) ===")
    print(f"Блоков: {len(blocks)} (до sub-cuts: {n_blocks_before_subcuts}, "
          f"sub-cuts: {n_subcuts}) в {n_sections} секци(ях)")
    print(f"Средний кадр: {total_dur / max(1, len(blocks)):.2f}с")
    by_section = {}
    for b, d in zip(blocks, durs):
        by_section.setdefault(b["section"], []).append(d)
    for name, ds in by_section.items():
        print(f"  {name}: {len(ds)} кадр(ов), средний {sum(ds) / len(ds):.2f}с, "
              f"сумма {sum(ds):.1f}с")
    print(f"Аудио: {total:.2f}с | сумма длительностей кадров: {total_dur:.2f}с | "
          f"бюджет склейки: {xfade_budget:.2f}с")
    drift_ms = abs(predicted_final - total) * 1000
    half_frame_ms = 500.0 / FPS
    drift_note = ("в пределах полукадра — тайминг сойдётся без заморозки в хвосте"
                  if drift_ms <= half_frame_ms else
                  "БОЛЬШЕ полукадра — при реальном рендере жди либо заморозку в хвосте "
                  "(pad_to_length), либо перебор, обрезаемый муксом; стоит перепроверить "
                  "block_durations()/estimate_xfade_budget() на этом сценарии")
    print(f"Прогноз длины смонтированного видео (сумма - бюджет): {predicted_final:.2f}с "
          f"(расхождение с аудио: {drift_ms:.0f} мс — {drift_note})")
    if n_generic:
        print(f"  ВНИМАНИЕ: {n_generic} слот(ов) без тематического запроса — ушли в "
              f"GENERIC_FALLBACKS (см. resolve_queries). Стоит расширить themes.json "
              f"ДО того, как тратить кредиты Pexels/AI-картинок на угадывание.")
    print("Файлы для проверки: media_plan/shot_manifest.json, subtitles.srt, chapters.txt")
    print("Готово (план). Для реальной сборки — запусти без --plan-only.")


def _timed_render(render_fn, clip_idx, *args, **kwargs):
    """Замер времени рендера ОДНОГО клипа.

    Обёртка СНАРУЖИ kenburns()/video_render()/parallax_kenburns(), а не
    таймер внутри них — сознательно: их исходный код хэшируется
    render_recipe_signature(), и правка тела (даже добавление строки
    замера) сменила бы params_hash и молча инвалидировала весь кэш
    temp_smart/ на 165 клипов. Реальный случай 01.09: monkeypatch
    choose_motion_mode ровно так и запустил незапланированный полный
    перерендер.

    Функция верхнего уровня, а не lambda/closure: ProcessPoolExecutor
    пикклит вызываемое, замыкание не пикклится. При STAGE_TIMER=0 —
    прозрачный проброс, поведение байт-в-байт прежнее."""
    with stage_timer.stage("clip_render", clip_idx=clip_idx, fn=render_fn.__name__):
        return render_fn(*args, **kwargs)


# Фильтры ffmpeg, без которых включённый слой не соберёт НИ ОДНОГО клипа.
# Ключ — имя флага реестра, значение — фильтры, которые этот слой реально
# вызывает. Проверяются только ВКЛЮЧЁННЫЕ слои: выключенный deflicker на
# сборке без deflicker не проблема.
REQUIRED_FFMPEG_FILTERS = {
    None:                ("zoompan", "xfade", "scale"),   # ядро, всегда
    "ON_SCREEN_TEXT":    ("drawtext",),
    "GRAIN_ENABLED":     ("blend",),
    "DEFLICKER_ENABLED": ("deflicker",),
    "MUSIC_BED":         ("sidechaincompress", "loudnorm"),
}

_FFMPEG_FILTERS_CACHE = None


def available_ffmpeg_filters():
    """Множество имён фильтров у ТОГО ffmpeg, который реально будет вызван."""
    global _FFMPEG_FILTERS_CACHE
    if _FFMPEG_FILTERS_CACHE is not None:
        return _FFMPEG_FILTERS_CACHE
    try:
        out = subprocess.run(["ffmpeg", "-hide_banner", "-filters"],
                             capture_output=True, text=True, encoding="utf-8",
                             errors="replace", timeout=30).stdout
        _FFMPEG_FILTERS_CACHE = set(re.findall(r'^\s*[A-Z.]{3}\s+(\S+)', out, re.M))
    except Exception:
        _FFMPEG_FILTERS_CACHE = set()   # не смогли спросить — не гейтим
    return _FFMPEG_FILTERS_CACHE


def check_ml_stack():
    """Назвать отсутствующий torch/transformers ДО рендера, тем же приёмом,
    что check_ffmpeg_filters() уже делает для фильтров ffmpeg (см. её
    докстринг) — тихий fail-open внутри smart_relevance_veto() правильно
    не роняет рендер, но БЕЗ этой функции узнать, что вторая проверка
    победителя молча не работала весь прогон, было бы неоткуда.

    ЧЕСТНО ПРО АВТОУСТАНОВКУ (по прямому требованию владельца "включи
    авто скачивание при рендере, чтобы применялись, а не просто лежали").
    Не тихая: пакеты весят ~2 ГБ и качаются минуты, а этот же файл в
    ДРУГОМ месте документирует, почему тяжёлые ML-зависимости в этом
    проекте НИКОГДА не ставятся неявно (requirements.txt: "безопасный
    откат, без регрессии" — тот же принцип, что у платных API-вызовов,
    которые не подтверждаются автоматически, см. --confirm-payg у
    lumean_tts.py). Автоустановка здесь — тоже ОПТ-ИН, включённый явно
    переменной AUTO_INSTALL_ML=1 в .env ЭТОГО канала, а не поведение
    по умолчанию для любого, кто клонирует репозиторий: у владельца
    другой машины/квоты трафика/дисциплины расходов быть не должно
    сюрприза "рендер сам скачал два гигабайта".

    С AUTO_INSTALL_ML=1 — реально ставит (pip install, ЭТОТ же интерпретатор
    sys.executable, не голый "pip" из PATH) ОДИН раз за прогон, если модели
    ещё нет; печатает, что делает, и почему. Без флага — печатает точную
    команду и продолжает: SMART_RELEVANCE_VETO молча остаётся no-op (тот же
    fail-open, что и всегда), CLIP как быстрый гейт всего пула не тронут."""
    if not feature_flags.enabled("SMART_RELEVANCE_VETO"):
        return
    try:
        import torch  # noqa: F401
        import transformers  # noqa: F401
        return
    except ImportError:
        pass
    if os.environ.get("AUTO_INSTALL_ML", "0") == "1":
        print("  AUTO_INSTALL_ML=1: ставлю torch/transformers/onnxruntime "
              "(вторая проверка кадра, ~2 ГБ, займёт несколько минут)...")
        cmd = [sys.executable, "-m", "pip", "install", "-q", "torch",
               "--index-url", "https://download.pytorch.org/whl/cpu",
               "transformers", "onnxruntime", "huggingface_hub"]
        try:
            r = subprocess.run(cmd, capture_output=True, text=True,
                              encoding="utf-8", errors="replace", timeout=1800)
            if r.returncode != 0:
                print(f"  ВНИМАНИЕ: автоустановка не удалась ({r.stderr[-400:]}) — "
                      f"вторая проверка кадра (SMART_RELEVANCE_VETO) на этом прогоне "
                      f"работать не будет, CLIP остаётся единственным гейтом.")
            else:
                print("  torch/transformers/onnxruntime поставлены.")
        except Exception as e:
            print(f"  ВНИМАНИЕ: автоустановка упала ({type(e).__name__}) — "
                  f"вторая проверка кадра на этом прогоне работать не будет.")
    else:
        print("  ВНИМАНИЕ: SMART_RELEVANCE_VETO включён, но torch/transformers не "
              "установлены — вторая проверка победителя слота (SigLIP2+Jina) на "
              "этом прогоне НЕ работает, CLIP остаётся единственным гейтом. "
              "Поставить вручную: pip install torch --index-url "
              "https://download.pytorch.org/whl/cpu transformers onnxruntime "
              "huggingface_hub — или один раз положить AUTO_INSTALL_ML=1 в .env, "
              "чтобы это делалось автоматически (~2 ГБ, минуты, один раз).")


def check_ffmpeg_filters():
    """Назвать отсутствующий фильтр ДО рендера, а не после трёх попыток.

    Реальный случай 14.09, стоивший целого прогона: в контейнере ffmpeg шёл
    из imageio-ffmpeg (символьная ссылка /usr/local/bin/ffmpeg), собранного
    БЕЗ drawtext — ffmpeg 7 требует для него libharfbuzz. Каждый клип с
    плашкой/титром падал с 'Filter not found', три попытки подряд, и только
    RENDER_STRICT_GATE не дал собрать ролик молча без экранного текста.
    Сообщение при этом не называло НИ отсутствующий фильтр (его имя тонуло
    в эхе всего filter_complex), НИ причину — диагностика заняла больше,
    чем сам рендер.

    Ничего не блокирует: печатает предупреждение и возвращает список — тот
    же fail-open, что у остальных проверок окружения. Сборка всё равно
    остановится на RENDER_STRICT_GATE, но теперь с названной причиной."""
    have = available_ffmpeg_filters()
    if not have:
        return []
    missing = []
    for flag, filters in REQUIRED_FFMPEG_FILTERS.items():
        if flag is not None and not feature_flags.enabled(flag):
            continue
        for f in filters:
            if f not in have:
                missing.append((f, flag or "ядро рендера"))
    if missing:
        print("  ВНИМАНИЕ: у этого ffmpeg НЕТ фильтров, которые нужны включённым слоям:")
        for f, flag in missing:
            print(f"    {f} — нужен для {flag}")
        print("    Клипы с этим слоем упадут с 'Filter not found'. Поставить сборку"
              " ffmpeg с этими фильтрами (например системный пакет вместо"
              " imageio-ffmpeg) либо выключить слой в .env.")
    return missing


def main():
    global PEXELS_QUOTA_RESERVE, SHOT_JUDGE_EPISODE_SLOTS
    if not os.path.exists(AUDIO_FILE):
        print(f"Аудио не найдено: {AUDIO_FILE}")
        return 1
    total = get_audio_duration()
    print(f"Аудио: {total:.1f}с ({total/60:.1f} мин)")
    # Какой пайплайн РЕАЛЬНО исполняется — до того, как потрачены часы CPU.
    # Дорогой слой, выключенный в .env, раньше было видно только по
    # отсутствию строк в логе где-то в середине рендера (или не видно вовсе).
    feature_flags.print_summary()
    check_ffmpeg_filters()
    check_ml_stack()
    feature_flags.write_snapshot(VIDEO_FOLDER)
    audio_qc(AUDIO_FILE)
    os.makedirs(TEMP_FOLDER, exist_ok=True)
    # Замер стадий — только при STAGE_TIMER=1, иначе путь не выставляется
    # и stage() остаётся пустым (см. scripts/stage_timer.py).
    if stage_timer.STAGE_TIMER_ENABLED:
        stage_timer.set_output_path(
            os.path.join(VIDEO_FOLDER, "media_plan", "stage_timings.jsonl"))
        print("  Замер стадий включён (STAGE_TIMER=1) -> media_plan/stage_timings.jsonl")
    # Огрызки .partial.mp4 от предыдущего прогона, убитого посреди рендера
    # клипа (SIGKILL/OOM/обрыв — см. render_tmp_path/finalize_render) —
    # безопасно чистить на старте: раз файл лежит под .partial.mp4, а не
    # под финальным именем, значит тот рендер так и не завершился успехом,
    # доедать его нечем, только место занимает.
    for stale in glob.glob(os.path.join(TEMP_FOLDER, "clip_*.mp4.partial.mp4")):
        try:
            os.remove(stale)
        except OSError:
            pass
    # Тот же огрызок, но от финального мукса (см. render_tmp_path(OUTPUT_FILE)
    # в конце main()) — лежит не в TEMP_FOLDER, а рядом с самим final.mp4.
    stale_final = render_tmp_path(OUTPUT_FILE)
    if os.path.exists(stale_final):
        try:
            os.remove(stale_final)
        except OSError:
            pass
    blocks = parse_blocks(SCRIPT_FILE) if os.path.exists(SCRIPT_FILE) else []
    if not blocks:
        print("Сценарий не найден/пуст")
        return 1
    auto_plan_episode(blocks)
    # Мир эпизода — в музейный фильтр: окно эпохи и чужие культуры из
    # паспорта, а не из дефолтов канала (см. museum_sources.set_episode_world).
    import museum_sources
    museum_sources.set_episode_world(episode_world_card())
    # ЛОКАЛЬНЫЙ РЕЖИССЁР (SHOT_PLANNER_LLM, дефолт 1). Заполняет РОВНО ТО ЖЕ
    # поле shot_brief, которое пишет автор тегом [shot:...] — и поэтому не
    # заводит ни одной новой связи: вопрос к полке (shelf_question), перевод
    # в короткий стоковый запрос (brief_to_stock_query), ключ кэша кандидата
    # (candidate_brief_key) и его инвалидация уже умеют работать с этим
    # полем. Бриф АВТОРА не перезаписывается никогда: он проверен человеком,
    # заявка модели — нет.
    #
    # Читается ГОТОВЫЙ план с диска, живых вызовов здесь не делается:
    # планирование — отдельная команда (scripts/shot_brief_director.py),
    # потому что оно идёт десятки минут на эпизод и не имеет права стоять
    # внутри рендера, который и так перезапускают. Сам план и его проверка
    # живут в shot_planner_llm — мозга там больше нет, только дисциплина.
    try:
        import shot_planner_llm
        if shot_planner_llm.enabled():
            _plan = shot_planner_llm.load_plan(VIDEO_FOLDER)
            _filled = shot_planner_llm.fill_briefs(blocks, _plan)
            if _filled:
                print(f"  Локальный режиссёр: заявка проставлена на {_filled} "
                      f"юнитов из {len(blocks)} (авторские брифы не тронуты)")
            elif _plan:
                print("  Локальный режиссёр: план есть, но ни одна заявка не "
                      "подошла к текущему script.txt — текст правился после "
                      "планирования, перезапусти shot_brief_director.py")
    except Exception as _e:
        # Fail-open той же дисциплины, что у остальных надстроек: сбой
        # планировщика не имеет права уронить рендер.
        print(f"  Локальный режиссёр пропущен ({type(_e).__name__})")
    # Запросы к стокам на каждую фразу (scripts/stock_query_planner.py) —
    # готовый план с диска, живых вызовов здесь нет. Проставляется ДО
    # нарезки блоков: под-кадры наследуют поле через dict(b).
    try:
        import stock_query_planner
        _sq = stock_query_planner.attach(blocks, stock_query_planner.load(VIDEO_FOLDER),
                                         stock_query_planner.load_specs(VIDEO_FOLDER))
        if _sq:
            print(f"  Запросы фраз: на {_sq} из {len(blocks)} блоков (media_plan/"
                  f"{stock_query_planner.PLAN_NAME})")
    except Exception as _e:
        print(f"  Запросы фраз пропущены ({type(_e).__name__})")
    # ИСХОДНЫЙ индекс блока — единственное, что связывает блок монтажа с юнитом
    # speech_plan.json ПОСЛЕ split_long_blocks()/merge_short_phrase_locked_blocks().
    # N4 из docs/AUDIT_2026-09_DEEP.md, измерено на этом эпизоде: главный цикл
    # идёт по 165 блокам, а speech_plan знает только 91 исходный — и раньше
    # arc_stage брался по индексу ЦИКЛА. Итог: 151 слот из 165 (92%) получал
    # либо чужую драматургическую стадию (77 слотов — например, слот 9 хука
    # брал стадию из BLOCK 1), либо вообще ничего (74 слота после 90-го).
    # Обе надстройки, которые на неё опираются (Look Management, Visual
    # Director), в .env стоят assist — то есть работали на неверных данных.
    # dict(b) в split_long_blocks() и dict(pb) в _merge_two_blocks() копируют
    # ключ сами: под-кадры наследуют индекс своей фразы, а слитый блок —
    # индекс первого из слитых, что и требуется.
    for _bi, _b in enumerate(blocks):
        _b["orig_index"] = _bi
    # Реальный тайминг считаем ДО sub-cuts — alignment.csv записан 1:1 на
    # исходные блоки (по [pause]/[short pause]), split_long_blocks() потом
    # честно делит вес пропорционально словам между получившимися кусками.
    real_weights = load_alignment_weights(blocks)
    if real_weights:
        known = sum(1 for w in real_weights if w is not None)
        print(f"Реальный тайминг (alignment.csv): {known}/{len(blocks)} блоков")
    n_before = len(blocks)
    blocks, real_weights = split_long_blocks(blocks, real_weights)
    SHOT_JUDGE_EPISODE_SLOTS = len(blocks)
    if len(blocks) != n_before:
        print(f"Sub-cuts: {n_before} -> {len(blocks)} блоков")
    # См. merge_short_phrase_locked_blocks() — PHRASE LOCK ветка строит
    # длительность строго по реальным онсетам речи, без единого пола, поэтому
    # сам HOOK_MIN_CLIP/MIN_CLIP её не защищает; здесь заранее сливаем
    # блоки, чья реальная фраза короче пола, чтобы КАЖДЫЙ уцелевший рез
    # (и в PHRASE LOCK, и в обычной ветке — обе читают уже этот blocks)
    # гарантированно не давал клип короче пола.
    n_before_merge = len(blocks)
    blocks, real_weights = merge_short_phrase_locked_blocks(blocks, real_weights, total)
    if len(blocks) != n_before_merge:
        print(f"Phrase-lock merge (клипы короче пола): {n_before_merge} -> {len(blocks)} блоков")
    # Кроссфейд между КАЖДОЙ парой кадров суммарно "съедает" какую-то часть
    # длительности — закладываем это в целевую длительность заранее, чтобы
    # после склейки общая длина видео снова совпала с аудио (без этого хвост
    # ролика проигрывался бы без картинки под конец аудиодорожки). Считаем
    # ПОСЛЕ split — sub-cuts добавляют новые склейки, бюджет должен их
    # учитывать. estimate_xfade_budget() — точная оценка по категориям
    # перехода (2.4), не плоская (n-1)*XFADE_DUR.
    # Граница урезанного пула — по РЕАЛЬНОЙ длине хука этого эпизода, а не
    # по фиксированному числу (см. fast_mode_start_for_blocks): на 02 хук
    # занимает 30 слотов, и при фиксированных 15 ровно его вторая половина
    # собиралась урезанным бюджетом. Ставится ЗДЕСЬ, после split/merge (состав
    # блоков окончателен) и до первого обращения к candidate_gate_signature()
    # — та кэширует подпись на первом вызове, и более поздняя правка границы
    # в неё бы уже не попала.
    global _FAST_MODE_START
    _FAST_MODE_START = fast_mode_start_for_blocks(blocks)
    _hook_slots = sum(1 for b in blocks if b["section"].startswith("HOOK"))
    print(f"Полный пул кандидатов: слоты 0..{_FAST_MODE_START - 1} "
          f"(хук — {_hook_slots} слот(ов)), дальше урезанный "
          f"(пол реестра — {FAST_MODE_START_INDEX})")

    xfade_budget = estimate_xfade_budget(blocks)
    target = total + xfade_budget
    durs = block_durations(blocks, target, real_weights=real_weights)

    # === PHRASE LOCK — рез строго на начале фразы =========================
    # Реальная, измеренная причина жалобы «кадр показывается не под озвучку»
    # (28 августа): ниже по коду длительность проходила через СЕМЬ
    # преобразований (floor/cap-клэмп и rescale внутри block_durations,
    # energy_mults, apply_section_boundary_shift ±250-400мс,
    # apply_within_cut_shift ±80-180мс, apply_human_jitter ±300мс,
    # snap_hook_cuts_to_energy, поштучное quantize_durations_to_frames).
    # Каждое двигает границу кадра ОТНОСИТЕЛЬНО фразы, и ошибки СКЛАДЫВАЮТСЯ
    # по накоплению — к концу хука рез уезжает от своей фразы на доли секунды
    # и больше, то есть кадр «принадлежит» уже не той фразе.
    #
    # Обоснование, почему это чистое улучшение, а не размен:
    # эти преобразования вводились как «оживление» механически ровной сетки —
    # но сетка перестала быть механической ровно тогда, когда появился
    # реальный alignment: длительности фраз и так неравномерны от природы
    # речи (в этом эпизоде 1.25с .. 4.58с). То есть джиттер добавляет
    # неравномерность, которая УЖЕ есть, и платит за это единственным, что
    # тут по-настоящему важно — совпадением кадра с произносимой фразой.
    # J/L-cut (apply_*_shift) в этой архитектуре тоже недостижим и честно
    # признан таковым в собственном докстринге («классический приём тут
    # физически не из чего собрать» — одна сплошная дорожка озвучки на весь
    # ролик): сдвиг видео-реза с границы фразы не создаёт J/L-cut, он
    # создаёт ровно тот рассинхрон, на который жалуется зритель.
    onsets = load_alignment_onsets(blocks) if PHRASE_LOCK else None
    if PHRASE_LOCK and not onsets:
        # N5: раньше здесь была тишина — эпизод собирался по оценочным
        # длительностям вместо реальных онсетов речи, и узнать об этом было
        # неоткуда. Теперь причина называется вслух и уезжает в манифест.
        _f = ALIGNMENT_ONSET_FAILURE or {"reason": "alignment не найден"}
        _det = ", ".join(f"{k}={v!r}" for k, v in _f.items() if k != "reason")
        print(f"  ВНИМАНИЕ: PHRASE LOCK ВЫКЛЮЧЕН — {_f['reason']}"
              + (f" ({_det})" if _det else ""))
        print("            Кадры будут привязаны к ОЦЕНОЧНЫМ длительностям, а не к речи. "
              "Если озвучка свежая — сверить script.txt с media_plan/alignment/*.csv.")
    phrase_locked = None
    if onsets:
        phrase_locked = phrase_locked_durations(
            onsets, total, effective_transition_plan(plan_transitions([b["section"] for b in blocks], blocks),
                                                    [b["section"] for b in blocks]))
    curve = audio_energy_curve(AUDIO_FILE)
    energy_lvls = [1.0] * len(blocks)

    if phrase_locked:
        durs = phrase_locked
        # Шкала аудио для субтитров/глав — те же самые онсеты, а не отдельная
        # оценка: раньше субтитры считались по block_durations() (оценка с
        # клэмпом и rescale), из-за чего они закономерно «не успевали за
        # озвучкой» — та же корневая причина, что и у картинки.
        sub_starts = [0.0] + [onsets[i] for i in range(1, len(onsets))]
        sub_baseline = [(sub_starts[i + 1] if i + 1 < len(sub_starts) else total) - sub_starts[i]
                        for i in range(len(sub_starts))]
        if curve:
            # Громкость больше НЕ двигает резы (это ломало бы привязку), но
            # по-прежнему даёт лёгкую пульсацию грейда — там она безвредна.
            energy_lvls = energy_levels(curve, sub_starts, sub_baseline)
        print(f"Тайминг: рез привязан к началу фразы по alignment "
              f"({len(onsets)}/{len(blocks)} блоков, точность ±полкадра)")
    else:
        # Прежнее поведение целиком — эпизод без alignment (или с текстом,
        # правленным после записи): точной шкалы фраз не существует, и
        # «оживление» ровной оценки остаётся осмысленным.
        if curve:
            baseline = block_durations(blocks, total, real_weights=real_weights)
            starts, acc = [], 0.0
            for d in baseline:
                starts.append(acc)
                acc += d
            mults = energy_pace_multipliers(curve, starts, baseline)
            durs = block_durations(blocks, target, energy_mults=mults, real_weights=real_weights)
            energy_lvls = energy_levels(curve, starts, baseline)
            print("Ритм по громкости: включён")
        durs = apply_section_boundary_shift(blocks, durs)
        durs = apply_within_cut_shift(blocks, durs)
        durs = apply_human_jitter(blocks, durs)
        sub_baseline = block_durations(blocks, total, real_weights=real_weights)
        sub_starts, sub_acc = [], 0.0
        for d in sub_baseline:
            sub_starts.append(sub_acc)
            sub_acc += d
        durs = snap_hook_cuts_to_energy(blocks, durs, sub_starts, AUDIO_FILE)
        durs = quantize_durations_to_frames(durs)
    print(f"Средний кадр: {sum(durs)/len(durs):.1f}с")

    write_subtitles(VIDEO_FOLDER, blocks, sub_starts, sub_baseline, real_weights=real_weights)
    write_chapters(VIDEO_FOLDER, blocks, sub_starts)

    # visual_starts — РЕАЛЬНЫЕ старты клипов на шкале визуального монтажа,
    # ПОСЛЕ всех "очеловечивающих" сдвигов durs выше (apply_section_boundary_shift/
    # apply_within_cut_shift/apply_human_jitter/snap_hook_cuts_to_energy) И
    # после xfade-нахлёста (см. hook_visual_starts). Нужны ТОЛЬКО для
    # rescale_hook_words_to_visual_time() ниже (P0-3) — sub_starts/sub_baseline
    # остаются аудио-шкалой для write_subtitles/write_chapters (это и должно
    # быть привязано к голосу, не к монтажу).
    visual_starts = hook_visual_starts(blocks, durs)

    # media_plan/phrase_timeline.json — ПРОВЕРЯЕМЫЙ аудит привязки кадра к
    # фразе. Пишется ВСЕГДА (даже когда привязки нет — тогда честно
    # locked=false), потому что «показалось ли вовремя» до этого нельзя было
    # проверить ничем, кроме просмотра глазами. Дрейф считается не по
    # намерению, а по РЕАЛЬНОЙ визуальной шкале монтажа (hook_visual_starts —
    # она уже учитывает сжатие таймлайна кроссфейдом), то есть отражает то,
    # что зритель действительно увидит.
    phrase_timeline = {"locked": bool(phrase_locked), "fps": FPS,
                       "audio_total_sec": total, "blocks": []}
    worst_drift = 0.0
    for i, b in enumerate(blocks):
        want = (0.0 if i == 0 else onsets[i]) if onsets else None
        drift = (visual_starts[i] - want) if want is not None else None
        if drift is not None:
            worst_drift = max(worst_drift, abs(drift))
        phrase_timeline["blocks"].append({
            "index": i, "section": b["section"], "text": b["text"][:120],
            "speech_onset_sec": want, "visual_start_sec": visual_starts[i],
            "duration_sec": durs[i], "drift_sec": drift,
        })
    phrase_timeline["worst_drift_sec"] = worst_drift if onsets else None
    phrase_timeline["max_allowed_drift_sec"] = 0.5 / FPS
    pt_path = os.path.join(VIDEO_FOLDER, "media_plan", "phrase_timeline.json")
    os.makedirs(os.path.dirname(pt_path), exist_ok=True)
    with open(pt_path + ".tmp", "w", encoding="utf-8") as f:
        json.dump(phrase_timeline, f, ensure_ascii=False, indent=2)
    os.replace(pt_path + ".tmp", pt_path)
    if phrase_locked:
        print(f"  Привязка кадра к фразе: худший дрейф {worst_drift * 1000:.0f}мс "
              f"(предел полкадра = {500 / FPS:.0f}мс) — media_plan/phrase_timeline.json")
    else:
        print("  ВНИМАНИЕ: точной привязки кадра к фразе НЕТ (нет alignment или текст "
              "правился после записи) — тайминг оценочный, см. media_plan/phrase_timeline.json")

    clips, clip_durs, clip_sections, clip_blocks = [], [], [], []
    missing = []   # индексы блоков, для которых не нашлось ни фото, ни видео
    media_log = []   # (индекс, путь_к_фото) — для QC-проверки на похожие кадры в конце
    render_manifest = {}   # индекс -> статус (ok/failed/skipped-no-media), для резюме/диагностики
    zoom_hist, pan_hist = [], []
    # История ПАР (режим, направление) для языка камеры — см.
    # camera_language.pick_direction(). Отдельно от zoom_hist: при
    # выключенном флаге работает прежний гвард на голом направлении, и
    # смешивать две разные истории в одном списке значило бы, что откат
    # флага меняет поведение не байт-в-байт.
    zoom_pair_hist = []
    # Пул на kenburns()/video_render() — НЕ на parallax_kenburns() (та
    # остаётся последовательной в этом же процессе, см. комментарий у
    # RENDER_POOL_ENABLED выше). Решение "что рендерить" (выбор фото/видео,
    # anti-repeat) остаётся ПОЛНОСТЬЮ последовательным, как и раньше —
    # параллелится только сам вызов ffmpeg, уже после того, как всё решено.
    # РЕАЛЬНЫЙ найденный вживую OOM (31 авг, полный рендер 01_ves-mecha,
    # dmesg): cgroup OOM-killer убил pid 1405 (anon-rss 8.66GB) и следом ещё
    # 3 форкнутых воркера пула — КАЖДЫЙ с тем же anon-rss ~8.66GB. kenburns()/
    # video_render() (единственное, что реально уходит в этот пул) сами по
    # себе не грузят ни одну ML-модель — им передаются уже готовые
    # wb/levels/look_filter/domain, посчитанные ДО submit(). Причина —
    # порядок вызовов: pexels_photo()/sentence_relevance() (SigLIP2-so400m +
    # Jina, лениво загружаются в главном процессе при первом обращении к
    # кандидату) отрабатывают РАНЬШЕ первого render_pool.submit() внутри
    # того же блока — то есть к моменту первого форка пул уже приходится
    # форкать процесс, в котором эти модели УЖЕ загружены. fork() на Linux
    # делит память через COW, но refcounting трогает заголовок почти
    # каждого объекта, которого касается воркер (в т.ч. периодическая
    # cyclic GC) — COW расходится, и воркер фактически получает свою копию
    # уже загруженного веса моделей, которые ему не нужны. mp_context=spawn
    # даёт форкнутому процессу чистый интерпретер (torch/onnxruntime/
    # transformers импортируются только ВНУТРИ get_clip_model()/
    # get_depth_model()/sentence_relevance(), не на уровне модуля — см.
    # `import` в этих функциях) — воркер, вызывающий только kenburns()/
    # video_render(), никогда их не касается и не тянет ни байта моделей.
    render_pool = (concurrent.futures.ProcessPoolExecutor(
                       max_workers=RENDER_POOL_WORKERS,
                       mp_context=multiprocessing.get_context("spawn"))
                   if RENDER_POOL_ENABLED and not SELECT_ONLY else None)
    pending_jobs = []   # [{i, out, d, section, block, video, photo, future|None, ok}], в порядке блоков
    # Накопленное время слотов, поглощённых соседом (см. ABSORBED_SLOTS).
    _carry_sec = 0.0
    # «Лучший из плохих» как исход разрешён только при снятом флаге. Читается
    # ОДИН раз на прогон осознанно: внутри цикла на 200+ слотов это решение
    # обязано быть одинаковым для всех слотов, иначе половина ролика собрана
    # одним правилом, половина другим (ровно та жалоба «то работает, то не
    # работает», из-за которой заведена _selection_stack_signature).
    never_show_known_bad = feature_flags.enabled("NEVER_SHOW_KNOWN_BAD")
    # Плашки с цифрой, чьи слоты поглощены: цифра — контент, она переезжает
    # на поглощающий клип, а не исчезает с экрана.
    stat_carry = []
    log_render_diagnostics("render_start")
    # Версия рецепта картинки — часть ключа кэша клипов (см.
    # render_recipe_signature): правка грейда/движения/оформления больше не
    # переживает молча уже отрендеренные клипы.
    global RENDER_RECIPE_SIG
    RENDER_RECIPE_SIG = recipe_sig = render_recipe_signature()
    reset_source_stats()
    reset_camera_language_stats()
    RUN_JOURNAL.clear()
    selection_attempt.reset_attempt_ids()
    # Шлюз судьи и его потолок расходов — на прогон, а не на процесс.
    _SHOT_JUDGE_STATE.update(gateway=None, made=False, refused=None, slots=set(), warned=False,
                             world_votes=None)
    _VIDEO_UNSHARP_CACHE.clear()
    SHOT_JUDGE_LOG.clear()
    # Каталоги попыток прерванного процесса — мусор: живых попыток при
    # старте нет, и в кэш такой файл не попадёт никогда.
    selection_attempt.sweep_orphans(os.path.join(TEMP_FOLDER, "staging"))
    use_local = os.path.isdir(MEDIA_FOLDER) and bool(local_photo(0))
    use_pexels = bool(PEXELS_API_KEY)
    # === PEXELS QUERIES === написан вручную по протоколу (CLAUDE.md ЧАСТЬ 13,
    # Шаг 3), но до этой строки НИКОГДА не читался пайплайном — см. докстринг
    # resolve_queries()/authored_queries. {} у эпизодов без этой секции
    # (напр. тестовые скрипты) -> ноль влияния, прежнее поведение.
    SHOT_TYPE_EXPLICIT.update(parse_query_shot_types(SCRIPT_FILE))
    if SHOT_TYPE_EXPLICIT:
        print(f"  Типы кадра из сценария: {len(SHOT_TYPE_EXPLICIT)} запрос(ов) размечены явно")
    authored_queries = parse_pexels_queries(SCRIPT_FILE)
    if authored_queries:
        print(f"  Авторские PEXELS QUERIES: {sum(len(v) for v in authored_queries.values())} "
              f"запрос(ов) на {len(authored_queries)} секци(й)")
        lint_authored_queries(authored_queries, blocks)
    queries = resolve_queries(blocks, authored_queries=authored_queries)
    # Собственный запрос слота — первый запрос его фразы из плана: план
    # написан для ЭТОЙ фразы, раздача авторских запросов по смыслу — нет
    # (живой промах: хук эпизода 94, см. stock_query_planner). Остальные
    # запросы фразы идут в пул слота перед запросами секции.
    queries = apply_phrase_queries(blocks, queries)
    # Пул запросов СЕКЦИИ на каждый блок (см. extra_queries в pexels_photo).
    # Раньше авторские запросы раздавались блокам ПОЗИЦИОННО ПО КРУГУ
    # (pool[idx % len(pool)]) — на секции из 16 блоков и 3 запросов это
    # означало, что блок про заточку клинка получал запрос "medieval castle
    # hall" просто потому, что выпал третьим по счёту. Реально измерено на
    # videos/01_ves-mecha: совпадало по смыслу примерно 1 из 3, остальное —
    # шум раздачи. Теперь позиция задаёт лишь ОСНОВНОЙ запрос (кэш/гейт), а
    # кандидаты собираются из всех запросов секции, и победителя выбирает
    # сопоставление ПОЛНОЙ ФРАЗЫ блока с картинкой (Semantic Visual Director,
    # sentence_relevance) — то, для чего эта модель и обучена, в отличие от
    # сравнения текста с текстом (проверено: на text-vs-text та же модель
    # ошибалась 3 раза из 4, поэтому этот путь сознательно не используется).
    section_query_pool = {}
    if authored_queries:
        for b in blocks:
            key = _normalize_section_key(b["section"])
            if key and key in authored_queries:
                section_query_pool[b["section"]] = authored_queries[key]

    # LLM-режиссёр, атмосферное обогащение ХУКА (SHOT_DIRECTOR_MODE=on) —
    # РЕАЛЬНЫЙ, найденный вживую пробел, отдельный от direct_query() выше
    # (тот покрывает только блоки БЕЗ запроса вообще). Прямая жалоба
    # пользователя: у "Пятнадцать килограммов" уже ЕСТЬ технически
    # релевантный авторский запрос ("weighing scale metal object"), но он
    # взят слишком буквально — реальный монтажёр связал бы число с темой
    # ролика (меч), не с бытовым предметом. enrich_atmospheric_queries()
    # даёт 2-3 альтернативных запроса на КАЖДЫЙ блок хука (не заменяет
    # own_query — добавляет в тот же extra_queries-пул, что уже кросс-
    # опыляет кандидатов внутри секции, см. комментарий выше). Отбор кадра
    # (relevance-гейт + Semantic Visual Director реранк по РЕАЛЬНОЙ фразе)
    # не меняется — слот физически не может стать хуже, только получить
    # более богатый пул на выбор. Только ХУК (не всё тело эпизода) — тот же
    # принцип, что и у всех остальных HOOK-специфичных решений пайплайна
    # (короче клипы, только hardcut, параллакс на всю секцию): это
    # "самый крутой обрыв на кривой удержания" (ЧАСТЬ 9 CLAUDE.md),
    # оправдывает трату бюджета Gemini именно здесь, а не размазывание по
    # всему эпизоду. Бюджет — тот же SHOT_DIRECTOR_MAX_CALLS_PER_RUN/кэш,
    # что у direct_query() (единый счётчик _calls_made в shot_director.py).
    if (feature_flags.mode("SHOT_DIRECTOR_MODE") == "on"
            and "HOOK" in section_query_pool):
        import shot_director
        atmo_extra = []
        for i, b in enumerate(blocks):
            if not b["section"].startswith("HOOK"):
                continue
            own_query = queries[i]
            if not own_query:
                continue
            context = section_query_pool.get(b["section"], [])
            alt = shot_director.enrich_atmospheric_queries(b["text"], own_query, context, VIDEO_FOLDER)
            if alt:
                atmo_extra.extend(alt)
        if atmo_extra:
            pool = list(section_query_pool.get("HOOK", []))
            base_len = len(pool)
            for q in atmo_extra:
                if q not in pool:
                    pool.append(q)
            section_query_pool["HOOK"] = pool
            print(f"  Атмосферное обогащение хука: +{len(pool) - base_len} "
                  f"запрос(ов) от LLM-режиссёра (media_plan/shot_director_cache/atmo_*.json)")

    write_shot_manifest(VIDEO_FOLDER, blocks, durs, queries)

    if PLAN_ONLY:
        print_plan_summary(blocks, durs, queries, total, xfade_budget, n_before)
        return 0

    # Предпросмотр звука — ЗДЕСЬ, до единого отрендеренного клипа: всё, что
    # нужно звуку (блоки, тайминг, моменты плашек), к этому моменту уже
    # посчитано, а видео к звуку отношения не имеет.
    if AUDIO_PREVIEW:
        return write_audio_preview(blocks, durs, sub_starts, sub_baseline,
                                    real_weights, total, phrase_locked)

    # Reference-Guided Look Management (scripts/look_reference.py) — ленивый импорт
    # (см. clip_relevance()/torch выше — тот же принцип: не тянуть модель/CLIP в
    # процесс, если режим off) — только для shadow/assist; look_ref остаётся
    # None иначе — весь блок ниже, использующий look_ref, безопасно
    # пропускается (look_filter=None на каждый клип, ноль влияния на рендер).
    # ДО look_cache_sig — тот вызывает look_ref.cache_signature(), которая
    # должна быть уже импортирована.
    look_ref = None
    if feature_flags.mode("LOOK_MANAGEMENT_MODE") in ("shadow", "assist"):
        import look_reference as look_ref  # noqa: F401
    look_cache_sig = _look_management_cache_signature(look_ref)
    # Semantic Visual Director (scripts/visual_director.py) — тот же ленивый
    # импорт по режиму, что look_ref выше (не тянуть CLIP-модель в процесс,
    # если режим off). visual_director сам импортирует pipeline_smart (см.
    # докстринг модуля) — это НЕ циклический импорт с точки зрения Python
    # (мы импортируем visual_director уже ВНУТРИ выполнения main(), после
    # того как pipeline_smart полностью загружен), тот же паттерн уже
    # использует look_reference.py.
    visual_director = None
    if feature_flags.mode("VISUAL_DIRECTOR_MODE") in ("shadow", "assist"):
        import visual_director as visual_director  # noqa: F401
        # Чистый отчёт по обрезке текста НА ЭТОТ прогон — модуль импортируется
        # один раз на процесс, и без сброса список копился бы между
        # эпизодами при повторном вызове main() в одном процессе (тесты,
        # пакетный прогон нескольких видео).
        visual_director.reset_text_truncation_report()
    director_cache_sig = _visual_director_cache_signature(visual_director)
    # П.4: доменная модуляция warm_mult (DOMAIN_WARM_PUSH_SCALE, film_look())
    # — НЕЗАВИСИМА от Look Management/Visual Director (свой режим, свой
    # дефолт), но переиспользует ту же classify_domain(), если look_ref уже
    # импортирован для Look Management — повторный import того же модуля
    # дёшев (sys.modules), только тогда, когда оба включены одновременно
    # реально считается CLIP дважды на кадр (Look Management сегодня off по
    # умолчанию у этого канала — для него domain_ref это единственный вызов).
    # Дефолт "on" (не "off", как у shadow/assist-систем выше) — сознательно:
    # эффект узкий (сегодня только домен snow, см. DOMAIN_WARM_PUSH_SCALE),
    # переиспользует уже проверенный код (не новый эксперимент), правится по
    # прямой жалобе на конкретный кадр, визуально сверен Шагом 7.5 перед тем
    # как считаться готовым.
    # РЕАЛЬНЫЙ БАГ, пойманный при разборе (найден и исправлен в этом же
    # коммите, до первого реального использования): `domain_ref = look_ref`
    # раньше стояло БЕЗ проверки DOMAIN_GRADE_MODE — если Look Management уже
    # включён (LOOK_MANAGEMENT_MODE=shadow/assist), домен-модуляция включалась
    # молча, даже когда DOMAIN_GRADE_MODE=off явно просил её выключить. Флаг
    # теперь проверяется ОДИН РАЗ и решает, участвует ли domain_ref вообще,
    # независимо от того, откуда берётся сам модуль (переиспользуется look_ref
    # или импортируется отдельно).
    domain_ref = None
    if feature_flags.mode("DOMAIN_GRADE_MODE") != "off":
        domain_ref = look_ref
        if domain_ref is None:
            import look_reference as domain_ref  # noqa: F401
    domain_cache_sig = _domain_grade_cache_signature(domain_ref)
    # Arc-stage awareness — см. _load_arc_stage_by_index() выше. Передаётся
    # НИЖЕ в look_ref.look_correction_filter()/director_score_fn, чтобы Look
    # Management/Visual Director реагировали на драматургическую стадию
    # текущего блока, а не только на содержимое кадра в изоляции (тот же
    # принцип, по которому проф. колорист/монтажёр держит цвет/крупность
    # плана ПОДЧИНЁННЫМИ сюжету, не одинаковыми по всему ролику). Загружаем
    # ОДИН РАЗ, только если хотя бы один потребитель реально активен —
    # иначе это чтение файла впустую.
    arc_stage_by_index = (_load_arc_stage_by_index(VIDEO_FOLDER)
                           if (look_ref is not None or visual_director is not None) else {})

    def arc_stage_for(block):
        """Драматургическая стадия блока — по ИСХОДНОМУ индексу фразы.

        Ключ — orig_index (проставлен сразу после parse_blocks()), а не индекс
        главного цикла: после split_long_blocks()/merge они расходятся, и
        обращение по индексу цикла давало чужую стадию либо None. См. N4 в
        docs/AUDIT_2026-09_DEEP.md и замер на videos/01_ves-mecha: 151 слот из
        165 получал неверные данные.
        """
        return arc_stage_by_index.get(block.get("orig_index"))

    if arc_stage_by_index:
        # Честный сигнал вместо тихой деградации: если speech_plan.json собран
        # для ДРУГОЙ версии сценария, часть блоков останется без стадии, и обе
        # надстройки молча потеряют драматургический вход. Раньше это было
        # видно только пересчётом вручную.
        _covered = sum(1 for _b in blocks if _b.get("orig_index") in arc_stage_by_index)
        if _covered < len(blocks):
            print(f"  ВНИМАНИЕ: arc_stage покрывает {_covered} из {len(blocks)} блоков — "
                  f"media_plan/speech_plan.json собран для другой версии script.txt. "
                  f"Look Management/Visual Director получат None на остальных; "
                  f"перезапусти scripts/speech_planner.py.")
    # РЕАЛЬНЫЙ, найденный вживую пробел (deep-audit, videos/_test20s, слот 0
    # "Пятнадцать килограммов", прямая жалоба пользователя на атмосферность
    # отбора). domain_match_bonus() уже существует и уже подключён к
    # compute_extra_score() — но text_domain_hint(sem_text) считается ТОЛЬКО
    # по локальному тексту 1-2 соседних блоков, а короткие "числовые"/связочные
    # фразы ("Пятнадцать килограммов.") физически не содержат ни одного
    # домен-слова (battle/museum/snow/...) — сигнал молча нулевой, и бонус
    # никогда не срабатывает именно там, где короткая фраза больше всего
    # нуждается в подсказке "к какой теме она принадлежит". Живая проверка:
    # domain_match_bonus для этого блока был 0.0 на КАЖДОМ кандидате
    # (candidate_domain неважен — text_domain уже None). section_domain_hint
    # — тот же text_domain_hint(), но по ОБЪЕДИНЁННОМУ тексту всех авторских
    # (+ атмосферно обогащённых, см. атмосферное обогащение хука выше)
    # запросов секции — считается РОВНО ОДИН раз на секцию (не на кандидата
    # и не на блок), copейки по стоимости. Используется ТОЛЬКО как fallback,
    # когда у КОНКРЕТНОГО блока свой сигнал отсутствует — блок с явным
    # локальным доменом ("зал кинотеатра" -> urban/night) им не переопределяется.
    #
    # РЕАЛЬНЫЙ, найденный вживую баг в ПЕРВОЙ версии этого фикса (тот же
    # заход, до коммита): join(pool) склеивал 20-30+ запросов в одну строку
    # ДЛИННЕЕ, чем текстовый энкодер CLIP умеет принять целиком — truncation
    # обрезает её до первых ~77 токенов, и КАКОЙ ИМЕННО домен выживает после
    # обрезки зависит от порядка запросов в пуле почти случайно. Живая
    # проверка на РЕАЛЬНОМ пуле этого эпизода (26-34 запроса, три чуть
    # разных состава пула между прогонами): join-версия дала три РАЗНЫХ
    # ответа — "battle", "archive_bw", None — на семантически одном и том же
    # пуле, где явное большинство (10 из 16 классифицированных запросов)
    # реально "battle". Голосование по домену КАЖДОГО запроса ПООТДЕЛЬНОСТИ
    # (короткие строки, никогда не обрезаются) и выбор самого частого —
    # устойчиво к порядку и к 1-2 отсутствующим/новым запросам, та же
    # проверка дала "battle" стабильно на всех трёх составах пула.
    section_domain_hint = {}
    if visual_director is not None:
        for sec, pool in section_query_pool.items():
            votes = {}
            for q in pool:
                d, _ = visual_director.lr.text_domain_hint(q)
                if d:
                    votes[d] = votes.get(d, 0) + 1
            if votes:
                section_domain_hint[sec] = max(votes.items(), key=lambda kv: kv[1])[0]
    # Шотлист прошлого прогона (см. load_shotlist/shotlist_locked_media выше):
    # залоченные слоты берутся из него как есть, остальные — обычный отбор.
    prev_shotlist = load_shotlist(VIDEO_FOLDER)
    shot_entries = {}   # индекс -> запись для media_plan/shotlist.json (каждый индекс, включая кэш-хит/пропуск)
    qc_unknown_cache_hits = []   # кэш-хиты без известного исходника — QC дублей/резкости по ним не выполнялся
    shotlist_locked_used = 0
    used_photo_ids = set()   # общий на весь ролик — не даём одной фотке всплыть дважды
    used_video_ids = set()   # то же самое, отдельно для видео (разные ID-пространства)
    used_photo_hashes = []   # aHash уже отобранных фото — ловит визуальные дубли под РАЗНЫМИ ID (см. pexels_photo)
    recent_shot_sizes = []   # скользящее окно масштаба плана (wide/medium/close/detail) — см. estimate_shot_size
    recent_media_types = []   # скользящее окно фото/видео — content-aware чередование, см. main() ниже
    recent_semantic_tags = []   # скользящее окно (domain, role) уже выбранных фото И видео (VIDEO_DIRECTOR_SCORE_VERSION) — см. visual_director.repetition_penalty
    stat_count = 0   # 2.2: номер плашки по счёту в ролике -> вариант оформления (chередуются по кругу)
    luma_ema = None   # для сглаживания скачков экспозиции между соседними склейками (см. measure_luma())
    look_report = {}   # индекс -> запись решения Look Management (каждый индекс, не только там, где сработало)
    look_state = None   # аналог luma_ema — {"delta","domain","reference_id"} между клипами (см. look_reference.EMPTY_STATE)
    director_report = {}   # индекс -> {"base_winner","director_winner","diverged"} (см. visual_director_report.json)

    def mark_reports_skipped(i, reason):
        """Единая точка записи "этот индекс пропущен" сразу в ОБА отчёта
        (look_report/director_report) — раньше каждая РАННЯЯ ветка цикла
        (continue до реального рендера кадра) дублировала обе строки по
        отдельности, и реальный баг уже случался: одну из веток добавили,
        забыв продублировать вторую запись (см. коммент у cache-hit ниже) —
        индекс тихо выпадал из visual_director_report.json. Полный путь
        (реальный рендер кадра, дальше по циклу) сюда не относится: там обе
        записи разной формы и без continue между ними, дублировать нечего."""
        look_report[i] = {"decision": reason}
        director_report[i] = {"decision": reason}

    # Звуковые моменты плашек считаются ОДНИМ вызовом до цикла рендера — см.
    # plan_stat_sound_cues(). Внутри цикла им делать нечего: они не зависят ни
    # от подобранного медиа, ни от рендера, а снаружи их может позвать
    # предпросмотр звука (--audio-preview), не трогая ни одного клипа.
    typewriter_click_times, plate_sfx_cues = plan_stat_sound_cues(
        blocks, durs, sub_starts, sub_baseline)
    # HOOK_KINETIC_CAPTIONS_ENABLED=False (см. его комментарий выше) -> hook_words
    # остаётся [] на весь эпизод, ни один клип хука не получит captions — тот
    # же честный откат, что и при отсутствии alignment.csv (D2).
    hook_words = (load_hook_word_timings(blocks, sub_starts, sub_baseline, real_weights)
                  if HOOK_KINETIC_CAPTIONS_ENABLED else [])
    # P0-3: слова с аудио-шкалы (sub_starts/sub_baseline) переносятся на
    # шкалу реально показанного кадра (visual_starts/durs) — см. докстринг
    # rescale_hook_words_to_visual_time().
    hook_words = rescale_hook_words_to_visual_time(hook_words, blocks, sub_starts, sub_baseline,
                                                     visual_starts, durs)
    for i, (b, d) in enumerate(zip(blocks, durs)):
        # ПЕРЕНОС ДЛИТЕЛЬНОСТИ ОТ ПОГЛОЩЁННЫХ СЛОТОВ. Слот, которому нечего
        # честно показать, не получает своего клипа — его время достаётся
        # ЭТОМУ клипу, то есть предыдущий проверенный кадр (а точнее —
        # следующий за поглощённым) держится на экране дольше и накрывает
        # обе фразы. Забираем перенос СРАЗУ и обнуляем: у цикла несколько
        # ранних continue (кэш-хит, отсутствие медиа), и без обнуления
        # здесь один и тот же перенос ушёл бы в два клипа.
        d = d + _carry_sec
        _carry_sec = 0.0
        absorb_reason = None
        # Титр темы — только на ПЕРВОМ кадре новой секции (BLOCK N: Название).
        is_section_start = i == 0 or blocks[i]["section"] != blocks[i - 1]["section"]
        title = section_title(b["section"]) if is_section_start else None
        stat = b.get("stat")
        if not ON_SCREEN_TEXT_ENABLED:
            title, stat = None, None
        stat_variant = stat_count
        # D2: кинетические подписи — только ХУК, только если alignment.csv
        # реально дал слова на эту секцию. hook_words уже пересчитаны в
        # ВИЗУАЛЬНУЮ шкалу (rescale_hook_words_to_visual_time, P0-3) —
        # поэтому здесь тоже visual_starts[i]/d (реальный старт/длительность
        # ЭТОГО клипа на шкале монтажа), а не sub_starts/sub_baseline
        # (аудио-шкала — она бы совпала с визуальной только без "очелове-
        # чивающих" сдвигов durs, см. apply_within_cut_shift и соседей).
        captions = (hook_captions_for_block(hook_words, visual_starts[i], d)
                    if (hook_words and b["section"].startswith("HOOK")) else None)
        if stat:
            stat_count += 1
        # Момент внутри клипа, когда число уже произнесено (см. stat_word_pos
        # в parse_blocks/split_long_blocks) — доля слов ДО тега [stat:...] от
        # общего числа слов В ЭТОМ куске, умноженная на его финальную
        # длительность. Та же word-count-пропорция, что уже используется как
        # честный фоллбэк тайминга по всему пайплайну (не выдумываем более
        # точную модель специально под этот случай).
        stat_word_pos = b.get("stat_word_pos")
        stat_delay = (stat_word_pos / max(1, b["words"]) * d) if (stat and stat_word_pos) else 0.0
        # D4: печатная машинка — только на 5-м варианте плашки (см. add_overlays).
        # Таймкоды щелчков считаем на РЕАЛЬНОЙ (не xfade-раздутой) шкале —
        # sub_starts/sub_baseline уже посчитаны выше по тексту, та же шкала,
        # что уже используется для субтитров (см. комментарий у sub_baseline).
        # Хэш параметров рендера в имени — иначе правка script.txt (текст,
        # тайминг, плашка) без ручной чистки temp_smart/ молча оставляла
        # старый клип под новые данные (тот же класс бага, что уже правили
        # для pexels_cache). Запрос (queries[i]) обязателен в хэше отдельно —
        # без него правка channel_themes.json/media_plan/themes.json при
        # совпавшей длительности тихо оставляла старый (уже нерелевантный)
        # клип под новым запросом — поймано QC-сверкой вживую: клип с новым
        # запросом "medieval sword close up" продолжал показывать старую
        # киноплёнку, потому что длительность/заголовок/плашка/секция не
        # изменились, а запрос в хэш не входил.
        # captions в хэше — D2, чтобы правка/пересчёт alignment.csv не
        # оставляла старые (без подписей или с другим текстом/таймингом)
        # закэшированные клипы висеть под тем же именем.
        # look_cache_sig — Reference-Guided Look Management (см.
        # _look_management_cache_signature()) — грубая, но безопасная
        # инвалидация всех клипов разом при смене lookbook.json/флага.
        # domain_cache_sig — та же грубая инвалидация для DOMAIN_GRADE_MODE/
        # DOMAIN_WARM_PUSH_SCALE (см. _domain_grade_cache_signature(), П.4) —
        # отдельная от Look Management модуляция, отдельная сигнатура.
        # director_cache_sig — РЕАЛЬНЫЙ баг, найден внешним форензик-аудитом
        # (P1-4): раньше params_hash не содержал НИЧЕГО про
        # VISUAL_DIRECTOR_MODE, поэтому off -> assist на уже отрендеренном
        # эпизоде не инвалидировал кэш — см. _visual_director_cache_signature().
        # arc_stage этого КОНКРЕТНОГО блока — тот же класс бага, если его не
        # включить: сгенерировать/пересчитать speech_plan.json ПОСЛЕ первого
        # рендера (или наоборот, удалить его) молча оставило бы старые
        # кэшированные клипы под именем, которое больше не отражает реальный
        # arc_stage, использованный при их рендере (Look Management/Visual
        # Director получили бы другую силу/бонус на пересчёте, а кэш этого
        # бы не заметил).
        # Залоченный шотлистом файл — часть ключа кэша клипа (см.
        # shotlist_lock_key): смена файла в shotlist.json обязана
        # перерендерить этот клип, а снятие lock — вернуть прежний ключ.
        lock_photo, lock_video = shotlist_locked_media(prev_shotlist, i, b["text"], VIDEO_FOLDER)
        lock_key = shotlist_lock_key(lock_photo, lock_video)
        # VLM-арбитр — ТОТ ЖЕ класс бага, что director_cache_sig выше, найден
        # состязательным аудитом собственной правки (03.09, сразу после того,
        # как дефолт VLM_ARBITER_MODE был приведён к документации и стал "on"):
        # арбитр реально меняет ВЫБОР кадра для хук-слотов, но params_hash про
        # него не знал ничего — на эпизоде с прогретым temp_smart/ клип берётся
        # из кэша по `os.path.exists(out) -> continue` ДО того, как вызывается
        # pexels_photo(..., arbiter_text=...), то есть включение арбитра было бы
        # молчаливым no-op, а оператор считал бы, что кадры хука выбраны им.
        # Сегмент добавляется ТОЛЬКО для HOOK-секций (arbiter_text передаётся
        # только им, см. main()) и ТОЛЬКО при mode=="on", причём отдельной
        # конкатенацией, а не ещё одним полем в f-строке: при выключенном
        # арбитре ключ обязан остаться байт-в-байт прежним, иначе сама эта
        # правка перерендерила бы весь кэш у всех. При включённом — меняются
        # только хук-клипы (единицы процентов эпизода), и это правильно: их
        # выбор кадра действительно мог стать другим.
        # candidate_gate_signature() — правила ОТБОРА кандидата. Реальный,
        # найденный 04.09 остаток Фазы 0: подпись отбора влияла только на
        # ИМЯ файла в pexels_cache, а ключ клипа её не содержал — и кэш-хит
        # клипа (ниже) делает continue ДО того, как кандидат вообще
        # переподбирается. Следствие: ужесточение гвардов, расширение
        # блоклиста или смена размера пула на прогретом temp_smart/ не
        # доходили до экрана вообще: клип брался готовым, собранный по
        # старым правилам. Честная цена этой строки — первый прогон после
        # правки правил отбора перерендеривает эпизод целиком. Это и есть
        # смысл: иначе правка правил отбора — просто запись в исходнике.
        cache_key = (
            f"{d:.3f}|{title}|{stat}|{stat_variant}|{b['section']}|{queries[i]}|{stat_delay:.3f}|"
            f"{captions}|{look_cache_sig}|{domain_cache_sig}|{director_cache_sig}|"
            f"{arc_stage_for(b)}|{recipe_sig}|{lock_key}|{candidate_gate_signature(i)}")
        cache_key += arbiter_cache_suffix(b["section"])
        params_hash = hashlib.md5(cache_key.encode()).hexdigest()[:8]
        out = os.path.join(TEMP_FOLDER, f"clip_{i:04d}_{params_hash}.mp4")
        if os.path.exists(out) and not verify_clip(out, d)[0]:
            # Кэш раньше доверял голому os.path.exists() — обрезанный/битый
            # клип от прошлого убитого прогона (SIGKILL/OOM ровно так уже
            # падал многочасовой рендер, см. render_tmp_path()) молча
            # принимался бы за готовый на следующем запуске. Теперь огрызок
            # чистится и падает в обычный (не кэш-хит) путь ниже — само-
            # исцеляется повторным рендером вместо того, чтобы либо портить
            # ролик, либо требовать ручной чистки temp_smart/.
            print(f"  [{i+1}] кэш битый (не прошёл verify_clip), перерендерю")
            try:
                os.remove(out)
            except OSError:
                pass
        if os.path.exists(out):
            # РЕАЛЬНЫЙ баг, пойманный вживую: раньше кэш-хит уходил в clips
            # СРАЗУ здесь, по ходу цикла, а промах кэша (ниже) — только В
            # pending_jobs, с append в clips ОТДЕЛЬНЫМ проходом ПОСЛЕ конца
            # всего цикла. Пока хэш параметров у блока не меняется — разницы
            # не видно, но стоило хэшу измениться у ОДНОЙ группы блоков
            # (здесь — у всего ХУКА разом, после правки D2-таймингов) — их
            # кэш-хиты соседних секций уходили в clips ПЕРВЫМИ по ходу цикла,
            # а сам хук (сплошь кэш-промахи) — единым блоком В КОНЕЦ, уже
            # после resolve-прохода. Итог на реальном ролике: хук отрендерился
            # верно, но склейка voed поставила его в самый хвост ролика, а
            # титр BLOCK 1 оказался в первых секундах. Фикс: кэш-хит идёт
            # ТЕМ ЖЕ путём (pending_jobs, future=None, ok сразу True) — единый
            # проход ниже строит clips строго по порядку индекса блока
            # независимо от того, кэш это или свежий рендер.
            pending_jobs.append({"i": i, "out": out, "d": d, "section": b["section"], "block": b,
                                  "video": False, "photo": None, "future": None, "ok": True})
            # Look Management/Semantic Visual Director не могут проанализировать
            # кэш-хит — нет сохранённого пути к исходному фото/свежих levels/wb
            # на этот прогон (см. ЗАМЕТКУ про shadow в look_reference.py).
            # Честная запись в ОБА отчёта (см. mark_reports_skipped() выше —
            # именно на этой ветке однажды реально забыли продублировать
            # вторую запись), не тишина — иначе shadow/director-отчёт на уже
            # отрендеренном эпизоде выглядел бы полным, хотя ничего не
            # проанализировано.
            mark_reports_skipped(i, "skipped_cache_hit")
            # Кэш-хит не знает, из какого файла сделан клип — переносим
            # запись из прошлого шотлиста (если фраза та же), иначе честно
            # пишем, что файл неизвестен, а не выдумываем.
            prev_shot = shotlist_shot(prev_shotlist, i)
            if lock_photo or lock_video:
                shotlist_locked_used += 1
            if prev_shot and _shotlist_norm_text(prev_shot.get("text")) == _shotlist_norm_text(b["text"]):
                shot_entries[i] = {"index": i, "section": b["section"], "text": b["text"], "query": queries[i],
                                   "kind": prev_shot.get("kind"), "file": prev_shot.get("file"),
                                   "source": "shotlist_lock" if (lock_photo or lock_video) else "cache_hit",
                                   "clip": os.path.basename(out),
                                   **shotlist_provenance(
                                       shotlist_resolve_file(prev_shot.get("file"), VIDEO_FOLDER))}
                # QC дублей (qc_report) считается по media_log — раньше кэш-хит
                # в него не попадал вообще (аудит 04.09: 9 из 18 слотов
                # байт-идентичны, отчёт пуст). Файл известен из шотлиста.
                prev_file = shotlist_resolve_file(prev_shot.get("file"), VIDEO_FOLDER)
                if prev_shot.get("kind") == "photo" and prev_file and os.path.exists(prev_file):
                    media_log.append((i, prev_file))
                else:
                    qc_unknown_cache_hits.append(i + 1)
                # РЕАЛЬНЫЙ дубль в опубликованном эпизоде (04.09): одна и та же
                # фотография (Pexels 31474665) стоит на 58-й секунде и на 11-й
                # минуте. Причина ровно здесь: при кэш-хите КЛИПА функция
                # подбора не вызывается вообще, поэтому кадр этого слота не
                # попадал ни в used_photo_ids, ни в used_photo_hashes — а на
                # частичном ре-рендере (161 кэш-хит из 165) структуры дедупа
                # оставались почти пустыми, и любой заново подбираемый слот
                # спокойно брал уже стоящий в ролике кадр. Возвращаем кадр в
                # дедуп по файлу из шотлиста: анти-дубль снова видит ВЕСЬ
                # эпизод, а не только пересобранные в этом прогоне слоты.
                if prev_file and os.path.exists(prev_file):
                    _cached = new_attempt(i, "clip_cache")
                    with selection_attempt.activate(_cached):
                        register_cached_media(
                            prev_file, used_ids=(used_photo_ids if prev_shot.get("kind") == "photo"
                                                 else used_video_ids),
                            used_hashes=used_photo_hashes,
                            kind=(prev_shot.get("kind") or "photo"))
                    close_slot(i, [_cached], shown=_cached, decisive=_cached,
                               outcome="clip_cache_hit")
            else:
                qc_unknown_cache_hits.append(i + 1)
                shot_entries[i] = {"index": i, "section": b["section"], "text": b["text"], "query": queries[i],
                                   "kind": None, "file": None, "source": "cache_hit_unknown_file",
                                   "clip": os.path.basename(out)}
            continue
        # Досюда доходят ТОЛЬКО слоты, которые в этом прогоне реально проходят
        # подбор медиа (кэш-хит клипа уже ушёл по continue выше). Именно про
        # них — и только про них — текущий прогон вправе что-то утверждать в
        # отчётах; см. merge_slot_report().
        RESOLVED_SLOTS_THIS_RUN.add(i)
        # Все попытки этого слота. Решение о слоте закрывает их разом в
        # close_slot(): одна принимается, остальные — отказом.
        slot_attempts = []
        request = None
        # Откуда взялся текущий кандидат на экран: "fetch" — из попытки
        # отбора (slot_attempts), иначе "locked"/"local"/"card" — такой файл
        # встаёт на экран тем же коммитом, через попытку-носитель
        # (given_attempt).
        media_origin = None
        locked_shot = bool(lock_photo or lock_video)
        if locked_shot:
            # Шотлист решил за нас — ни Pexels, ни гейтов, ни локального
            # перебора: ровно тот файл, который человек проверил и залочил.
            photo, video = lock_photo, lock_video
            media_origin = "locked"
            shotlist_locked_used += 1
        else:
            photo = local_photo(i) if use_local else None
            # Машинный сток Шага 4 проходит ТОТ ЖЕ relevance-гейт, что и
            # кандидат Pexels (см. local_file_is_machine_stock). Не прошёл —
            # слот идёт обычным путём отбора ниже, как будто локального файла
            # не было: пустым он не останется, там полный стек источников и
            # лестница фолбэков. is_relevant_candidate() fail-open при
            # недоступном CLIP (возвращает True) — без torch поведение
            # прежнее байт-в-байт.
            if (photo and feature_flags.enabled("LOCAL_STOCK_GATE")
                    and local_file_is_machine_stock(photo)):
                try:
                    _stock_ok = is_relevant_candidate(photo, queries[i])
                except Exception:
                    _stock_ok = True
                if not _stock_ok:
                    print(f"    [{i+1}] media/{os.path.basename(photo)} не прошёл "
                          f"relevance-гейт по запросу {queries[i]!r} — слот идёт обычным отбором")
                    LOCAL_STOCK_GATE_REJECTED.append(
                        {"index": i, "file": os.path.basename(photo), "query": queries[i]})
                    photo = None
            video = None
            if photo:
                media_origin = "local"
        # Semantic Visual Director — role/text_domain/director_score_fn
        # существуют для этой итерации независимо от того, каким путём в
        # итоге получено медиа (используются ниже при записи director_report),
        # но САМИ СЧИТАЮТСЯ (text_domain_hint — CLIP-вызов) ТОЛЬКО когда
        # реально есть шанс дойти до pexels_photo() — местный photo уже
        # решённый блок (use_local) сюда вообще не заходит, счёт впустую не
        # тратим (см. докстринг visual_director.py про cost-tradeoff).
        director_role = None
        director_text_domain = None
        director_score_fn = None
        director_entry = None
        director_assist = visual_director is not None and visual_director.VISUAL_DIRECTOR_MODE == "assist"
        # is_opening — САМЫЙ ПЕРВЫЙ блок всего эпизода (i==0, HOOK по
        # построению сценария) — см. OPENING_AESTHETIC_WEIGHT в
        # visual_director.py и is_opening в arbitrate_hook_candidates.
        # Реальная жалоба пользователя (/goal, 29 августа): "самое
        # начало... нужно самый красивый впечатляющий кадр для наивысшего
        # удержания" — работает ДАЖЕ без VLM-арбитра/Gemini (см. её
        # блок-комментарий), т.к. решает сам base/director выбор.
        is_opening_shot = (i == 0)
        # РЕАЛЬНЫЙ, найденный вживую катастрофический баг (11.09, эпизод 02):
        # `use_pexels` — по имени "есть ли Pexels", а по факту единственный
        # гейт на вызов pexels_photo()/pexels_video() ЦЕЛИКОМ — а внутри них
        # теперь ещё музеи (museum_sources), архивы (Openverse) и VLM-арбитр,
        # ни один из которых от Pexels не зависит. Живой прогон: Pexels
        # отдал 500 шесть раз подряд (внешний сбой, не наш баг),
        # _note_pexels_failure() честно взвела PEXELS_BROKEN — и ЕЁ ЖЕ
        # докстрин обещает "одиночная ошибка стоит одному слоту, не эпизоду".
        # Обещание нарушалось этой строкой: `use_pexels=False` гасило поиск
        # НАВСЕГДА для всех оставшихся слотов эпизода — 215 из 219 слотов
        # получили "no_media_at_all" и текстовую карточку, хотя музеи и
        # архивы в этот момент были живы и отвечали (лог: десятки успешных
        # "Архивы: ... (20 канд.)" ДО обрыва, ни одной строки после — поиск
        # просто перестал вызываться). Сама функция _pexels_search_photos()
        # безопасно fail-open на каждый вызов (одна неудача = пустой список
        # для ЭТОГО источника в ЭТОМ запросе), внешний круг не нужен.
        if not photo and not video:
            # Смысловая оценка кадра-пробника ВИДЕО против полной фразы —
            # раньше видео-путь такой оценки не имел вообще (только фото),
            # и видео-слот молча оставался на позиционно доставшемся
            # запросе: на реальном рендере фраза "сколько весил настоящий
            # боевой меч" получила зал кинотеатра.
            #
            # VIDEO_DIRECTOR_SCORE_VERSION (08.09): video_sentence_fn — ТОТ
            # ЖЕ director_score_fn, что уходит фото, не голый
            # sentence_relevance(). Раньше видео получало только смысловую
            # релевантность фразы и не участвовало вообще в arc_stage-
            # осознанной крупности плана, совпадении домена и анти-повторе,
            # хотя это примерно половина слотов эпизода. compute_extra_score()
            # уже принимает candidate_query/aesthetic_val как опциональные
            # keyword (по умолчанию None) — вызов sentence_score_fn(probe)
            # одним позиционным аргументом (см. pexels_video()) по-прежнему
            # валиден, просто без её собственных SAME_QUERY_BONUS/
            # opening-бонусов, которые видео-путь и так добавляет вручную
            # ниже (см. SAME_QUERY_BONUS/OPENING_AESTHETIC_WEIGHT в
            # pexels_video()) — двойного счёта нет.
            sem_text = semantic_context_text(blocks, i)
            video_sentence_fn = None
            if visual_director is not None:
                director_role = visual_director.functional_role(b, is_section_start)
                director_text_domain, _ = visual_director.lr.text_domain_hint(sem_text)
                if director_text_domain is None:
                    director_text_domain = section_domain_hint.get(b["section"])
                director_score_fn = functools.partial(
                    visual_director.compute_extra_score, role=director_role, block_text=sem_text,
                    text_domain=director_text_domain, recent_semantic_tags=recent_semantic_tags,
                    arc_stage=arc_stage_for(b), own_query=queries[i], is_opening=is_opening_shot)
                director_entry = {}
                video_sentence_fn = director_score_fn
            # Content-aware чередование вместо механического i%2 (ЧАСТЬ 14
            # раньше просто нечётные->фото/чётные->видео) — зритель
            # подсознательно считывает такую периодичность. Видео заказываем,
            # когда текст блока реально описывает действие/движение
            # (ACTION_WORDS — "штурм"/"погоня"/"удар" и т.п., там сток-видео
            # осмысленно показывает движение), плюс детерминированный хэш
            # текста как база для обычного визуального разнообразия (иначе
            # почти весь ролик без экшн-лексики ушёл бы в чистое фото).
            # Никогда видео под цифру-плашку — движущийся фон мешает читать
            # число (см. static_hold в choose_motion_mode — тот же принцип
            # для фото, но video_render своей motion_mode-ветки не имеет).
            # Не встык 2 видео подряд (видео — акцент, не фон) и не больше
            # 3 фото подряд (иначе монотонно) — то же разнообразие, что уже
            # держат zoom_hist/pan_hist через pick_no_repeat, но асимметрично
            # (видео реже, чем фото, по самой природе приёма).
            spec = b.get("shot_spec")
            if spec and not stat:
                # Спецификация фразы (stock_query_planner v3) знает, требует
                # ли главное движения. Обязательное движение — первым
                # добывается вид, который может его показать. Иначе вид
                # решает ритм по недавним видам (без словаря и хэша); смысл
                # всё равно решает сравнение видов ниже, ритм лишь выбирает,
                # с чего начать.
                import stock_query_planner
                if stock_query_planner.has_motion(spec, must=True):
                    want_video = True
                else:
                    want_video = (recent_media_types[-1:] != ["video"]
                                  and len(recent_media_types) >= 3
                                  and all(t == "photo" for t in recent_media_types[-3:]))
            else:
                h_text = int(hashlib.md5(b["text"][:40].encode()).hexdigest()[:8], 16)
                want_video = (has_action_word(b["text"]) or h_text % 2 == 1) and not stat
                if want_video and recent_media_types[-1:] == ["video"]:
                    want_video = False
                if (not want_video and not stat and len(recent_media_types) >= 3
                        and all(t == "photo" for t in recent_media_types[-3:])):
                    want_video = True
            prefer_video = want_video and d >= MIN_CLIP + 1.0
            act_qual = action_video_qualifier(b["text"])
            # VLM-арбитр — ТОЛЬКО хук (см. shot_director.arbitrate_hook_
            # candidates, HOOK-only-скоуп объявлен пользователю явно, не
            # скрытый компромисс: свободный тариф Gemini не выдержал бы
            # арбитраж на весь эпизод, см. её блок-комментарий). Реальный,
            # НЕ дополненный соседями текст блока (в отличие от sem_text) —
            # VLM понимает короткую фразу саму по себе.
            hook_arbiter_text = b["text"] if b["section"].startswith("HOOK") else None
            # ОДИН запрос на слот — для всех его попыток, включая спасение
            # фотографией ниже. Раньше каждая попытка перечисляла аргументы
            # заново, и спасающий вызов годами шёл без брифа фразы
            # (shot_brief/block_text): в эпизоде 94 так искались 5 слотов из 8.
            PEXELS_QUOTA_RESERVE = 2 * (len(blocks) - i)
            request = build_slot_request(
                index=i, query=queries[i],
                extra_queries=slot_extra_queries(b, section_query_pool.get(b["section"])),
                text_key=sem_text, shot_brief=b.get("shot_brief"), block_text=b["text"],
                shot_spec=b.get("shot_spec"),
                arbiter_text=hook_arbiter_text, is_opening=is_opening_shot,
                slot_dur=d, action_qualifier=act_qual, target_luma=luma_ema,
                director_score_fn=director_score_fn, director_assist=director_assist,
                director_report=director_entry, video_score_fn=video_sentence_fn,
                used_photo_ids=used_photo_ids, used_video_ids=used_video_ids,
                used_hashes=used_photo_hashes, recent_sizes=recent_shot_sizes)
            if prefer_video:
                video = fetch_in_attempt(slot_attempts, i, "video", select_media, request, "video")
                if not video:
                    photo = fetch_in_attempt(slot_attempts, i, "photo", select_media, request, "photo")
            else:
                photo = fetch_in_attempt(slot_attempts, i, "photo", select_media, request, "photo")
                if not photo and d >= MIN_CLIP + 1.0:
                    video = fetch_in_attempt(slot_attempts, i, "video", select_media, request, "video")
            # ФОТО ИЛИ ВИДЕО — ПО ОЦЕНКЕ СУДЬИ. Первый вид выбран правилом
            # выше (действие во фразе, ритм), но это догадка по тексту: какой
            # кадр лучше показывает фразу, знает только тот, кто на кадры
            # посмотрел. Живой случай (эпизод 94, слот 7): фото встало лишь
            # потому, что все видео провалили проверки. Второй вид добывается,
            # только если первый не получил высшую оценку — при высшей второй
            # может лишь сравняться, а ничью решает то же правило вида.
            # Под плашкой с цифрой видео не бывает (движущийся фон мешает
            # читать число), короткому слоту видео не хватает длины.
            import shot_judge
            first_att = attempt_of(slot_attempts, photo or video)
            first_score = (first_att.notes.get("quality") or first_att.notes.get("judge_score")) \
                if first_att else None
            first_kind = "video" if video else "photo"
            other_kind = "photo" if video else "video"
            # Второй вид уже добывался в этом слоте (первый не дал кадра, и
            # слот перешёл к нему) — повтор дал бы тот же отказ.
            other_tried = any(a.kind == other_kind for a in slot_attempts)
            if (shot_judge_active(i) and not stat and d >= MIN_CLIP + 1.0 and not other_tried
                    and first_score is not None and not quality_perfect(_as_quality(first_score))):
                other = fetch_in_attempt(slot_attempts, i, other_kind, select_media, request, other_kind)
                if other:
                    other_att = attempt_of(slot_attempts, other)
                    other_score = (other_att.notes.get("quality") or other_att.notes.get("judge_score")) \
                        if other_att else None
                    kind = pick_kind_by_judge(first_kind, first_score, other_score, prefer_video)
                    print(f"    [{i+1}] {first_kind} {first_score} против {other_kind} "
                          f"{other_score if other_score is not None else '—'} -> {kind}")
                    if kind == other_kind:
                        photo, video = (other, None) if other_kind == "photo" else (None, other)
            # Вторая страница каскада (см. CASCADE_PAGE): кадра нет или он
            # известен как брак — фото ищется среди следующих кандидатов.
            cur_att = attempt_of(slot_attempts, photo or video)
            if (shot_judge_active(i) and not locked_shot
                    and (cur_att is None or known_bad_reason(cur_att.verdicts))):
                with cascade_page(1):
                    page2 = fetch_in_attempt(slot_attempts, i, "photo", select_media, request, "photo")
                page2_att = attempt_of(slot_attempts, page2)
                if page2 and page2_att is not None and not known_bad_reason(page2_att.verdicts):
                    print(f"    [{i+1}] кадр найден на второй странице каскада")
                    photo, video = page2, None
            # Раньше Pexels отключался навсегда после ЛЮБОГО промаха, включая
            # обычную пустую выдачу по одному неудачному запросу. Гасим источник
            # только если API реально отвалился.
            if not photo and not video and PEXELS_BROKEN:
                use_pexels = False
            if photo or video:
                media_origin = "fetch"
        # ЛЕСТНИЦА ФОЛБЭКОВ, уровень «не может быть неверным» (см.
        # known_bad_reason/fallback_card.py). Слот заполнен, но система
        # САМА только что записала, что кадр негодный: арбитр отказал, сток
        # исчерпан или победитель ниже порога релевантности. Раньше это
        # оставалось строчкой в отчёте, а зрителю показывали «лучшего из
        # плохих» — так в опубликованный эпизод попали и младенец с
        # бутылочкой, и улица Барселоны с туристом.
        # СТУПЕНЬ «ВИДЕО -> ФОТО». Измерено на эпизоде 02 (10.09): среди
        # видео-слотов брак 63% (41 из 65), среди фото — 23% (35 из 154).
        # Причина структурная: видео-корпус Pexels на исторические темы
        # тоньше фото-корпуса, а музейные API (где эпоха предмета известна из
        # паспорта, см. museum_sources.py) видео не отдают вообще. Поэтому
        # там, где система САМА записала, что видео негодное, честнее взять
        # фотографию — подлинный кинжал 1450 года с медленным зумом сильнее и
        # мусорного видео, и текстовой карточки. Пробуем ДО карточки: карточка
        # остаётся последним уровнем, а не первым.
        video_att = attempt_of(slot_attempts, video)
        if (video and not photo and not locked_shot
                and feature_flags.enabled("VIDEO_PHOTO_RESCUE")
                # Фото уже добывалось и проиграло видео по оценке судьи —
                # повторная добыча дала бы тот же проигравший кадр.
                and not any(a.kind == "photo" and a.media for a in slot_attempts)
                and video_att is not None and known_bad_reason(video_att.verdicts)):
            # Вердикты отвергнутого видео принадлежат ЕГО попытке: снимать и
            # возвращать их не нужно — правдой о слоте станут вердикты той
            # попытки, чей кадр встанет на экран (close_slot).
            rescue = fetch_in_attempt(slot_attempts, i, "photo", select_media, request, "photo")
            if rescue:
                reason = ", ".join(sorted({k for k, _rec in effective_verdicts(video_att.verdicts)}))
                print(f"    [{i+1}] негодное видео заменено фотографией ({reason})")
                VIDEO_RESCUED_BY_PHOTO.append(
                    {"index": i, "reason": reason, "query": queries[i]})
                photo, video = rescue, None
        # Попытка, чей кадр сейчас кандидат на экран, — она и решает судьбу
        # слота. У локального/залоченного файла попытки отбора нет.
        decisive_att = attempt_of(slot_attempts, photo or video)
        if (photo or video) and not locked_shot:
            bad_reason = known_bad_reason(decisive_att.verdicts) if decisive_att else None
            if bad_reason and not never_show_known_bad:
                if fallback_card_allowed(i, len(blocks), is_opening=is_opening_shot):
                    card = build_slot_fallback_card(i, b["text"], bad_reason)
                    if card:
                        photo, video = card, None
                        media_origin = "card"
            elif bad_reason:
                # «ЛУЧШИЙ ИЗ ПЛОХИХ» УДАЛЁН КАК ИСХОД. Система только что
                # сама записала, что этот кадр негодный (арбитр отказал,
                # сток исчерпан, победитель ниже порога релевантности) —
                # значит он НЕ идёт на экран. Ни карточкой, ни повтором:
                # слот поглощается соседним проверенным кадром (решение
                # владельца, 17.09). Замер, ради которого это сделано: по
                # золотому набору эпизода 01 ровно так в опубликованный
                # ролик попали 8 браков из 17 — гейты знали правильный
                # ответ и не имели чем воспользоваться.
                photo, video = None, None
                absorb_reason = bad_reason
        if not photo and not video and not never_show_known_bad:
            # Прежнее поведение (флаг снят): последняя попытка — локальная
            # папка ПО КРУГУ. Повтор картинки хуже свежего кадра, но лучше
            # пропущенного блока. При включённом флаге повтор запрещён: по
            # золотому набору `duplicate` — такой же брак, как анахронизм,
            # а продление соседа не создаёт ни дубля, ни несоответствия.
            photo = local_photo(i, allow_cycle=True)
            if photo:
                media_origin = "local"
        if not photo and not video and not never_show_known_bad:
            # Медиа нет вообще. Раньше блок просто выпадал из ролика (а при
            # RENDER_STRICT_GATE=1 — останавливал всю сборку). Карточка здесь
            # сильнее любого повтора: она про эту самую фразу.
            card = build_slot_fallback_card(i, b["text"], FALLBACK_NO_MEDIA_REASON)
            if card:
                photo = card
                media_origin = "card"
        if not photo and not video and never_show_known_bad:
            # Поглощение: слот не получает клипа, его время уходит соседу.
            # Плашка с цифрой — КОНТЕНТ, а не картинка: она наследуется
            # поглощающим клипом ниже (stat_carry), а не теряется.
            reason = absorb_reason or FALLBACK_NO_MEDIA_REASON
            # Ни одна попытка не принята: ни резерва, ни файла в кэше. В
            # отчёт слота идут вердикты отвергнутого кадра, а если кадра не
            # было вовсе — вердикты всех попыток (почему пусто).
            close_slot(i, slot_attempts, shown=None,
                       decisive=decisive_att if absorb_reason else None,
                       outcome="absorbed")
            ABSORBED_SLOTS.append({"index": i, "reason": reason,
                                   "text": b["text"], "carried_sec": round(d, 3)})
            if stat:
                stat_carry.append((stat, stat_variant, stat_delay))
            _carry_sec = d
            print(f"    [{i+1}] нет проверенного кадра ({reason}) — "
                  f"{d:.1f}с отдано соседнему кадру")
            render_manifest[i] = {"index": i, "status": "absorbed",
                                   "reason": reason, "section": b["section"],
                                   "duration": d}
            mark_reports_skipped(i, "absorbed_into_neighbour")
            shot_entries[i] = {"index": i, "section": b["section"], "text": b["text"],
                               "query": queries[i], "kind": None, "file": None,
                               "source": "absorbed", "clip": None}
            continue
        if not photo and not video:
            close_slot(i, slot_attempts, shown=None, decisive=None, outcome="missing")
            print(f"  [{i+1}] нет медиа")
            missing.append(i + 1)
            render_manifest[i] = {"index": i, "status": "failed",
                                   "reason": "нет медиа (ни фото, ни видео)", "section": b["section"]}
            mark_reports_skipped(i, "skipped_no_media")
            shot_entries[i] = {"index": i, "section": b["section"], "text": b["text"], "query": queries[i],
                               "kind": None, "file": None, "source": "missing", "clip": None}
            continue
        if stat_carry and not stat:
            # Цифра поглощённого слота переезжает сюда. Задержка берётся
            # ИСХОДНАЯ: поглощённая фраза звучит в начале объединённого
            # клипа (клип начинается там, где начинался поглощённый слот),
            # поэтому её момент появления на экране не сдвигается.
            stat, stat_variant, stat_delay = stat_carry.pop(0)
            print(f"    [{i+1}] плашка «{stat}» перенесена с поглощённого слота")
        elif stat_carry:
            # У этого клипа своя цифра — двух плашек на один клип add_overlays
            # не рисует. Говорим вслух, что именно потеряно, а не молчим.
            lost = [t for t, _v, _d in stat_carry]
            print(f"    ВНИМАНИЕ: [{i+1}] уже несёт свою плашку, "
                  f"не перенесены: {lost}")
            stat_carry.clear()
        # Попытка, которая понесёт этот кадр на экран. У кадра из отбора она
        # уже есть; локальный, залоченный файл или карточка получают
        # попытку-носитель — на экран всё встаёт одним и тем же коммитом.
        if media_origin == "fetch":
            shown_att = attempt_of(slot_attempts, photo or video)
        else:
            shown_att = given_attempt(slot_attempts, i, media_origin, photo or video)
        # Крупность плана пополнялась только внутри pexels_photo() — локальные и
        # залоченные фото (каждый AI-слот протокола) в окно не попадали, и
        # choose_motion_mode получал крупность ЧУЖОГО кадра (аудит 04.09).
        if photo and (locked_shot or photo.startswith(MEDIA_FOLDER)):
            try:
                shown_att.effect("shot_size", recent_shot_sizes, estimate_shot_size(photo))
            except Exception:
                pass
        # Semantic Visual Director — аудит-трейл + скользящее окно
        # (domain, role) для repetition_penalty. director_entry.get(
        # "base_winner") — надёжный маркер того, что pexels_photo() реально
        # дошёл до цикла скачивания/ранжирования (не кэш-хит, не local_photo,
        # не video) — см. комментарий про director_entry=None по умолчанию
        # выше. Домен победившего кадра считается ЗАНОВО, отдельным вызовом
        # candidate_domain_for() на уже выбранном файле (не переносится из
        # pexels_photo через report) — так pexels_photo остаётся семантически
        # "не знающим", что такое домен, только считает extra_score.
        if visual_director is None:
            director_report[i] = {"decision": "skipped_disabled"}
        elif video:
            director_report[i] = {"decision": "skipped_video"}
            # DIRECTOR_RELEVANCE_MISSES для ВИДЕО — реальный, найденный вживую
            # пробел (27 августа, videos/_test20s, слот 7): фото-путь получил
            # свой пол релевантности выше, видео-путь — нет (эта ветка раньше
            # заканчивалась одной строкой "skipped_video"). На практике сам
            # гейт резкости кандидата (video_sharpness_ok в pexels_video())
            # может отсеять ВСЕ кандидаты правильной по смыслу темы (сток
            # "мужчина заносит клинок" почти всегда с motion-blur) и оставить
            # победителем видео из ДРУГОГО запроса общего пула секции (общая
            # гантель для текста про занесённый клинок) — семантически
            # проверить и это тоже, тем же порогом и тем же методом, что и
            # фото (кадр-пробник + sentence_relevance), а не молчать.
            probe, cleanup = extract_video_probe_frame(video)
            if probe is not None:
                try:
                    director_rel = visual_director.sentence_relevance(probe, sem_text)
                    # recent_semantic_tags — то же скользящее окно (domain,
                    # role) для repetition_penalty, что фото-победители
                    # пополняют в ветке ниже (см. её комментарий). ДО
                    # VIDEO_DIRECTOR_SCORE_VERSION видео вообще не участвовало
                    # в этом сигнале ни как кандидат, ни как история — теперь,
                    # когда pexels_video() САМА штрафует повтор через тот же
                    # compute_extra_score(), история обязана видеть и
                    # видео-победителей тоже, иначе два видео подряд в одном
                    # домене/роли не считаются повтором вообще.
                    candidate_domain = visual_director.candidate_domain_for(probe)
                    shown_att.effect("history", recent_semantic_tags,
                                     (candidate_domain, director_role),
                                     visual_director.REPETITION_WINDOW)
                    # recent_shot_sizes — тот же принцип: pexels_video() теперь
                    # штрафует повтор крупности через recent_sizes (см.
                    # shot_size_ok в pexels_video()), а история пополнялась
                    # только фото-победителями (см. ветку ниже). Без этого два
                    # видео одной крупности подряд не считались бы повтором.
                    try:
                        shown_att.effect("shot_size", recent_shot_sizes, estimate_shot_size(probe))
                    except Exception:
                        pass
                finally:
                    if cleanup and os.path.exists(probe):
                        os.remove(probe)
                if director_rel is not None and director_rel < visual_director.DIRECTOR_RELEVANCE_FLOOR:
                    shown_att.verdict("director", {
                        "index": i, "text": sem_text, "photo": shown_att.final_path(video), "kind": "video",
                        "relevance": director_rel, "threshold": visual_director.DIRECTOR_RELEVANCE_FLOOR,
                    })
        elif director_entry is None or director_entry.get("base_winner") is None:
            director_report[i] = {"decision": "skipped_not_scored"}
        else:
            director_entry["decision"] = "scored"
            director_entry["role"] = director_role
            director_entry["text_domain"] = director_text_domain
            director_report[i] = director_entry
            candidate_domain = visual_director.candidate_domain_for(photo)
            shown_att.effect("history", recent_semantic_tags, (candidate_domain, director_role),
                             visual_director.REPETITION_WINDOW)
            # DIRECTOR_RELEVANCE_MISSES — тот же принцип, что RELEVANCE_GATE_
            # MISSES (см. её докстринг): is_relevant в кортеже _score_and_pick
            # гейтит только по ORIGIN QUERY (английский запрос-посредник),
            # НЕ по реальному тексту блока — Директор (compute_extra_score)
            # добавляет sentence_relevance() как доп. ранжирующий сигнал, но
            # у НЕГО САМОГО не было пола: победитель мог оказаться семантически
            # слабым по смыслу фразы и всё равно выиграть, если он лучший
            # (не идеальный) среди прошедших origin-query гейт. Реальный
            # найденный случай (27 августа, videos/_test20s, слот 1):
            # sentence_relevance("Так говорят кино, видеоигры и школьные
            # учебники...", фото весов) = 0.041 — фото победило, потому что
            # было лучшим доступным, а не потому что подходило по смыслу.
            # DIRECTOR_RELEVANCE_FLOOR откалиброван на 8 реальных парах этого
            # же эпизода (visual_director.py, см. её докстринг у константы) —
            # только отчёт, победителя не меняет (иначе пришлось бы решать,
            # ЧЕМ его заменить, когда весь пул одинаково слаб).
            director_rel = visual_director.sentence_relevance(photo, sem_text)
            if director_rel is not None and director_rel < visual_director.DIRECTOR_RELEVANCE_FLOOR:
                shown_att.verdict("director", {
                    "index": i, "text": sem_text, "photo": shown_att.final_path(photo), "kind": "photo",
                    "relevance": director_rel, "threshold": visual_director.DIRECTOR_RELEVANCE_FLOOR,
                })
        # Непрерывность экспозиции: измеряем яркость ИМЕННО этого кадра,
        # сравниваем со скользящим средним последних клипов — если скачок
        # большой (сток из разных источников редко совпадает по свету),
        # подмешиваем небольшую компенсацию в brightness, а не выравниваем
        # целиком (иначе пропала бы естественная вариативность вообще).
        # ВТОРАЯ точка решения о карточке. Нужна из-за ПОРЯДКА, а не из-за
        # новой логики, и это измеренный дефект, а не перестраховка.
        #
        # Вердикт Директора про ЭТОТ кадр записывается в его попытку строками
        # выше — то есть ПОСЛЕ того, как медиа уже выбрано (иначе нечего
        # оценивать). А первая проверка known_bad_reason() стоит раньше, и
        # вердикта Директора там ещё нет. Замер 14.09 (videos/_test60s): слот с
        # современным музеем на фразе про упавшего рыцаря получил 0.20x от
        # пола Директора, причина честно срабатывала в юнит-тесте — и была
        # ИНЕРТНОЙ в проде: карточек в ролике ноль, кадр остался на экране.
        #
        # Остальные причины (отказ арбитра, исчерпанный сток, порог
        # релевантности) известны РАНЬШЕ отбора и обслуживаются первой
        # проверкой — её трогать нельзя, иначе видео-путь потеряет
        # спасение фотографией, которое идёт до карточки.
        if (photo or video) and not locked_shot and not any(
                sl.get("index") == i for sl in FALLBACK_CARD_SLOTS):
            late_reason = known_bad_reason(shown_att.verdicts)
            if (late_reason == "director_relevance_decisive"
                    and fallback_card_allowed(i, len(blocks),
                                              is_opening=is_opening_shot)):
                late_card = build_slot_fallback_card(i, b["text"], late_reason)
                if late_card:
                    # Решил отвергнутый кадр (его вердикт уходит в отчёт), а
                    # на экран идёт карточка: резервы отвергнутого кадра не
                    # применяются, кэш его не получает.
                    decisive_att = shown_att
                    photo, video = late_card, None
                    media_origin = "card"
                    shown_att = given_attempt(slot_attempts, i, "card", late_card)
        shown_att.effect("history", recent_media_types, "video" if video else "photo", 6)
        # РЕШЕНИЕ ПРИНЯТО — единственная точка, где оно становится
        # состоянием эпизода (см. close_slot).
        _final = close_slot(i, slot_attempts, shown=shown_att, decisive=decisive_att,
                            outcome=("shown" if media_origin == "fetch" else media_origin))
        if video:
            video = _final
        else:
            photo = _final
        shot_entries[i] = {"index": i, "section": b["section"], "text": b["text"], "query": queries[i],
                           "kind": "video" if video else "photo",
                           "file": shotlist_relative_file(video or photo, VIDEO_FOLDER),
                           "source": shotlist_source_for(video or photo, VIDEO_FOLDER, locked=locked_shot),
                           "clip": os.path.basename(out),
                           **shotlist_provenance(video or photo)}
        # Нашла ли проверка на этом кадре главное фразы. Замена без главного
        # (лучшее из найденного) видна в шотлисте поимённо, а не молча.
        _focus = (shown_att.notes.get("focus_met") if shown_att is not None else None)
        if _focus is not None:
            shot_entries[i]["focus_met"] = bool(_focus)
            if not _focus:
                print(f"    [{i+1}] главное фразы на кадре не найдено — стоит ближайшая замена")
        luma = measure_luma(photo, is_video=False) if photo else measure_luma(video, is_video=True)
        if luma is not None:
            _clamp, _gain = luma_match_params()
            brightness_bias = (0.0 if luma_ema is None
                               else max(-_clamp, min(_clamp, (luma_ema - luma) * _gain)))
            luma_ema = luma if luma_ema is None else luma_ema * 0.6 + luma * 0.4
        else:
            brightness_bias = 0.0
        if SELECT_ONLY:
            # ТОЧКА СРЕЗА (см. SELECT_ONLY): состояние отбора для следующего
            # слота уже полностью обновлено, всё ниже — параметры рендера.
            _stock_api_pacing(i, use_pexels, use_local)
            continue
        # Адаптивная ТЕХНИЧЕСКАЯ нормализация экспозиции ЭТОГО кадра (auto-
        # levels по перцентилям, см. measure_levels()/auto_levels_params()) —
        # решает другую задачу, чем brightness_bias выше (тот сглаживает
        # скачок МЕЖДУ соседними кадрами, это подтягивает разброс ВНУТРИ
        # одного кадра к общей базе), применяется в film_look() ПЕРЕД
        # неизменным творческим грейдом, не вместо него.
        levels, wb = (measure_levels(photo, is_video=False, want_wb=True) if photo
                      else measure_levels(video, is_video=True, want_wb=True))
        # П.2 (аудит "зерно vs частицы в мире"): частицастость ИСХОДНИКА —
        # снижает GRAIN_OPACITY для этого клипа при финальном блендинге,
        # см. measure_particle_score()/PARTICLE_SCORE_THRESHOLD (калибровано
        # на реальных кадрах, не на глаз).
        particle_score = (measure_particle_score(photo, is_video=False) if photo
                           else measure_particle_score(video, is_video=True))
        grain_scale = (PARTICLE_GRAIN_SCALE if (particle_score is not None
                        and particle_score >= PARTICLE_SCORE_THRESHOLD) else 1.0)
        energy_bias = max(-0.5, min(0.5, energy_lvls[i] - 1.0))
        # Reference-Guided Look Management (см. scripts/look_reference.py) —
        # ТОЛЬКО для фото (video-клипы не входят в эту версию системы, см.
        # докстринг модуля). Каждый индекс блока получает запись в
        # look_report — даже когда фича выключена или это video-клип — тот
        # же принцип полноты аудита, что уже применяет render_manifest
        # (пользователь указал на этот пробел явно). has_face — свой,
        # отдельный вызов detect_face_anchor() (та же функция, что уже
        # использует resolve_crop_anchor() внутри kenburns()/
        # parallax_kenburns() для кропа, второй недорогой вызов здесь — не
        # переиспользование внутреннего состояния тех функций, т.к. решение
        # о коррекции нужно ДО диспетчеризации рендера). scene_boundary —
        # is_section_start уже посчитан выше в этой же итерации, сигнал для
        # сброса EMA-сглаживания на границе секции сценария (см.
        # look_correction_filter()).
        look_filter = None
        if not photo:
            look_report[i] = {"decision": "skipped_video" if video else "skipped_no_media"}
        elif look_ref is None:
            look_report[i] = {"decision": "skipped_disabled"}
        else:
            has_face = detect_face_anchor(photo) is not None
            look_filter, look_entry, look_state = look_ref.look_correction_filter(
                photo, levels, wb, has_face, scene_boundary=is_section_start,
                section=b["section"], prev_state=look_state, arc_stage=arc_stage_for(b))
            look_report[i] = look_entry
        # П.4: домен кадра для DOMAIN_WARM_PUSH_SCALE (film_look()) — только
        # фото (видео не участвует, тот же скоуп, что Look Management выше),
        # свой независимый вызов classify_domain() (не переиспользует
        # look_entry — та не гарантирует поле "domain" на всех ветках
        # решения Look Management, см. look_correction_filter()).
        domain = None
        if photo and domain_ref is not None:
            try:
                domain, _domain_margin = domain_ref.classify_domain(photo)
            except Exception:
                domain = None
        # Один непойманный сбой в рендере ОДНОГО кадра (редкий edge case —
        # битый файл, неожиданный тип данных и т.п.) раньше падал наружу и
        # убивал весь многочасовой прогон main() целиком, теряя ВСЮ уже
        # проделанную работу. kenburns()/video_render() и так возвращают
        # False на предсказуемые сбои (ffmpeg не встал и т.п.) — это перехват
        # именно НЕПРЕДВИДЕННОГО исключения, кадр просто уходит в missing
        # (как и любой другой honest-failure), рендер продолжается дальше.
        future = None
        try:
            if video:
                if render_pool:
                    future = render_pool.submit(
                        _timed_render, video_render, i, video, out, d, title=title, stat=stat, section=b["section"],
                        stat_variant=stat_variant, brightness_bias=brightness_bias,
                        energy_bias=energy_bias, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                        handheld=wants_handheld(b), captions=captions,
                        ffmpeg_threads=RENDER_FFMPEG_THREADS)
                    ok = None
                else:
                    ok = _timed_render(video_render, i, video, out, d, title=title, stat=stat, section=b["section"],
                                       stat_variant=stat_variant, brightness_bias=brightness_bias,
                                       energy_bias=energy_bias, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                                       handheld=wants_handheld(b), captions=captions)
            else:
                # anti-repetition: хэш сам по себе не мешает 3 зумам подряд случайно
                # совпасть — держим окно последних решений и форсируем смену при повторе.
                _, zi_cand, pd_cand = kb_hash_choices(photo)
                # НАПРАВЛЕНИЕ (наезд или отъезд) сегодня решает бит хэша
                # имени файла — у ВСЕХ кадров без исключения (замер на
                # эпизоде 02: 142 из 142). Там, где стадия рассказа имеет
                # содержательное мнение — придвинуться к разоблачению,
                # отпустить на выводе, открыть место на заходе — кандидатом
                # становится оно, а не монетка.
                #
                # anti-repeat СОХРАНЯЕТ право вето: три одинаковых движения
                # подряд читаются как штамп независимо от того, насколько
                # осмысленно каждое по отдельности. Сколько раз вето реально
                # перебило стадию — пишется в отчёт (camera_language_report),
                # а не остаётся догадкой.
                # Режим движения считается ДО направления — иначе защита от
                # повтора не может смотреть на пару (режим, направление), а
                # только на голое направление, и ломает замысел там, где
                # повторяться нечему (замер: 18 случаев из 27, см.
                # camera_language.pick_direction). Функция чистая, лишний
                # вызов ничего не стоит.
                _stage = arc_stage_for(b)
                photo_hash, _, _ = kb_hash_choices(photo)
                cur_shot_size = recent_shot_sizes[-1] if recent_shot_sizes else None
                motion_mode = choose_motion_mode(b, is_section_start, photo_hash,
                                                 shot_size=cur_shot_size,
                                                 arc_stage=_stage)
                # КАРТОЧКА — ЭТО ТЕКСТ, А НЕ ФОТОГРАФИЯ. Найдено ГЛАЗАМИ на
                # готовом ролике 02 (17.09): на 200-й секунде надпись
                # «Лезвие, которое выпустило бы кишки, встречает нагрудни…»
                # ОБРЕЗАНА по обоим краям кадра. Причина не в вёрстке —
                # fallback_card.py верстает с переносом ровно в 1920x1080, —
                # а в том, что дальше карточка идёт общим фото-путём и
                # получает Ken Burns: на t=200 зум ещё крупный и съедает
                # края, к t=203 отходит и текст влезает целиком. Для плашки
                # с цифрой статика форсируется давно (b["stat"] в
                # choose_motion_mode), для карточки правила не было.
                if is_fallback_card_media(photo):
                    motion_mode = "static_hold"
                _stage_zi = None
                if _stage and feature_flags.enabled("CAMERA_LANGUAGE"):
                    import camera_language
                    _stage_zi = camera_language.stage_zoom_in(_stage)
                if feature_flags.enabled("CAMERA_LANGUAGE"):
                    import camera_language
                    zoom_in = camera_language.pick_direction(
                        zoom_pair_hist, motion_mode,
                        zi_cand if _stage_zi is None else _stage_zi, max_repeat=2)
                else:
                    zoom_in = pick_no_repeat(
                        zoom_hist, zi_cand if _stage_zi is None else _stage_zi,
                        [True, False], max_repeat=2)
                if _stage_zi is not None:
                    CAMERA_LANGUAGE_STATS["stage_had_direction"] += 1
                    if zoom_in != _stage_zi:
                        CAMERA_LANGUAGE_STATS["direction_overridden_by_antirepeat"] += 1
                pan_dir = pick_no_repeat(pan_hist, pd_cand, PAN_DIRECTIONS, max_repeat=2)
                # Параллакс — только на самые заметные точки ролика (хук целиком +
                # первый кадр каждого раздела + момент [climax]), не на все фото:
                # покадровый рендер с depth-моделью в разы дороже по времени
                # zoompan-версии, на 40+ кадрах это лишние десятки минут ради
                # эффекта, который большую часть ролика зритель всё равно не
                # разглядывает так пристально, как хук/открывашки/разоблачение.
                # По прямому запросу пользователя (17-28-минутные ролики,
                # "в отдельных местах уже нельзя сделать отдельно параллакс,
                # например когда что-то важное") — [climax] добавлен третьим
                # условием: та же разметка, что уже используют reveal_hold в
                # speech_planner.py и climax dip в музыке (CLIMAX_DIP_LEAD_SEC),
                # не новый сигнал, тот же самый "момент разоблачения", который
                # сценарист и так помечает тегом. Кадр НЕ дублируется — climax
                # даёт максимум 1 доп. слот на секцию (см. is_climax присвоение
                # выше, k==0). Всегда ПОСЛЕДОВАТЕЛЬНО в главном процессе (см.
                # RENDER_POOL_ENABLED выше) — только тут живёт depth-модель.
                is_highlight = is_parallax_highlight(b, is_section_start)
                ok = False
                if PARALLAX_ENABLED and is_highlight:
                    # Параллакс (2.5D depth remap) — своя, уже отдельно проверенная
                    # зум/пан-математика, motion_mode на него не распространяем:
                    # это отдельный, более дорогой визуальный приём для самых
                    # заметных точек ролика, не нуждается в дополнительной
                    # категоризации поверх собственной.
                    ok = _timed_render(parallax_kenburns, i, photo, out, d, title=title, zoom_in=zoom_in,
                                            pan_dir=pan_dir, stat=stat, section=b["section"],
                                            stat_variant=stat_variant, brightness_bias=brightness_bias,
                                            energy_bias=energy_bias, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                                            captions=captions, look_filter=look_filter, domain=domain)
                if not ok:
                    CAMERA_LANGUAGE_STATS["modes"][motion_mode] = \
                        CAMERA_LANGUAGE_STATS["modes"].get(motion_mode, 0) + 1
                    if _stage:
                        CAMERA_LANGUAGE_STATS["with_stage"] += 1
                    else:
                        CAMERA_LANGUAGE_STATS["without_stage"] += 1
                    if render_pool:
                        future = render_pool.submit(
                            _timed_render, kenburns, i, photo, out, d, title=title, zoom_in=zoom_in, pan_dir=pan_dir,
                            stat=stat, section=b["section"], motion_mode=motion_mode,
                            brightness_bias=brightness_bias, energy_bias=energy_bias,
                            stat_variant=stat_variant, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                            captions=captions, look_filter=look_filter, ffmpeg_threads=RENDER_FFMPEG_THREADS, domain=domain)
                        ok = None
                    else:
                        ok = _timed_render(kenburns, i, photo, out, d, title=title, zoom_in=zoom_in, pan_dir=pan_dir,
                                      stat=stat, section=b["section"], motion_mode=motion_mode,
                                      brightness_bias=brightness_bias, energy_bias=energy_bias,
                                      stat_variant=stat_variant, stat_delay=stat_delay, levels=levels, wb=wb, grain_scale=grain_scale,
                                      captions=captions, look_filter=look_filter, domain=domain)
        except Exception as e:
            print(f"  [{i+1}] непредвиденный сбой рендера, пропускаю кадр: {type(e).__name__} {e}")
            ok, future = False, None
        pending_jobs.append({"i": i, "out": out, "d": d, "section": b["section"], "block": b,
                              "video": bool(video), "photo": photo, "future": future, "ok": ok})
        if i % 20 == 0 or i < 3:
            print(f"  [{i+1}/{len(blocks)}] {d:.1f}с {b['words']} слов ({'видео' if video else 'фото'}, "
                  f"{'в очереди' if future is not None else 'готово' if ok else 'пропуск'})")
        if i % 10 == 9:
            log_render_diagnostics(f"block_{i+1}/{len(blocks)}")
        _stock_api_pacing(i, use_pexels, use_local)

    if not SELECT_ONLY:
        # Резолвим отложенные (в пуле) рендеры — future.result() блокирует, только
        # если этот конкретный клип ещё не доехал, к этому моменту у воркеров уже
        # было всё время работы цикла выше, чтобы прогрызть очередь. Порядок —
        # строго по индексу блока (pending_jobs собран в порядке цикла), не по
        # порядку завершения — xfade-склейка ниже требует правильную последовательность.
        check_jobs_in_order(pending_jobs)
        for job in pending_jobs:
            if job["future"] is not None:
                try:
                    job["ok"] = job["future"].result()
                except Exception as e:
                    print(f"  [{job['i']+1}] непредвиденный сбой рендера в пуле, пропускаю кадр: "
                          f"{type(e).__name__} {e}")
                    job["ok"] = False
            if job["ok"]:
                clips.append(job["out"])
                clip_durs.append(job["d"])
                clip_sections.append(job["section"])
                clip_blocks.append(job["block"])
                if not job["video"] and job["photo"]:
                    media_log.append((job["i"], job["photo"]))
                    # Пост-рендер QC (RENDER_SHARPNESS_DROP_RATIO выше) — единственная
                    # проверка в пайплайне, которая смотрит на ГОТОВЫЙ кадр, а не на
                    # исходное фото ДО Ken Burns/параллакса/ГРИП/грейда. Дёшево (Лапла-
                    # сиан на уже скачанном исходнике + один кадр-пробник уже готового
                    # клипа, без новой модели/сети) — считается синхронно здесь же, не
                    # в пуле, лишние доли секунды на клип не стоят отдельного воркера.
                    flagged, ratio = render_sharpness_regression(job["photo"], job["out"])
                    if flagged:
                        RENDER_QC_REPORT.append({
                            "index": job["i"], "source": job["photo"], "rendered": job["out"],
                            "ratio": ratio, "threshold": RENDER_SHARPNESS_DROP_RATIO,
                        })
                elif job["video"]:
                    # Второй, независимый предохранитель поверх селекционного
                    # гейта (video_sharpness_ok в pexels_video()): если ВЕСЬ пул
                    # кандидатов был смазан (fallback всё равно не оставляет слот
                    # пустым, см. философию ЧАСТИ 13), это честно всплывает здесь
                    # на ГОТОВОМ клипе — та же логика, что render_sharpness_
                    # regression() даёт фото, но для видео нет "источника"
                    # отдельно от рендера (клип и есть исходник, без Ken Burns/
                    # ГРИП поверх), поэтому проверяем абсолютную резкость, не
                    # отношение.
                    v_sharp_ok = video_sharpness_ok(job["out"])
                    if v_sharp_ok is False:
                        RENDER_QC_REPORT.append({
                            "index": job["i"], "source": None, "rendered": job["out"],
                            "ratio": None, "threshold": VIDEO_SHARPNESS_REJECT,
                            "reason": "video_median_sharpness_below_threshold",
                        })
                render_manifest[job["i"]] = {"index": job["i"], "status": "ok", "path": job["out"],
                                              "section": job["section"], "duration": job["d"],
                                              "kind": "video" if job["video"] else "photo"}
            else:
                missing.append(job["i"] + 1)
                render_manifest[job["i"]] = {"index": job["i"], "status": "failed",
                                              "reason": "см. консольный лог выше (run_ffmpeg_with_retry) — "
                                                        f"после {RENDER_RETRY_ATTEMPTS} попыток",
                                              "section": job["section"], "duration": job["d"]}
        if render_pool:
            render_pool.shutdown(wait=True)
        log_render_diagnostics("render_done")
        print(f"  Рендер завершён: {len(clips)}/{len(blocks)} клипов")
        if never_show_known_bad and not clips:
            # Поглощать некого: ни один слот не получил проверенного кадра.
            # Собирать ролик из брака нельзя (для этого правило и заведено), а
            # карточки владелец не разрешил — значит честный стоп с причиной, а
            # не пустой файл и не молчаливая деградация.
            print("\nСТОП: ни один слот не получил ПРОВЕРЕННОГО кадра — "
                  f"поглощено {len(ABSORBED_SLOTS)} слот(ов), показывать нечего. "
                  "Смотреть media_plan/absorbed_slots_report.json: чаще всего это "
                  "нет ключей стоков, исчерпанная квота или запрос, которому "
                  "мир эпизода противоречит.")
            return 1

        manifest_path = os.path.join(VIDEO_FOLDER, "media_plan", "render_manifest.json")
        os.makedirs(os.path.dirname(manifest_path), exist_ok=True)
        manifest_tmp = manifest_path + ".tmp"
        with open(manifest_tmp, "w", encoding="utf-8") as f:
            json.dump({"total_blocks": len(blocks), "ok": len(clips), "missing": missing,
                        "clips": [render_manifest[i] for i in sorted(render_manifest)]},
                       f, ensure_ascii=False, indent=2)
        os.replace(manifest_tmp, manifest_path)
    else:
        # Режим отбора: клипов нет по построению, поэтому «есть ли что показать»
        # считается по самим решениям отбора, а не по отрендеренным клипам.
        # Тот же честный стоп, что у рендера строками выше, по той же причине.
        if never_show_known_bad and not any(
                e.get("file") for e in shot_entries.values()):
            print("\nСТОП (отбор): ни один слот не получил ПРОВЕРЕННОГО кадра — "
                  f"поглощено {len(ABSORBED_SLOTS)} слот(ов). Смотреть "
                  "media_plan/absorbed_slots_report.json.")
            return EXIT_NOT_BUILT

    # Шотлист — что РЕАЛЬНО выбрано под каждую фразу и какие гейты реально
    # работали (см. блок-комментарий у SHOTLIST_VERSION). Пишется всегда.
    selection_gates = {
        "pexels_api_key": bool(use_pexels),
        "local_media_folder": bool(use_local),
        "clip_relevance_enabled": bool(CLIP_ENABLED),
        "clip_broken_this_run": bool(CLIP_BROKEN),
        "clip_model_loaded": _clip_model is not None,
        "aesthetic_score_enabled": bool(AESTHETIC_ENABLED),
        "parallax": bool(PARALLAX_ENABLED and not PARALLAX_BROKEN),
        "visual_director_mode": (visual_director.VISUAL_DIRECTOR_MODE if visual_director is not None else "off"),
        "look_management_mode": feature_flags.value("LOOK_MANAGEMENT_MODE"),
        "shot_director_mode": feature_flags.value("SHOT_DIRECTOR_MODE"),
        "vlm_arbiter_mode": feature_flags.value("VLM_ARBITER_MODE"),
        "gemini_key_present": bool(os.environ.get("GEMINI_API_KEY")),
        "shotlist_locked_slots_used": shotlist_locked_used,
        # Раньше по артефактам готового ролика нельзя было узнать, что
        # большая его часть собиралась урезанным бюджетом подбора: граница
        # зашита в код, в реестр флагов не входит и в feature_flags.json не
        # попадает. Теперь она записана там же, где остальные ответы на
        # вопрос "каким пайплайном собран этот ролик".
        "full_pool_until_slot": _FAST_MODE_START,
        "full_pool_floor": FAST_MODE_START_INDEX,
    }
    selection_gates["source_contribution"] = {src: dict(v) for src, v in SOURCE_STATS.items()}
    shotlist_file = write_shotlist(VIDEO_FOLDER, shot_entries, selection_gates, prev=prev_shotlist)
    write_source_contribution(VIDEO_FOLDER)
    write_run_journal(VIDEO_FOLDER)
    if not SELECT_ONLY:
        write_camera_language_report(VIDEO_FOLDER)
    print(f"  Шотлист: media_plan/shotlist.json ({len(shot_entries)} слотов, "
          f"{shotlist_locked_used} по lock) — контактный лист: python scripts/shotlist_contact.py {VIDEO_FOLDER}")

    # RELEVANCE_GATE_MISSES — см. её докстринг у объявления выше: слоты, где
    # ВЕСЬ просмотренный пул кандидатов провалил relevance-гейт, но слот всё
    # равно не остался пустым (философия ЧАСТИ 13). Тот же принцип честной
    # записи, что уже применяет look_manifest.json чуть ниже — пишем ВСЕГДА
    # (даже пустой список), не пропускаем файл молча.
    relevance_report_path = os.path.join(VIDEO_FOLDER, "media_plan", "relevance_gate_report.json")
    # Гейт релевантности работает над ЛЮБЫМ удалённым источником (музеи,
    # Openverse, Pixabay, Unsplash, Pexels), не только над Pexels — раньше
    # отчёт писал «CLIP-гейт не выполнялся (нет ключа Pexels)», при том что
    # музейные кандидаты через него проходили. Загруженная модель — и есть
    # факт, что гейт кого-то проверял.
    relevance_checked = bool(CLIP_ENABLED and not CLIP_BROKEN and _clip_model is not None)
    # merge_slot_report, а не запись целиком: слоты, отданные кэш-хитом клипа,
    # в этом прогоне не проверялись — стирать про них прошлый вердикт значит
    # выдавать неведение за чистый результат (см. докстринг merge_slot_report).
    merge_slot_report(
        relevance_report_path, RELEVANCE_GATE_MISSES,
        resolved_slots=RESOLVED_SLOTS_THIS_RUN,
        extra={"checked": relevance_checked,
               "note": None if relevance_checked else
               "CLIP-гейт релевантности НЕ выполнялся в этом прогоне (нет ключа Pexels, CLIP выключен/сломан "
               "или модель не загружалась) — пустой список misses не означает «прошло»"})
    if not relevance_checked:
        print("  ВНИМАНИЕ: релевантность/анахронизмы кандидатов НЕ проверялись (CLIP не загружен или нет Pexels) — "
              "смотреть кадры глазами обязательно (Шаг 7.5)")
    if RELEVANCE_GATE_MISSES:
        # Формулировка "весь пул провалил гейт" здесь исторически неточна —
        # см. докстринг STOCK_EXHAUSTED_MISSES выше: на деле проверяется
        # только ПОБЕДИТЕЛЬ, а лексикографический кортеж _score_and_pick()
        # может предпочесть нерелевантного, но уникального кандидата
        # релевантному дублю — победитель нерелевантен, а пул при этом не
        # обязательно исчерпан. Честная пул-вайд проверка — ниже.
        print(f"  ВНИМАНИЕ: {len(RELEVANCE_GATE_MISSES)} слот(ов) получили кандидата НИЖЕ порога "
              f"relevance — см. media_plan/relevance_gate_report.json, сверить глазами на Шаге 7.5.")

    # STOCK_EXHAUSTED_MISSES — см. её докстринг у объявления выше: строго
    # более сильный сигнал, чем RELEVANCE_GATE_MISSES — не "победитель не
    # идеален", а "ни один кандидат из ВСЕГО просмотренного пула не прошёл
    # ни relevance, ни резкость одновременно" (независимо от дедупа). На
    # это стоит реагировать иначе, чем на обычный промах: не "сверить
    # глазами", а "стоку тут физически нечего предложить — см. Шаг 5,
    # AI-картинка/видео вместо стока для этого слота".
    stock_exhausted_path = os.path.join(VIDEO_FOLDER, "media_plan", "stock_exhausted_report.json")
    merge_slot_report(stock_exhausted_path, STOCK_EXHAUSTED_MISSES,
                      resolved_slots=RESOLVED_SLOTS_THIS_RUN)
    if STOCK_EXHAUSTED_MISSES:
        idxs = [m["index"] for m in STOCK_EXHAUSTED_MISSES]
        # ЧЕСТНАЯ ФОРМУЛИРОВКА (21.09). Раньше здесь стояло «весь просмотренный
        # пул честно исчерпан», и это читалось — в том числе мной при разборе —
        # как «на стоке для этой фразы физически ничего нет». Прямой дамп пула
        # показал обратное: у слота, получившего эту строку, в пуле было 232
        # кандидата, а ПРОСМОТРЕНО из них три (бюджет попыток видео). Число
        # «сколько было предложено» теперь печатается рядом с «сколько
        # просмотрено», чтобы вывод «сток — тупик» делался по фактам.
        seen = sum(m.get("n_candidates_examined") or 0 for m in STOCK_EXHAUSTED_MISSES)
        avail = sum(m.get("n_candidates_available") or 0 for m in STOCK_EXHAUSTED_MISSES)
        scope = (f"просмотрено {seen} кандидат(ов) из {avail} предложенных пулом"
                 if avail else f"просмотрено {seen} кандидат(ов)")
        print(f"  ВНИМАНИЕ: {len(STOCK_EXHAUSTED_MISSES)} слот(ов) {idxs} — среди ПРОСМОТРЕННЫХ "
              f"кандидатов ни один не прошёл и relevance, и резкость ({scope}) — см. "
              f"media_plan/stock_exhausted_report.json. Если просмотрено заметно меньше, чем "
              f"предложено, это упёрлось в бюджет попыток, а не в пустой сток.")

    # ARBITER_REJECTED_ALL — самый сильный из сигналов о подборе: не «порог
    # не взят» (число), а «модель посмотрела кандидатов и сказала: ни один
    # не подходит». Пишется отдельным отчётом, потому что и реакция другая:
    # численный промах — повод сверить глазами, отказ арбитра — повод
    # заменить кадр, он уже проверен более сильным судьёй, чем косинус.
    arbiter_rejected_path = os.path.join(VIDEO_FOLDER, "media_plan",
                                          "arbiter_rejected_report.json")
    merge_slot_report(arbiter_rejected_path, ARBITER_REJECTED_ALL,
                      resolved_slots=RESOLVED_SLOTS_THIS_RUN)
    if ARBITER_REJECTED_ALL:
        idxs = [m["index"] for m in ARBITER_REJECTED_ALL]
        print(f"  ВНИМАНИЕ: {len(ARBITER_REJECTED_ALL)} слот(ов) {idxs} — VLM-арбитр ЯВНО "
              f"ответил «ни один кандидат не подходит», и слот всё равно заполнен выбором "
              f"эмбеддинга — см. media_plan/arbiter_rejected_report.json. Это не «порог не "
              f"взят», а прямой отказ более сильного судьи: кадр надо заменить, а не сверять.")

    # Судья кадров: слоты, где лучший кадр по его оценке — брак (как у
    # соседних отчётов), и полный журнал оценок с ценой — чтобы по готовому
    # ролику было видно, кто и во сколько решил каждый слот.
    gw = _SHOT_JUDGE_STATE["gateway"]
    if gw is not None:
        merge_slot_report(os.path.join(VIDEO_FOLDER, "media_plan", "shot_judge_report.json"),
                          SHOT_JUDGE_MISSES, resolved_slots=RESOLVED_SLOTS_THIS_RUN)
    if gw is not None or SHOT_JUDGE_LOG:
        with open(os.path.join(VIDEO_FOLDER, "media_plan", "shot_judge_log.json"), "w",
                  encoding="utf-8") as f:
            json.dump({"model": shot_judge_model(), "gateway": gw.summary() if gw else None,
                       "calls": SHOT_JUDGE_LOG}, f, ensure_ascii=False, indent=1)
        if gw is not None:
            s_ = gw.summary()
            print(f"  Судья кадров: вызовов {s_['calls']}, сбоев {s_['failures']}, потрачено "
                  f"{s_['spent']} из {s_['spend_cap']}" + (f" — ВЫКЛЮЧЕН: {s_['dead']}" if s_['dead'] else ""))
    if SHOT_JUDGE_MISSES:
        print(f"  ВНИМАНИЕ: {len(SHOT_JUDGE_MISSES)} слот(ов) {[m['index'] for m in SHOT_JUDGE_MISSES]} — "
              f"судья кадров оценил лучший найденный кадр как брак — см. "
              f"media_plan/shot_judge_report.json")

    # SMART_VETO_MISSES — тот же принцип: отчёт отдельно, не только строка
    # в absorbed_slots_report.json (см. ЧАСТЬ 13 Шаг 7.3), потому что здесь
    # известна ДОПОЛНИТЕЛЬНАЯ деталь — какой именно запрос отклонён и какой
    # моделью, а слотовый отчёт о поглощении этого не знает.
    smart_veto_path = os.path.join(VIDEO_FOLDER, "media_plan",
                                    "smart_veto_report.json")
    merge_slot_report(smart_veto_path, SMART_VETO_MISSES,
                      resolved_slots=RESOLVED_SLOTS_THIS_RUN)
    if SMART_VETO_MISSES:
        idxs = [m["index"] for m in SMART_VETO_MISSES]
        print(f"  ВНИМАНИЕ: {len(SMART_VETO_MISSES)} слот(ов) {idxs} — вторая проверка "
              f"(SigLIP2+Jina) отклонила уже выбранного CLIP победителя — см. "
              f"media_plan/smart_veto_report.json. При NEVER_SHOW_KNOWN_BAD=1 (дефолт) "
              f"слот поглощён соседним проверенным кадром, а не показан.")

    # FALLBACK_CARD_SLOTS — где вместо кадра стоит процедурная карточка.
    # Это НЕ повод для тревоги сам по себе (карточка честнее заведомо
    # плохого кадра), но повод посмотреть: много карточек = сток по этой
    # теме исчерпан, нужны архивы или AI-картинки (Шаг 5).
    # Поглощённые слоты — отдельный отчёт, а не строка в консоли: по
    # готовому ролику иначе невозможно ответить, почему кадр держится
    # дольше своей фразы и какая фраза осталась без своего кадра.
    absorbed_path = os.path.join(VIDEO_FOLDER, "media_plan",
                                  "absorbed_slots_report.json")
    merge_slot_report(absorbed_path, ABSORBED_SLOTS,
                      resolved_slots=RESOLVED_SLOTS_THIS_RUN,
                      extra={"never_show_known_bad": never_show_known_bad,
                             "tail_carry_sec": round(_carry_sec, 3)})
    fallback_cards_path = os.path.join(VIDEO_FOLDER, "media_plan",
                                        "fallback_cards_report.json")
    merge_slot_report(fallback_cards_path, FALLBACK_CARD_SLOTS,
                      resolved_slots=RESOLVED_SLOTS_THIS_RUN)
    if FALLBACK_CARD_SLOTS:
        idxs = [m["index"] for m in FALLBACK_CARD_SLOTS]
        print(f"  {len(FALLBACK_CARD_SLOTS)} слот(ов) {idxs} заполнены процедурной "
              f"карточкой вместо кадра — см. media_plan/fallback_cards_report.json. "
              f"Это осознанная замена заведомо плохого кадра, но если карточек много — "
              f"стоку по этой теме нечего предложить: нужны архивы или AI-картинки (Шаг 5).")

    # VIDEO_RESCUED_BY_PHOTO — слоты, где негодное видео уступило место
    # фотографии. Пишется отдельно от карточек: это не «нечего показать», а
    # «показали другое и лучше», и по отчёту должно быть видно, сколько раз
    # видео-корпус стока не справился на этом эпизоде.
    rescue_path = os.path.join(VIDEO_FOLDER, "media_plan",
                               "video_photo_rescue_report.json")
    merge_slot_report(rescue_path, VIDEO_RESCUED_BY_PHOTO,
                      resolved_slots=RESOLVED_SLOTS_THIS_RUN)
    if LOCAL_STOCK_GATE_REJECTED:
        idxs = [m["index"] + 1 for m in LOCAL_STOCK_GATE_REJECTED]
        print(f"  {len(LOCAL_STOCK_GATE_REJECTED)} слот(ов) {idxs}: файл media/*_stock.* "
              f"из Шага 4 не прошёл relevance-гейт и заменён обычным отбором "
              f"(AI-картинки не гейтятся никогда, см. LOCAL_STOCK_GATE)")
    if VIDEO_TOO_SHORT_FILTERED:
        dropped = sum(m["dropped"] for m in VIDEO_TOO_SHORT_FILTERED)
        print(f"  {len(VIDEO_TOO_SHORT_FILTERED)} слот(ов): отсеяно {dropped} видео-кандидат(ов), "
              f"которых пришлось бы замедлить сильнее {VIDEO_MAX_TIME_STRETCH}x под длину слота "
              f"(см. VIDEO_MAX_TIME_STRETCH). Пул ни на одном слоте не опустел.")
    if VIDEO_RESCUED_BY_PHOTO:
        idxs = [m["index"] + 1 for m in VIDEO_RESCUED_BY_PHOTO]
        print(f"  {len(VIDEO_RESCUED_BY_PHOTO)} слот(ов) {idxs}: негодное видео "
              f"заменено фотографией — см. media_plan/video_photo_rescue_report.json")

    # RENDER_QC_REPORT — см. render_sharpness_regression()/RENDER_SHARPNESS_
    # DROP_RATIO выше: клипы, где ГОТОВЫЙ рендер ощутимо размытее своего же
    # источника (реальный найденный случай — DOF-баг 27 августа). Advisory,
    # не hard-reject — тот же принцип честной записи, что и у остальных
    # отчётов здесь.
    render_qc_path = os.path.join(VIDEO_FOLDER, "media_plan", "render_qc_report.json")
    if not SELECT_ONLY:
        render_qc_tmp = render_qc_path + ".tmp"
        with open(render_qc_tmp, "w", encoding="utf-8") as f:
            json.dump({"flagged": RENDER_QC_REPORT}, f, ensure_ascii=False, indent=2)
        os.replace(render_qc_tmp, render_qc_path)
    if RENDER_QC_REPORT:
        print(f"  ВНИМАНИЕ: {len(RENDER_QC_REPORT)} клип(ов) заметно размытее своего исходника "
              f"(rendered/source < {RENDER_SHARPNESS_DROP_RATIO}) — см. media_plan/render_qc_report.json, "
              f"сверить глазами на Шаге 7.5.")

    # DIRECTOR_RELEVANCE_MISSES — см. её докстринг у объявления выше и
    # DIRECTOR_RELEVANCE_FLOOR в visual_director.py: победитель Директора
    # семантически слаб по РЕАЛЬНОМУ тексту блока (не по origin query).
    # Пустой список, если VISUAL_DIRECTOR_MODE не assist (условие "scored"
    # выше просто никогда не срабатывает) — пишем файл всё равно, тот же
    # принцип честной записи "нечего сообщить", что и у остальных отчётов.
    director_rel_path = os.path.join(VIDEO_FOLDER, "media_plan", "director_relevance_report.json")
    merge_slot_report(director_rel_path, DIRECTOR_RELEVANCE_MISSES,
                      resolved_slots=RESOLVED_SLOTS_THIS_RUN)
    if DIRECTOR_RELEVANCE_MISSES:
        print(f"  ВНИМАНИЕ: {len(DIRECTOR_RELEVANCE_MISSES)} слот(ов) — выбранный кадр семантически "
              f"слаб по РЕАЛЬНОМУ тексту блока (не по запросу) — см. "
              f"media_plan/director_relevance_report.json, сверить глазами на Шаге 7.5.")

    # TEXT_TRUNCATION_REPORT (см. visual_director.py, _report_truncation_if_any) —
    # честная видимость молчаливой обрезки текста по лимиту токенов модели
    # (SigLIP2 — 64, Jina — 77). Ничего не чинит и не меняет в подборе
    # картинки — только показывает факт, который раньше был не виден вообще
    # (реальный замер на опубликованном сценарии: 25% смысловых юнитов
    # обрезаются молча). Пишем всегда, даже пустой список — тот же принцип
    # честной записи "нечего сообщить", что и у остальных отчётов здесь.
    truncation_report = visual_director.TEXT_TRUNCATION_REPORT if visual_director is not None else []
    truncation_path = os.path.join(VIDEO_FOLDER, "media_plan", "text_truncation_report.json")
    truncation_tmp = truncation_path + ".tmp"
    with open(truncation_tmp, "w", encoding="utf-8") as f:
        json.dump({"enabled": visual_director is not None, "truncated": truncation_report},
                   f, ensure_ascii=False, indent=2)
    os.replace(truncation_tmp, truncation_path)
    if truncation_report:
        by_model = {}
        for r in truncation_report:
            by_model[r["model"]] = by_model.get(r["model"], 0) + 1
        print(f"  ВНИМАНИЕ: {len(truncation_report)} текст(ов) молча обрезаны по лимиту токенов "
              f"модели ({', '.join(f'{k}: {v}' for k, v in sorted(by_model.items()))}) — модель "
              f"оценивала соответствие картинки фразе, не дочитав её до конца. См. "
              f"media_plan/text_truncation_report.json.")

    # Reference-Guided Look Management — аудит-трейл (см. scripts/
    # look_reference.py). look_report пуст, если фича выключена/lookbook
    # пуст (реальный случай сегодня — см. LOOKBOOK_JSON_PATH) — тогда пишем
    # пустой отчёт с enabled=False, не пропускаем файл молча (тот же принцип
    # честной записи "нечего сообщить", что уже применяет speech_validator.py
    # к media_plan/pause_decisions.json).
    if not SELECT_ONLY:
        look_manifest_path = os.path.join(VIDEO_FOLDER, "media_plan", "look_manifest.json")
        look_manifest_tmp = look_manifest_path + ".tmp"
        cache_hits_skipped_analysis = sum(1 for e in look_report.values() if e.get("decision") == "skipped_cache_hit")
        with open(look_manifest_tmp, "w", encoding="utf-8") as f:
            json.dump({"enabled": look_ref is not None,
                        "cache_hits_skipped_analysis": cache_hits_skipped_analysis,
                        "clips": [look_report[i] for i in sorted(look_report)]},
                       f, ensure_ascii=False, indent=2)
        os.replace(look_manifest_tmp, look_manifest_path)
    # Честное предупреждение: shadow/assist на уже отрендеренном эпизоде
    # (temp_smart/ содержит кэш из прошлого прогона) не анализирует
    # кэш-хиты — у них физически нет сохранённого пути к исходному фото на
    # этот прогон (см. докстринг look_reference.py). Отчёт в этом случае
    # НЕ полная симуляция assist — печатаем это явно, не оставляем
    # оператора гадать, почему клипов в look_manifest.json меньше, чем
    # блоков в эпизоде.
    if not SELECT_ONLY and look_ref is not None and cache_hits_skipped_analysis:
        print(f"  Look Management: {cache_hits_skipped_analysis} клип(ов) пропущено анализом "
              f"(кэш из прошлого прогона) — для честного shadow/assist-прогона на этом эпизоде "
              f"очисти temp_smart/ и перезапусти.")

    # Semantic Visual Director — аудит-трейл (см. scripts/visual_director.py).
    # Тот же принцип, что look_manifest.json чуть выше: пустой/enabled=False
    # отчёт при выключенной фиче — не тишина, честная запись "нечего сообщить".
    director_manifest_path = os.path.join(VIDEO_FOLDER, "media_plan", "visual_director_report.json")
    director_manifest_tmp = director_manifest_path + ".tmp"
    director_scored = sum(1 for e in director_report.values() if e.get("decision") == "scored")
    director_diverged = sum(1 for e in director_report.values() if e.get("diverged"))
    director_cache_hits_skipped = sum(1 for e in director_report.values() if e.get("decision") == "skipped_cache_hit")
    with open(director_manifest_tmp, "w", encoding="utf-8") as f:
        json.dump({"enabled": visual_director is not None,
                    "mode": visual_director.VISUAL_DIRECTOR_MODE if visual_director is not None else "off",
                    "scored": director_scored,
                    "diverged_from_base": director_diverged,
                    "cache_hits_skipped_analysis": director_cache_hits_skipped,
                    # Номер слота — в самой записи: позиция в списке совпадает
                    # со слотом только пока в отчёте нет пропусков.
                    "clips": [{"index": i, **director_report[i]} for i in sorted(director_report)]},
                   f, ensure_ascii=False, indent=2)
    os.replace(director_manifest_tmp, director_manifest_path)
    # То же честное предупреждение, что уже есть у Look Management чуть выше
    # (см. cache_hits_skipped_analysis там) — тот же класс "shadow/assist на
    # уже отрендеренном эпизоде не полная симуляция".
    if visual_director is not None and director_cache_hits_skipped:
        print(f"  Visual Director: {director_cache_hits_skipped} клип(ов) пропущено анализом "
              f"(кэш из прошлого прогона) — для честного shadow/assist-прогона на этом эпизоде "
              f"очисти temp_smart/ и перезапусти.")

    if SELECT_ONLY:
        return finish_select_only(shot_entries, len(blocks))

    # Жёсткий финальный гейт: цель не "никогда не упасть" (нечестное
    # обещание — сеть/диск/память могут отказать всегда), а чтобы одиночный
    # сбой не портил ГОТОВЫЙ ролик молча. Раньше пропущенный клип просто
    # уходил в missing, а final.mp4 всё равно собирался с меньшим числом
    # клипов и растянутым freeze-кадром на месте пропуска (см.
    # pad_to_length ниже) — ненулевой код возврата был единственным
    # признаком проблемы, и его легко не заметить в конце многочасового
    # лога. RENDER_STRICT_GATE=0 возвращает старое поведение для тех, кому
    # осознанно нужна частичная сборка (ручная досборка позже).
    if missing and RENDER_STRICT_GATE:
        print(f"\nСТОП: {len(missing)} клип(ов) не приняты — final.mp4 НЕ собран "
              f"(RENDER_STRICT_GATE=1). Причины — {manifest_path}:")
        for i in missing:
            entry = render_manifest.get(i - 1, {})
            print(f"  [{i}] {entry.get('reason', 'причина не зафиксирована')}")
        print("Перезапусти прогон — уже готовые клипы (atomic-кэш) переиспользуются, "
              "перерендерятся только пропущенные.")
        return 1

    if not clips:
        print("Нет клипов")
        return 1
    merged = os.path.join(TEMP_FOLDER, "merged.mp4")
    with stage_timer.stage("assembly_xfade", n_clips=len(clips)):
        ok, xfade_total = xfade_chain_chunked(clips, clip_durs, clip_sections, merged, TEMP_FOLDER,
                                               blocks=clip_blocks)
    if not ok:
        concat = os.path.join(TEMP_FOLDER, "concat.txt")
        # Пути ТОЛЬКО абсолютные: concat-демуксер ffmpeg резолвит относительные
        # пути от папки самого concat.txt, а не от cwd — иначе сборка падает.
        open(concat, "w", encoding="utf-8").write(
            "".join(f"file '{os.path.abspath(c)}'\n" for c in clips))
        # Тот же пробел, что у xfade_chain()/финального мукса выше — fallback-
        # путь на concat не должен быть НЕЗАЩИЩЁННЕЕ пути, с которого он
        # откатывается. -c copy — тоже быстрый ремукс, щедрый множитель
        # достаточен как последний рубеж против настоящего зависания.
        try:
            r = subprocess.run(["ffmpeg", "-y", "-f", "concat", "-safe", "0",
                                "-i", concat, "-c", "copy", merged], capture_output=True, text=True, encoding="utf-8", errors="replace",
                               timeout=max(180, total))
        except subprocess.TimeoutExpired:
            print(f"Склейка (concat) зависла (таймаут {max(180, total):.0f}с).")
            return 1
        if r.returncode != 0:
            print("Склейка:", r.stderr[-300:])
            return 1
    merged, pad_gap = pad_to_length(merged, total, TEMP_FOLDER)
    # Симметричный контроль расхождения. Гейт по pad_gap ниже ловит только
    # СЛИШКОМ КОРОТКОЕ видео (заморозка в хвосте). Обратная сторона —
    # видео ДЛИННЕЕ аудио — раньше не диагностировалась вообще: финальный
    # мукс просто обрезал лишнее по -t, и это выглядело как штатная
    # сборка, хотя означало, что картинка накопительно отстаёт от голоса
    # (ровно тот баг, который лечат plan_transitions/
    # quantize_durations_to_frames). Теперь перебор виден в логе числом.
    try:
        merged_dur = get_media_duration(merged)
        overshoot = merged_dur - total
        if overshoot > 0.5:
            print(f"  ВНИМАНИЕ: смонтированное видео на {overshoot:.2f}с длиннее аудио "
                  f"({merged_dur:.2f}с против {total:.2f}с) — финальный мукс обрежет хвост "
                  f"по -t, но это значит, что картинка к концу отстаёт от голоса на эту "
                  f"же величину. Ожидаемое расхождение после кадровой сетки — доли "
                  f"секунды; больше — повод смотреть на бюджет склейки "
                  f"(estimate_xfade_budget/plan_transitions) или на пропущенные клипы.")
    except Exception:
        pass
    # Freeze-padding существует ТОЛЬКО чтобы закрыть маленький остаточный
    # зазор от xfade-округления (обычно доли секунды) — не как приёмный
    # механизм для реально пропущенного клипа. Раньше большой pad_gap
    # (например, вся длительность потерянного кадра) просто ронял код
    # возврата в конце main(), но final.mp4 всё равно ЗАПИСЫВАЛСЯ с
    # замороженным хвостом — ненулевой exit code легко потерять в конце
    # многочасового лога, а файл выглядит "готовым". Это ПРОВЕРКА ЦЕЛОСТНОСТИ:
    # ловит ЛЮБОЕ необъяснённое расхождение длительности (включая
    # гипотетическую ошибку расчёта xfade-бюджета), не только missing —
    # но именно НЕОБЪЯСНЁННОЕ. Если missing уже непустой и мы вообще
    # добрались сюда, значит RENDER_STRICT_GATE=0 (иначе гейт выше уже
    # вернул бы 1) — пользователь осознанно попросил старое поведение
    # "частичная сборка вместо срыва", и pad_gap тут ПОЛНОСТЬЮ объясняется
    # длительностью уже залогированных пропущенных клипов, а не скрытым
    # багом бюджета xfade. Дважды наказывать за один и тот же осознанный
    # пропуск (сначала пометить missing, потом всё равно не собрать файл)
    # значит не давать lenient-режиму вообще ничего лениться.
    # ХВОСТОВОЕ ПОГЛОЩЕНИЕ — НАМЕРЕННОЕ ПРОДЛЕНИЕ, А НЕ ПОТЕРЯННЫЙ КЛИП.
    # Если поглощён последний слот эпизода, наследовать его время некому
    # (следующего клипа нет), и остаток закрывается той же заморозкой
    # последнего кадра, которой закрывается округление xfade. Допуск
    # ослабляется РОВНО на эту известную величину: гейт заведён против
    # тихой потери клипа, а здесь потери нет — есть решение, записанное в
    # absorbed_slots_report.json. Всё, что сверху неё, по-прежнему стоп.
    _tail_carry = round(_carry_sec, 3)
    if _tail_carry > 0.05:
        print(f"  Хвост эпизода: последние {_tail_carry:.1f}с закрыты "
              f"продлением последнего проверенного кадра "
              f"({len(ABSORBED_SLOTS)} поглощённых слот(ов) всего)")
    if pad_gap - _tail_carry > PAD_GAP_HARD_CAP_SEC and not (missing and not RENDER_STRICT_GATE):
        print(f"\nСТОП: заморозка в хвосте {pad_gap:.1f}с превышает допуск "
              f"{PAD_GAP_HARD_CAP_SEC:.1f}с — final.mp4 НЕ собран (расчёт длительностей "
              f"разошёлся сильнее, чем можно списать на округление xfade).")
        return 1

    # -shortest САМ ПО СЕБЕ недостаточен с -c:v copy: копирование пакетов
    # режет только по границам GOP исходного клипа, а не по факту конца
    # аудио — на реальном 17-минутном ролике это давало +6с видео без
    # звука сверху (проверено вживую). Явный -t с точной длительностью
    # аудио режет ровно там, где надо, независимо от размера GOP.
    # A1: атмосферная подложка + сайдчейн-дакинг под голосом (build_music_mix,
    # безопасный откат на чистый голос, если ассет отсутствует/выключен).
    # A7: loudnorm теперь считается на ГОТОВОМ миксе голос+музыка, а не на
    # одном голосе — иначе музыка добавляла бы громкость ПОСЛЕ калибровки
    # под цель (LOUDNORM_TARGET_I) и сводила бы её к нулю (та же ошибка,
    # что "нормализовать трек, потом наложить ещё один трек поверх без
    # пересчёта").
    # A2: границы HOOK/FINAL по реальным длительностям отрендеренных клипов
    # (не по словам сценария — клипы уже учитывают все реальные подрезки/
    # sub-cuts) — секции идут по порядку HOOK -> BLOCK* -> FINAL, так что
    # достаточно суммы длительностей внутри каждой без отдельного поиска границ.
    # Аудит 04.09 (измерено на ep_base): clip_durs включают длительности
    # переходов (target = total + xfade_budget), их сумма раздута на нахлёсты
    # — FINAL-настроение музыки приходило на +2.27с позже реальной смены
    # секции уже на 17 склейках, на длинном эпизоде — на десятки секунд. Тот
    # же корень, что чинит hook_visual_starts() для подписей. Границы берём
    # с АУДИО-шкалы (sub_starts — та же, что у субтитров/глав): музыка
    # живёт на дорожке голоса, не на визуальном таймлайне.
    hook_end, final_start = section_audio_bounds(blocks, sub_starts, total)
    # A6: обработка голоса (highpass/EQ/деэссер/компрессия) ДО подмешивания
    # музыки — тот же порядок, что в реальном пост-продакшене: сначала
    # приводишь дорожку диктора в порядок, потом кладёшь её в микс.
    voice_processed = os.path.join(TEMP_FOLDER, "voice_processed.wav")
    voice_processed = process_voice(AUDIO_FILE, voice_processed)
    premix = build_episode_audio_layers(
        voice_processed, VIDEO_FOLDER, TEMP_FOLDER, blocks, sub_starts, real_weights,
        total, hook_end, final_start, typewriter_click_times, plate_sfx_cues,
        phrase_locked=bool(phrase_locked))
    # loudnorm — целевая громкость YouTube (-14 LUFS integrated, -1.5dB
    # true peak потолок, LRA 11) вместо "как есть от TTS". Было -16: на
    # этой платформе тише целевой означает, что ролик звучит глуше соседних
    # в ленте (платформа поднимает громкость только ГРОМКИХ роликов, тихие
    # не подтягивает). ЧЕТЫРЕ места обязаны совпадать — дефолт target_i у
    # measure_loudnorm_stats() и три литерала ниже: первый проход меряет
    # под одну цель, второй применяет под другую, и рассинхрон дал бы
    # смещение громкости, которого нет ни в одном логе. Разные
    # заказы озвучки/движки иначе дают заметно разную громкость от эпизода
    # к эпизоду — не проф. уровень, если зритель тянется к громкости между
    # роликами одного канала. Двухпроходный (measure -> linear=true) вместо
    # однопроходного динамического — тот подстраивает усиление на лету и
    # даёт неровную громкость внутри самого ролика. afade — раньше ролик
    # начинался и обрывался всухую (щелчок на монтажный лад, не финал).
    loud_stats = measure_loudnorm_stats(premix)
    fade_out_st = max(0.0, total - 2.0)
    # Аудит 04.09, измерено на готовом файле: fade-in 0.4с давал -12.8 дБ на
    # 100 мс и -5.6 дБ на 200 мс — хук начинается с нулевой секунды, первое
    # слово реальной озвучки глушилось. 50 мс достаточно против щелчка.
    AUDIO_FADE_IN_SEC = 0.05
    af = build_master_af(loud_stats, fade_out_st, AUDIO_FADE_IN_SEC)
    # Атомарная запись — тот же принцип, что render_tmp_path()/finalize_render()
    # у отдельных клипов (см. коммент там): final.mp4 — то, что пользователь
    # ФАКТИЧЕСКИ проверяет как "готово или нет". Обрыв ровно на этом финальном
    # проходе (пусть и короткий по времени — это -c:v copy, не перекодирование)
    # раньше оставлял бы обрезанный final.mp4 под финальным именем, что
    # выглядело бы как "готовый, но битый" файл, а не как "рендер не доехал".
    output_tmp = render_tmp_path(OUTPUT_FILE)
    # РЕАЛЬНЫЙ пробел, пойманный аудитом того же класса багов, что и
    # SPEED_RAMP_MAX_SOURCE_FPS/parallax stderr-deadlock/xfade_chain выше —
    # у ПОСЛЕДНЕГО шага перед final.mp4 (после часов рендера всех клипов)
    # не было никакого timeout вообще. Зависание здесь молча теряло бы весь
    # уже сделанный прогон. -c:v copy — быстрый ремукс, не перекодирование,
    # поэтому щедрого множителя достаточно (сама операция обычно на порядок
    # быстрее total, это именно последний рубеж против настоящего
    # зависания, не бюджет под скорость).
    #
    # РЕАЛЬНЫЙ, измеренный вживую баг (deep-audit, videos/_test20s, 28 августа):
    # "-t {total} ... -c:v copy ... -shortest" резало ВИДЕО не там, где нужно.
    # merged.mp4 (прямой выход xfade_chain_chunked/pad_to_length) на этом
    # эпизоде — ровно 575 кадров/23.958333с (совпадает с планом
    # phrase_locked_durations байт-в-байт), total (аудио) — 23.955354с, то
    # есть видео ДЛИННЕЕ аудио всего на ~3мс — меньше кадра. Ожидаемая обрезка
    # -t/-shortest — доля кадра. РЕАЛЬНАЯ, измеренная на этом же merged.mp4 +
    # premix.wav (тем же ffmpeg, теми же байтами) — 572 кадра/23.833333с,
    # то есть ЦЕЛЫХ 3 КАДРА (125мс) видео потеряны молча. Причина —
    # PTS-based "-t"/"-shortest" при "-c:v copy" режет по границе, которую
    # диктует B-frame/GOP reordering контейнера, а не точный счётчик кадров:
    # "лишних" кадров на выходе НЕ бывает (аудио и так не длиннее видео), то
    # есть -t/-shortest здесь вообще не нужны видео-потоку — их работу
    # (не дать видео убежать от аудио) полностью покрывает pad_to_length()
    # выше по коду, который уже гарантирует merged >= total. Живая проверка
    # (тот же merged.mp4+premix.wav, только "-vframes {N} -c:v copy" без
    # "-t"/"-shortest" на видео): 575/23.958333с — точное совпадение с
    # merged.mp4, ни одного потерянного кадра. Худший случай — хвост
    # ПОСЛЕДНЕГО клипа эпизода (для этого рендера это как раз клип, теряющий
    # 3 кадра из финальной фразы хука) укорачивается молча на до ~4 кадров
    # ПОСЛЕ того, как весь остальной пайплайн (alignment.csv,
    # phrase_locked_durations, кадровая сетка) уже добился точности до
    # полукадра — единственное место, где вся эта точность бы терялась.
    # Аудио по-прежнему явно триммится "-t" (оно перекодируется в AAC —
    # PTS-обрезка там точна, тот же принцип, что и раньше).
    video_frames_target = min(round(total * FPS), round(get_media_duration(merged) * FPS))
    _mux_t0 = time.perf_counter()
    try:
        r = subprocess.run(["ffmpeg", "-y", "-i", merged, "-i", premix,
                            "-t", f"{total:.3f}",
                            "-af", af,
                            # -ar 48000 обязателен именно ЗДЕСЬ (поймано вживую на
                            # реальном рендере): loudnorm с TP (true peak, для
                            # inter-sample пиков по ITU-R BS.1770 нужен передискрет)
                            # сам меняет частоту потока на выходе фильтра — без
                            # явного -ar это утекает прямо в AAC-энкодер (поймано:
                            # 96000Hz на итоговом final.mp4 при всём остальном
                            # звуке 48000Hz — единственное место в файле, где
                            # -ar не был проставлен явно, все остальные 11
                            # вызовов это уже получили в P2-17).
                            "-c:v", "copy", "-vframes", str(video_frames_target),
                            "-c:a", "aac", "-b:a", "192k", "-ar", "48000",
                            "-movflags", "+faststart",
                            output_tmp], capture_output=True, text=True, encoding="utf-8", errors="replace",
                           timeout=max(180, total))
    except subprocess.TimeoutExpired:
        stage_timer.record("final_mux", time.perf_counter() - _mux_t0, ok=False)
        print(f"Финальный мукс завис (таймаут {max(180, total):.0f}с) — final.mp4 не собран.")
        finalize_render(output_tmp, OUTPUT_FILE, False)
        return 1
    stage_timer.record("final_mux", time.perf_counter() - _mux_t0)
    if r.returncode != 0:
        print("Аудио:", r.stderr[-300:])
        finalize_render(output_tmp, OUTPUT_FILE, False)
        return 1
    finalize_render(output_tmp, OUTPUT_FILE, True)
    # Честная цифра вместо "надеемся" — измеряем итоговую громкость ГОТОВОГО
    # файла (не входного audio.mp3): если разошлось с целью (см. loudnorm=I=
    # в финальном миксе выше, сейчас -14) больше, чем на децибел, это видно
    # в отчёте, а не тонет молча. РЕАЛЬНЫЙ найденный баг (02.09): при смене
    # цели -16 -> -14 эта проверка осталась зашита на -16.0 отдельно от
    # четырёх точек loudnorm= — честный рендер на -14.3 (в пределах цели)
    # печатал ложную тревогу "разошлось с целью -16". Вынесено в константу
    # рядом с самим loudnorm=, а не восьмым магическим числом.
    final_lufs = None
    try:
        fr = subprocess.run(["ffmpeg", "-i", OUTPUT_FILE, "-af",
                              f"loudnorm=I={LOUDNORM_TARGET_I}:TP={LOUDNORM_TARGET_TP}:"
                              f"LRA={LOUDNORM_TARGET_LRA}:print_format=json",
                              "-f", "null", "-"], capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=60)
        fs, fe = fr.stderr.rindex("{"), fr.stderr.rindex("}") + 1
        final_lufs = float(json.loads(fr.stderr[fs:fe])["input_i"])
    except Exception:
        pass
    # QC того, что реально услышит зритель. Проверка входного голоса (выше,
    # до сборки) не видит ничего, что делает мастер-цепочка: подложку, дакинг,
    # loudnorm и лимитер. Именно там и жили обе найденные поломки звука.
    audio_qc(OUTPUT_FILE, label="Audio QC финала")
    write_audio_master_report(VIDEO_FOLDER, final_lufs)
    mb = os.path.getsize(OUTPUT_FILE) / (1024 * 1024)
    # Пропущенные кадры и раньше не останавливали сборку (стратегия
    # "лучше меньше клипов, чем сорванный рендер") — но раньше это тонуло
    # в середине лога, а ГОТОВО выглядело как чистый успех. Теперь пропуски
    # видны в итоговой строке, и код возврата честно отражает, что не всё
    # доехало (не 0, если что-то пропущено).
    dupes = qc_report(media_log)
    if qc_unknown_cache_hits:
        print(f"  ВНИМАНИЕ: QC дублей/резкости НЕ выполнялся для {len(qc_unknown_cache_hits)} кэшированных "
              f"клипов без известного исходника (слоты {qc_unknown_cache_hits[:10]}"
              f"{'…' if len(qc_unknown_cache_hits) > 10 else ''}) — пустой QC-отчёт по ним не означает «чисто»")
    status = f" | ПРОПУЩЕНО {len(missing)} блоков: {missing}" if missing else ""
    if final_lufs is not None:
        status += f" | Громкость: {final_lufs:.1f} LUFS" + (
            "" if abs(final_lufs - LOUDNORM_TARGET_I) <= 1.0
            else f" (!!! разошлось с целью {LOUDNORM_TARGET_I:.0f})")
    # Дубли по фото — та же логика: не блокируем сборку (видео уже готово
    # и в целом смотрибельно), но не даём находке потеряться в середине
    # лога и не даём коду возврата соврать, что всё чисто.
    status += f" | QC: {len(dupes)} похожих пар кадров — проверь глазами" if dupes else ""
    # Freeze-padding (2.4) — estimate_xfade_budget() должен был свести его
    # к нулю почти всегда; заметный (>PAD_GAP_HARD_CAP_SEC) случай уже
    # остановил бы сборку выше (см. проверку сразу после pad_to_length) —
    # если мы вообще добрались сюда, pad_gap заведомо <= допуска, но мелкий
    # ненулевой остаток всё ещё стоит показать честно, не молчать про него.
    status += f" | заморозка в хвосте: {pad_gap:.2f}с (в пределах допуска)" if pad_gap > 0.1 else ""
    # Явный отказ арбитра — тоже «собрано, но с замечаниями», и притом
    # замечание сильнее дублей: там «две похожие пары, посмотри», здесь
    # «судья сказал, что кадр не подходит, а он всё равно в ролике».
    # Раньше такой слот не влиял на код возврата вообще — прогон
    # заканчивался чистым нулём.
    status += (f" | арбитр отклонил ВСЕХ кандидатов на {len(ARBITER_REJECTED_ALL)} слот(ах)"
               if ARBITER_REJECTED_ALL else "")
    # Сколько слотов система САМА признала негодными и всё равно показала
    # зрителю живым кадром (бюджет карточек кончился, см. FALLBACK_CARD_
    # MAX_SHARE). Реальный измеренный разрыв на эпизоде 02_ne-mechom: 76
    # слотов помечены браком, 17 закрыты карточками, 59 доехали до экрана —
    # и ни одна строка лога об этом не говорила, число жило только в JSON.
    # Отчёт, который никто не открывает в момент сдачи, знанием не является.
    known_bad_idx = ({m["index"] for m in RELEVANCE_GATE_MISSES} |
                     {m["index"] for m in STOCK_EXHAUSTED_MISSES} |
                     {m["index"] for m in ARBITER_REJECTED_ALL})
    shipped_bad = sorted(known_bad_idx - {s["index"] for s in FALLBACK_CARD_SLOTS})
    if shipped_bad:
        status += (f" | ИЗВЕСТНЫЙ БРАК НА ЭКРАНЕ: {len(shipped_bad)} слот(ов) "
                   f"(карточками закрыто {len(FALLBACK_CARD_SLOTS)}) — "
                   f"слоты {[i + 1 for i in shipped_bad[:10]]}"
                   f"{'…' if len(shipped_bad) > 10 else ''}")
    print(f"\nГОТОВО: {OUTPUT_FILE} ({mb:.0f} MB, {total/60:.1f} мин, {len(clips)} кадров){status}")
    return (EXIT_BUILT_WITH_WARNINGS
            if (missing or dupes or ARBITER_REJECTED_ALL or shipped_bad) else EXIT_OK)


if __name__ == "__main__":
    sys.exit(main())
